TURATH_CHUNK(3,[{"num":600,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَاءَ إِلَى سَعْدِ بْنِ عُبَادَةَ، فَجَاءَ بِخُبْزٍ وَزَيْتٍ فَأَكَلَ، ثُمَّ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ."],"takhrij":"صحيح: رواه أبو داود (3854) عن مخلد بن خالد، حدّثنا عبدالرّزاق، أخبرنا معمر، عن ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب صلاة الملائكة على من أطعم الطعام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (3854), ʿAbd al-Razzāq (7907), and Aḥmad (12406).","chapter_en":"The Angels’ Supplication for the One Who Provides Food","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالملائكة","group_en":"Collection of Chapters Concerning Belief in the Angels","part_no":2,"group_no":4,"chapter_no":62,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: The Prophet ﷺ came to Saʿd ibn ʿUbādah may Allah be pleased with him, who brought bread and oil, and the Prophet ﷺ ate. Then the Prophet ﷺ said: “May fasting people break their fast with you, may the righteous eat your food, and may the angels invoke blessings upon you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3854)، وعبد الرزاق (7907)، وأحمد (12406)."},{"num":601,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، عَنْ أَكْلِ الْبَصَلِ، وَالْكُرَّاثِ، فَغَلَبَتْنَا الْحَاجَةُ فَأَكَلْنَا مِنْهَا، فَقَالَ: مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ الْمُنْتِنَةِ، فَلَا يَقْرَبَنَّ مَسْجِدَنَا، فَإِنَّ الْمَلَائِكَةَ تَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ الإِنْسُ.","وَفِي رِوَايَةِ: مَنْ أَكَلَ مِنْ هَذِهِ الْبَقْلَةِ الثُّومِ وَقَالَ مَرَّةً: مَنْ أَكَلَ الْبَصَلَ وَالثُّومَ وَالْكُرَّاثَ فَلَا يَقْرَبَنَّ مَسْجِدَنَا، فَإِنَّ الْمَلَائِكَةَ تَتَأَذَّى مِمَّا يَتَأَذَّى مِنْهُ بَنُو آدَمَ."],"takhrij":"صحيح: رواه مسلم في المساجد (564) عن أبي بكر بن أبي شيبة، حدّثنا كثير بن هشام، عن هشام الدّستوائيّ، عن أبي الزّبير، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب الملائكة تتأذّى مما يتأذّى به الإنسان","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (564). The second wording was also narrated by Muslim.","chapter_en":"Chapter The angels are harmed by what harms human beings.","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالملائكة","group_en":"Collection of Chapters Concerning Belief in the Angels","part_no":2,"group_no":4,"chapter_no":63,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, reported: The Messenger of Allah ﷺ prohibited eating onions and leeks. But necessity overcame us, so we ate some of them. He then said: “Whoever eats from this offensive plant must not come near our mosque, for the angels are harmed by what harms human beings.” In another narration:","“Whoever eats from this plant — garlic.” And on another occasion he said: “Whoever eats onions, garlic, and leeks must not come near our mosque, for the angels are harmed by what harms the children of Adam.”"]},"intro":{"ar":["٦٠١"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (564)، والرواية الثانية رواها مسلم."},{"num":602,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا قَامَ أَحَدُكُمْ إِلَى الصَّلَاةِ فَلَا يَبْصُقْ أَمَامَهُ، فَإِنَّمَا يُنَاجِي اللَّهَ مَا دَامَ فِي مُصَلَّاهُ وَلَا عَنْ يَمِينِهِ، فَإِنَّ عَنْ يَمِينِهِ مَلَكًا، وَلْيَبْصُقْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ فَيَدْفِنُهَا."],"takhrij":"صحيح: رواه البخاريّ في الصّلاة (416) عن إسحاق بن نصر، قال: حدّثنا عبدالرزّاق، عن معمر، عن همّام، سمع أبا هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب أنّ على يمين المصلي ملكاً","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (416) and Muslim (547).","chapter_en":"Chapter There is an angel on the right side of the one praying.","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالملائكة","group_en":"Collection of Chapters Concerning Belief in the Angels","part_no":2,"group_no":4,"chapter_no":64,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “When one of you stands for prayer, he must not spit in front of himself, for he is privately conversing with Allah as long as he remains in his place of prayer; nor should he spit to his right, for there is an angel on his right. Rather, let him spit to his left or beneath his foot and bury it.”"]},"intro":{"ar":["٦٠٢"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3125],"tks":"صحيح: رواه البخاري (416)، ومسلم (547)."},{"num":603,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا هُوَ جِبْرِيلُ، لَمْ أَرَهُ عَلَى صُورَتِهِ الَّتِي خُلِقَ عَلَيْهَا، غَيْرَ هَاتَيْنِ الْمَرَّتَيْنِ، رَأَيْتُهُ مُنْهَبِطًا مِنَ السَّمَاءِ، سَادًّا عِظَمُ خَلْقِهِ مَا بَيْنَ السَّمَاءِ إِلَى الأَرْضِ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4855)، ومسلم في الإيمان (177) كلاهما من طريق عامر الشّعبيّ، عن مسروق، قال: قلت لعائشة، فذكر الحديث في سياق طويل.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صفة جبريل عليه السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4855) and Muslim (177).","chapter_en":"What Has Been Reported Concerning the Description of Jibrīl, peace be upon him,","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Prophet ﷺ said: “It was Jibrīl. I did not see him in the form in which he was created except on these two occasions. I saw him descending from the sky, the immensity of his creation filling what lay between the heaven and the earth.”"]},"buhuth":{"en":["In another narration in al-Bukhārī:","“He used to come to him in the form of a man, but on this occasion he came to him in his own true form, filling the horizon.”","Imām Aḥmad (24885) also narrated the addition:","“He was wearing garments of sundus, with pearls and rubies suspended upon him.”","Its chain is Ḥasan."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4855)، ومسلم (177)."},{"num":604,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ: أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَى جِبْرِيلَ لَهُ سِتُّ مِائَةِ جَنَاحٍ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3232)، ومسلم في الإيمان (174) كلاهما عن أبي إسحاق الشّيبانيّ، قال: سألت زرَّ بن حبيش عن قول الله عزّ وجلّ ﴿فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى﴾ [سورة النجم: 9] فقال: أخبرني عبدالله بن مسعود، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في صفة جبريل عليه السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3232) and Muslim (174).","chapter_en":"What Has Been Reported Concerning the Description of Jibrīl, peace be upon him,","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Ibn Masʿūd may Allah be pleased with him reported that the Prophet ﷺ saw Jibrīl with six hundred wings."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3232)، ومسلم (174)."},{"num":605,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ قَالَ: ﴿لَقَدْ رَأَى مِنْ آيَاتِ رَبِّهِ الْكُبْرَى﴾ [سورة النجم: 18] قَالَ: رَأَى رَفْرَفًا أَخْضَرَ سَدَّ أُفُقَ السَّمَاءِ."],"takhrij":"صحيح: رواه البخاريّ في بدأ الخلق (3233) عن حفص بن عمر، حدثنا شعبة، عن الأعمش، عن إبراهيم، عن علقمة، عن عبدالله بن مسعود، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في صفة جبريل عليه السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3233).","chapter_en":"What Has Been Reported Concerning the Description of Jibrīl, peace be upon him,","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him said regarding the verse: “He certainly saw some of the greatest signs of his Lord.” [Sūrat al-Najm 53:18] He said: “He saw a green rafraf filling the horizon of the sky.”"]},"buhuth":{"en":["Al-Tirmidhī (3283) narrated through another route that he said regarding the verse:","“The heart did not deny what it saw.”","[Sūrat al-Najm 53:11]","He said:","“The Messenger of Allah ﷺ saw Jibrīl wearing a garment of rafraf that filled what lay between the heaven and the earth.”","The word:","“rafraf”","refers to a type of fine, luxurious cloth."]}},"tuhfa":{},"full":1,"dr":1,"rep":[431],"tks":"صحيح: رواه البخاري (3233)."},{"num":606,"demo":false,"sanad":"","matn":["عَنِ ابْنِ مَسْعُودٍ أَنَّهُ قَالَ فِي هَذِهِ الْآيَةِ: ﴿وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى﴾ [سورة النّجم: 13] قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَيْتُ جِبْرِيلَ عِنْدَ سِدْرَةِ الْمُنْتَهَى، عَلَيْهِ سِتُّ مِائَةِ جَنَاحٍ، يُنْتَثَرُ مِنْ رِيشِهِ التَّهَاوِيلُ: الدُّرُّ وَالْيَاقُوتُ."],"takhrij":"حسن: رواه الإمام أحمد (3915)، والطبراني في الكبير (9054) كلاهما من طريق عاصم بن بهدلة، عن زرّ، عن ابن مسعود.","grade":"حسن","chapter_ar":"باب ما جاء في صفة جبريل عليه السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (3915) and al-Ṭabarānī in al-Muʿjam al-Kabīr (9054).","chapter_en":"What Has Been Reported Concerning the Description of Jibrīl, peace be upon him,","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["Ibn Masʿūd may Allah be pleased with him said regarding the verse: “And he certainly saw him another time.” [Sūrat al-Najm 53:13] The Messenger of Allah ﷺ said: “I saw Jibrīl at Sidrat al-Muntahā. He had six hundred wings, and wondrous things — pearls and rubies — were scattering from his feathers.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (3915)، والطبراني في الكبير (9054)."},{"num":607,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ثُمَّ فَتَرَ عَنِّي الْوَحْيُ فَتْرَةً، فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالْأَرْضِ، فَجَئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الْأَرْضِ، فَجِئْتُ أَهْلِي، فَقُلْتُ: زَمِّلُونِي زَمِّلُونِي، فَأَنْزَلَ اللَّهُ تَعَالَى: ﴿يَا أَيُّهَا الْمُدَّثِّرُ (1) قُمْ فَأَنْذِرْ (2) وَرَبَّكَ فَكَبِّرْ (3) وَثِيَابَكَ فَطَهِّرْ (4) وَالرُّجْزَ فَاهْجُرْ (5)﴾ [سورة المدثر: 1 – 5]."],"takhrij":"متفق عليه: رواه البخاريّ في تفسير القرآن (3238)، ومسلم في الإيمان (161: 256) كلاهما من حديث الليث بن سعد، قال: حدثني عُقيل بن خالد، عن ابن شهاب، قال: سمعتُ أبا سلمة بن عبدالرحمن، يقول: أخبرني جابر بن عبدالله، فذكر الحديث، واللّفظ للبخاريّ. وفي لفظ مسلم: فجئثتُ منه فرقاً.","grade":"متفق عليه","chapter_ar":"باب ما جاء في جلوس جبريل على كرسي بين السماء والأرض","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3238) and Muslim (161:256).","chapter_en":"What Has Been Reported Concerning Jibrīl Sitting on a Chair Between Heaven and Earth","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":3,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that he heard the Prophet ﷺ say, while speaking about the pause in revelation: “While I was walking, I heard a voice from the sky. I raised my gaze toward the sky, and there was the angel who had come to me at Ḥirāʾ, sitting upon a chair between heaven and earth. I was seized with such terror that I fell to the ground. Then I went to my family and said: ‘Wrap me up! Wrap me up!’” Then Allah Most High revealed: “O you who are wrapped up! Arise and warn. Magnify your Lord. Purify your garments. And shun impurity.” [Sūrat al-Muddaththir 74:1–5]"]},"buhuth":{"en":["His words:","“I was seized with terror”","mean that he became frightened and overwhelmed with fear.","His words:","“I fell”","mean that he fell down to the ground."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3238)، ومسلم (161: 256)."},{"num":608,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ إِذَا أَحَبَّ عَبْدًا دَعَا جِبْرِيلَ، فَقَالَ: إِنِّي أُحِبُّ فُلَانًا فَأَحِبَّهُ، قَالَ: فَيُحِبُّهُ جِبْرِيلُ، ثُمَّ يُنَادِي فِي السَّمَاءِ، فَيَقُولُ: إِنَّ اللَّهَ يُحِبُّ فُلَانًا فَأَحِبُّوهُ فَيُحِبُّهُ أَهْلُ السَّمَاءِ، قَالَ: ثُمَّ يُوضَعُ لَهُ الْقَبُولُ فِي الْأَرْضِ، وَإِذَا أَبْغَضَ عَبْدًا دَعَا جِبْرِيلَ، فَيَقُولُ: إِنِّي أُبْغِضُ فُلَانًا فَأَبْغِضْهُ، قَالَ: فَيُبْغِضُهُ جِبْرِيلُ، ثُمَّ يُنَادِي فِي أَهْلِ السَّمَاءِ إِنَّ اللَّهَ يُبْغِضُ فُلَانًا فَأَبْغِضُوهُ، قَالَ: فَيُبْغِضُونَهُ ثُمَّ تُوضَعُ لَهُ الْبَغْضَاءُ فِي الْأَرْضِ."],"takhrij":"متفق عليه: رواه مسلم في البر والصلة (2637) عن زهير بن حرب، حدثنا جرير، عن سهيل، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب إن جبريل ينادي في السماء أن الله يحب فلانًا فأحبوه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2637) and al-Bukhārī (7485).","chapter_en":"Jibrīl Calls Out in Heaven That Allah Loves So-and-So, So Love Him","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “When Allah loves a servant, He calls Jibrīl and says: ‘Indeed, I love so-and-so, so love him.’ Jibrīl then loves him. Jibrīl then calls out in heaven: ‘Indeed, Allah loves so-and-so, so love him.’ The inhabitants of heaven then love him, and acceptance is placed for him upon the earth. And when Allah hates a servant, He calls Jibrīl and says: ‘Indeed, I hate so-and-so, so hate him.’ Jibrīl then hates him. He then calls out among the inhabitants of heaven: ‘Indeed, Allah hates so-and-so, so hate him.’ They then hate him, and hatred is placed for him upon the earth.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12721,13977,14655],"tks":"متفق عليه: رواه مسلم (2637)، والبخاري (7485)."},{"num":609,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عُرِضَ عَلَيَّ الأَنْبِيَاءُ، فَإِذَا مُوسَى ضَرْبٌ مِنَ الرِّجَالِ، كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ، وَرَأَيْتُ عِيسَى ابْنَ مَرْيَمَ عَلَيْهِ السَّلَام، فَإِذَا أَقْرَبُ مَنْ، رَأَيْتُ بِهِ شَبَهًا عُرْوَةُ بْنُ مَسْعُودٍ، وَرَأَيْتُ إِبْرَاهِيمَ صَلَوَاتُ اللَّهِ عَلَيْهِ، فَإِذَا أَقْرَبُ مَنْ، رَأَيْتُ بِهِ شَبَهًا صَاحِبُكُمْ يَعْنِي نَفْسَهُ، وَرَأَيْتُ جِبْرِيلَ عَلَيْهِ السَّلَام، فَإِذَا أَقْرَبُ مَنْ، رَأَيْتُ بِهِ شَبَهًا دَحْيَةُ.","وَفِي رِوَايَةِ: دَحْيَةُ بْنُ خَلِيفَةَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (167) من طرق عن الليث بن سعد، عن أبي الزبير، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب كان جبريل عليه السلام يتمثل بدحية الكلبي","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (167).","chapter_en":"Jibrīl, peace be upon him, Would Appear in the Form of Diḥyah al-Kalbī","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Jābir may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The Prophets were shown to me. Mūsā was a lean-built man, as though he were from the men of Shanūʾah. I saw ʿĪsā ibn Maryam peace be upon him, and the person I have seen who most resembled him was ʿUrwah ibn Masʿūd. I saw Ibrāhīm, may Allah’s blessings be upon him, and the person I have seen who most resembled him was your companion” — meaning himself ﷺ — “and I saw Jibrīl, peace be upon him,, and the person I have seen who most resembled him was Diḥyah.”","In another narration: “Diḥyah ibn Khalīfah.”"]},"buhuth":{"en":["Regarding the word:","“ḍarb,”","al-Nawawī said that the scholars of language explained it here as referring to a man of lean build, with little flesh.","“Shanūʾah”","is a well-known tribe from the south of the Arabian Peninsula.","Diḥyah was Diḥyah ibn Khalīfah al-Kalbī may Allah be pleased with him, a well-known Companion who was proverbial for his handsome appearance."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8625],"tks":"صحيح: رواه مسلم (167)."},{"num":610,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَكَانَ جِبْرِيلُ عَلَيْهِ السَّلَام يَأْتِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي صُورَةِ دِحْيَةَ."],"takhrij":"صحيح: رواه الإمام أحمد (5857) عن عفّان، حدّثنا حمّاد بن سلمة، عن إسحاق بن سويد، عن يحيى بن يَعْمُر، عن ابن عمر، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب كان جبريل عليه السلام يتمثل بدحية الكلبي","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (5857).","chapter_en":"Jibrīl, peace be upon him, Would Appear in the Form of Diḥyah al-Kalbī","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Prophet ﷺ said: “Jibrīl, peace be upon him, used to come to the Prophet ﷺ in the form of Diḥyah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه الإمام أحمد (5857)."},{"num":611,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بَارِزًا لِلنَّاسِ، فَأَتَاهُ رَجُلٌ فَقَالَ: فَذَكَرَ الْحَدِيثَ بِطُولِهِ. وَفِيهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا جِبْرِيلُ، جَاءَ لِيُعَلِّمَ النَّاسَ دِينَهُمْ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (50)، ومسلم في الإيمان (9) كلاهما من حديث إسماعيل بن إبراهيم بن عليّة، عن أبي حيان التّيمي، عن أبي زرعة، عن أبي هريرة، فذكر الحديث بطوله. انظر أوائل الإيمان. ولم يذكر في الحديث هيئة جبريل ولكن الظّاهر أنه أتى بالصّورة التي وصفها عمر بن الخطّاب في الحديث الآتي.","grade":"متفق عليه","chapter_ar":"باب كان جبريل يتمثل بالرجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (50) and Muslim (9).","chapter_en":"Jibrīl Would Appear in the Form of a Man","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: The Prophet ﷺ was out among the people one day when a man came to him. He then mentioned the ḥadīth at length. In it, the Prophet ﷺ said: “This was Jibrīl. He came to teach the people their religion.”"]},"intro":{"ar":["قال الله تعالى:","﴿فَأَرْسَلْنَا إِلَيْهَا رُوحَنَا فَتَمَثَّلَ لَهَا بَشَرًا سَوِيًّا﴾","[مريم: ١٧]","والروح اسم من أسماء جبريل عليه السلام، مثل قوله تعالى:","﴿تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِمْ مِنْ كُلِّ أَمْرٍ﴾","[القدر: ٤]","قال ابن عباس رضي الله عنهما:","الروح هو جبريل.","Ibn ʿAbbās رضي الله عنهما said:"],"en":["Allah Most High said:","“Then We sent to her Our Spirit, and he appeared before her as a well-proportioned man.”","[Sūrat Maryam 19:17]","“The Spirit” is one of the names of Jibrīl, peace be upon him,, as in the saying of Allah Most High:","“The angels and the Spirit descend therein by permission of their Lord with every matter.”","[Sūrat al-Qadr 97:4]","“The Spirit is Jibrīl.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (50)، ومسلم (9)."},{"num":612,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ الْحَارِثَ بْنَ هِشَامٍ سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَيْفَ يَأْتِيكَ الْوَحْيُ ؟ قَالَ: كُلُّ ذَاكَ يَأْتِي الْمَلَكُ أَحْيَانًا فِي مِثْلِ صَلْصَلَةِ الْجَرَسِ فَيَفْصِمُ عَنِّي وَقَدْ وَعَيْتُ مَا قَالَ: وَهُوَ أَشَدُّهُ عَلَيَّ وَيَتَمَثَّلُ لِي الْمَلَكُ أَحْيَانًا رَجُلًا فَيُكَلِّمُنِي فَأَعِي مَا يَقُولُ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3215)، ومسلم في الفضائل (2333) كلاهما من طريق هشام بن عروة، عن أبيه، عن عائشة، فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب كان جبريل يتمثل بالرجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3215) and Muslim (2333).","chapter_en":"Jibrīl Would Appear in the Form of a Man","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her, the wife of the Prophet ﷺ, reported that al-Ḥārith ibn Hishām asked the Prophet ﷺ: “How does revelation come to you?” He replied: “All of that occurs. Sometimes the angel comes to me with something like the ringing of a bell, and then it ceases from me after I have fully retained what he said; and this is the most difficult upon me. At other times, the angel appears to me in the form of a man and speaks to me, and I fully comprehend what he says.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3215)، ومسلم (2333)."},{"num":613,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ الْخَطَّابِ قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ، إِذْ طَلَعَ عَلَيْنَا رَجُلٌ شَدِيدُ بَيَاضِ الثِّيَابِ، شَدِيدُ سَوَادِ الشَّعَرِ، لَا يُرَى عَلَيْهِ أَثَرُ السَّفَرِ، وَلَا يَعْرِفُهُ مِنَّا أَحَدٌ. فَذَكَرَ الْحَدِيثَ، وَفِيهِ: قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عُمَرُ أَتَدْرِي مَنِ السَّائِلُ؟ قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَإِنَّهُ جِبْرِيلُ أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ."],"takhrij":"صحيح: رواه مسلم في الإيمان (8) من طرق عن يحيى بن يعمر، عن ابن عمر، عن عمر بن الخطاب، فذكر الحديث بطوله. انظر: أوائل كتاب الإيمان.","grade":"صحيح","chapter_ar":"باب كان جبريل يتمثل بالرجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (8).","chapter_en":"Jibrīl Would Appear in the Form of a Man","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb, may Allah be pleased with him, reported: “While we were sitting with the Messenger of Allah ﷺ one day, a man appeared before us whose clothes were intensely white and whose hair was intensely black. No trace of travel could be seen upon him, and none of us knew him…” He then mentioned the ḥadīth. In it, the Prophet ﷺ said: “O ʿUmar, do you know who the questioner was?” I replied: “Allah and His Messenger know best.” He said: “That was Jibrīl. He came to you to teach you your religion.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (8)."},{"num":614,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَاهُ جِبْرِيلُ عَلَيْهِ السَّلامُ وَهُوَ يَلْعَبُ مَعَ الْغِلْمَانِ، فَأَخَذَهُ فَصَرَعَهُ، فَشَقَّ قَلْبَهُ، فَاسْتَخْرَجَ الْقَلْبَ.... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (162: 261) عن شيبان بن فروخ، حدّثنا حماد بن سلمة، حدّثنا ثابت البنانيّ، عن أنس بن مالك، فذكر الحديث في قصة الإسراء والمعراج.","grade":"صحيح","chapter_ar":"باب كان جبريل يتمثل بالرجل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (162:261).","chapter_en":"Jibrīl Would Appear in the Form of a Man","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":6,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: “Jibrīl came to the Messenger of Allah ﷺ while he was playing with the boys. He took hold of him, laid him down, opened his chest, and removed his heart…” The ḥadīth continues."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (162: 261)."},{"num":615,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ الْمُسَيِّبِ، عَنْ أَبِي هُرَيْرَةَ: أَنَّ عُمَرَ مَرَّ بِحَسَّانَ وَهُوَ يُنْشِدُ الشِّعْرَ فِي الْمَسْجِدِ فَلَحَظَ إِلَيْهِ، فَقَالَ: قَدْ كُنْتُ أُنْشِدُ وَفِيهِ مَنْ هُوَ خَيْرٌ مِنْكَ، ثُمَّ الْتَفَتَ إِلَى أَبِي هُرَيْرَةَ، فَقَالَ: أَنْشُدُكَ اللَّهَ أَسَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَجِبْ عَنِّي اللَّهُمَّ أَيِّدْهُ بِرُوحِ الْقُدُسِ، قَالَ: اللَّهُمَّ نَعَمْ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3212)، ومسلم في فضائل الصّحابة (2485) كلاهما من طريق سفيان بن عيينة، عن الزهريّ، عن سعيد بن المسيب، فذكره. واللفظ لمسلم، ولفظ البخاريّ نحوه.","grade":"متفق عليه","chapter_ar":"باب من أسماء جبريل: الروح","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3212) and Muslim (2485).","chapter_en":"One of the Names of Jibrīl Is “the Spirit”","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["Saʿīd ibn al-Musayyib narrated from Abū Hurayrah may Allah be pleased with him that ʿUmar may Allah be pleased with him passed by Ḥassān while he was reciting poetry in the mosque. He looked toward him, whereupon Ḥassān said: “I used to recite poetry here when one who was better than you was present.” He then turned to Abū Hurayrah may Allah be pleased with him and said: “I adjure you by Allah: did you hear the Messenger of Allah ﷺ say: ‘Respond on my behalf. O Allah, support him with the Holy Spirit’?” He replied: “Yes, by Allah.”"]},"intro":{"ar":["قال الله تعالى:","﴿نَزَلَ بِهِ الرُّوحُ الْأَمِينُ﴾","[الشعراء: ١٩٣]","وقال تعالى:","﴿قُلْ نَزَّلَهُ رُوحُ الْقُدُسِ مِنْ رَبِّكَ بِالْحَقِّ﴾","[النحل: ١٠٢]"],"en":["Allah Most High said:","“The Trustworthy Spirit brought it down.”","[Sūrat al-Shuʿarāʾ 26:193]","And He said:","“Say: The Holy Spirit has brought it down from your Lord in truth.”","[Sūrat al-Naḥl 16:102]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3212)، ومسلم (2485)."},{"num":616,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي رُكُوعِهِ وَسُجُودِهِ: سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ."],"takhrij":"صحيح: رواه مسلم في الصّلاة (487) من طرق عن قتادة، عن مطرف بن عبدالله بن الشّخير، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب من أسماء جبريل: الروح","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (487).","chapter_en":"One of the Names of Jibrīl Is “the Spirit”","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Prophet ﷺ used to say in his bowing and prostration: “All-Glorious, All-Holy, Lord of the angels and the Spirit.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (487)."},{"num":617,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ لِحَسَّانَ بْنِ ثَابِتٍ: اهْجُهُمْ أَوْ هَاجِهِمْ وَجِبْرِيلُ مَعَكَ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3212)، ومسلم في فضائل الصحابة (2486) كلاهما من حديث شعبة، عن عدي بن ثابت، عن البراء فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أن جبريل مع حسان بن ثابت عند هجاء المشركين","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3212) and Muslim (2486).","chapter_en":"What Has Been Reported That Jibrīl Was With Ḥassān ibn Thābit When He Satirized the Polytheists","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":8,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib, may Allah be pleased with him, reported: I heard the Prophet ﷺ say to Ḥassān ibn Thābit may Allah be pleased with him: “Satirize them — or attack them with satire — and Jibrīl is with you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14595],"tks":"متفق عليه: رواه البخاري (3212)، ومسلم (2486)."},{"num":618,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِجِبْرِيلَ: أَلَا تَزُورُنَا أَكْثَرَ مِمَّا تَزُورُنَا؟ قَالَ: فَنَزَلَتْ: ﴿وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ لَهُ مَا بَيْنَ أَيْدِينَا وَمَا خَلْفَنَا﴾ [سورة مريم: 64]."],"takhrij":"صحيح: رواه البخاريّ في بدء الخلق (3218) من طرق عن عمر بن ذرّ، عن أبيه، عن سعيد بن جبير، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب ما كان ينزل جبريل إلا بأمر من الله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3218).","chapter_en":"Jibrīl Would Not Descend Except by the Command of Allah","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: The Messenger of Allah ﷺ said to Jibrīl: “Will you not visit us more often than you do?” Then Allah Most High revealed: “We do not descend except by the command of your Lord. To Him belongs what is before us, what is behind us, and what is between that; and your Lord is never forgetful.” [Sūrat Maryam 19:64]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3218)."},{"num":619,"demo":false,"sanad":"","matn":["عَنِ ابْنِ شِهَابٍ أَنَّ عُمَرَ بْنَ عَبْدِ الْعَزِيزِ، أَخَّرَ الصَّلَاةَ يَوْمًا فَدَخَلَ عَلَيْهِ عُرْوَةُ بْنُ الزُّبَيْرِ، فَأَخْبَرَهُ أَنَّ الْمُغِيرَةَ بْنَ شُعْبَةَ أَخَّرَ الصَّلَاةَ يَوْمًا وَهُوَ بِالْكُوفَةِ، فَدَخَلَ عَلَيْهِ أَبُو مَسْعُودٍ الْأَنْصَارِيُّ، فَقَالَ: مَا هَذَا يَا مُغِيرَةُ؟ أَلَيْسَ قَدْ عَلِمْتَ أَنَّ جِبْرِيلَ نَزَلَ فَصَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: بِهَذَا أُمِرْتُ.","فَقَالَ عُمَرُ بْنُ عَبْدِ الْعَزِيزِ: اعْلَمْ مَا تُحَدِّثُ بِهِ يَا عُرْوَةُ، أَوَ إِنَّ جِبْرِيلَ هُوَ الَّذِي أَقَامَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقْتَ الصَّلَاةِ؟ قَالَ عُرْوَةُ: كَذَلِكَ كَانَ بَشِيرُ بْنُ أَبِي مَسْعُودٍ الْأَنْصَارِيُّ يُحَدِّثُ، عَنْ أَبِيهِ."],"takhrij":"متفق عليه: رواه مالك في وقوت الصلاة (1) عن ابن شهاب، به، مثله.","grade":"متفق عليه","chapter_ar":"باب إمامة جبريل للنبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (1), al-Bukhārī (521), and Muslim (610:167).","chapter_en":"Jibrīl Leading the Prophet ﷺ in Prayer","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":10,"content":{"translation":{"en":["Ibn Shihāb reported that ʿUmar ibn ʿAbd al-ʿAzīz delayed the prayer one day. ʿUrwah ibn al-Zubayr entered upon him and informed him that al-Mughīrah ibn Shuʿbah had once delayed the prayer while he was in Kūfah. Abū Masʿūd al-Anṣārī may Allah be pleased with him then entered upon al-Mughīrah and said: “What is this, O Mughīrah? Did you not know that Jibrīl descended and prayed, and the Messenger of Allah ﷺ prayed; then he prayed, and the Messenger of Allah ﷺ prayed; then he prayed, and the Messenger of Allah ﷺ prayed; then he prayed, and the Messenger of Allah ﷺ prayed; then he prayed, and the Messenger of Allah ﷺ prayed; then he said: ‘This is what I have been commanded’?”","ʿUmar ibn ʿAbd al-ʿAzīz then said: “Be certain about what you are narrating, O ʿUrwah. Was it Jibrīl who established the prayer times for the Messenger of Allah ﷺ?” ʿUrwah replied: “That is how Bashīr ibn Abī Masʿūd al-Anṣārī used to narrate it from his father.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1)، والبخاري (521)، ومسلم (610: 167)."},{"num":620,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجْوَدَ النَّاسِ، وَكَانَ أَجْوَدُ مَا يَكُونُ فِي رَمَضَانَ حِينَ يَلْقَاهُ جِبْرِيلُ، وَكَانَ يَلْقَاهُ فِي كُلِّ لَيْلَةٍ مِنْ رَمَضَانَ فَيُدَارِسُهُ الْقُرْآنَ، فَلَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَجْوَدُ بِالْخَيْرِ مِنَ الرِّيحِ الْمُرْسَلَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الوحي (6)، ومسلمٌ في الفضائل (2308) كلاهما من طريق الزّهريّ، قال: أخبرني عبيد الله بن عبدالله، عن ابن عباس، فذكر الحديث، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب كان جبريل يدارس القرآن مع النبي ﷺ في كل ليلة من رمضان","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6) and Muslim (2308). The wording is that of al-Bukhārī.","chapter_en":"Jibrīl Would Review the Qurʾān With the Prophet ﷺ Every Night in Ramaḍān","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: “The Messenger of Allah ﷺ was the most generous of people, and he was at his most generous during Ramaḍān when Jibrīl would meet him. Jibrīl would meet him every night of Ramaḍān and review the Qurʾān with him. When Jibrīl met him, the Messenger of Allah ﷺ was more generous in doing good than the freely blowing wind.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6)، ومسلم (2308)، واللفظ للبخاري."},{"num":621,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أَقْبَلَتْ فَاطِمَةُ تَمْشِي كَأَنَّ مِشْيَتَهَا مَشْيُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَرْحَبًا بِابْنَتِي ثُمَّ أَجْلَسَهَا عَنْ يَمِينِهِ أَوْ عَنْ شِمَالِهِ، ثُمَّ أَسَرَّ إِلَيْهَا حَدِيثًا فَبَكَتْ، فَقُلْتُ لَهَا: لِمَ تَبْكِينَ؟ ثُمَّ أَسَرَّ إِلَيْهَا حَدِيثًا فَضَحِكَتْ، فَقُلْتُ: مَا رَأَيْتُ كَالْيَوْمِ فَرَحًا أَقْرَبَ مِنْ حُزْنٍ فَسَأَلْتُهَا عَمَّا، قَالَ: فَقَالَتْ: مَا كُنْتُ لِأُفْشِيَ سِرَّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى قُبِضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلْتُهَا؟ فَقَالَتْ: أَسَرَّ إِلَيَّ إِنَّ جِبْرِيلَ كَانَ يُعَارِضُنِي الْقُرْآنَ كُلَّ سَنَةٍ مَرَّةً وَإِنَّهُ عَارَضَنِي الْعَامَ مَرَّتَيْنِ وَلَا أُرَاهُ إِلَّا حَضَرَ أَجَلِي وَإِنَّكِ أَوَّلُ أَهْلِ بَيْتِي لَحَاقًا بِي فَبَكَيْتُ، فَقَالَ: أَمَا تَرْضَيْنَ أَنْ تَكُونِي سَيِّدَةَ نِسَاءِ أَهْلِ الْجَنَّةِ أَوْ نِسَاءِ الْمُؤْمِنِينَ؟ فَضَحِكْتُ لِذَلِكَ."],"takhrij":"متفق عليه: رواه البخاريّ في علامات النّبوة (3623)، ومسلم في فضائل الصحابة (2450) كلاهما من حديث فراس، عن عامر، عن مسروق، عن عائشة، فذكرتْه.","grade":"متفق عليه","chapter_ar":"باب كان جبريل يدارس القرآن مع النبي ﷺ في كل ليلة من رمضان","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3623) and Muslim (2450).","chapter_en":"Jibrīl Would Review the Qurʾān With the Prophet ﷺ Every Night in Ramaḍān","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported: “Fāṭimah came walking, and her manner of walking resembled that of the Prophet ﷺ. The Prophet ﷺ said: ‘Welcome, my daughter.’ Then he seated her to his right or to his left and spoke privately to her, whereupon she wept. I asked her: ‘Why are you crying?’ Then he spoke privately to her again, and she laughed. I said: ‘I have never seen joy come so close after sadness as I have today.’ I asked her what he had said, but she replied: ‘I would never disclose the secret of the Messenger of Allah ﷺ.’ After the Prophet ﷺ passed away, I asked her again. She said: ‘He confided to me: “Jibrīl used to review the Qurʾān with me once every year, but this year he reviewed it with me twice. I do not think this means anything except that my appointed time has drawn near, and you will be the first of my household to join me.” So I wept. Then he said: “Are you not pleased to be the leader of the women of Paradise — or of the believing women?” So I laughed because of that.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3623)، ومسلم (2450)."},{"num":622,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ (جِبْرِيل) يَعْرِضُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْقُرْآنَ كُلَّ عَامٍ مَرَّةً، فَعَرَضَ عَلَيْهِ مَرَّتَيْنِ فِي الْعَامِ الَّذِي قُبِضَ..."],"takhrij":"صحيح: رواه البخاريّ في فضائل القرآن (4998) عن خالد بن يزيد، حدّثنا أبو بكر، عن أبي حصين، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب كان جبريل يدارس القرآن مع النبي ﷺ في كل ليلة من رمضان","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4998).","chapter_en":"Jibrīl Would Review the Qurʾān With the Prophet ﷺ Every Night in Ramaḍān","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: “Jibrīl used to review the Qurʾān with the Prophet ﷺ once every year, but he reviewed it with him twice during the year in which the Prophet ﷺ passed away.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4998)."},{"num":623,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَقْرَأَنِي جِبْرِيلُ عَلَى حَرْفٍ فَرَاجَعْتُهُ فَلَمْ أَزَلْ أَسْتَزِيدُهُ، وَيَزِيدُنِي حَتَّى انْتَهَى إِلَى سَبْعَةِ أَحْرُفٍ."],"takhrij":"متفق عليه: رواه البخاري في بدء الخلق (3219)، وفي فضائل القرآن bukhari(4991)، ومسلم في صلاة المسافرين (819) كلاهما من حديث ابن شهاب الزّهريّ، قال: حدّثني عبيد الله بن عبدالله بن عتبة، أنّ ابن عباس حدَّثه، فذكر الحديث ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب أن جبريل أقرأ النبي ﷺ القرآن على سبعة أحرف","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4991, 3219) and Muslim (819).","chapter_en":"Jibrīl Taught the Prophet ﷺ to Recite the Qurʾān in Seven Aḥruf","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Jibrīl taught me to recite according to one ḥarf. I continued asking him for more, and he continued increasing it for me until he reached seven aḥruf.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4991، 3219)، ومسلم (819)."},{"num":624,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: سَمِعَ عَبْدُ اللَّهِ بْنُ سَلَامٍ بِقُدُوم رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ فِي أَرْضٍ يَخْتَرِفُ فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنِّي سَائِلُكَ عَنْ ثَلَاثٍ لَا يَعْلَمُهُنَّ إِلَّا نَبِيٌّ فَمَا أَوَّلُ أَشْرَاطِ السَّاعَةِ؟ وَمَا أَوَّلُ طَعَامِ أَهْلِ الْجَنَّةِ؟ وَمَا يَنْزِعُ الْوَلَدُ إِلَى أَبِيهِ أَوْ إِلَى أُمِّهِ؟ قَالَ: أَخْبَرَنِي بِهِنَّ جِبْرِيلُ آنِفًا. قَالَ: جِبْرِيلُ؟ قَالَ: نَعَمْ، قَالَ: ذَاكَ عَدُوُّ الْيَهُودِ مِنَ الْمَلَائِكَةِ، فَقَرَأَ هَذِهِ الْآيَةَ ﴿مَنْ كَانَ عَدُوًّا لِجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلَى قَلْبِكَ﴾ [ سورة البقرة: 97] أَمَّا أَوَّلُ أَشْرَاطِ السَّاعَةِ، فَنَارٌ تَحْشُرُ النَّاسَ مِنَ الْمَشْرِقِ إِلَى الْمَغْرِبِ، وَأَمَّا أَوَّلُ طَعَامٍ يَأْكُلُهُ أَهْلُ الْجَنَّةِ، فَزِيَادَةُ كَبِدِ حُوتٍ، وَإِذَا سَبَقَ مَاءُ الرَّجُلِ مَاءَ الْمَرْأَةِ نَزَعَ الْوَلَدَ، وَإِذَا سَبَقَ مَاءُ الْمَرْأَةِ نَزَعَتْ، قَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ، يَا رَسُولَ اللَّهِ، إِنَّ الْيَهُودَ قَوْمٌ بُهُتٌ، وَإِنَّهُمْ إِنْ يَعْلَمُوا بِإِسْلَامِي قَبْلَ أَنْ تَسْأَلَهُمْ يَبْهَتُونِي، فَجَاءَتْ الْيَهُودُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّ رَجُلٍ عَبْدُ اللَّهِ فِيكُمْ؟ قَالُوا: خَيْرُنَا وَابْنُ خَيْرِنَا، وَسَيِّدُنَا وَابْنُ سَيِّدِنَا، قَالَ: أَرَأَيْتُمْ إِنْ أَسْلَمَ عَبْدُ اللَّهِ بْنُ سَلَامٍ؟ فَقَالُوا: أَعَاذَهُ اللَّهُ مِنْ ذَلِكَ، فَخَرَجَ عَبْدُ اللَّهِ، فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، فَقَالُوا: شَرُّنَا وَابْنُ شَرِّنَا وَانْتَقَصُوهُ، قَالَ: فَهَذَا الَّذِي كُنْتُ أَخَافُ يَا رَسُولَ اللَّهِ."],"takhrij":"صحيح: رواه البخاريّ في التفسير (4480) عن عبدالله بن منير، سمع عبدالله بن بكر، حدّثنا حميد، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب أن جبريل كان يخبر النبي ﷺ الجواب إذا سُئل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4480).","chapter_en":"Jibrīl Would Inform the Prophet ﷺ of the Answer When He Was Asked","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":13,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: ʿAbdullāh ibn Salām heard of the arrival of the Messenger of Allah ﷺ while he was working in his land harvesting. He came to the Prophet ﷺ and said: “I will ask you about three matters that none knows except a prophet: What is the first sign of the Hour? What will be the first food eaten by the people of Paradise? And what causes a child to resemble his father or his mother?” The Prophet ﷺ said: “Jibrīl has just informed me about them.” He asked: “Jibrīl?!” He replied: “Yes.” He said: “He is the enemy of the Jews among the angels.” The Prophet ﷺ then recited: “Whoever is an enemy to Jibrīl — indeed, he has brought it down upon your heart…” [Sūrat al-Baqarah 2:97] He then said: “As for the first sign of the Hour, it will be a fire that gathers the people from the east to the west. As for the first food of the people of Paradise, it will be the extra lobe of a fish’s liver. And when the man’s fluid precedes the woman’s fluid, the child resembles him; and when the woman’s fluid precedes, the child resembles her.” ʿAbdullāh ibn Salām said: “I bear witness that there is no deity worthy of worship except Allah, and I bear witness that you are the Messenger of Allah. O Messenger of Allah, the Jews are a people of false accusation. If they learn of my Islam before you ask them about me, they will slander me.” The Jews then came, and the Prophet ﷺ asked: “What kind of man is ʿAbdullāh among you?” They replied: “Our best man and the son of our best; our leader and the son of our leader.” He asked: “What would you say if ʿAbdullāh ibn Salām accepted Islam?” They replied: “May Allah protect him from that.” Then ʿAbdullāh came out and said: “I bear witness that there is no deity worthy of worship except Allah and that Muḥammad is the Messenger of Allah.” They said: “He is the worst of us and the son of the worst of us,” and began disparaging him. ʿAbdullāh said: “This is what I feared, O Messenger of Allah.” Allah Most High said: “Whoever is an enemy to Jibrīl — indeed, he has brought it down upon your heart by Allah’s permission, confirming what came before it, and as guidance and glad tidings for the believers.” [Sūrat al-Baqarah 2:97]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4480)."},{"num":625,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنُ عَبَّاسٍ: حَضَرَتْ عِصَابَةٌ مِنَ الْيَهُودِ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا فَقَالُوا: يَا أَبَا الْقَاسِمِ، حَدِّثْنَا عَنْ خِلَالٍ نَسْأَلُكَ عَنْهُنَّ لَا يَعْلَمُهُنَّ إِلَّا نَبِيٌّ قَالَ: سَلُونِي عَمَّا شِئْتُمْ، وَلَكِنْ اجْعَلُوا لِي ذِمَّةَ اللَّهِ، وَمَا أَخَذَ يَعْقُوبُ عَلَيْهِ السَّلَام عَلَى بَنِيهِ، لَئِنْ حَدَّثْتُكُمْ شَيْئًا فَعَرَفْتُمُوهُ، لَتُتَابِعُنِّي عَلَى الْإِسْلَامِ، قَالُوا: فَذَلِكَ لَكَ قَالَ: فَسَلُونِي عَمَّا شِئْتُمْ، قَالُوا: أَخْبِرْنَا عَنْ أَرْبَعِ خِلَالٍ نَسْأَلُكَ عَنْهُنَّ: أَخْبِرْنَا أَيُّ الطَّعَامِ حَرَّمَ إِسْرَائِيلُ عَلَى نَفْسِهِ مِنْ قَبْلِ أَنْ تُنَزَّلَ التَّوْرَاةُ؟ وَأَخْبِرْنَا كَيْفَ مَاءُ الْمَرْأَةِ، وَمَاءُ الرَّجُلِ؟ كَيْفَ يَكُونُ الذَّكَرُ مِنْهُ؟ وَأَخْبِرْنَا كَيْفَ هَذَا النَّبِيُّ الْأُمِّيُّ فِي النَّوْمِ؟ وَمَنْ وَلِيُّهُ مِنَ الْمَلَائِكَةِ؟ قَالَ: فَعَلَيْكُمْ عَهْدُ اللَّهِ وَمِيثَاقُهُ لَئِنْ أَنَا أَخْبَرْتُكُمْ لَتُتَابِعُنِّي؟ قَالَ: فَأَعْطَوْهُ مَا شَاءَ مِنْ عَهْدٍ وَمِيثَاقٍ قَالَ: فَأَنْشُدُكُمْ بِالَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى عَلَيْهِ السلاَّمَ، هَلْ تَعْلَمُونَ أَنَّ إِسْرَائِيلَ يَعْقُوبَ عَلَيْهِ السَّلَام، مَرِضَ مَرَضًا شَدِيدًا، وَطَالَ سَقَمُهُ، فَنَذَرَ لِلَّهِ نَذْرًا لَئِنْ شَفَاهُ اللَّهُ تَعَالَى مِنْ سَقَمِهِ، لَيُحَرِّمَنَّ أَحَبَّ الشَّرَابِ إِلَيْهِ، وَأَحَبَّ الطَّعَامِ إِلَيْهِ، وَكَانَ أَحَبَّ الطَّعَامِ إِلَيْهِ لُحْمَانُ الْإِبِلِ، وَأَحَبَّ الشَّرَابِ إِلَيْهِ أَلْبَانُهَا؟ قَالُوا: اللَّهُمَّ نَعَمْ، قَالَ: اللَّهُمَّ اشْهَدْ عَلَيْهِمْ، فَأَنْشُدُكُمْ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، الَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى، هَلْ تَعْلَمُونَ أَنَّ مَاءَ الرَّجُلِ أَبْيَضُ غَلِيظٌ، وَأَنَّ مَاءَ الْمَرْأَةِ أَصْفَرُ رَقِيقٌ، فَأَيُّهُمَا عَلَا كَانَ لَهُ الْوَلَدُ وَالشَّبَهُ بِإِذْنِ اللَّهِ، إِنْ عَلَا مَاءُ الرَّجُلِ عَلَى مَاءِ الْمَرْأَةِ كَانَ ذَكَرًا بِإِذْنِ اللَّهِ، وَإِنْ عَلَا مَاءُ الْمَرْأَةِ عَلَى مَاءِ الرَّجُلِ كَانَ أُنْثَى بِإِذْنِ اللَّهِ؟ قَالُوا: اللَّهُمَّ نَعَمْ، قَالَ: اللَّهُمَّ اشْهَدْ عَلَيْهِمْ، فَأَنْشُدُكُمْ بِالَّذِي أَنْزَلَ التَّوْرَاةَ عَلَى مُوسَى، هَلْ تَعْلَمُونَ أَنَّ هَذَا النَّبِيَّ الْأُمِّيَّ تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ؟ قَالُوا: اللَّهُمَّ نَعَمْ، قَالَ: اللَّهُمَّ اشْهَدْ، قَالُوا: وَأَنْتَ الْآنَ فَحَدِّثْنَا، مَنْ وَلِيُّكَ مِنَ الْمَلَائِكَةِ؟ فَعِنْدَهَا نُجَامِعُكَ أَوْ نُفَارِقُكَ، قَالَ: فَإِنَّ وَلِيِّيَ جِبْرِيلُ عَلَيْهِ السَّلَام، وَلَمْ يَبْعَثْ اللَّهُ نَبِيًّا قَطُّ إِلَّا وَهُوَ وَلِيُّهُ، قَالُوا: فَعِنْدَهَا نُفَارِقُكَ، لَوْ كَانَ وَلِيُّكَ سِوَاهُ مِنَ الْمَلَائِكَةِ لَتَابَعْنَاكَ وَصَدَّقْنَاكَ، قَالَ: فَمَا يَمْنَعُكُمْ مِنْ أَنْ تُصَدِّقُوهُ ؟، قَالُوا: إِنَّهُ عَدُوُّنَا، قَالَ: فَعِنْدَ ذَلِكَ قَالَ اللَّهُ عَزَّ وَجَلَّ: ﴿قُلْ مَنْ كَانَ عَدُوًّا لِجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلَى قَلْبِكَ﴾ إِلَى قَوْلِهِ: ﴿....كِتَابَ اللَّهِ وَرَاءَ ظُهُورِهِمْ كَأَنَّهُمْ لَا يَعْلَمُونَ﴾ [البقرة: 97، 101]، فَعِنْدَ ذَلِكَ ﴿فَبَاءُوا بِغَضَبٍ عَلَى غَضَبٍ﴾ [البقرة: 90]."],"takhrij":"حسن: رواه الإمام أحمد (2514) عن هاشم بن القاسم، حدّثنا عبدالحميد، حدّثنا شهر، قال ابن عباس: فذكر مثله.","grade":"حسن","chapter_ar":"باب أن جبريل كان ولياً للنبي ﷺ وولي جميع الأنبياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (2514).","chapter_en":"Jibrīl Was an Ally and Supporter of the Prophet ﷺ and of All the Prophets","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās, may Allah be pleased with them, reported: A group of Jews came to the Prophet of Allah ﷺ one day and said: “O Abū al-Qāsim, tell us about certain matters we will ask you about, which none knows except a prophet.” He said: “Ask me whatever you wish, but give me the covenant of Allah and the covenant that Jacob peace be upon him took from his sons: if I tell you something and you recognize it as true, you will follow me in Islam.” They replied: “You have that.” He said: “Then ask me whatever you wish.” They said: “Tell us about four matters: Why did Israel forbid a certain food to himself before the Torah was revealed? Tell us about the fluid of the woman and the fluid of the man, and how a male child results from them. Tell us about this unlettered Prophet during sleep. And who is his ally among the angels?” He said: “Then the covenant and pledge of Allah are binding upon you that if I inform you, you will follow me.” They gave him whatever pledge and covenant he requested. He then said: “I ask you by the One who sent down the Torah to Moses, peace be upon him: do you know that Israel — Jacob peace be upon him — became severely ill and remained ill for a long time, so he vowed to Allah that if Allah Most High cured him, he would forbid himself the drink and food he loved most? The food he loved most was camel meat, and the drink he loved most was camel milk.” They replied: “By Allah, yes.” He said: “O Allah, bear witness against them. I ask you by Allah, besides whom there is no deity, who sent down the Torah to Moses: do you know that the man’s fluid is white and thick, while the woman’s fluid is yellow and thin; whichever one predominates, the child and resemblance follow accordingly by Allah’s permission? If the man’s fluid predominates over the woman’s, the child is male by Allah’s permission; and if the woman’s fluid predominates over the man’s, the child is female by Allah’s permission?” They replied: “By Allah, yes.” He said: “O Allah, bear witness against them. I ask you by the One who sent down the Torah to Moses: do you know that this unlettered Prophet’s eyes sleep while his heart does not sleep?” They replied: “By Allah, yes.” He said: “O Allah, bear witness.” They then said: “Now tell us who your ally among the angels is. On that basis we will either join you or part from you.” He replied: “My ally is Jibrīl, peace be upon him. Allah has never sent a prophet except that Jibrīl was his ally.” They said: “Then we part from you. Had your ally been another angel, we would have followed you and believed you.” He asked: “What prevents you from believing him?” They replied: “He is our enemy.” At that point Allah, Mighty and Majestic, revealed: “Say: Whoever is an enemy to Jibrīl — indeed, he has brought it down upon your heart by Allah’s permission…” through His statement: “A group of those who were given the Scripture threw the Book of Allah behind their backs as though they did not know.” [Sūrat al-Baqarah 2:97–101] And: “So they returned with wrath upon wrath.” [Sūrat al-Baqarah 2:90] “Say: Whoever is an enemy to Jibrīl — indeed, he has brought it down upon your heart by Allah’s permission, confirming what came before it, and as guidance and glad tidings for the believers.” [Sūrat al-Baqarah 2:97] “Whoever is an enemy to Allah, His angels, His messengers, Jibrīl, and Mīkāl — then indeed Allah is an enemy to the disbelievers.” [Sūrat al-Baqarah 2:98] “We have certainly sent down to you clear signs, and none rejects them except the defiantly disobedient.” [Sūrat al-Baqarah 2:99] “Is it not that whenever they make a covenant, a group of them casts it aside? Rather, most of them do not believe.” [Sūrat al-Baqarah 2:100] “And when a messenger from Allah came to them confirming what was with them, a group of those who were given the Scripture threw the Book of Allah behind their backs as though they did not know.” [Sūrat al-Baqarah 2:101] “So they returned with wrath upon wrath, and for the disbelievers is a humiliating punishment.” [Sūrat al-Baqarah 2:90]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (2514)."},{"num":626,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: كَانَ إِذَا اشْتَكَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَقَاهُ جِبْرِيلُ قَالَ: بِاسْمِ اللَّهِ يُبْرِيكَ وَمِنْ كُلِّ دَاءٍ يَشْفِيكَ وَمِنْ شَرِّ حَاسِدٍ إِذَا حَسَدَ وَشَرِّ كُلِّ ذِي عَيْنٍ."],"takhrij":"صحيح: رواه مسلم في السلام (2185) عن محمد بن أبي عمر المكيّ، حدّثنا عبدالعزيز الدّراورديّ، عن يزيد (وهو ابن عبدالله بن أسامة بن الهاد)، عن محمد ابن إبراهيم، عن أبي سلمة بن عبدالرحمن، عن عائشة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب إذا كان النبي ﷺ يشتكي فينزل جبريل ويرقيه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2185).","chapter_en":"When the Prophet ﷺ Became Ill, Jibrīl Would Descend and Perform Ruqyah for Him","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported: “When the Messenger of Allah ﷺ became ill, Jibrīl would perform ruqyah for him, saying: ‘In the Name of Allah, may He cure you; from every illness may He heal you; from the evil of an envier when he envies, and from the evil of every possessor of an evil eye.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2185)."},{"num":627,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ أَنَّ جِبْرِيلَ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا مُحَمَّدُ، اشْتَكَيْتَ؟ فَقَالَ: نَعَمْ، قَالَ: بِاسْمِ اللَّهِ أَرْقِيكَ، مِنْ كُلِّ شَيْءٍ يُؤْذِيكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنِ حَاسِدٍ، اللَّهُ يَشْفِيكَ بِاسْمِ اللَّهِ أَرْقِيكَ."],"takhrij":"صحيح: رواه مسلم في السّلام (2186) عن بشر بن هلال الصّواف، حدّثنا عبدالوارث، حدّثنا عبدالعزيز بن صُهيب، عن أبي نَضْرة، عن أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب إذا كان النبي ﷺ يشتكي فينزل جبريل ويرقيه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2186).","chapter_en":"When the Prophet ﷺ Became Ill, Jibrīl Would Descend and Perform Ruqyah for Him","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":15,"content":{"translation":{"en":["Abū Saʿīd, may Allah be pleased with him, reported: Jibrīl came to the Prophet ﷺ and asked: “O Muḥammad, are you ill?” He replied: “Yes.” Jibrīl said: “In the Name of Allah I perform ruqyah for you, from everything that harms you, from the evil of every soul or the eye of an envier. May Allah heal you. In the Name of Allah I perform ruqyah for you.”"]}},"tuhfa":{},"full":1,"rep":[3471,11480,13824],"tks":"صحيح: رواه مسلم (2186)."},{"num":628,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: أَتَى جِبْرِيلُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ هَذِهِ خَدِيجَةُ قَدْ أَتَتْ مَعَهَا إِنَاءٌ فِيهِ إِدَامٌ أَوْ طَعَامٌ أَوْ شَرَابٌ، فَإِذَا هِيَ أَتَتْكَ فَاقْرَأْ عَلَيْهَا السَّلَامَ مِنْ رَبِّهَا وَمِنِّي، وَبَشِّرْهَا بِبَيْتٍ فِي الْجَنَّةِ مِنْ قَصَبٍ لَا صَخَبَ فِيهِ وَلَا نَصَبَ."],"takhrij":"متفق عليه: رواه البخاريّ في المناقب (3820)، ومسلم في فضائل الصّحابة (2432) كلاهما من حديث محمد بن فُضيل، عن عمارة، عن أبي زرعة، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سلام جبريل على بعض أزواج النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3820) and Muslim (2432).","chapter_en":"What Has Been Reported Concerning Jibrīl Greeting Some of the Wives of the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: Jibrīl came to the Prophet ﷺ and said: “O Messenger of Allah, Khadījah is coming to you carrying a vessel containing stew, food, or drink. When she comes to you, convey to her greetings of peace from her Lord and from me, and give her glad tidings of a house in Paradise made of hollowed pearl, in which there will be neither noise nor fatigue.”"]}},"tuhfa":{},"full":1,"rep":[10371,12608],"tks":"متفق عليه: رواه البخاري (3820)، ومسلم (2432)."},{"num":629,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهَا: يَا عَائِشَةُ هَذَا جِبْرِيلُ يَقْرَأُ عَلَيْكِ السَّلَامَ، فَقَالَتْ: وَعَلَيْهِ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ تَرَى مَا لَا أَرَى تُرِيدُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3217)، ومسلم في الفضائل (2447) كلاهما من طريق الزّهريّ، عن أبي سلمة بن عبدالرحمن، عن عائشة، فذكرته، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في سلام جبريل على بعض أزواج النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3217) and Muslim (2447), with the wording of al-Bukhārī.","chapter_en":"What Has Been Reported Concerning Jibrīl Greeting Some of the Wives of the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":16,"content":{"translation":{"en":["ʿĀʾishah, the wife of the Prophet ﷺ, reported that the Prophet ﷺ said to her: “O ʿĀʾishah, this is Jibrīl conveying salām to you.” She replied: “And upon him be peace, the mercy of Allah, and His blessings. You see what I do not see.” She meant the Prophet ﷺ."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3217)، ومسلم (2447)، واللفظ للبخاري."},{"num":630,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ أُحُدٍ وَمَعَهُ رَجُلَانِ يُقَاتِلَانِ عَنْهُ، عَلَيْهِمَا ثِيَابٌ بِيضٌ كَأَشَدِّ الْقِتَالِ، مَا رَأَيْتُهُمَا قَبْلُ وَلَا بَعْدُ.","وَفِي رِوَايَةِ: رَأَيْتُ عَنْ يَمِينِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَنْ شِمَالِهِ يَوْمَ أُحُدٍ، رَجُلَيْنِ عَلَيْهِمَا ثِيَابُ بَيَاضٍ، مَا رَأَيْتُهُمَا قَبْلُ وَلَا بَعْدُ يَعْنِي جِبْرِيلَ، وَمِيكَائِيلَ عَلَيْهِمَا السَّلَام."],"takhrij":"متفق عليه: رواه البخاريّ في المغازي (4054)، ومسلم في الفضائل (2306) كلاهما من حديث إبراهيم بن سعد، عن أبيه (سعد)، عن جدّه (إبراهيم ابن عبدالرحمن بن عوف)، عن سعد بن أبي وقاص، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في قتال جبريل وميكائيل عن النبي ﷺ يوم أحد","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4054) and Muslim (2306).","chapter_en":"What Has Been Reported Concerning Jibrīl and Mīkāʾīl Fighting in Defense of the Prophet ﷺ on the Day of Uḥud","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":17,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ, may Allah be pleased with him, reported: “On the Day of Uḥud, I saw the Messenger of Allah ﷺ with two men fighting fiercely in his defense. They were wearing white garments. I had never seen them before, nor did I see them afterward.”","In another narration: “On the Day of Uḥud, I saw two men to the right and left of the Messenger of Allah ﷺ wearing white garments. I had never seen them before nor afterward.” He meant Jibrīl and Mīkāʾīl peace be upon them."]},"buhuth":{"en":["The second narration is also found in al-Bukhārī (5826) and Muslim (2306)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4054)، ومسلم (2306)."},{"num":631,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: لَمَّا رَجَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ الْخَنْدَقِ وَوَضَعَ السِّلَاحَ وَاغْتَسَلَ، أَتَاهُ جِبْرِيلُ عَلَيْهِ السَّلَام فَقَالَ: قَدْ وَضَعْتَ السِّلَاحَ؟ وَاللَّهِ مَا وَضَعْنَاهُ، فَاخْرُجْ إِلَيْهِمْ، قَالَ: فَإِلَى أَيْنَ؟ قَالَ: هَا هُنَا، وَأَشَارَ إِلَى بَنِي قُرَيْظَةَ فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِمْ."],"takhrij":"صحيح: رواه البخاريّ في المغازي (4117) عن عبدالله بن أبي شيبة، حدّثنا ابن نمير، عن هشام، عن أبيه، عن عائشة، فذكرت مثله.","grade":"صحيح","chapter_ar":"باب في حمل جبريل عليه السلام السلاح","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (2813, 4117).","chapter_en":"Jibrīl peace be upon him Carrying Weapons","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":18,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported: “When the Prophet ﷺ returned from the Trench, laid down his weapons, and bathed, Jibrīl, peace be upon him, came to him and said: ‘Have you laid down your weapons? By Allah, we have not laid ours down. Go out against them.’ He asked: ‘Where?’ Jibrīl replied: ‘There,’ and pointed toward Banū Qurayẓah. So the Prophet ﷺ went out against them.”"]},"buhuth":{"en":["In it is the wording:","“Jibrīl came to him with dust covering his head.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[513,8936],"tks":"صحيح: رواه البخاري (2813، 4117)."},{"num":632,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: كَأَنِّي أَنْظُرُ إِلَى الْغُبَارِ سَاطِعًا فِي زُقَاقِ بَنِي غَنْمٍ مَوْكِبَ جِبْرِيلَ حِينَ سَارَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى بَنِي قُرَيْظَةَ."],"takhrij":"صحيح: رواه البخاريّ في المغازي (4118) عن موسى، حدّثنا جرير بن حازم، عن حُميد بن هلال، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في موكب جبريل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4118).","chapter_en":"What Has Been Reported Concerning the Procession of Jibrīl","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":19,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: “It is as though I can still see the dust rising in the alleyway of Banū Ghanm — the procession of Jibrīl — when the Messenger of Allah ﷺ set out toward Banū Qurayẓah.”"]},"buhuth":{"en":["The expression:","“The procession of Jibrīl”","refers to a manner of traveling, a group of horsemen, or a group of riders moving together in an orderly manner."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8937],"tks":"صحيح: رواه البخاري (4118)."},{"num":633,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّيْتُ مَعَهُ الْمَغْرِبَ فَصَلَّى حَتَّى صَلَّى الْعِشَاءَ ثُمَّ انْفَتَلَ فَتَبِعْتُهُ فَسَمِعَ صَوْتِي فَقَالَ: مَنْ هَذَا؟ حُذَيْفَةُ؟ قُلْتُ: نَعَمْ، قَالَ: مَا حَاجَتُكَ غَفَرَ اللَّهُ لَكَ وَلِأُمِّكَ؟ قَالَ: إِنَّ هَذَا مَلَكٌ لَمْ يَنْزِلِ الْأَرْضَ قَطُّ قَبْلَ هَذِهِ اللَّيْلَةِ اسْتَأْذَنَ رَبَّهُ أَنْ يُسَلِّمَ عَلَيَّ وَيُبَشِّرَنِي بِأَنَّ فَاطِمَةَ سَيِّدَةُ نِسَاءِ أَهْلِ الْجَنَّةِ، وَأَنَّ الْحَسَنَ وَالْحُسَيْنَ سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ."],"takhrij":"حسن: رواه الترمذيّ (3781) عن عبدالله بن عبدالرحمن، وإسحاق بن منصور، قالا: أخبرنا محمد بن يوسف، عن إسرائيل، عن ميسرة بن حبيب، عن المنهال بن عمرو، عن زرّ بن حبيش، عن حذيفة في حديث أطول منه، وسيأتي في أبواب النوافل.","grade":"حسن","chapter_ar":"باب بشارة جبريل بأن الحسن والحسين سيدا شباب أهل الجنة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (3781), who graded it Ḥasan; Ibn Ḥibbān (6960); and al-Ḥākim (3/381).","chapter_en":"Jibrīl’s Glad Tidings That al-Ḥasan and al-Ḥusayn Are the Leaders of the Youth of Paradise","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":20,"content":{"translation":{"en":["Ḥudhayfah, may Allah be pleased with him, reported: “I came to the Prophet ﷺ and prayed Maghrib with him. He continued praying until he prayed ʿIshāʾ, then he departed and I followed him. He heard a sound and said: ‘Who is this? Ḥudhayfah?’ I replied: ‘Yes.’ He said: ‘What do you need? May Allah forgive you and your mother.’ Then he said: ‘This is an angel who had never descended to the earth before this night. He sought permission from his Lord to greet me with salām and give me the glad tidings that Fāṭimah is the leader of the women of Paradise, and that al-Ḥasan and al-Ḥusayn are the leaders of the youth of Paradise.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3781) وحسنه، وابن حبان (6960)، والحاكم (3/381)."},{"num":634,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: أَتَانِي جِبْرِيلُ، فَبَشَّرَنِي أَنَّهُ مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ، قُلْتُ: وَإِنْ سَرَقَ، وَإِنْ زَنَى؟ قَالَ: وَإِنْ سَرَقَ وَإِنْ زَنَى."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7487)، ومسلم في الإيمان (94) كلاهما عن محمد بن بشار، حدثنا محمد بن جعفر غندر، حدثنا شعبة، عن واصل الأحدب، عن المعرور بن سُويد قال: سمعتُ أبا ذر فذكره.","grade":"متفق عليه","chapter_ar":"باب تبشير جبريل بأن من مات ولم يشرك بالله شيئاً دخل الجنة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7487) and Muslim (94).","chapter_en":"Jibrīl’s Glad Tidings That Whoever Dies Without Associating Anything With Allah Will Enter Paradise","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":21,"content":{"translation":{"en":["Abū Dharr may Allah be pleased with him reported that the Prophet ﷺ said: “Jibrīl came to me and gave me the glad tidings that whoever dies without associating anything with Allah will enter Paradise.” I asked: “Even if he steals and even if he commits adultery?” He replied: “Even if he steals and even if he commits adultery.”"]}},"tuhfa":{},"full":1,"rep":[85],"tks":"متفق عليه: رواه البخاري (7487)، ومسلم (94)."},{"num":635,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ، عَنْ أَبِيهِ وَكَانَ أَبُوهُ مِنْ أَهْلِ بَدْرٍ قَالَ: جَاءَ جِبْرِيلُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ مَا تَعُدُّونَ أَهْلَ بَدْرٍ فِيكُمْ؟ قَالَ: مِنْ أَفْضَلِ الْمُسْلِمِينَ أَوْ كَلِمَةً نَحْوَهَا قَالَ: وَكَذَلِكَ مَنْ شَهِدَ بَدْرًا مِنْ الْمَلَائِكَةِ."],"takhrij":"صحيح: رواه البخاريّ في المغازي (3992) عن إسحاق بن إبراهيم، أخبرنا جرير، عن يحيى بن سعيد، عن معاذ بن رفاعة بن رافع، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب شهود جبريل والملائكة بدراً","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3992).","chapter_en":"Jibrīl and the Angels Witnessing Badr","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["Muʿādh ibn Rifāʿah ibn Rāfiʿ al-Zuraqī reported from his father — who was among those who participated at Badr — that: Jibrīl came to the Prophet ﷺ and asked: “How do you regard those among you who participated at Badr?” He replied: “Among the best of the Muslims,” or words to that effect. Jibrīl said: “And likewise are those among the angels who witnessed Badr.”"]}},"tuhfa":{},"full":1,"rep":[10063],"tks":"صحيح: رواه البخاري (3992)."},{"num":636,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يَوْمَ بَدْرٍ: هَذَا جِبْرِيلُ آخِذٌ بِرَأْسِ فَرَسِهِ عَلَيْهِ أَدَاةُ الْحَرْبِ."],"takhrij":"صحيح: رواه البخاريّ في المغازي (3995) عن إبراهيم بن موسى، أخبرنا عبدالوهّاب، حدّثنا خالد، عن عكرمة، عن ابن عباس، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب شهود جبريل والملائكة بدراً","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3995).","chapter_en":"Jibrīl and the Angels Witnessing Badr","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":22,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Prophet ﷺ said on the Day of Badr: “This is Jibrīl, holding the head of his horse, wearing the equipment of war.”"]}},"tuhfa":{},"full":1,"rep":[8753,12358],"tks":"صحيح: رواه البخاري (3995)."},{"num":637,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: غَزَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْمًا مِنْ جُهَيْنَةَ، فَقَاتَلُونَا قِتَالًا شَدِيدًا، فَلَمَّا صَلَّيْنَا الظُّهْرَ، قَالَ الْمُشْرِكُونَ: لَوْ مِلْنَا عَلَيْهِمْ مَيْلَةً لَاقْتَطَعْنَاهُمْ، فَأَخْبَرَ جِبْرِيلُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَلِكَ. فذكر الحديث."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (840: 308) عن أحمد بن عبدالله بن يونس، حدّثنا زهير، حدّثنا أبو الزّبير، عن جابر، فذكره، وسيأتي بكامله في صلاة الخوف.","grade":"صحيح","chapter_ar":"باب إخبار جبريل النبي ﷺ بمؤامرة المشركين في غزوة قوم من جهينة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (840:308).","chapter_en":"Jibrīl Informing the Prophet ﷺ of the Polytheists’ Plot During the Expedition Against a People From Juhaynah","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":23,"content":{"translation":{"en":["Jābir, may Allah be pleased with him, reported: “We went on an expedition with the Messenger of Allah ﷺ against a people from Juhaynah, and they fought us fiercely. After we prayed Ẓuhr, the polytheists said: ‘If we launched one sudden attack against them, we could cut them off.’ Jibrīl informed the Messenger of Allah ﷺ of this.” The ḥadīth continues."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (840: 308)."},{"num":638,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَلَا قَوْلَ اللَّهِ عَزَّ وَجَلَّ فِي إِبْرَاهِيمَ: ﴿رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي﴾ [إبراهيم: 36]، فَرَفَعَ يَدَيْهِ، وَقَالَ: اللَّهُمَّ أُمَّتِي أُمَّتِي، وَبَكَى، فَقَالَ اللَّهُ عَزَّ وَجَلَّ: يَا جِبْرِيلُ، اذْهَبْ إِلَى مُحَمَّدٍ وَرَبُّكَ أَعْلَمُ، فَسَلْهُ مَا يُبْكِيكَ؟ فَأَتَاهُ جِبْرِيلُ عَلَيْهِ السَّلَامُ فَسَأَلَهُ، فَأَخْبَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَا قَالَ، وَهُوَ أَعْلَمُ، فَقَالَ اللَّهُ: يَا جِبْرِيلُ، اذْهَبْ إِلَى مُحَمَّدٍ فَقُلْ: إِنَّا سَنُرْضِيكَ فِي أُمَّتِكَ وَلَا نَسُوؤُكَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (202) عن يونس بن عبدالأعلى الصدفي، أخبرنا ابنُ وهب، قال: أخبرني عمرو بن الحارث، أنّ بكر بن سوادة حدَّثه عن عبدالرحمن بن جبير، عن عبدالله بن عمرو بن العاص، فذكره.","grade":"صحيح","chapter_ar":"باب إرسال الله جبريل إلى النبي ﷺ للسؤال عن بكائه","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (202).","chapter_en":"Allah Sending Jibrīl to the Prophet ﷺ to Ask About His Weeping","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":24,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ, may Allah be pleased with them, reported: The Prophet ﷺ recited the statement of Allah, Mighty and Majestic: “My Lord, indeed they have led many people astray. So whoever follows me is of me…” [Sūrat Ibrāhīm 14:36] Then he raised his hands and said: “O Allah, my Ummah! My Ummah!” and he wept. Allah, Mighty and Majestic, said: “O Jibrīl, go to Muḥammad — and your Lord knows best — and ask him what makes him weep.” Jibrīl, peace be upon him, came to him and asked him, and the Messenger of Allah ﷺ told him what he had said — although Allah already knew. Then Allah said: “O Jibrīl, go to Muḥammad and say: ‘Indeed, We will please you concerning your Ummah and will not cause you grief.’”"]},"intro":{"ar":["قال الله تعالى:","﴿رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي وَمَنْ عَصَانِي فَإِنَّكَ غَفُورٌ رَحِيمٌ﴾","[إبراهيم: ٣٦]"],"en":["“My Lord, indeed they have led many people astray. So whoever follows me is truly of me; and whoever disobeys me — then indeed You are Most Forgiving, Most Merciful.”","[Sūrat Ibrāhīm 14:36]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (202)."},{"num":639,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ (فَذَكَرَهُ فِي سِيَاقِ طَوِيلٍ) فِي قَوْلِهِ تَعَالَى: ﴿فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ﴾ [القيامة: 18] قَالَ: فَاسْتَمِعْ وَأَنْصِتْ، ثُمَّ إِنَّ عَلَيْنَا أَنْ تَقْرَأَهُ، قَالَ: فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَاهُ جِبْرِيلُ اسْتَمَعَ، فَإِذَا انْطَلَقَ جِبْرِيلُ قَرَأَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا أَقْرَأَهُ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الوحي (5)، ومسلم في الصّلاة (448) كلاهما من حديث أبي عوانة، عن موسى بن أبي عائشة، عن سعيد بن جبير، عن ابن عباس، فذكره في سياق أطول منه.","grade":"متفق عليه","chapter_ar":"باب أمر النبي ﷺ لاستماع قراءة جبريل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5) and Muslim (448).","chapter_en":"The Prophet ﷺ Being Commanded to Listen to Jibrīl’s Recitation","part_en":"The Book of Faith","group_ar":"جموع الإيمان بخلق جبريل وصفته وما وُكِّل به","group_en":"Collection of Chapters Concerning Belief in the Creation of Jibrīl, His Description, and What He Was Entrusted With","part_no":2,"group_no":5,"chapter_no":25,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them said concerning the statement of Allah Most High: “So when We have recited it, then follow its recitation.” [Sūrat al-Qiyāmah 75:18] That is: “Listen attentively and remain silent; then it is upon Us to enable you to recite it.” He said: When Jibrīl came to the Messenger of Allah ﷺ, he would listen attentively. Then, after Jibrīl departed, the Prophet ﷺ would recite it exactly as Jibrīl had taught him."]},"intro":{"ar":["قال الله تعالى:","﴿فَإِذَا قَرَأْنَاهُ فَاتَّبِعْ قُرْآنَهُ﴾","[القيامة: ١٨]"],"en":["“So when We have recited it, then follow its recitation.”","[Sūrat al-Qiyāmah 75:18]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5)، ومسلم (448)."},{"num":640,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدَبٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى صَلَاةً أَقْبَلَ عَلَيْنَا بِوَجْهِهِ، فَقَالَ: مَنْ رَأَى مِنْكُمُ اللَّيْلَةَ رُؤْيَا؟ قَالَ: فَإِنْ رَأَى أَحَدٌ قَصَّهَا، فَيَقُولُ: مَا شَاءَ اللَّهُ، فَسَأَلَنَا يَوْمًا، فَقَالَ: هَلْ رَأَى أَحَدٌ مِنْكُمْ رُؤْيَا؟ قُلْنَا: لَا، قَالَ: لَكِنِّي رَأَيْتُ اللَّيْلَةَ رَجُلَيْنِ أَتَيَانِي، فَأَخَذَا بِيَدِي فَأَخْرَجَانِي إِلَى الْأَرْضِ الْمُقَدَّسَةِ. فَذَكَرَ الْحَدِيثَ طَوِيلاً.","وَفِيهِ لَفْظُ: الَّذِي يُوقِدُ النَّارَ مَالِكٌ خَازِنُ النَّارِ، وَأَنَا جِبْرِيلُ، وَهَذَا مِيكَائِيلُ."],"takhrij":"صحيح: رواه البخاريّ في الجنائز (1386)، وفي بدء الخلق (3236) مختصراً عن موسى بن إسماعيل، حدّثنا جرير بن حازم، حدّثنا أبو رجاء، عن سمرة بن جندب، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ذكر ميكائيل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3236, 1386).","chapter_en":"What Has Been Reported Concerning Mīkāʾīl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Samurah ibn Jundub, may Allah be pleased with him, reported: Whenever the Prophet ﷺ finished a prayer, he would turn his face toward us and ask: “Who among you saw a dream last night?” If someone had seen a dream, he would relate it, and the Prophet ﷺ would say: “Whatever Allah wills.” One day he asked us: “Did any of you see a dream?” We replied: “No.” He said: “But last night I saw two men come to me. They took me by the hand and brought me to the Holy Land.” He then mentioned the lengthy ḥadīth. Among it is:","“The one who kindles the Fire is Mālik, the keeper of the Fire. I am Jibrīl, and this is Mīkāʾīl.”"]},"intro":{"ar":["قال الله تعالى:","﴿مَنْ كَانَ عَدُوًّا لِلَّهِ وَمَلَائِكَتِهِ وَرُسُلِهِ وَجِبْرِيلَ وَمِيكَالَ فَإِنَّ اللهَ عَدُوٌّ لِلْكَافِرِينَ﴾","[البقرة: ٩٨]"],"en":["“Whoever is an enemy to Allah, His angels, His messengers, Jibrīl, and Mīkāl — then indeed Allah is an enemy to the disbelievers.”","[Sūrat al-Baqarah 2:98]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3236، 1386)."},{"num":641,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ سَأَلَ جِبْرِيلُ: مَا لِي لَا أَرَى مِيكَائِيلَ يَضْحَكُ؟ قَالَ جِبْرِيلُ: مَا ضَحِكَ مِيكَائِيلُ مُنْذُ خُلِقَتِ النَّارُ."],"takhrij":"حسن: رواه ابنُ أبي الدنيا في الرقّة والبكاء (408)، وعبد الغني المقدسي في ذكر النار (107) كلاهما من طريق عبد الله بن وهب المصري، حدثنا يحيى بن أيوب وابنُ لهيعة، عن عمارة بن غزيّة، عن حميد الطويل قال: سمعتُ أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذكر ميكائيل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Abī al-Dunyā in al-Riqqah wa al-Bukāʾ (408) and ʿAbd al-Ghanī al-Maqdisī in Dhikr al-Nār (107).","chapter_en":"What Has Been Reported Concerning Mīkāʾīl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Prophet ﷺ asked Jibrīl: “Why do I not see Mīkāʾīl laughing?” Jibrīl replied: “Mīkāʾīl has not laughed since the Fire was created.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي الدنيا في الرقة والبكاء (408)، وعبد الغني المقدسي في ذكر النار (107)."},{"num":642,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ قَالَ: سَأَلْتُ عَائِشَةَ أُمَّ الْمُؤْمِنِينَ، بِأَيِّ شَيْءٍ كَانَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْتَتِحُ صَلَاتَهُ، إِذَا قَامَ مِنَ اللَّيْلِ؟ قَالَتْ: كَانَ إِذَا قَامَ مِنَ اللَّيْلِ افْتَتَحَ صَلَاتَهُ اللَّهُمَّ رَبَّ جَبْرَائِيلَ، وَمِيكَائِيلَ، وَإِسْرَافِيلَ، فَاطِرَ السَّمَاوَاتِ وَالأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ، اهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ، إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (770) من طرق عن عمر بن يونس، حدّثنا عكرمة بن عمّار، حدّثنا يحيى بن أبي كثير، حدّثني أبو سلمة بن عبدالرحمن بن عوف، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في ذكر إسرافيل وما كُلِّف به","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (770).","chapter_en":"What Has Been Reported Concerning Isrāfīl and What He Was Entrusted With","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Abū Salamah ibn ʿAbd al-Raḥmān ibn ʿAwf reported: I asked ʿĀʾishah, the Mother of the Believers may Allah be pleased with her: “With what did the Prophet of Allah ﷺ begin his prayer when he stood for prayer at night?” She replied: When he stood for prayer at night, he would begin his prayer by saying: “O Allah, Lord of Jibrīl, Mīkāʾīl, and Isrāfīl; Originator of the heavens and the earth; Knower of the unseen and the witnessed; You judge between Your servants concerning that over which they used to differ. Guide me, by Your permission, to the truth concerning that over which there is disagreement. Indeed, You guide whomever You will to a straight path.”"]}},"tuhfa":{},"full":1,"rep":[8208],"tks":"صحيح: رواه مسلم (770)."},{"num":643,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: جَلَسَ جِبْرِيلُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَظَرَ إِلَى السَّمَاءِ، فَإِذَا مَلَكٌ يَنْزِلُ، فَقَالَ جِبْرِيلُ: إِنَّ هَذَا الْمَلَكَ مَا نَزَلَ مُنْذُ يَوْمِ خُلِقَ قَبْلَ السَّاعَةِ، فَلَمَّا نَزَلَ، قَالَ: يَا مُحَمَّدُ! أَرْسَلَنِي إِلَيْكَ رَبُّكَ، قَالَ: أَفَمَلِكًا نَبِيًّا يَجْعَلُكَ، أَوْ عَبْدًا رَسُولًا؟ قَالَ جِبْرِيلُ: تَوَاضَعْ لِرَبِّكَ يَا مُحَمَّدُ، قَالَ: بَلْ عَبْدًا رَسُولًا."],"takhrij":"صحيح: رواه الإمام أحمد (7160)، والبزّار- كشف الأستار (2462)، وأبو يعلى (6105) كلّهم عن محمد بن فضيل، عن عمارة بن أبي زرعة، قال: لا أعلمه إلاّ عن أبي هريرة، قال (فذكر الحديث).","grade":"صحيح","chapter_ar":"باب ما جاء في ذكر إسرافيل وما كُلِّف به","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (7160), al-Bazzār in Kashf al-Astār (2462), and Abū Yaʿlā (6105).","chapter_en":"What Has Been Reported Concerning Isrāfīl and What He Was Entrusted With","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: Jibrīl sat with the Prophet ﷺ and looked toward the sky, when suddenly an angel was descending. Jibrīl said: “This angel has never descended since the day he was created until this moment.” When the angel descended, he said: “O Muḥammad, your Lord has sent me to you: shall He make you a king and a prophet, or a servant and a messenger?” Jibrīl said: “Humble yourself before your Lord, O Muḥammad.” The Prophet ﷺ replied: “Rather, a servant and a messenger.”"]},"buhuth":{"en":["This unnamed angel is said to have been Isrāfīl."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (7160)، والبزار في كشف الأستار (2462)، وأبو يعلى (6105)."},{"num":644,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا قُبِرَ الْمَيِّتُ، أَوْ قَالَ: أَحَدُكُمْ أَتَاهُ مَلَكَانِ أَسْوَدَانِ أَزْرَقَانِ يُقَالُ لِأَحَدِهِمَا: الْمُنْكَرُ وَالْآخَرُ النَّكِيرُ، فَيَقُولَانِ: مَا كُنْتَ تَقُولُ فِي هَذَا الرَّجُلِ ؟.... فَذَكَرَ الْحَدِيثَ بِطُولِهِ، وَسَيَأْتِي فِي مَوْضِعِهِ كَامِلًا."],"takhrij":"حسن: رواه الترمذيّ (1071) عن أبي سلمة يحيى بن خلف، حدّثنا بشر بن المفضّل، عن عبدالرحمن بن إسحاق، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في ذكر منكر ونكير من الملائكة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (1071), who said:","chapter_en":"What Has Been Reported Concerning the Angels Munkar and Nakīr","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “When the deceased is buried, two black-and-blue angels come to him. One of them is called Munkar and the other Nakīr. They ask: ‘What did you used to say about this man?’” The lengthy ḥadīth continues and will appear in full in its appropriate place."]},"buhuth":{"en":["“Ḥasan Gharīb.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1071)، وقال:."},{"num":645,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَثَلُ الَّذِي يَقْرَأُ الْقُرْآنَ وَهُوَ حَافِظٌ لَهُ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ، وَمَثَلُ الَّذِي يَقْرَأُ القرآن وَهُوَ يَتَعَاهَدُهُ وَهُوَ عَلَيْهِ شَدِيدٌ فَلَهُ أَجْرَانِ.","وَفِي رِوَايَةِ: الْمَاهِرُ بِالْقُرْآنِ مَعَ السَّفَرَةِ الْكِرَامِ الْبَرَرَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4937)، ومسلم في صلاة المسافرين (798) كلاهما من حديث قتادة، قال: سمعتُ زرارة بن أوفى يحدِّثُ عن سعد بن هشام، عن عائشة، فذكرت الحديث، واللّفظ للبخاريّ، وفي لفظ مسلم: والذي يقرأ القرآن ويتعتع فيه، وهو عليه شاق له أجران.","grade":"متفق عليه","chapter_ar":"باب ما جاء في السفرة الكرام البررة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4937) and Muslim (798).","chapter_en":"What Has Been Reported Concerning the Noble and Righteous Scribes","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":4,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Prophet ﷺ said: “The one who recites the Qurʾān while having memorized it is with the noble scribes, while the one who recites it, continually striving to maintain it while finding it difficult, will have two rewards. The one proficient in the Qurʾān is with the noble and righteous scribes.”"]},"buhuth":{"en":["The wording above is that of al-Bukhārī.","In Muslim’s wording:","“The one who recites the Qurʾān and stammers through it, finding it difficult, will have two rewards.”","The “scribes” are the angels."]},"intro":{"ar":["قال الله تعالى:","﴿بِأَيْدِي سَفَرَةٍ ۝ كِرَامٍ بَرَرَةٍ﴾","[عبس: ١٥–١٦]"],"en":["“In the hands of scribes, noble and righteous.”","[Sūrat ʿAbasa 80:15–16]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4937)، ومسلم (798)."},{"num":646,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ أَنْفَقَ زَوْجَيْنِ فِي سَبِيلِ اللَّهِ دَعَتْهُ خَزَنَةُ الْجَنَّةِ أَيْ فُلُ هَلُمَّ، فَقَالَ أَبُو بَكْرٍ: ذَاكَ الَّذِي لَا تَوَى عَلَيْهِ، قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرْجُو أَنْ تَكُونَ مِنْهُمْ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3216)، ومسلم في كتاب الزّكاة (1027: 86) كلاهما من حديث شيبان بن عبدالرحمن، عن يحيى بن أبي كثير، عن أبي سلمة بن عبدالرحمن، أنه سمع أبا هريرة، فذكر الحديث.وسيأتي بالتفصيل في كتاب الزّكاة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خزنة الجنة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3216) and Muslim (1027:86).","chapter_en":"What Has Been Reported Concerning the Keepers of Paradise","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: I heard the Prophet ﷺ say: “Whoever spends a pair of something in the path of Allah will be called by the keepers of Paradise: ‘O so-and-so, come!’” Abū Bakr may Allah be pleased with him asked: “Such a person will have no cause for loss?” The Prophet ﷺ replied: “I hope that you will be among them.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَسِيقَ الَّذِينَ اتَّقَوْا رَبَّهُمْ إِلَى الْجَنَّةِ زُمَرًا حَتَّى إِذَا جَاءُوهَا وَفُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا سَلَامٌ عَلَيْكُمْ طِبْتُمْ فَادْخُلُوهَا خَالِدِينَ﴾","[الزمر: ٧٣]"],"en":["“Those who feared their Lord will be led to Paradise in groups until, when they reach it and its gates are opened, its keepers will say to them: ‘Peace be upon you. You have done well, so enter it to remain forever.’”","[Sūrat al-Zumar 39:73]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3216)، ومسلم (1027: 86)."},{"num":647,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: آتِي بَابَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ، فَأَسْتَفْتِحُ، فَيَقُولُ الْخَازِنُ: مَنْ أَنْتَ؟ فَأَقُولُ: مُحَمَّدٌ، فَيَقُولُ: بِكَ أُمِرْتُ، لَا أَفْتَحُ لِأَحَدٍ قَبْلَكَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (197) من طرق عن هاشم بن القاسم، حدّثنا سليمان بن المغيرة، عن ثابت، عن أنس بن مالك، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب أن خازن الجنة أول من يفتح له باب الجنة هو نبينا ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (197).","chapter_en":"The Keeper of Paradise Will Open Its Gate First for Our Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I will come to the gate of Paradise on the Day of Resurrection and ask for it to be opened. The keeper will ask: ‘Who are you?’ I will reply: ‘Muḥammad.’ He will say: ‘I was commanded concerning you; I am not to open it for anyone before you.’”"]},"buhuth":{"en":["In another narration:","“I will have the greatest number of followers among the prophets on the Day of Resurrection, and I will be the first to knock at the gate of Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[800,16344],"tks":"صحيح: رواه مسلم (197)."},{"num":648,"demo":false,"sanad":"","matn":["عَنِ ابْنَ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: رَأَيْتُ لَيْلَةَ أُسْرِيَ بِي مُوسَى رَجُلًا آدَمَ طُوَالًا جَعْدًا كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ، وَرَأَيْتُ عِيسَى رَجُلًا مَرْبُوعًا مَرْبُوعَ الْخَلْقِ إِلَى الْحُمْرَةِ وَالْبَيَاضِ سَبِطَ الرَّأْسِ، وَرَأَيْتُ مَالِكًا خَازِنَ النَّارِ وَالدَّجَّالَ فِي آيَاتٍ أَرَاهُنَّ اللَّهُ إِيَّاهُ فَلَا تَكُنْ فِي مِرْيَةٍ مِنْ لِقَائِهِ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الخلق (3239)، ومسلم في الإيمان (165) كلاهما من حديث شعبة، عن قتادة، عن أبي العالية يقول: حدثني ابنُ عمّ نبيّكم، يعني ابن عباس، فذكر الحديث. واللّفظ للبخاريّ، ولفظ مسلم مختصر. ولكن رواه من طريق شيبان بن عبدالرحمن، عن قتادة، مثل شعبة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في مالك خازن النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3239) and Muslim (165).","chapter_en":"What Has Been Reported Concerning Mālik, the Keeper of the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Prophet ﷺ said: “On the night I was taken on the Night Journey, I saw Mūsā: a tall, dark-complexioned man with curly hair, as though he were one of the men of Shanūʾah. I saw ʿĪsā: a man of medium stature and well-proportioned build, with a complexion between reddish and white, and straight hair. I also saw Mālik, the keeper of the Fire, and the Dajjāl, among the signs that Allah showed me. So do not be in doubt concerning meeting him.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ قَالَ إِنَّكُمْ مَاكِثُونَ﴾","[الزخرف: ٧٧]","ومالك هو خازن جهنم.","وقال تعالى:","﴿عَلَيْهَا تِسْعَةَ عَشَرَ﴾","[المدثر: ٣٠]","لعل مالكاً هو رئيسهم أو هو أعظم، ولذا خُص بالذكر من بينهم."],"en":["“And they will call: ‘O Mālik, let your Lord put an end to us!’ He will say: ‘Indeed, you will remain.’”","[Sūrat al-Zukhruf 43:77]","Mālik is the keeper of Hell.","“Over it are nineteen.”","[Sūrat al-Muddaththir 74:30]","Perhaps Mālik is their chief, or the greatest among them, and therefore he was singled out for mention."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3239)، ومسلم (165)."},{"num":649,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: رَأَيْتُ اللَّيْلَةَ رَجُلَيْنِ أَتَيَانِي قَالَا: الَّذِي يُوقِدُ النَّارَ مَالِكٌ خَازِنُ النَّارِ، وَأَنَا جِبْرِيلُ وَهَذَا مِيكَائِيلُ."],"takhrij":"صحيح: رواه البخاريّ في بدء الخلق (3236) عن موسى، حدّثنا جرير، حدّثنا أبو رجاء، عن سمرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في مالك خازن النار","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3236).","chapter_en":"What Has Been Reported Concerning Mālik, the Keeper of the Fire","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Samurah may Allah be pleased with him reported that the Prophet ﷺ said: “Last night I saw two men who came to me and said: ‘The one who kindles the Fire is the keeper of the Fire. I am Jibrīl, and this is Mīkāʾīl.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16450],"tks":"صحيح: رواه البخاري (3236)."},{"num":650,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَاءَ مَلَكُ الْمَوْتِ إِلَى مُوسَى عَلَيْهِ السَّلَام، فَقَالَ لَهُ: أَجِبْ رَبَّكَ، قَالَ: فَلَطَمَ مُوسَى عَلَيْهِ السَّلَام عَيْنَ مَلَكِ الْمَوْتِ، فَفَقَأَهَا، قَالَ: فَرَجَعَ الْمَلَكُ إِلَى اللَّهِ تَعَالَى، فَقَالَ: إِنَّكَ أَرْسَلْتَنِي إِلَى عَبْدٍ لَكَ، لَا يُرِيدُ الْمَوْتَ، وَقَدْ فَقَأَ عَيْنِي، قَالَ: فَرَدَّ اللَّهُ إِلَيْهِ عَيْنَهُ، وَقَالَ: ارْجِعْ إِلَى عَبْدِي فَقُلِ: الْحَيَاةَ تُرِيدُ؟ فَإِنْ كُنْتَ تُرِيدُ الْحَيَاةَ، فَضَعْ يَدَكَ عَلَى مَتْنِ ثَوْرٍ، فَمَا تَوَارَتْ يَدُكَ مِنْ شَعْرَةٍ فَإِنَّكَ تَعِيشُ بِهَا سَنَةً، قَالَ: ثُمَّ مَهْ؟ قَالَ: ثُمَّ تَمُوتُ، قَالَ: فَالْآنَ مِنْ قَرِيبٍ رَبِّ أَمِتْنِي مِنَ الْأَرْضِ الْمُقَدَّسَةِ رَمْيَةً بِحَجَرٍ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَاللَّهِ لَوْ أَنِّي عِنْدَهُ لَأَرَيْتُكُمْ قَبْرَهُ إِلَى جَانِبِ الطَّرِيقِ عِنْدَ الْكَثِيبِ الْأَحْمَرِ."],"takhrij":"صحيح: رواه مسلم في كتاب الفضائل (2373: 158) عن محمد بن رافع، حدّثنا عبدالرزّاق، حدّثنا معمر، عن همّام بن منبّه، قال: هذا ما حدّثنا أبو هريرة عن رسول الله صلى الله عليه وسلم، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ذكر ما جاء في ملك الموت","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in Kitāb al-Faḍāʾil (2373:158).","chapter_en":"Mention of What Has Been Reported Concerning the Angel of Death","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بوجود الملائكة الآخرين وصفاتهم وما كُلِّفوا به من الأعمال","group_en":"Collection of Chapters Concerning Belief in the Existence of the Other Angels, Their Descriptions, and the Duties Assigned to Them","part_no":2,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The Angel of Death came to Mūsā, peace be upon him, and said to him: ‘Respond to your Lord.’ Mūsā, peace be upon him, struck the Angel of Death in the eye and put it out. The angel returned to Allah Most High and said: ‘You sent me to a servant of Yours who does not want death, and he has put out my eye.’ Allah restored his eye and said: ‘Return to My servant and say: Do you desire life? If you desire life, place your hand upon the back of an ox. For every hair covered by your hand, you will live one year.’ Mūsā asked: ‘Then what?’ He replied: ‘Then you will die.’ Mūsā said: ‘Then let it be now, soon. My Lord, cause me to die within a stone’s throw of the Holy Land.’” The Messenger of Allah ﷺ said: “By Allah, if I were there, I would show you his grave beside the road near the red sand dune.”"]},"buhuth":{"en":["Al-Bukhārī also narrated it (1339, 3407), but in his route only the final portion is explicitly raised to the Prophet ﷺ — the words: “By Allah, if I were there, I would show you his grave beside the road near the red sand dune.” He also points to Maʿmar’s narration from Hammām from Abū Hurayrah with similar wording."]},"intro":{"ar":["قال الله تعالى:","﴿قُلْ يَتَوَفَّاكُمْ مَلَكُ الْمَوْتِ الَّذِي وُكِّلَ بِكُمْ ثُمَّ إِلَى رَبِّكُمْ تُرْجَعُونَ﴾","[السجدة: ١١]"],"en":["“Say: ‘The Angel of Death, who has been entrusted with you, will take your souls; then to your Lord you will be returned.’”","[Sūrat al-Sajdah 32:11]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2373: 158)."},{"num":651,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: احْتَجَّ آدَمُ وَمُوسَى، فَقَالَ مُوسَى: يَا آدَمُ أَنْتَ أَبُونَا خَيَّبْتَنَا وَأَخْرَجْتَنَا مِنَ الْجَنَّةِ، فَقَالَ لَهُ آدَمُ: أَنْتَ مُوسَى اصْطَفَاكَ اللَّهُ بِكَلَامِهِ وَخَطَّ لَكَ بِيَدِهِ، أَتَلُومُنِي عَلَى أَمْرٍ قَدَّرَهُ اللَّهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَنِي بِأَرْبَعِينَ سَنَةً؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَحَجَّ آدَمُ مُوسَى، فَحَجَّ آدَمُ مُوسَى.","وَفِي حَدِيثِ ابْنِ أَبِي عُمَرَ، وَابْنِ عَبْدَةَ، قَالَ أَحَدُهُمَا: خَطَّ، وقَالَ الْآخَرُ: كَتَبَ لَكَ التَّوْرَاةَ بِيَدِهِ."],"takhrij":"متفق عليه: رواه مسلم في القدر (2652)، عن محمد بن حاتم، وإبراهيم بن دينار، وابن أبي عمر المكي، وأحمد بن عبده الضّبيّ، جميعاً عن ابن عيينة (واللّفظ لابن حاتم، وابن دينار) قالا: حدّثنا سفيان بن عيينة، عن عمرو، عن طاوس، قال: سعتُ أبا هريرة، يقول: فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في التوراة بأن الله تعالى كتبها بيده وأنزلها على نبيه وكليمه موسى عليه السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim in al-Qadar (2652) and al-Bukhārī in al-Qadar (6614).","chapter_en":"What Has Been Reported Concerning the Torah: That Allah Most High Wrote It With His Hand and Revealed It to His Prophet and Kalīm, Moses, peace be upon him,","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Adam and Moses disputed. Moses said to him: ‘O Adam, you are our father. You disappointed us and caused us to be expelled from Paradise.’ Adam replied: ‘O Moses, Allah chose you by speaking directly to you and inscribed for you with His Hand. Do you blame me for a matter that Allah decreed for me forty years before He created me?’ Thus Adam prevailed over Moses in the argument; Adam prevailed over Moses.” In the narration of Ibn Abī ʿUmar and Ibn ʿAbdah, one of them narrated:","“He inscribed for you,” while the other narrated: “He wrote the Torah for you with His Hand.”"]},"buhuth":{"en":["Abū Dāwūd (4701) also narrated it, in which Adam said:","“You are Moses. Allah chose you by speaking directly to you and inscribed the Torah for you with His Hand.”"]},"intro_majmu":{"ar":["قال الله تعالى:","﴿قُولُوا آمَنَّا بِاللهِ وَمَا أُنْزِلَ إِلَيْنَا وَمَا أُنْزِلَ إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى وَمَا أُوتِيَ النَّبِيُّونَ مِنْ رَبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ﴾","[البقرة: ١٣٦]","وقد أنزل الله تعالى الصحف على إبراهيم وموسى عليهما السلام.","قال تعالى:","﴿إِنَّ هَذَا لَفِي الصُّحُفِ الْأُولَى ۝ صُحُفِ إِبْرَاهِيمَ وَمُوسَى﴾","[الأعلى: ١٨–١٩]","وأنزل الزبور على داود عليه السلام.","قال تعالى:","﴿وَلَقَدْ فَضَّلْنَا بَعْضَ النَّبِيِّينَ عَلَى بَعْضٍ وَآتَيْنَا دَاوُودَ زَبُورًا﴾","[الإسراء: ٥٥]","وأنزل الإنجيل على عيسى عليه السلام.","قال تعالى:","﴿وَقَفَّيْنَا عَلَى آثَارِهِمْ بِعِيسَى ابْنِ مَرْيَمَ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرَاةِ وَآتَيْنَاهُ الْإِنْجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرَاةِ وَهُدًى وَمَوْعِظَةً لِلْمُتَّقِينَ﴾","[المائدة: ٤٦]"],"en":["“Say: We believe in Allah and what has been sent down to us, and what was sent down to Abraham, Ishmael, Isaac, Jacob, and the Tribes, and what was given to Moses and Jesus, and what was given to the prophets from their Lord. We make no distinction between any of them, and to Him we submit.”","[Sūrat al-Baqarah 2:136]","Allah Most High revealed the Scriptures to Abraham and Moses peace be upon them.","“Indeed, this is in the former Scriptures: the Scriptures of Abraham and Moses.”","[Sūrat al-Aʿlā 87:18–19]","And He revealed the Zabūr to David peace be upon him.","“We have certainly favored some of the prophets over others, and We gave David the Zabūr.”","[Sūrat al-Isrāʾ 17:55]","And He revealed the Injīl to Jesus, peace be upon him.","“And We sent, following in their footsteps, Jesus son of Mary, confirming what came before him of the Torah. We gave him the Gospel, in which was guidance and light, confirming what came before it of the Torah, and as guidance and an admonition for the God-fearing.”","[Sūrat al-Māʾidah 5:46]"]},"intro":{"ar":["قال الله تعالى:","﴿وَكَتَبْنَا لَهُ فِي الْأَلْوَاحِ مِنْ كُلِّ شَيْءٍ مَوْعِظَةً وَتَفْصِيلًا لِكُلِّ شَيْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا بِأَحْسَنِهَا﴾","[الأعراف: ١٤٥]","وقال الله تعالى:","﴿إِنَّا أَنْزَلْنَا التَّوْرَاةَ فِيهَا هُدًى وَنُورٌ يَحْكُمُ بِهَا النَّبِيُّونَ الَّذِينَ أَسْلَمُوا لِلَّذِينَ هَادُوا وَالرَّبَّانِيُّونَ وَالْأَحْبَارُ بِمَا اسْتُحْفِظُوا مِنْ كِتَابِ اللهِ وَكَانُوا عَلَيْهِ شُهَدَاءَ﴾","[المائدة: ٤٤]"],"en":["“We wrote for him upon the Tablets an admonition concerning all things and a detailed explanation of all things: ‘Take them firmly and command your people to follow the best of them.’”","[Sūrat al-Aʿrāf 7:145]","“Indeed, We sent down the Torah, in which was guidance and light. The prophets who submitted judged by it for the Jews, as did the devoted scholars and rabbis, by that which they were entrusted to preserve of the Book of Allah, and they were witnesses to it.”","[Sūrat al-Māʾidah 5:44]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2652)، والبخاري (6614)."},{"num":652,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ الْخَبَرُ كَالْمُعَايَنَةِ، إِنَّ اللَّهَ عَزَّ وَجَلَّ أَخْبَرَ مُوسَى بِمَا صَنَعَ قَوْمُهُ فِي الْعِجْلِ، فَلَمْ يُلْقِ الْأَلْوَاحَ، فَلَمَّا عَايَنَ مَا صَنَعُوا، أَلْقَى الْأَلْوَاحَ فَانْكَسَرَتْ."],"takhrij":"صحيح: رواه أحمد (2447)، والطبراني في الأوسط (25)، وفي الكبير (1183، 1184)، والبزّار - كما في كشف الأستار (200)، كلّهم من طريق أبي بشر، عن سعيد بن جبير، عن ابن عباس، فذكر نحوه. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في أن موسى عليه السلام ألقى الألواح فانكسرت","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (2447), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (25) and al-Muʿjam al-Kabīr (1183, 1184), and al-Bazzār as cited in Kashf al-Astār (200).","chapter_en":"What Has Been Reported Concerning Moses, peace be upon him, Throwing Down the Tablets and Their Breaking","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “Being informed is not like seeing with one’s own eyes. Allah, Mighty and Majestic, informed Moses of what his people had done regarding the calf, yet he did not throw down the Tablets. But when he saw with his own eyes what they had done, he threw down the Tablets and they broke.”"]},"buhuth":{"en":["It was also authenticated by Ibn Ḥibbān (6213, 6214) and al-Ḥākim (2/321, 2/380), who said: “It meets the conditions of the two Shaykhs.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَلَمَّا رَجَعَ مُوسَى إِلَى قَوْمِهِ غَضْبَانَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِي مِنْ بَعْدِي أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى الْأَلْوَاحَ﴾","[الأعراف: ١٥٠]"],"en":["“When Moses returned to his people angry and deeply grieved, he said: ‘How evil is what you did in my absence! Did you hasten the command of your Lord?’ And he threw down the Tablets.”","[Sūrat al-Aʿrāf 7:150]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1207,12338],"tks":"صحيح: رواه أحمد (2447)، والطبراني في الأوسط (25)، وفي الكبير (1183، 1184)، والبزار كما في كشف الأستار (200)."},{"num":653,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: أَخْبَرَنِي أَبُو سُفْيَانَ بْنُ حَرْبٍ، أَنَّ هِرَقْلَ... (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ) دَعَا بِكِتَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي بَعَثَ بِه دِحْيَةُ إِلَى عَظِيمِ بُصْرَى فَدَفَعَهُ إِلَى هِرَقْلَ فَقَرَأَهُ، فَإِذَا فِيهِ: بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ، مِنْ مُحَمَّدٍ عَبْدِ اللَّهِ وَرَسُولِهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ، سَلَامٌ عَلَى مَنِ اتَّبَعَ الْهُدَى، أَمَّا بَعْدُ، فَإِنِّي أَدْعُوكَ بِدِعَايَةِ الْإِسْلَامِ أَسْلِمْ تَسْلَمْ يُؤْتِكَ اللَّهُ أَجْرَكَ مَرَّتَيْنِ، فَإِنْ تَوَلَّيْتَ فَإِنَّ عَلَيْكَ إِثْمَ الْأَرِيسِيِّينَ ﴿قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللَّهِ فَإِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ﴾ [سورة آل عمران: 64]...الْحَدِيثَ."],"takhrij":"متفق عليه: رواه البخاريّ في بدء الوحي (7)، ومسلم في كتاب الجهاد والسير (1773)، كلاهما من حديث الزّهريّ، عن عبيد اله بن عبدالله بن عتبة، عن ابن عباس، قال: فذكر الحديث بطوله، وسيأتي في مواضعه كاملاً.","grade":"متفق عليه","chapter_ar":"باب ترجمة كتاب الله إلى اللغات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7) and Muslim (1773).","chapter_en":"Translating the Book of Allah Into Other Languages","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: Abū Sufyān ibn Ḥarb may Allah be pleased with him informed me that Heraclius called for the letter of the Messenger of Allah ﷺ which Diḥyah had delivered to the ruler of Buṣrā, who then forwarded it to Heraclius. He read it, and it stated: “In the Name of Allah, the Most Merciful, the Especially Merciful. From Muḥammad, the servant of Allah and His Messenger, to Heraclius, the ruler of the Romans. Peace be upon whoever follows guidance. To proceed: I invite you with the call of Islam. Accept Islam and you will be safe; Allah will give you your reward twice. But if you turn away, then upon you will be the sin of the Arīsiyyīn. ‘Say: O People of the Scripture, come to a word that is equitable between us and you: that we worship none except Allah, associate nothing with Him, and that none of us take others as lords besides Allah. But if they turn away, then say: Bear witness that we are Muslims.’” [Āl ʿImrān 3:64]"]},"intro":{"ar":["قال الله تعالى:","﴿قُلْ فَأْتُوا بِالتَّوْرَاةِ فَاتْلُوهَا إِنْ كُنْتُمْ صَادِقِينَ﴾","[آل عمران: ٩٣]"],"en":["“Say: ‘Then bring the Torah and recite it, if you are truthful.’”","[Āl ʿImrān 3:93]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7)، ومسلم (1773)."},{"num":654,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ أَنَّهُ قَالَ: جَاءَتْ الْيَهُودُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَذَكَرُوا لَهُ أَنَّ رَجُلًا مِنْهُمْ وَامْرَأَةً زَنَيَا، فَقَالَ لَهُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا تَجِدُونَ فِي التَّوْرَاةِ فِي شَأْنِ الرَّجْمِ؟ فَقَالُوا: نَفْضَحُهُمْ وَيُجْلَدُونَ. فَقَالَ عَبْدُ اللَّهِ بْنُ سَلَامٍ: كَذَبْتُمْ إِنَّ فِيهَا الرَّجْمَ. فَأَتَوْا بِالتَّوْرَاةِ فَنَشَرُوهَا، فَوَضَعَ أَحَدُهُمْ يَدَهُ عَلَى آيَةِ الرَّجْمِ، ثُمَّ قَرَأَ مَا قَبْلَهَا وَمَا بَعْدَهَا، فَقَالَ لَهُ عَبْدُ اللَّهِ بْنُ سَلَامٍ: ارْفَعْ يَدَكَ فَرَفَعَ يَدَهُ، فَإِذَا فِيهَا آيَةُ الرَّجْمِ، فَقَالُوا: صَدَقَ يَا مُحَمَّدُ، فِيهَا آيَةُ الرَّجْمِ، فَأَمَرَ بِهِمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُجِمَا. فَقَالَ عَبْدُ اللَّهِ بْنُ عُمَرَ: فَرَأَيْتُ الرَّجُلَ يَحْنِي عَلَى الْمَرْأَةِ يَقِيهَا الْحِجَارَةَ."],"takhrij":"متفق عليه: رواه مالك في الحدود (1) عن نافع، عن ابن عمر، فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ترجمة كتاب الله إلى اللغات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Ḥudūd (1), al-Bukhārī (3635), and Muslim (1699:27).","chapter_en":"Translating the Book of Allah Into Other Languages","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar, may Allah be pleased with them, reported: “The Jews came to the Messenger of Allah ﷺ and informed him that a man and a woman from among them had committed adultery. The Messenger of Allah ﷺ asked them: ‘What do you find in the Torah concerning stoning?’ They replied: ‘We disgrace them publicly and flog them.’ ʿAbdullāh ibn Salām said: ‘You have lied. It contains the punishment of stoning.’ They brought the Torah and opened it. One of them placed his hand over the verse of stoning and read what came before it and after it. ʿAbdullāh ibn Salām said: ‘Lift your hand.’ He lifted his hand, and there was the verse of stoning. They said: ‘You have spoken the truth, O Muḥammad. It contains the verse of stoning.’ The Messenger of Allah ﷺ then ordered that the two be stoned. ʿAbdullāh ibn ʿUmar said: ‘I saw the man leaning over the woman, shielding her from the stones.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (1)، والبخاري (3635)، ومسلم (1699: 27)."},{"num":655,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ أَهْلُ الْكِتَابِ يَقْرَءُونَ التَّوْرَاةَ بِالْعِبْرَانِيَّةِ وَيُفَسِّرُونَهَا بِالْعَرَبِيَّةِ لِأَهْلِ الْإِسْلَامِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تُصَدِّقُوا أَهْلَ الْكِتَابِ وَلَا تُكَذِّبُوهُمْ وَقُولُوا: ﴿آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا وَمَا أُنْزِلَ إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى وَمَا أُوتِيَ النَّبِيُّونَ مِنْ رَبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ﴾ [سورة البقرة: 136]."],"takhrij":"صحيح: رواه البخاريّ في التفسير (4485)، وفي الاعتصام bukhari(7362)، وفي التوحيد bukhari(7542) في جميع المواضع عن محمد بن بشار، حدّثنا عثمان بن عمر، أخبرنا علي بن المبارك، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة، فذكره، واللّفظ سواء في الجميع.","grade":"صحيح","chapter_ar":"باب ترجمة كتاب الله إلى اللغات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (7542, 7362, 4485).","chapter_en":"Translating the Book of Allah Into Other Languages","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: “The People of the Book used to read the Torah in Hebrew and explain it in Arabic to the Muslims. The Messenger of Allah ﷺ said: ‘Neither affirm what the People of the Book tell you nor deny them. Rather say: “We believe in Allah and what has been sent down to us, and what was sent down to Abraham, Ishmael, Isaac, Jacob, and the Tribes, and what was given to Moses and Jesus, and what was given to the prophets from their Lord. We make no distinction between any of them, and to Him we submit.”’” [Sūrat al-Baqarah 2:136]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12985],"tks":"صحيح: رواه البخاري (7542، 7362، 4485)."},{"num":656,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ: أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْوَحْيِ الرُّؤْيَا الصَّالِحَةُ فِي النَّوْمِ، فَكَانَ لَا يَرَى رُؤْيَا إِلَّا جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ، ثُمَّ حُبِّبَ إِلَيْهِ الْخَلَاءُ وَكَانَ يَخْلُو بِغَارِ حِرَاءٍ، فَيَتَحَنَّثُ فِيهِ وَهُوَ التَّعَبُّدُ اللَّيَالِيَ ذَوَاتِ الْعَدَدِ قَبْلَ أَنْ يَنْزِعَ إِلَى أَهْلِهِ وَيَتَزَوَّدُ لِذَلِكَ، ثُمَّ يَرْجِعُ إِلَى خَدِيجَةَ فَيَتَزَوَّدُ لِمِثْلِهَا حَتَّى جَاءَهُ الْحَقُّ وَهُوَ فِي غَارِ حِرَاءٍ، فَجَاءَهُ الْمَلَكُ، فَقَالَ: اقْرَأْ، قَالَ: مَا أَنَا بِقَارِئٍ، قَالَ: فَأَخَذَنِي فَغَطَّنِي حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي، فَقَالَ: اقْرَأْ، قُلْتُ: مَا أَنَا بِقَارِئٍ، فَأَخَذَنِي فَغَطَّنِي الثَّانِيَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي، فَقَالَ: اقْرَأْ، فَقُلْتُ مَا أَنَا بِقَارِئٍ، فَأَخَذَنِي فَغَطَّنِي الثَّالِثَةَ، ثُمَّ أَرْسَلَنِي فَقَالَ: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ (1) خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ (2) اقْرَأْ وَرَبُّكَ الْأَكْرَمُ (3) الَّذِي عَلَّمَ بِالْقَلَمِ (4) عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ (5)﴾ [سورة العلق: 1، 5]...الْحَدِيثَ بِطُولِهِ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (3)، ومسلم في الإيمان (160) كلاهما من حديث الليث بن سعد، عن عُقيل بن خالد، عن ابن شهاب، عن عروة يقول: سمعت عائشة، فذكر الحديث. واللفظ للبخاريّ، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب الإيمان بأن القرآن كلام الله، أنزله الله تعالى بواسطة جبريل","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3) and Muslim (160).","chapter_en":"Belief That the Qurʾān Is the Speech of Allah, Revealed by Allah Most High Through Jibrīl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["ʿĀʾishah, the Mother of the Believers may Allah be pleased with her, reported: “The beginning of revelation to the Messenger of Allah ﷺ was the true dream during sleep. He would not see a dream except that it came true as clearly as the breaking of dawn. Then seclusion was made beloved to him. He would seclude himself in the cave of Ḥirāʾ and devote himself to worship there for a number of nights before returning to his family, taking provisions for that purpose. Then he would return to Khadījah and take provisions for another similar period, until the Truth came to him while he was in the cave of Ḥirāʾ. The angel came to him and said: ‘Read.’ He replied: ‘I am not a reader.’ He said: ‘He seized me and pressed me until I reached the limit of my endurance, then released me.’ Then he said: ‘Read.’ I replied: ‘I am not a reader.’ He seized me and pressed me a second time until I reached the limit of my endurance, then released me. Then he said: ‘Read.’ I replied: ‘I am not a reader.’ He seized me and pressed me a third time, then released me and said: ‘Read in the Name of your Lord who created. He created the human being from a clinging substance. Read, and your Lord is the Most Generous, who taught by the pen, taught the human being what he did not know.’” [Sūrat al-ʿAlaq 96:1–5] The lengthy ḥadīth continues."]},"buhuth":{"ar":["واللفظ للبخاري، ولفظ مسلم نحوه."],"en":["The wording is that of al-Bukhārī; Muslim’s wording is similar."]},"intro":{"ar":["قال الله تعالى:","﴿وَأَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ﴾","[المائدة: ٤٨]"],"en":["“We have sent down to you the Book in truth, confirming the Scriptures that came before it and as a guardian over them.”","[Sūrat al-Māʾidah 5:48]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3)، ومسلم (160)."},{"num":657,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْوَحْيِ الرُّؤْيَا الصَّالِحَةُ فِي النَّوْمِ، فَكَانَ لَا يَرَى رُؤْيَا إِلَّا جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ، ثُمَّ حُبِّبَ إِلَيْهِ الْخَلَاءُ وَكَانَ يَخْلُو بِغَارِ حِرَاءٍ، فَيَتَحَنَّثُ فِيهِ وَهُوَ التَّعَبُّدُ اللَّيَالِيَ ذَوَاتِ الْعَدَدِ قَبْلَ أَنْ يَنْزِعَ إِلَى أَهْلِهِ وَيَتَزَوَّدُ لِذَلِكَ، ثُمَّ يَرْجِعُ إِلَى خَدِيجَةَ فَيَتَزَوَّدُ لِمِثْلِهَا حَتَّى جَاءَهُ الْحَقُّ وَهُوَ فِي غَارِ حِرَاءٍ، فَجَاءَهُ الْمَلَكُ، فَقَالَ: اقْرَأْ، قَالَ: مَا أَنَا بِقَارِئٍ، قَالَ: فَأَخَذَنِي فَغَطَّنِي حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي، فَقَالَ: اقْرَأْ، قُلْتُ: مَا أَنَا بِقَارِئٍ، فَأَخَذَنِي فَغَطَّنِي الثَّانِيَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ، ثُمَّ أَرْسَلَنِي، فَقَالَ: اقْرَأْ، فَقُلْتُ مَا أَنَا بِقَارِئٍ، فَأَخَذَنِي فَغَطَّنِي الثَّالِثَةَ، ثُمَّ أَرْسَلَنِي فَقَالَ: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ (1) خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ (2) اقْرَأْ وَرَبُّكَ الْأَكْرَمُ (3) الَّذِي عَلَّمَ بِالْقَلَمِ (4) عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ (5)﴾ [سورة العلق: 1، 5]. فَرَجَعَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْجُفُ فُؤَادُهُ، فَدَخَلَ عَلَى خَدِيجَةَ بِنْتِ خُوَيْلِدٍ رَضِيَ اللَّهُ عَنْهَا، فَقَالَ: زَمِّلُونِي زَمِّلُونِي، فَزَمَّلُوهُ حَتَّى ذَهَبَ عَنْهُ الرَّوْعُ، فَقَالَ لِخَدِيجَةَ، وَأَخْبَرَهَا الْخَبَرَ: لَقَدْ خَشِيتُ عَلَى نَفْسِي، فَقَالَتْ خَدِيجَةُ: كَلَّا وَاللَّهِ مَا يُخْزِيكَ اللَّهُ أَبَدًا، إِنَّكَ لَتَصِلُ الرَّحِمَ، وَتَحْمِلُ الْكَلَّ، وَتَكْسِبُ الْمَعْدُومَ، وَتَقْرِي الضَّيْفَ، وَتُعِينُ عَلَى نَوَائِبِ الْحَقِّ، فَانْطَلَقَتْ بِهِ خَدِيجَةُ حَتَّى أَتَتْ بِهِ وَرَقَةَ بْنَ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى ابْنَ عَمِّ خَدِيجَةَ، وَكَانَ امْرَأً تَنَصَّرَ فِي الْجَاهِلِيَّةِ، وَكَانَ يَكْتُبُ الْكِتَابَ الْعِبْرَانِيَّ، فَيَكْتُبُ مِنَ الْإِنْجِيلِ بِالْعِبْرَانِيَّةِ مَا شَاءَ اللَّهُ أَنْ يَكْتُبَ، وَكَانَ شَيْخًا كَبِيرًا قَدْ عَمِيَ، فَقَالَتْ لَهُ خَدِيجَةُ: يَا ابْنَ عَمِّ، اسْمَعْ مِنَ ابْنِ أَخِيكَ، فَقَالَ لَهُ وَرَقَةُ: يَا ابْنَ أَخِي، مَاذَا تَرَى، فَأَخْبَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَبَرَ مَا رَأَى، فَقَالَ لَهُ وَرَقَةُ: هَذَا النَّامُوسُ الَّذِي نَزَّلَ اللَّهُ عَلَى مُوسَى صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَا لَيْتَنِي فِيهَا جَذَعًا، لَيْتَنِي أَكُونُ حَيًّا إِذْ يُخْرِجُكَ قَوْمُكَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَوَمُخْرِجِيَّ هُمْ؟ قَالَ: نَعَمْ، لَمْ يَأْتِ رَجُلٌ قَطُّ بِمِثْلِ مَا جِئْتَ بِهِ إِلَّا عُودِيَ، وَإِنْ يُدْرِكْنِي يَوْمُكَ أَنْصُرْكَ نَصْرًا مُؤَزَّرًا، ثُمَّ لَمْ يَنْشَبْ وَرَقَةُ أَنْ تُوُفِّيَ وَفَتَرَ الْوَحْيُ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (3)، ومسلم في الإيمان (160) كلاهما من حديث الليث بن سعد، عن عُقيل بن خالد، عن ابن شهاب، عن عروة يقول: سمعت عائشة، فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أول ما نزل من القرآن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3) and Muslim (160).","chapter_en":"What Has Been Reported Concerning the First of the Qurʾān to Be Revealed","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["ʿĀʾishah, the Mother of the Believers may Allah be pleased with her, reported: “The beginning of revelation to the Messenger of Allah ﷺ was the true dream during sleep. He would not see a dream except that it came true as clearly as the breaking of dawn. Then seclusion was made beloved to him. He would seclude himself in the cave of Ḥirāʾ and devote himself to worship there for a number of nights before returning to his family, taking provisions for that purpose. Then he would return to Khadījah and take provisions for another similar period, until the Truth came to him while he was in the cave of Ḥirāʾ. The angel came to him and said: ‘Read.’ He replied: ‘I am not a reader.’ He said: ‘He seized me and pressed me until I reached the limit of my endurance, then released me.’ Then he said: ‘Read.’ I replied: ‘I am not a reader.’ He seized me and pressed me a second time until I reached the limit of my endurance, then released me. Then he said: ‘Read.’ I replied: ‘I am not a reader.’ He seized me and pressed me a third time, then released me and said: ‘Read in the Name of your Lord who created. He created the human being from a clinging substance. Read, and your Lord is the Most Generous, who taught by the pen, taught the human being what he did not know.’” [Sūrat al-ʿAlaq 96:1–5] The Messenger of Allah ﷺ returned with those verses, his heart trembling. He entered upon Khadījah bint Khuwaylid may Allah be pleased with her and said: “Cover me! Cover me!” They covered him until the fear left him. He then told Khadījah what had happened and said: “I feared for myself.” Khadījah replied: “Never! By Allah, Allah will never disgrace you. You maintain ties of kinship, support the burdened, provide for those who have nothing, honor the guest, and assist people through the calamities of truth.” Khadījah then took him to Waraqah ibn Nawfal ibn Asad ibn ʿAbd al-ʿUzzā, a cousin of Khadījah. He had embraced Christianity during the pre-Islamic period and used to write in Hebrew, writing from the Gospel in Hebrew whatever Allah willed him to write. He was an elderly man who had become blind. Khadījah said to him: “O son of my uncle, listen to your nephew.” Waraqah asked him: “O son of my brother, what have you seen?” The Messenger of Allah ﷺ told him what he had seen. Waraqah said: “This is the Nāmūs who came down to Moses. If only I were young and strong! If only I were alive when your people drive you out!” The Messenger of Allah ﷺ asked: “Will they really drive me out?” He replied: “Yes. No man has ever brought what you have brought except that he was opposed. If I live to see your day, I will support you with mighty support.” Not long afterward, Waraqah died, and revelation paused."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3)، ومسلم (160)."},{"num":658,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: أَوَّلَ سُورَةٍ نَزَلَتْ: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾."],"takhrij":"حسن: رواه الحاكم (2873) عن أبي بكر أحمد بن إسحاق الفقيه، أنبأنا بشر بن موسى، ثنا الحميديّ، ثنا سفيان، عن محمد بن إسحاق، عن الزّهريّ، عن عروة، عن عائشة، فذكرت الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في أول ما نزل من القرآن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ḥākim (2873).","chapter_en":"What Has Been Reported Concerning the First of the Qurʾān to Be Revealed","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her said: “The first sūrah to be revealed was: ‘Read in the Name of your Lord who created.’” [Sūrat al-ʿAlaq 96:1]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (2873)."},{"num":659,"demo":false,"sanad":"","matn":["عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ قَالَ: سَأَلْتُ أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ، عَنْ أَوَّلِ مَا نَزَلَ مِنَ الْقُرْآنِ قَالَ: ﴿يَا أَيُّهَا الْمُدَّثِّرُ﴾. قُلْتُ: يَقُولُونَ ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ﴾ فَقَالَ أَبُو سَلَمَةَ: سَأَلْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ عَنْ ذَلِكَ، وَقُلْتُ لَهُ مِثْلَ الَّذِي قُلْتَ، فَقَالَ جَابِرٌ: لَا أُحَدِّثُكَ إِلَّا مَا حَدَّثَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَاوَرْتُ بِحِرَاءٍ، فَلَمَّا قَضَيْتُ جِوَارِي هَبَطْتُ، فَنُودِيتُ، فَنَظَرْتُ عَنْ يَمِينِي فَلَمْ أَرَ شَيْئًا، وَنَظَرْتُ عَنْ شِمَالِي فَلَمْ أَرَ شَيْئًا، وَنَظَرْتُ أَمَامِي فَلَمْ أَرَ شَيْئًا، وَنَظَرْتُ خَلْفِي فَلَمْ أَرَ شَيْئًا، فَرَفَعْتُ رَأْسِي فَرَأَيْتُ شَيْئًا، فَأَتَيْتُ خَدِيجَةَ، فَقُلْتُ: دَثِّرُونِي وَصُبُّوا عَلَيَّ مَاءً بَارِدًا، قَالَ: فَدَثَّرُونِي وَصَبُّوا عَلَيَّ مَاءً بَارِدًا، قَالَ: فَنَزَلَتْ: ﴿يَا أَيُّهَا الْمُدَّثِّرُ (1) قُمْ فَأَنْذِرْ (2) وَرَبَّكَ فَكَبِّرْ (3)﴾ [سورة المدثر: 1ـ 3]."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4922)، ومسلم في الإيمان (161) كلاهما من حديث عبدالله بن المبارك، عن يحيى بن أبي كثير، بإسناده، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أول ما نزل من القرآن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4922) and Muslim (161).","chapter_en":"What Has Been Reported Concerning the First of the Qurʾān to Be Revealed","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Yaḥyā ibn Abī Kathīr reported: I asked Abū Salamah ibn ʿAbd al-Raḥmān concerning the first portion of the Qurʾān to be revealed. He replied: “O you who are wrapped up.” [Sūrat al-Muddaththir 74:1] I said: “People say: ‘Read in the Name of your Lord who created.’” [Sūrat al-ʿAlaq 96:1] Abū Salamah replied: I asked Jābir ibn ʿAbdullāh may Allah be pleased with them about that and said to him what you have just said to me. Jābir replied: I will tell you only what the Messenger of Allah ﷺ told us. He said: “I remained in seclusion at Ḥirāʾ. When I completed my period of seclusion, I descended and heard myself being called. I looked to my right but saw nothing. I looked to my left but saw nothing. I looked in front of me but saw nothing. I looked behind me but saw nothing. Then I raised my head and saw something. I went to Khadījah and said: ‘Wrap me up, and pour cold water over me.’ So they wrapped me up and poured cold water over me. Then there was revealed: ‘O you who are wrapped up! Arise and warn. And magnify your Lord.’” [Sūrat al-Muddaththir 74:1–3]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4922)، ومسلم (161)."},{"num":660,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: آخِرُ سُورَةٍ نَزَلَتْ ﴿بَرَاءَةٌ﴾، وَآخِرُ آيَةٍ نَزَلَتْ: ﴿يَسْتَفْتُونَكَ قُلِ اللَّهُ يُفْتِيكُمْ فِي الْكَلَالَةِ ﴾ [النساء: 176]."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4605)، ومسلم في الفرائض (1618) كلاهما من حديث شعبة، عن أبي إسحاق، قال: سمعت البراء، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في آخر ما نزل من القرآن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4605) and Muslim (1618).","chapter_en":"What Has Been Reported Concerning the Last of the Qurʾān to Be Revealed","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib, may Allah be pleased with him, said: “The last sūrah revealed was: ‘Barāʾah.’” [Sūrat al-Tawbah 9:1] “And the last verse revealed was: ‘They ask you for a ruling. Say: Allah gives you a ruling concerning al-kalālah.’” [Sūrat al-Nisāʾ 4:176]"]},"buhuth":{"en":["In another narration:","“The last sūrah to be revealed in full was Sūrat al-Tawbah.”","Narrated by Muslim."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11733],"tks":"متفق عليه: رواه البخاري (4605)، ومسلم (1618)."},{"num":661,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ قَالَ: آخِرِ مَا نَزَلَ مِنَ الْقُرْآنِ: ﴿لَقَدْ جَاءَكُمْ رَسُولٌ مِنْ أَنْفُسِكُمْ عَزِيزٌ عَلَيْهِ مَا عَنِتُّمْ حَرِيصٌ عَلَيْكُمْ بِالْمُؤْمِنِينَ رَءُوفٌ رَحِيمٌ﴾ [سورة التوبة: 128]."],"takhrij":"صحيح: رواه الحاكم (3296) عن أبي العباس محمد بن يعقوب، ثنا بكار بن قتيبة القاضي، ثنا أبو عامر عبدالله بن عمرو العقديّ، ثنا شعبة، عن يونس بن عبيد، وعلي بن زيد، عن يوسف بن مهران، عن ابن عباس، عن أبي بن كعب بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في آخر ما نزل من القرآن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ḥākim (3296).","chapter_en":"What Has Been Reported Concerning the Last of the Qurʾān to Be Revealed","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Ubayy ibn Kaʿb, may Allah be pleased with him, said: “The last of the Qurʾān to be revealed was: ‘There has certainly come to you a Messenger from among yourselves. Grievous to him is what you suffer; he is deeply concerned for you, and to the believers he is compassionate and merciful.’” [Sūrat al-Tawbah 9:128]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (3296)."},{"num":662,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: أُنْزِلَ الْقُرْآنُ جُمْلَةً مِنَ الذِّكْرِ فِي لَيْلَةِ أَرْبَعٍ وَعِشْرِينَ مِنْ رَمَضَانَ، فَجُعِلَ فِي بَيْتِ الْعِزَّةِ."],"takhrij":"صحيح: رواه النّسائيّ في الكبرى (7937)، والطّبرانيّ في الكبير (12381)، والحاكم (4216)، وابن جرير الطّبريّ في تفسيره (736) من طرق عن الأعمش، عن حسان بن أبي الأشرس، عن سعيد بن جبير، عن ابن عباس.","grade":"صحيح","chapter_ar":"باب نزول القرآن جملة واحدة في ليلة القدر إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī in al-Sunan al-Kubrā (7991), al-Ṭabarānī in al-Muʿjam al-Kabīr (12381), al-Ḥākim (2/223), and Ibn Jarīr al-Ṭabarī in his Tafsīr (3/189).","chapter_en":"The Qurʾān Descended All at Once on Laylat al-Qadr to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās, may Allah be pleased with them, said: “The Qurʾān was sent down all at once from al-Dhikr on the twenty-fourth night of Ramaḍān and was placed in Bayt al-ʿIzzah.”"]},"buhuth":{"en":["In another narration:","“Then Jibrīl began descending with it to the Prophet ﷺ, reciting it in measured recitation.”"]},"intro":{"ar":["قال الله تعالى:","﴿إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾","[القدر: ١]","وقال تعالى:","﴿شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ﴾","[البقرة: ١٨٥]","أي: إنه نزل في ليلة القدر من اللوح المحفوظ إلى السماء الدنيا، ثم أُنزل على النبي ﷺ على ما أراد الله إنزاله إليه.","جاء ذلك عن ابن عباس رضي الله عنهما من طرق كثيرة، ولم نجد له مخالفاً من أحد من الصحابة، ومن هذه الطرق:"],"en":["Allah Most High said:","“Indeed, We sent it down on the Night of Decree.”","[Sūrat al-Qadr 97:1]","And He said:","“Ramaḍān is the month in which the Qurʾān was sent down.”","[Sūrat al-Baqarah 2:185]","That is, it descended on Laylat al-Qadr from the Preserved Tablet to the lowest heaven, and thereafter it was sent down to the Prophet ﷺ according to what Allah willed to reveal to him.","This has been reported from Ibn ʿAbbās may Allah be pleased with them through numerous routes, and the manuscript states that no opposing report from any of the Companions has been found. Among these routes are the following:"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في الكبرى (7937)، والطبراني في الكبير (12381)، والحاكم (4216)، وابن جرير الطبري في تفسيره (736)."},{"num":663,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: أُنْزِلَ الْقُرْآنُ جُمْلَةً وَاحِدَةً إِلَى السَّمَاءِ الدُّنْيَا لَيْلَةَ الْقَدْرِ. ثُمَّ أُنْزِلَ بَعْدَ ذَلِكَ فِي عِشْرِينَ سَنَةً: ﴿وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَاكَ بِالْحَقِّ وَأَحْسَنَ تَفْسِيرًا﴾ [سورة الفرقان: 33]."],"takhrij":"صحيح: رواه النسائيّ في السنن الكبرى (7935)، وفي فضائل القرآن (14)، والحاكم (2879)،  واللّفظ له، كلاهما من حديث داود بن أبي هند، عن عكرمة، عن ابن عباس، فذكره. وفي لفظ للنسائيّ: فَكَانَ إِذَا أَرَادَ اللهُ أَنْ يُحْدِثَ شَيْئًا نَزَّلَ فَكَانَ بَيْنَ أَوَّلِهِ وَآخِرِهِ عِشْرِينَ سَنَةً.","grade":"صحيح","chapter_ar":"باب نزول القرآن جملة واحدة في ليلة القدر إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī in al-Sunan al-Kubrā (7935), in Faḍāʾil al-Qurʾān (14), and al-Ḥākim (2879), whose wording this is.","chapter_en":"The Qurʾān Descended All at Once on Laylat al-Qadr to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, said: “The Qurʾān was sent down all at once to the lowest heaven on Laylat al-Qadr, then it was sent down after that over twenty years: ‘They do not bring you any argument except that We bring you the truth and the best explanation.’” [Sūrat al-Furqān 25:33]"]},"buhuth":{"en":["In a wording of al-Nasāʾī:","“Whenever Allah willed to bring about something, it would descend; and between its beginning and its end were twenty years.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في السنن الكبرى (7935)، وفي فضائل القرآن (14)، والحاكم (2879)، واللفظ له."},{"num":664,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: نَزَلَ الْقُرْآنُ كلّه جُمْلَةً وَاحِدَةً فِي لَيْلَةِ الْقَدْرِ إِلَى هَذِهِ السَّمَاءِ الدُّنْيَا، فَكَانَ اللَّهُ إِذَا أَرَادَ أَنْ يُحْدِثَ فِي الْأَرْضِ شَيْئًا أَنْزَلَهُ مِنْهُ حَتَّى جَمَعَهُ."],"takhrij":"صحيح: رواه ابن جرير الطّبريّ في تفسيره (8154)، والحاكم (2877)، وعنه البيهقيّ في الأسماء والصفات (498) عن ابن المثنى، قال: ثنا عبدالأعلى، قال: ثنا داود، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب نزول القرآن جملة واحدة في ليلة القدر إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Jarīr al-Ṭabarī in his Tafsīr (24/542) and al-Ḥākim (2877).","chapter_en":"The Qurʾān Descended All at Once on Laylat al-Qadr to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, said: “The entire Qurʾān descended all at once on Laylat al-Qadr in Ramaḍān to the lowest heaven. Then whenever Allah willed to bring about something upon the earth, He would send down from it until it was completed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن جرير الطبري في تفسيره (8154)، والحاكم (2877)."},{"num":665,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ فِي قَوْلِهِ تَعَالَى: ﴿إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾ قَالَ: أُنْزِلَ الْقُرْآنُ جُمْلَةً وَاحِدَةً فِي لَيْلَةِ الْقَدْرِ إِلَى السَّمَاءِ الدُّنْيَا، فَكَانَ بِمَوْقِعِ النُّجُومِ، فَكَانَ اللَّهُ يُنَزِّلُهُ عَلَى رَسُولِهِ بَعْضَهُ أَثَرِ بَعْضٍ."],"takhrij":"صحيح: رواه ابن جرير في تفسيره (8154)، والنسائيّ في السنن الكبرى (11689)، وابن الضريس في فضائل القرآن، والحاكم (2878) كلّهم من طريق جرير، عن منصور، عن سعيد بن جبير، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب نزول القرآن جملة واحدة في ليلة القدر إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Jarīr in his Tafsīr (24/543) and al-Nasāʾī in al-Sunan al-Kubrā (11689).","chapter_en":"The Qurʾān Descended All at Once on Laylat al-Qadr to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them said concerning the statement of Allah Most High: “Indeed, We sent it down on the Night of Decree.” [Sūrat al-Qadr 97:1] “The Qurʾān was sent down all at once on Laylat al-Qadr to the lowest heaven. Thereafter, it descended according to the positions of the stars, and Allah would send portions of it down to His Messenger one after another.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن جرير في تفسيره (8154)، والنسائي في السنن الكبرى (11689)."},{"num":666,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَالَ لَهُ رَجُلٌ: أَنَّهُ وَقَعَ فِي قَلْبِي الشَّكُّ مِنْ قَوْلِ اللَّهِ تَعَالَى: ﴿شَهْرُ رَمَضَانَ الَّذِي أُنْزِلَ فِيهِ الْقُرْآنُ﴾ [سورة البقرة: 185]، وَقَوْلُهُ تَعَالَى: ﴿إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةٍ مُبَارَكَةٍ﴾ [الدخان: 3]، وَقَوْلُهُ تَعَالَى: ﴿إِنَّا أَنْزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ﴾ [سورة القدر: 1]، وَقَدْ أُنْزِلَ فِي شَوَّالَ، وَفِي ذِي الْقِعْدَةِ وغيره؟! قَالَ: إنّما نَزَلَ فِي رَمَضَانَ، فِي لَيْلَةِ الْقَدْرِ وَفِي لَيْلَةٍ مُبَارَكَةٍ جُمْلَةً وَاحِدَةً، ثُمَّ أُنْزِلَ عَلَى مَوَاقِعِ النُّجُومَ رَتَّلَا فِي الشُّهُورِ وَالْأَيَّامِ... (فَذَكَرَ الْحَدِيثَ)."],"takhrij":"حسن: رواه ابن جرير الطّبريّ (737)، وابن أبي حاتم في تفسيره (1/310)، والبيهقيّ في الأسماء والصّفات (501) كلّهم من طريق عبيد الله بن موسى، عن إسرائيل، عن السُّديّ، عن محمد بن أبي المجالد، عن مقسم، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"باب نزول القرآن جملة واحدة في ليلة القدر إلى السماء الدنيا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Jarīr al-Ṭabarī (3/192) and Ibn Abī Ḥātim (1/310).","chapter_en":"The Qurʾān Descended All at Once on Laylat al-Qadr to the Lowest Heaven","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["A man said to Ibn ʿAbbās may Allah be pleased with them: “Doubt has entered my heart because of Allah’s statement: ‘Ramaḍān is the month in which the Qurʾān was sent down,’ [Sūrat al-Baqarah 2:185] and His statement: ‘Indeed, We sent it down on a blessed night,’ [Sūrat al-Dukhān 44:3] and His statement: ‘Indeed, We sent it down on the Night of Decree,’ [Sūrat al-Qadr 97:1] yet Allah also revealed portions of it during Shawwāl, Dhū al-Qaʿdah, and other months.” Ibn ʿAbbās replied: “It was sent down in Ramaḍān, on Laylat al-Qadr — the blessed night — all at once. Thereafter, it was sent down according to the positions of the stars, in successive portions throughout the months and days.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن جرير الطبري (737)، وابن أبي حاتم (1/310)."},{"num":667,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: بُعِثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَرْبَعِينَ سَنَةً، فَمَكُثَ بِمَكَّةَ ثَلَاثَ عَشْرَةَ سَنَةً يُوحَى إِلَيْهِ، ثُمَّ أُمِرَ بِالْهِجْرَةِ فَهَاجَرَ عَشْرَ سِنِينَ، وَمَاتَ وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ."],"takhrij":"متفق عليه: رواه البخاريّ في الفضائل (3902) عن مطر بن فضل، حدّثنا روح، حدّثنا هشام، حدّثنا عكرمة، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب مدة نزول القرآن على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3902) and Muslim (2351).","chapter_en":"The Duration of the Revelation of the Qurʾān to the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, said: “The Messenger of Allah ﷺ was sent as a Prophet at the age of forty. He remained in Makkah for thirteen years receiving revelation. Then he was commanded to migrate, and he lived for ten years after the migration, and he died at the age of sixty-three.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8554,8659],"tks":"متفق عليه: رواه البخاري (3902)، ومسلم (2351)."},{"num":668,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: أُنْزِلَ الْقُرْآنُ جُمْلَةً وَاحِدَةً إِلَى السَّمَاءِ الدُّنْيَا لَيْلَةَ الْقَدْرِ . أُنْزِلَ بَعْدَ ذَلِكَ فِي عِشْرِينَ سَنَةً: ﴿وَلَا يَأْتُونَكَ بِمَثَلٍ إِلَّا جِئْنَاكَ بِالْحَقِّ وَأَحْسَنَ تَفْسِيرًا﴾ [سورة الفرقان: 33]، ﴿وَقُرْآنًا فَرَقْنَاهُ لِتَقْرَأَهُ عَلَى النَّاسِ عَلَى مُكْثٍ وَنَزَّلْنَاهُ تَنْزِيلًا﴾ [سورة الإسراء: 106]."],"takhrij":"صحيح: رواه النسائيّ في الكبرى (7935)، والحاكم (2879)، كلاهما من طريق داود بن أبي هند، عن عكرمة، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب مدة نزول القرآن على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī in al-Sunan al-Kubrā (7935) and al-Ḥākim (2879).","chapter_en":"The Duration of the Revelation of the Qurʾān to the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, said: “The Qurʾān was sent down all at once to the lowest heaven on the Night of Decree. Thereafter, it was sent down over twenty years: ‘They do not bring you any argument except that We bring you the truth and the best explanation.’ [Sūrat al-Furqān 25:33] ‘And a Qurʾān which We have separated so that you may recite it to the people over time, and We have sent it down in stages.’” [Sūrat al-Isrāʾ 17:106]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي في الكبرى (7935)، والحاكم (2879)."},{"num":669,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةُ، وَابْنُ عَبَّاسٍ قَالَا: لَبِثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ عَشْرَ سِنِينَ يَنْزِلُ عَلَيْهِ الْقُرْآنُ، وَبِالْمَدِينَةِ عَشْرًا."],"takhrij":"صحيح: رواه البخاريّ في فضائل القرآن (4978، 4979) من طريق شيبان، عن يحيى، عن أبي سلمة، قال: أخبرتني عائشة، وابن عباس، فذكراه.","grade":"صحيح","chapter_ar":"باب مدة نزول القرآن على النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4978, 4979).","chapter_en":"The Duration of the Revelation of the Qurʾān to the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["ʿĀʾishah and Ibn ʿAbbās, may Allah be pleased with them, said: “The Prophet ﷺ remained in Makkah for ten years while the Qurʾān was being revealed to him, and in Madinah for ten years.” Regarding the words: “Ten years,” what is relied upon is that the Prophet ﷺ lived for sixty-three years. Reports differing from this may either disregard fractional portions of years or round portions of months. Regarding this narration and the one preceding it, they may be reconciled by noting that he was commissioned as a Prophet upon completing forty years of age. The period of true dreams lasted six months until the angel came to him in Ramaḍān. Revelation then paused, after which it became continuous and successive. Thus, its period of continuous and successive revelation in Makkah, excluding the pause, was ten years."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11740],"tks":"صحيح: رواه البخاري (4978، 4979)."},{"num":670,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّمَا مَثَلُ صَاحِبِ الْقُرْآنِ كَمَثَلِ صَاحِبِ الْإِبِلِ الْمُعَقَّلَةِ، إِنْ عَاهَدَ عَلَيْهَا أَمْسَكَهَا، وَإِنْ أَطْلَقَهَا ذَهَبَتْ."],"takhrij":"متفق عليه: رواه مالك في القرآن (6) عن نافع، عن عبدالله بن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب استذكار القرآن وتعاهده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Qurʾān (6), al-Bukhārī (5031), and Muslim (789).","chapter_en":"Reviewing the Qurʾān and Maintaining It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “The example of the companion of the Qurʾān is like the owner of tethered camels: if he keeps careful watch over them, he retains them; but if he releases them, they go away.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (6)، والبخاري (5031)، ومسلم (789)."},{"num":671,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّمَا مَثَلُ الْقُرْآنِ كَمَثَلِ الْإِبِلِ الْمُعَقَّلَةِ، إِذَا عَاهَدَهَا صَاحِبُهَا عَلَى عُقُلِهَا أَمْسَكَهَا، وَإِذَا أَغْفَلَهَا ذَهَبَتْ، إِذَا قَامَ صَاحِبُ الْقُرْآنِ فَقَرَأَهُ بِاللَّيْلِ وَالنَّهَارِ ذَكَرَهُ، وَإِذَا لَمْ يَقْرَأْهُ نَسِيَهُ."],"takhrij":"صحيح: رواه النسائي في الكبرى (7989) عن قتيبة بن سعيد، حدثنا يعقوب بن عبدالرحمن، عن موسى بن عقبة، عن ابن عمر قال: فذكره.","grade":"صحيح","chapter_ar":"باب استذكار القرآن وتعاهده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Nasāʾī in al-Sunan al-Kubrā (7989) and Muslim (789:227).","chapter_en":"Reviewing the Qurʾān and Maintaining It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “The example of the Qurʾān is like tethered camels. If their owner keeps careful watch over their tethers, he retains them; but if he neglects them, they go away.”"]},"buhuth":{"en":["Muslim adds:","“If the companion of the Qurʾān stands and recites it by night and by day, he remembers it; but if he does not recite it, he forgets it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11850],"tks":"صحيح: رواه النسائي في الكبرى (7989)، ومسلم (789: 227)."},{"num":672,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: أَمَرَ عُثْمَانُ زَيْدَ بْنَ ثَابِتٍ وسَعِيدَ بْنَ الْعَاصِ وعَبْدَ اللَّهِ بْنَ الزُّبَيْرِ وعَبْدَ الرَّحْمَنِ بْنَ الْحَارِثِ بْنِ هِشَامٍ أَنْ يَنْسَخُوهَا فِي الْمَصَاحِفِ، وَقَالَ لَهُمْ: إِذَا اخْتَلَفْتُمْ أَنْتُمْ وزَيْدُ بْنُ ثَابِتٍ فِي عَرَبِيَّةٍ مِنْ عَرَبِيَّةِ الْقُرْآنِ، فَاكْتُبُوهَا بِلِسَانِ قُرَيْشٍ، فَإِنَّ الْقُرْآنَ أُنْزِلَ بِلِسَانِهِمْ فَفَعَلُوا."],"takhrij":"صحيح:  رواه البخاريّ في فضائل القرآن (4984) عن أبي اليمان، حدّثنا شعيب، عن الزّهريّ. وأخبرني أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب أن القرآن نزل بلسان عربي مبين وبلسان قريش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4984).","chapter_en":"The Qurʾān Was Revealed in a Clear Arabic Tongue and in the Dialect of Quraysh","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, said: “ʿUthmān ordered Zayd ibn Thābit, Saʿīd ibn al-ʿĀṣ, ʿAbdullāh ibn al-Zubayr, and ʿAbd al-Raḥmān ibn al-Ḥārith ibn Hishām to copy it into the muṣḥafs. He said to them: ‘If you and Zayd ibn Thābit differ concerning any Arabic expression of the Qurʾān, write it in the dialect of Quraysh, for the Qurʾān was revealed in their dialect.’ So they did so.”"]},"intro":{"ar":["قال الله تعالى:","﴿نَزَلَ بِهِ الرُّوحُ الْأَمِينُ ۝ عَلَى قَلْبِكَ لِتَكُونَ مِنَ الْمُنْذِرِينَ ۝ بِلِسَانٍ عَرَبِيٍّ مُبِينٍ﴾","[الشعراء: ١٩٣–١٩٥]","وقال تعالى:","﴿وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ قُرْآنًا عَرَبِيًّا لِتُنْذِرَ أُمَّ الْقُرَى وَمَنْ حَوْلَهَا﴾","[الشورى: ٧]"],"en":["Allah Most High said:","“The Trustworthy Spirit brought it down upon your heart so that you may be among the warners, in a clear Arabic tongue.”","[Sūrat al-Shuʿarāʾ 26:193–195]","And He said:","“And thus We have revealed to you an Arabic Qurʾān so that you may warn the Mother of Cities and those around it.”","[Sūrat al-Shūrā 42:7]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4984)."},{"num":673,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ حَدَّثَهُ أَنَّ حُذَيْفَةَ بْنَ الْيَمَانِ قَدِمَ عَلَى عُثْمَانَ، وَكَانَ يُغَازِي أَهْلَ الشَّأْمِ فِي فَتْحِ إِرْمِينِيَةَ وَأَذْرَبِيجَانَ مَعَ أَهْلِ الْعِرَاقِ، فَأَفْزَعَ حُذَيْفَةَ اخْتِلَافُهُمْ فِي الْقِرَاءَةِ، فَقَالَ حُذَيْفَةُ لِعُثْمَانَ: يَا أَمِيرَ الْمُؤْمِنِينَ، أَدْرِكْ هَذِهِ الْأُمَّةَ قَبْلَ أَنْ يَخْتَلِفُوا فِي الْكِتَابِ اخْتِلَافَ الْيَهُودِ وَالنَّصَارَى، فَأَرْسَلَ عُثْمَانُ إِلَى حَفْصَةَ، أَنْ أَرْسِلِي إِلَيْنَا بِالصُّحُفِ نَنْسَخُهَا فِي الْمَصَاحِفِ ثُمَّ نَرُدُّهَا إِلَيْكِ، فَأَرْسَلَتْ بِهَا حَفْصَةُ إِلَى عُثْمَانَ، فَأَمَرَ زَيْدَ بْنَ ثَابِتٍ وعَبْدَ اللَّهِ بْنَ الزُّبَيْرِ وسَعِيدَ بْنَ الْعَاصِ وعَبْدَ الرَّحْمَنِ بْنَ الْحَارِثِ بْنِ هِشَامٍ فَنَسَخُوهَا فِي الْمَصَاحِفِ، وَقَالَ عُثْمَانُ لِلرَّهْطِ الْقُرَشِيِّينَ الثَّلَاثَةِ: إِذَا اخْتَلَفْتُمْ أَنْتُمْ وزَيْدُ بْنُ ثَابِتٍ فِي شَيْءٍ مِنَ الْقُرْآنِ، فَاكْتُبُوهُ بِلِسَانِ قُرَيْشٍ، فَإِنَّمَا نَزَلَ بِلِسَانِهِمْ، فَفَعَلُوا حَتَّى إِذَا نَسَخُوا الصُّحُفَ فِي الْمَصَاحِفِ رَدَّ عُثْمَانُ الصُّحُفَ إِلَى حَفْصَةَ، وَأَرْسَلَ إِلَى كُلِّ أُفُقٍ بِمُصْحَفٍ مِمَّا نَسَخُوا، وَأَمَرَ بِمَا سِوَاهُ مِنَ الْقُرْآنِ فِي كُلِّ صَحِيفَةٍ أَوْ مُصْحَفٍ أَنْ يُحْرَقَ."],"takhrij":"صحيح: رواه البخاريّ في فضائل القرآن (4987) عن موسى، حدّثنا إبراهيم، حدّثنا ابنُ شهاب، أنّ أنس بن مالك، قال (فذكره).","grade":"صحيح","chapter_ar":"باب أن القرآن نزل بلسان عربي مبين وبلسان قريش","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4987).","chapter_en":"The Qurʾān Was Revealed in a Clear Arabic Tongue and in the Dialect of Quraysh","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: “Ḥudhayfah ibn al-Yamān came to ʿUthmān while he had been campaigning with the people of al-Shām in the conquest of Armenia and Azerbaijan alongside the people of Iraq. Ḥudhayfah became alarmed by their differences in recitation. Ḥudhayfah said to ʿUthmān: ‘O Commander of the Believers, save this Ummah before they differ concerning the Book as the Jews and Christians differed.’ So ʿUthmān sent word to Ḥafṣah: ‘Send us the written sheets so that we may copy them into the muṣḥafs, then we will return them to you.’ Ḥafṣah sent them to ʿUthmān, and he ordered Zayd ibn Thābit, ʿAbdullāh ibn al-Zubayr, Saʿīd ibn al-ʿĀṣ, and ʿAbd al-Raḥmān ibn al-Ḥārith ibn Hishām to copy them into the muṣḥafs. ʿUthmān said to the three Qurashī men: ‘If you and Zayd ibn Thābit differ concerning anything in the Qurʾān, write it in the dialect of Quraysh, for it was revealed in their dialect.’ They did so. When they had copied the sheets into the muṣḥafs, ʿUthmān returned the sheets to Ḥafṣah and sent to every region a muṣḥaf from those they had copied. He ordered that every other sheet or muṣḥaf containing Qurʾānic material besides these be burned.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4987)."},{"num":674,"demo":false,"sanad":"","matn":["عَنْ مَسْرُوقٍ قَالَ: ذَكَرُوا عَبْدِ اللَّهِ بْنِ مَسْعُودٍ عِنْدَ عَبْدِ اللَّهِ بْنِ عَمْرٍو فَقَالَ: ذَاكَ رَجُلٌ لَا أَزَالُ أُحِبُّهُ بَعْدَمَا سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: اسْتَقْرِئُوا الْقُرْآنَ مِنْ أَرْبَعَةٍ: مِنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، وَسَالِمٍ مَوْلَى أَبِي حُذَيْفَةَ، وَأُبَيِّ بْنِ كَعْبٍ، وَمُعَاذِ بْنِ جَبَلٍ."],"takhrij":"متفق عليه: رواه البخاريّ في فضائل القرآن (4999)، ومسلم في فضائل الصحابة (2464) كلاهما من حديث شعبة، عن عمرو بن مرّة، عن إبراهيم، عن مسروق، فذكره، واللّفظ لمسلم، ولفظ البخاري نحوه.","grade":"متفق عليه","chapter_ar":"باب القراء من أصحاب النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4999) and Muslim (2464).","chapter_en":"The Reciters Among the Companions of the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Masrūq reported: Ibn Masʿūd was mentioned in the presence of ʿAbdullāh ibn ʿAmr may Allah be pleased with them, and he said: “He is a man whom I will continue to love after I heard the Messenger of Allah ﷺ say: ‘Learn the recitation of the Qurʾān from four: Ibn Masʿūd, Sālim the freedman of Abū Ḥudhayfah, Ubayy ibn Kaʿb, and Muʿādh ibn Jabal.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4999)، ومسلم (2464)."},{"num":675,"demo":false,"sanad":"","matn":["عَنْ قَتَادَةَ قَالَ: سَأَلْتُ أَنَسَ بْنَ مَالِكٍ: مَنْ جَمَعَ الْقُرْآنَ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: أَرْبَعَةٌ كُلُّهُمْ مِنْ الْأَنْصَارِ: أُبَيُّ بْنُ كَعْبٍ، ومُعَاذُ بْنُ جَبَلٍ، وزَيْدُ بْنُ ثَابِتٍ، وأَبُو زَيْدٍ."],"takhrij":"متفق عليه: رواه البخاريّ في فضائل القرآن (5003) عن حفص بن عمر، حدّثنا همام، حدّثنا، قتادة، قال: سألتُ أنساً، فذكره.","grade":"متفق عليه","chapter_ar":"باب القراء من أصحاب النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5003, 3810) and Muslim (2465).","chapter_en":"The Reciters Among the Companions of the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Qatādah reported: I asked Anas ibn Mālik may Allah be pleased with him: “Who compiled the Qurʾān during the lifetime of the Prophet ﷺ?” He replied: “Four, all of them from the Anṣār: Ubayy ibn Kaʿb, Muʿādh ibn Jabal, Zayd ibn Thābit, and Abū Zayd.”"]},"buhuth":{"en":["Qatādah said:","“I asked Anas ibn Mālik:","‘Who was Abū Zayd?’","He replied:","‘One of my paternal uncles.’”","These were four from the Anṣār. Earlier, two from the Muhājirūn and two from the Anṣār were mentioned. This indicates that the Prophet ﷺ made these statements at different times, and therefore there is no contradiction between these narrations."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5003، 3810)، ومسلم (2465)."},{"num":676,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: مَاتَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلَمْ يَجْمَعِ الْقُرْآنَ غَيْرُ أَرْبَعَةٍ: أَبُو الدَّرْدَاءِ، وَمُعَاذُ بْنُ جَبَلٍ، وَزَيْدُ بْنُ ثَابِتٍ، وَأَبُو زَيْدٍ، قَالَ: وَنَحْنُ وَرِثْنَاهُ."],"takhrij":"صحيح: رواه البخاريّ في فضائل القرآن (5004) عن معلى بن أسد، حدّثنا عبدالله بن المثنى، قال: حدّثني ثابت البنانيّ وثمامة، عن أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب القراء من أصحاب النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (5004).","chapter_en":"The Reciters Among the Companions of the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, said: “The Prophet ﷺ died, and none had compiled the Qurʾān except four: Abū al-Dardāʾ, Muʿādh ibn Jabal, Zayd ibn Thābit, and Abū Zayd.” He added: “And we inherited Abū Zayd.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5004)."},{"num":677,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا قَامَ أَحَدُكُمْ مِنَ اللَّيْلِ فَاسْتَعْجَمَ الْقُرْآنُ عَلَى لِسَانِهِ فَلَمْ يَدْرِ مَا يَقُولُ فَلْيَضْطَجِعْ."],"takhrij":"صحيح: رواه مسلم في المسافرين (787) عن محمد بن رافع، حدّثنا عبدالرزّاق، حدّثنا معمر، عن همام بن منبه، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب إذا استعجم القرآن على اللسان في قيام الليل فليضطجع","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (787).","chapter_en":"If the Qurʾān Becomes Unclear on One’s Tongue During the Night Prayer, Let Him Lie Down","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “If one of you stands in prayer at night and the Qurʾān becomes confused upon his tongue so that he does not know what he is saying, then let him lie down.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (787)."},{"num":678,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: نَهَى رَسُولُ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنْ يُسَافَرَ بِالْقُرْآنِ إِلَى أَرْضِ الْعَدُوِّ.","قَالَ مَالِك: وَإِنَّمَا ذَلِكَ مَخَافَةَ أَنْ يَنَالَهُ الْعَدُوُّ."],"takhrij":"متفق عليه: رواه مالك في الجهاد (7) عن نافع، عن عبدالله بن عمر، فذكره","grade":"متفق عليه","chapter_ar":"باب كراهية السفر بالقرآن إلى أرض العدو","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (6), al-Bukhārī (2990), and Muslim (1869).","chapter_en":"The Dislike of Traveling With the Qurʾān to Enemy Territory","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالكتب المنزلة من الله عز وجل","group_en":"Collection of Chapters Concerning Belief in the Books Revealed by Allah, Mighty and Majestic","part_no":2,"group_no":7,"chapter_no":14,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar, may Allah be pleased with them, said: “The Messenger of Allah ﷺ prohibited traveling with the Qurʾān into enemy territory.” Mālik said:","“This was only out of fear that the enemy might obtain it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (7)، والبخاري (2990)، ومسلم (1869)."},{"num":679,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ ّرَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنَ الأَنْبِيَاءِ مِنْ نَبِيٍّ، إِلَّا قَدْ أُعْطِيَ مِنَ الآيَاتِ مَا مِثْلُهُ، آمَنَ عَلَيْهِ الْبَشَرُ، وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَى اللَّهُ إِلَيَّ، فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في فضائل القرآن (4981)، ومسلم في الإيمان (152) كلاهما من حديث اللّيث، عن سعيد بن أبي سعيد المقبريّ، عن أبيه، عن أبي هريرة، فذكره. واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب ما من نبي إلا وقد أُعطي من المعجزات ما آمن عليها البشر","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4981) and Muslim (152).","chapter_en":"No Prophet Was Sent Except That He Was Given Miracles by Which People Believed","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “There was no prophet among the prophets except that he was given signs the like of which caused people to believe. What I have been given, however, is revelation which Allah revealed to me, and therefore I hope that I will have the greatest number of followers among them on the Day of Resurrection.”"]},"buhuth":{"en":["The wording is that of al-Bukhārī.","That is, every prophet was given miracles comparable to those given to prophets before him, through which people believed. As for the great and manifest miracle of the Prophet ﷺ, it is the Qurʾān, the like of which no one before him was given."]},"intro_majmu":{"ar":["قال الله تعالى:","﴿إِنَّ الَّذِينَ يَكْفُرُونَ بِاللهِ وَرُسُلِهِ وَيُرِيدُونَ أَنْ يُفَرِّقُوا بَيْنَ اللهِ وَرُسُلِهِ وَيَقُولُونَ نُؤْمِنُ بِبَعْضٍ وَنَكْفُرُ بِبَعْضٍ وَيُرِيدُونَ أَنْ يَتَّخِذُوا بَيْنَ ذَلِكَ سَبِيلًا ۝ أُولَئِكَ هُمُ الْكَافِرُونَ حَقًّا وَأَعْتَدْنَا لِلْكَافِرِينَ عَذَابًا مُهِينًا ۝ وَالَّذِينَ آمَنُوا بِاللهِ وَرُسُلِهِ وَلَمْ يُفَرِّقُوا بَيْنَ أَحَدٍ مِنْهُمْ أُولَئِكَ سَوْفَ يُؤْتِيهِمْ أُجُورَهُمْ وَكَانَ اللهُ غَفُورًا رَحِيمًا﴾","[النساء: ١٥٠–١٥٢]","وقال تعالى:","﴿رُسُلًا مُبَشِّرِينَ وَمُنْذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى اللهِ حُجَّةٌ بَعْدَ الرُّسُلِ وَكَانَ اللهُ عَزِيزًا حَكِيمًا﴾","[النساء: ١٦٥]"],"en":["Allah Most High said:","“Indeed, those who disbelieve in Allah and His messengers and wish to make a distinction between Allah and His messengers, saying, ‘We believe in some and disbelieve in others,’ wishing to take a way in between — those are truly the disbelievers, and We have prepared for the disbelievers a humiliating punishment.","As for those who believe in Allah and His messengers and make no distinction between any of them, He will give them their rewards. And Allah is Most Forgiving, Most Merciful.”","[Sūrat al-Nisāʾ 4:150–152]","And He said:","“Messengers as bearers of glad tidings and warners, so that mankind would have no argument against Allah after the messengers. And Allah is Mighty, All-Wise.”","[Sūrat al-Nisāʾ 4:165]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12025,12988,15657],"tks":"متفق عليه: رواه البخاري (4981)، ومسلم (152)."},{"num":680,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: عُرِضَتْ عَلَيَّ الأُمَمُ، فَرَأَيْتُ النَّبِيَّ وَمَعَهُ الرُّهَيْطُ، وَالنَّبِيَّ وَمَعَهُ الرَّجُلُ وَالرَّجُلَانِ، وَالنَّبِيَّ لَيْسَ مَعَهُ أَحَدٌ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6541)، ومسلم في الإيمان (220: 374) كلاهما من حديث هشيم، أخبرنا حصين بن عبد الرحمن قال: كنت عند سعيد بن جبير، فقال: حدثني ابن عباس قال فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب من الأنبياء من لم يصدقه من أمته إلا رجل واحد، ومنهم من لم يصدقه أحد","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6541) and Muslim (220:374).","chapter_en":"Among the Prophets Were Those Whom Only One Man From Their Nation Believed, and Others Whom No One Believed","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Prophet ﷺ said: “The nations were presented before me. I saw a prophet accompanied by a small group, another prophet accompanied by one or two men, and another prophet with no one accompanying him.”"]},"buhuth":{"en":["The wording above is that of Muslim.","Al-Bukhārī’s wording is:","“The nations were presented before me. A prophet would pass with an entire nation accompanying him; another prophet would pass with a small group; another prophet would pass with ten people; another prophet with five; and another prophet would pass alone.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6541)، ومسلم (220: 374)."},{"num":681,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَا أَوَّلُ شَفِيعٍ فِي الْجَنَّةِ، لَمْ يُصَدَّقْ نَبِيٌّ مِنَ الأَنْبِيَاءِ مَا صُدِّقْتُ، وَإِنَّ مِنَ الأَنْبِيَاءِ نَبِيًّا، مَا يُصَدِّقُهُ مِنْ أُمَّتِهِ، إِلَّا رَجُلٌ وَاحِدٌ."],"takhrij":"صحيح: رواه مسلم في الإيمان (196: 332) عن أبي بكر بن أبي شيبة، حدّثنا حسين بن علي، عن زائدة، عن المختار بن فُلفل، قال: قال أنس بن مالك، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب من الأنبياء من لم يصدقه من أمته إلا رجل واحد، ومنهم من لم يصدقه أحد","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (196:332).","chapter_en":"Among the Prophets Were Those Whom Only One Man From Their Nation Believed, and Others Whom No One Believed","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Prophet ﷺ said: “I will be the first intercessor concerning Paradise. No prophet among the prophets was believed by as many people as believed me, and indeed, among the prophets was a prophet whom only one man from his nation believed.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (196: 332)."},{"num":682,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ إِذَا أَرَادَ رَحْمَةَ أُمَّةٍ مِنْ عِبَادِهِ، قَبَضَ نَبِيَّهَا قَبْلَهَا، فَجَعَلَهُ لَهَا فَرَطًا وَسَلَفًا، وَإِذَا أَرَادَ هَلَكَةَ أُمَّةٍ عَذَّبَهَا وَنَبِيُّهَا حَيٌّ، فَأَقَرَّ عَيْنَهُ بِهَلَكَتِهَا حِينَ كَذَّبُوهُ وَعَصَوْا أَمْرَهُ."],"takhrij":"صحيح: رواه ابن حبان (6647) عن محمد بن المسيب بن اسحاق، حدثنا ابراهيم بن سعيد الجوهري، حدثنا أبو أسامة، حدثنا بُريد، عن أبي بردة، عن أبي موسى فذكره.","grade":"صحيح","chapter_ar":"باب أن الله إذا أراد رحمة أمة قبض نبيها قبلها","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Ḥibbān (6647). Muslim (2288) also mentioned part of it.","chapter_en":"When Allah Intends Mercy for a Nation, He Takes Its Prophet Before It","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Abū Mūsā may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “When Allah intends mercy for a nation among His servants, He takes its Prophet before them and makes him a forerunner and predecessor for them. But when He intends the destruction of a nation, He punishes them while their Prophet is still alive, thereby bringing comfort to his eyes through their destruction after they denied him and disobeyed his command.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (6647)، وذكر مسلم (2288) منه طرفا."},{"num":683,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَرَرْتُ عَلَى مُوسَى لَيْلَةَ أُسْرِيَ بِي، عِنْدَ الْكَثِيبِ الْأَحْمَرِ، وَهُوَ قَائِمٌ يُصَلِّي فِي قَبْرِهِ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2375) من طرق عن حماد بن سلمة، عن ثابت البنانيّ، وسليمان التيميّ، عن أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب في الأنبياء أنهم أحياء في قبورهم يصلون","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2375).","chapter_en":"The Prophets Are Alive in Their Graves and Pray","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “On the night I was taken on the Night Journey, I passed by Moses near the red sandhill, and he was standing in his grave praying.”"]}},"tuhfa":{},"full":1,"rep":[3822],"tks":"صحيح: رواه مسلم (2375)."},{"num":684,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْأَنْبِيَاءُ أَحْيَاءٌ فِي قُبُورِهِمْ يُصَلُّونَ."],"takhrij":"صحيح: رواه أبو يعلى (3425) عن أبي الجهم الأزرق بن علي، ثنا يحيى بن أبي بكير، ثنا المستلم بن سعيد، عن الحجّاج، عن ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب في الأنبياء أنهم أحياء في قبورهم يصلون","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Yaʿlā (3425).","chapter_en":"The Prophets Are Alive in Their Graves and Pray","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The prophets are alive in their graves, praying.”"]},"buhuth":{"en":["This life is a life of the Barzakh and is not the same as worldly life in any respect. Therefore, their life in the grave should not be compared to the life of this world."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (3425)."},{"num":685,"demo":false,"sanad":"","matn":["عَنْ أَوْسِ بْنِ أَوْسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنْ أَفْضَلِ أَيَّامِكُمْ يَوْمَ الْجُمُعَةِ، فِيهِ خُلِقَ آدَمُ، وَفِيهِ قُبِضَ، وَفِيهِ النَّفْخَةُ، وَفِيهِ الصَّعْقَةُ، فَأَكْثِرُوا عَلَيَّ مِنَ الصَّلَاةِ فِيهِ فَإِنَّ صَلَاتَكُمْ مَعْرُوضَةٌ عَلَيَّ قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ، وَكَيْفَ تُعْرَضُ صَلَاتُنَا عَلَيْكَ وَقَدْ أَرِمْتَ؟ يَقُولُونَ: بَلِيتَ، فَقَالَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ عَلَى الْأَرْضِ أَجْسَادَ الْأَنْبِيَاءِ."],"takhrij":"صحيح: رواه أبو داود (1047) والنسائي (1374) وابن ماجة (1636) كلهم من طريق عبــد الرحمن بن يزيد بن جابر، عن أبي الأشعث الصنعاني، عن أوس بن أوس، قال: فذكره.","grade":"صحيح","chapter_ar":"باب إن الله حرَّم على الأرض أن تأكل أجساد الأنبياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (1047), al-Nasāʾī (1374), and Ibn Mājah (1636).","chapter_en":"Allah Has Forbidden the Earth From Consuming the Bodies of the Prophets","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Aws ibn Aws may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Indeed, among the best of your days is Friday. On it Adam was created, on it he died, on it the Trumpet will be blown, and on it the great swooning will occur. So send abundant blessings upon me on that day, for your blessings are presented to me.” They asked: “O Messenger of Allah, how will our blessings be presented to you after your body has decayed?” — meaning: after it has worn away. He replied: “Indeed, Allah, Mighty and Majestic, has forbidden the earth from consuming the bodies of the prophets.”"]},"buhuth":{"en":["It was also authenticated by Ibn Khuzaymah (1733), Ibn Ḥibbān (910), and al-Ḥākim (1/278)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3238,3821,10750,10873,16132],"tks":"صحيح: رواه أبو داود (1047)، والنسائي (1374)، وابن ماجه (1636)."},{"num":686,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ) قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَكَذَلِكَ الْأَنْبِيَاءُ تَنَامُ أَعْيُنُهُمْ وَلَا تَنَامُ قُلُوبُهُمْ..."],"takhrij":"متفق عليه: رواه البخاريّ في التوحيد (7517)، ومسلم في الإيمان (162) كلاهما من حديث سليمان بن بلال، عن شريك بن عبدالله، أنه قال: سمعتُ أنس بن مالك، فذكر الحديث بطوله في قصة الإسراء والمعراج، وسيأتي بكامله.","grade":"متفق عليه","chapter_ar":"باب من خصائص الأنبياء: تنام أعينهم ولا تنام قلوبهم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7517) and Muslim (162).","chapter_en":"Among the Special Characteristics of the Prophets: Their Eyes Sleep but Their Hearts Do Not","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Prophet ﷺ said: “Indeed, the prophets’ eyes sleep, but their hearts do not sleep.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7517)، ومسلم (162)."},{"num":687,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ (فَذَكَرَهَا فِي حَدِيثِ طَوِيل) قَالَتْ: قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عَائِشَةُ، إِنَّ عَيْنَيَّ تَنَامَانِ وَلَا يَنَامُ قَلْبِي."],"takhrij":"متفق عليه: رواه مالك في صلاة اللّيل (9) عن سعيد بن أبي سعيد المقبريّ، عن أبي سلمة بن عبدالرحمن بن عوف، أنّه سأل عائشة: كيف كانت صلاة رسول الله صلى الله عليه وسلم في رمضان؟ فقالت: (فذكرت الحديث بطوله)، وسيأتي في موضعه.","grade":"متفق عليه","chapter_ar":"باب من خصائص الأنبياء: تنام أعينهم ولا تنام قلوبهم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (9), al-Bukhārī (1147), and Muslim (738).","chapter_en":"Among the Special Characteristics of the Prophets: Their Eyes Sleep but Their Hearts Do Not","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Prophet ﷺ said: “O ʿĀʾishah, indeed my eyes sleep, but my heart does not sleep.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (9)، والبخاري (1147)، ومسلم (738)."},{"num":688,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّهُ قَالَ: لَمَّا صَلَّى رَكْعَتَيْ الْفَجْرِ، اضْطَجَعَ حَتَّى نَفَخَ، فَكُنَّا نَقُولُ لِعَمْرٍو إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: تَنَامُ عَيْنَايَ وَلَا يَنَامُ قَلْبِي."],"takhrij":"صحيح: رواه الإمام أحمد (1911) عن سفيان، عن عمرو، قال: أخبرنيّ كريب، عن ابن عباس، فذكره. وأصله في الصّحيحين، وسيأتي في كتاب الصّلاة.","grade":"صحيح","chapter_ar":"باب من خصائص الأنبياء: تنام أعينهم ولا تنام قلوبهم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (1911).","chapter_en":"Among the Special Characteristics of the Prophets: Their Eyes Sleep but Their Hearts Do Not","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: After the Prophet ﷺ prayed Fajr, he lay down until the sound of his breathing could be heard. So we used to say to ʿAmr: “Indeed, the Messenger of Allah ﷺ said: ‘My eyes sleep, but my heart does not sleep.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه الإمام أحمد (1911)."},{"num":689,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ) قَالَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: النَّبِيَّ الْأُمِّيَّ تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ."],"takhrij":"حسن: رواه الإمام أحمد (2514) عن هاشم بن القاسم، حدثنا عبدالحميد، حدّثنا شهر، قال: قال ابن عباس، فذكر الحديث مطوّلاً وقد مضى في الإيمان بالملائكة. وشهر فيه كلام إلا أنه توبع.","grade":"حسن","chapter_ar":"باب من خصائص الأنبياء: تنام أعينهم ولا تنام قلوبهم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan due to supporting narrations: Narrated by Imām Aḥmad (2514).","chapter_en":"Among the Special Characteristics of the Prophets: Their Eyes Sleep but Their Hearts Do Not","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Prophet ﷺ said: “A prophet’s eyes sleep, but his heart does not sleep.”"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه الإمام أحمد (2514)."},{"num":690,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم: تَنَامُ عَيْنِي، وَلَا يَنَامُ قَلْبِي."],"takhrij":"حسن: رواه الإمام أحمد (7417) عن يحيى بن سعيد، عن ابن عجلان، قال: سمعت أبي، عن أبي هريرة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب من خصائص الأنبياء: تنام أعينهم ولا تنام قلوبهم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (7417), Ibn Khuzaymah (48), and Ibn Ḥibbān (6386).","chapter_en":"Among the Special Characteristics of the Prophets: Their Eyes Sleep but Their Hearts Do Not","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “My eyes sleep, but my heart does not sleep.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (7417)، وابن خزيمة (48)، وابن حبان (6386)."},{"num":691,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ: أَنَّ رَجُلَا قَالَ: يَا رَسُولَ اللَّهِ، أَنَبِيٌّ كَانَ آدَمُ؟ قَالَ: نَعَمْ، مُكَلَّمٌ، قَالَ: فَكَمْ كَانَ بَيْنَهُ وَبَيْنَ نُوحٍ؟ قَالَ: عَشَرَةُ قُرُونٍ."],"takhrij":"صحيح: رواه ابن حبان في صحيحه (6190) عن محمد بن عمر بن يوسف، حدثنا محمد بن عبدالملك بن زنجويه، حدثنا أبو توبة، حدثنا معاوية بن سلام، عن أخيه زيد بن سلام، قال: سمعت أبا سلام، قال: سمعت أبا أمامة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في نبوة آدم عليه السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Ḥibbān in his Ṣaḥīḥ (6190) and Ibn Mandah in al-Tawḥīd (571).","chapter_en":"What Has Been Reported Concerning the Prophethood of Adam peace be upon him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Abū Umāmah, may Allah be pleased with him, reported: A man asked: “O Messenger of Allah, was Adam a prophet?” He replied: “Yes, a prophet to whom Allah spoke.” The man asked: “How much time was there between him and Noah?” He replied: “Ten generations.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8329,8355,11992],"tks":"صحيح: رواه ابن حبان في صحيحه (6190)، وابن منده في التوحيد (571)."},{"num":692,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَنْبَغِي لِعَبْدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ يُونُسَ بْنِ مَتَّى."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3416)، ومسلم في الفضائل (2376) كلاهما من حديث شعبة، عن سعد بن إبراهيم، سمعت حميد بن عبدالرحمن، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية المفاضلة بين الأنبياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3416) and Muslim (2376).","chapter_en":"What Has Been Reported Concerning the Dislike of Preferring One Prophet Over Another","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “It is not appropriate for a servant to say: ‘I am better than Jonah son of Mattā.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8417],"tks":"متفق عليه: رواه البخاري (3416)، ومسلم (2376)."},{"num":693,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَنْبَغِي لِعَبْدٍ أَنْ يَقُولَ: أَنَا خَيْرٌ مِنْ يُونُسَ بْنِ مَتَّى...(فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3395)، ومسلم في الفضائل (2377) كلاهما عن محمّد بن بشار، حدّثنا غندر محمد بن جعفر، حدّثنا شعبة، عن قتادة، قال: سمعت أبا العالية قال: حدّثنا ابنُ عمِّ نبيِّكم، يعني ابن عباس، ، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية المفاضلة بين الأنبياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3395) and Muslim (2377).","chapter_en":"What Has Been Reported Concerning the Dislike of Preferring One Prophet Over Another","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās may Allah be pleased with them reported that the Prophet ﷺ said: “It is not appropriate for a servant to say: ‘I am better than Jonah son of Mattā.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3395)، ومسلم (2377)."},{"num":694,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا يَنْبَغِي لِأَحَدٍ أَنْ يَقُولَ: أَنَا خَيْرٌ مِنْ يُونُسَ بْنِ مَتَّى."],"takhrij":"صحيح: رواه البخاريّ في التفسير (4603) عن مسعود، حدّثنا يحيى، عن سفيان، قال: حدّثني الأعمش، عن أبي وائل، عن عبدالله، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في كراهية المفاضلة بين الأنبياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (4603).","chapter_en":"What Has Been Reported Concerning the Dislike of Preferring One Prophet Over Another","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him reported that the Prophet ﷺ said: “No one should say: ‘I am better than Jonah son of Mattā.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4603)."},{"num":695,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تُخَيِّرُونِي عَلَى مُوسَى، فَإِنَّ النَّاسَ يَصْعَقُونَ يَوْمَ الْقِيَامَةِ فَأَصْعَقُ مَعَهُمْ، فَأَكُونُ أَوَّلَ مَنْ يُفِيقُ، فَإِذَا مُوسَى بَاطِشٌ جَانِبَ الْعَرْشِ، فَلَا أَدْرِي أَكَانَ فِيمَنْ صَعِقَ فَأَفَاقَ قَبْلِي، أَوْ كَانَ مِمَّنْ اسْتَثْنَى اللَّهُ."],"takhrij":"متفق عليه: رواه البخاريّ في الخصومات (2411)، ومسلم في فضائل موسى (2373: 160) كلاهما من حديث إبراهيم بن سعد، عن ابن شهاب، عن أبي سلمة وعبدالرحمن الأعرج، عن أبي هريرة، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية المفاضلة بين الأنبياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2411) and Muslim (2373:160).","chapter_en":"What Has Been Reported Concerning the Dislike of Preferring One Prophet Over Another","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Do not give me preference over Moses, for the people will be struck unconscious on the Day of Resurrection, and I will be struck unconscious along with them. Then I will be the first to regain consciousness, and there will be Moses grasping the side of the Throne. I do not know whether he was among those who were struck unconscious and regained consciousness before me, or whether he was among those whom Allah exempted.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[476],"tks":"متفق عليه: رواه البخاري (2411)، ومسلم (2373: 160)."},{"num":696,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تُخَيِّرُوا بَيْنَ الْأَنْبِيَاءِ، فَإِنَّ النَّاسَ يَصْعَقُونَ يَوْمَ الْقِيَامَةِ، فَأَكُونُ أَوَّلَ مَنْ تَنْشَقُّ عَنْهُ الْأَرْضُ، فَإِذَا أَنَا بِمُوسَى آخِذٌ بِقَائِمَةٍ مِنْ قَوَائِمِ الْعَرْشِ، فَلَا أَدْرِي أَكَانَ فِيمَنْ صَعِقَ أَمْ حُوسِبَ بِصَعْقَةِ الْأُولَى."],"takhrij":"متفق عليه: رواه البخاريّ في الخصومات (2412) عن موسى بن إسماعيل، حدّثنا وُهيب، حدّثنا عمرو بن يحيى، عن أبيه، عن أبي سعيد، فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في كراهية المفاضلة بين الأنبياء","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2412).","chapter_en":"What Has Been Reported Concerning the Dislike of Preferring One Prophet Over Another","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Do not give preference among the prophets. The people will be struck unconscious on the Day of Resurrection, and I will be the first for whom the earth is split open. Then I will find Moses holding one of the supports of the Throne. I do not know whether he was among those who were struck unconscious or whether the first striking was counted for him.”"]},"buhuth":{"en":["It was also narrated by al-Bukhārī (3398) and Muslim (2374), but those two versions do not mention the supports of the Throne.","The scholars said:","The Prophet ﷺ said this out of humility, or before he had been informed of his superior rank; therefore, there is no contradiction. The Qurʾān and Sunnah establish that Allah, Blessed and Exalted, favored some messengers over others, as Allah Most High said:","“Those messengers — We favored some of them over others. Among them were those to whom Allah spoke, and He raised some of them in degrees.”","[Sūrat al-Baqarah 2:253]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[475],"tks":"متفق عليه: رواه البخاري (2412)."},{"num":697,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَشَدُّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ: رَجُلٌ قَتَلَهُ نَبِيٌّ، أَوْ قَتَلَ نَبِيًّا، وَإِمَامُ ضَلَالَةٍ، وَمُمَثِّلٌ مِنَ الْمُمَثِّلِينَ."],"takhrij":"حسن: رواه أحمد (3868)، والبزار –كشف الأستار (1603) كلاهما من طريق عبد الصمد، عن أبان بن يزيد، عن عاصم، عن أبي وائل، عن عبد الله (هو ابن مسعود) فذكره.","grade":"حسن","chapter_ar":"باب أشد الناس عذابًا يوم القيامة من قتله نبي أو قتل نبيًّا","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (3868) and al-Bazzār in Kashf al-Astār (1603).","chapter_en":"Among the People Most Severely Punished on the Day of Resurrection Are One Whom a Prophet Killed and One Who Killed a Prophet","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Among the people who will receive the most severe punishment on the Day of Resurrection are a man whom a prophet killed, a man who killed a prophet, a leader of misguidance, and an image-maker among image-makers.”"]},"buhuth":{"en":["The expression “an image-maker among image-makers” means one who makes images or representations."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (3868)، والبزار في كشف الأستار (1603)."},{"num":698,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ قَالَ: كُنْتُ أَكْتُبُ كُلَّ شَيْءٍ أَسْمَعُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُرِيدُ حِفْظَهُ، فَنَهَتْنِي قُرَيْشٌ، وَقَالُوا: أَتَكْتُبُ كُلَّ شَيْءٍ تَسْمَعُهُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَشَرٌ يَتَكَلَّمُ فِي الْغَضَبِ وَالرِّضَا ؟، فَأَمْسَكْتُ عَنِ الْكِتَابِ، فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَوْمَأَ بِأُصْبُعِهِ إِلَى فِيهِ، فَقَالَ: اكْتُبْ، فَوَالَّذِي نَفْسِي بِيَدِهِ، مَا يَخْرُجُ مِنْهُ إِلَّا حَقٌّ."],"takhrij":"صحيح: رواه أبو داود (3646) عن مسدّد وأبي بكر بن أبي شيبة، قالا: حدّثنا يحيى، عن عبيد الله بن الأخنس، عن الوليد بن عبدالله بن أبي مغيث، عن يوسف بن ماهك، عن عبدالله بن عمرو، قال (فذكره).","grade":"صحيح","chapter_ar":"باب عصمة الأنبياء فيما يخبرون عن الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (3646), Aḥmad (6510), and al-Ḥākim (359).","chapter_en":"The Protection of the Prophets From Error in What They Convey From Allah Most High","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, reported: “I used to write down everything I heard from the Messenger of Allah ﷺ because I wanted to preserve it. Quraysh prohibited me and said: ‘Do you write everything you hear from the Messenger of Allah ﷺ, even though the Messenger of Allah ﷺ is a human being who speaks in times of anger and pleasure?’ So I stopped writing. I mentioned this to the Messenger of Allah ﷺ, and he pointed with his finger toward his mouth and said: ‘Write. By the One in whose Hand is my soul, nothing comes out of it except the truth.’”"]},"intro":{"ar":["قال الله تعالى:","﴿قُولُوا آمَنَّا بِاللهِ وَمَا أُنْزِلَ إِلَيْنَا وَمَا أُنْزِلَ إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى وَمَا أُوتِيَ النَّبِيُّونَ مِنْ رَبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْهُمْ وَنَحْنُ لَهُ مُسْلِمُونَ﴾","[البقرة: ١٣٦]","الأنبياء عليهم الصلاة والسلام معصومون فيما يخبرون عن الله سبحانه وتعالى، وفي تبليغ رسالاته باتفاق الأمة؛ ولهذا وجب الإيمان بكل ما أتوا به.","وقال تعالى:","﴿آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ﴾","[البقرة: ٢٨٥]","والأنبياء معصومون من الإقرار على المعصية، وإن وقع منهم شيء سارعوا إلى التوبة ولا يصرون عليه.","ولذلك لم يذكر القرآن شيئًا من ذلك عن نبي من الأنبياء إلا مقرونًا بالتوبة والاستغفار، كقول آدم وزوجته:","﴿قَالَا رَبَّنَا ظَلَمْنَا أَنْفُسَنَا وَإِنْ لَمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ﴾","[الأعراف: ٢٣]","وقول نوح عليه السلام:","﴿قَالَ رَبِّ إِنِّي أَعُوذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُنْ مِنَ الْخَاسِرِينَ﴾","[هود: ٤٧]","وقول الخليل إبراهيم عليه السلام:","﴿وَالَّذِي أَطْمَعُ أَنْ يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّينِ﴾","[الشعراء: ٨٢]","وقول موسى عليه السلام:","﴿قَالَ رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي فَغَفَرَ لَهُ﴾","[القصص: ١٦]","وقوله:","﴿فَلَمَّا أَفَاقَ قَالَ سُبْحَانَكَ تُبْتُ إِلَيْكَ وَأَنَا أَوَّلُ الْمُؤْمِنِينَ﴾","[الأعراف: ١٤٣]","وقوله تعالى عن داود عليه السلام:","﴿وَظَنَّ دَاوُودُ أَنَّمَا فَتَنَّاهُ فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَابَ﴾","[ص: ٢٤]","وقوله تعالى عن سليمان عليه السلام:","﴿قَالَ رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكًا لَا يَنْبَغِي لِأَحَدٍ مِنْ بَعْدِي إِنَّكَ أَنْتَ الْوَهَّابُ﴾","[ص: ٣٥]"],"en":["Allah Most High said:","“Say: We believe in Allah and what has been sent down to us, and what was sent down to Abraham, Ishmael, Isaac, Jacob, and the Tribes, and what was given to Moses and Jesus, and what was given to the prophets from their Lord. We make no distinction between any of them, and to Him we submit.”","[Sūrat al-Baqarah 2:136]","The prophets, peace and blessings be upon them, are protected from error in what they convey concerning Allah, Glorified and Exalted, and in delivering His messages, by the agreement of the Ummah. Therefore, it is obligatory to believe everything they brought.","Allah Most High said:","“The Messenger believes in what has been sent down to him from his Lord, and so do the believers. Each believes in Allah, His angels, His Books, and His messengers. ‘We make no distinction between any of His messengers.’ And they say: ‘We hear and we obey. We seek Your forgiveness, our Lord, and to You is the final return.’”","[Sūrat al-Baqarah 2:285]","The prophets are protected from persisting in disobedience. If something occurs from them, they hasten to repentance and do not persist in it.","For this reason, the Qurʾān does not mention anything of this nature concerning a prophet except together with repentance and seeking forgiveness, such as the statement of Adam and his wife:","“They said: ‘Our Lord, we have wronged ourselves. If You do not forgive us and have mercy upon us, we will surely be among the losers.’”","[Sūrat al-Aʿrāf 7:23]","And the statement of Noah, peace be upon him:","“He said: ‘My Lord, I seek refuge with You from asking You about that of which I have no knowledge. Unless You forgive me and have mercy upon me, I will be among the losers.’”","[Sūrat Hūd 11:47]","And the statement of Abraham, al-Khalīl peace be upon him:","“And He is the One whom I hope will forgive my shortcomings on the Day of Judgment.”","[Sūrat al-Shuʿarāʾ 26:82]","And the statement of Moses, peace be upon him:","“He said: ‘My Lord, indeed I have wronged myself, so forgive me.’ And He forgave him.”","[Sūrat al-Qaṣaṣ 28:16]","And His statement concerning Moses, peace be upon him:","“When he recovered, he said: ‘Glory be to You! I repent to You, and I am the first of the believers.’”","[Sūrat al-Aʿrāf 7:143]","And Allah Most High said concerning David peace be upon him:","“David realized that We had tested him, so he sought forgiveness from his Lord",", fell down bowing, and turned in repentance.”","[Sūrat Ṣād 38:24]","And Allah Most High said concerning Solomon peace be upon him:","“He said: ‘My Lord, forgive me and grant me a kingdom that will belong to no one after me. Indeed, You are the Bestower.’”","[Sūrat Ṣād 38:35]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1169],"tks":"صحيح: رواه أبو داود (3646)، وأحمد (6510)، والحاكم (359)."},{"num":699,"demo":false,"sanad":"","matn":["عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ التَّيْمِيّ قَالَ: مَرَرْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، بِقَوْمٍ عَلَى رُءُوسِ النَّخْلِ، فَقَالَ: مَا يَصْنَعُ هَؤُلَاءِ؟ فَقَالُوا يُلَقِّحُونَهُ، يَجْعَلُونَ الذَّكَرَ فِي الْأُنْثَى، فَيَلْقَحُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَظُنُّ يُغْنِي ذَلِكَ شَيْئًا، قَالَ: فَأُخْبِرُوا بِذَلِكَ، فَتَرَكُوهُ، فَأُخْبِرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِذَلِكَ، فَقَالَ: إِنْ كَانَ يَنْفَعُهُمْ ذَلِكَ، فَلْيَصْنَعُوهُ، فَإِنِّي إِنَّمَا ظَنَنْتُ ظَنًّا، فَلَا تُؤَاخِذُونِي بِالظَّنِّ، وَلَكِنْ إِذَا حَدَّثْتُكُمْ عَنِ اللَّهِ شَيْئًا، فَخُذُوا بِهِ، فَإِنِّي لَنْ أَكْذِبَ عَلَى اللَّهِ عَزَّ وَجَلّ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2361) من طرق عن أبي عوانة، عن سماك، عن موسى بن طلحة، عن أبيه، قال (فذكره).","grade":"صحيح","chapter_ar":"باب عصمة الأنبياء فيما يخبرون عن الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2361).","chapter_en":"The Protection of the Prophets From Error in What They Convey From Allah Most High","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Ṭalḥah ibn ʿUbaydillāh al-Taymī, may Allah be pleased with him, reported: “I passed with the Messenger of Allah ﷺ by some people who were at the tops of date-palm trees. He asked: ‘What are these people doing?’ They replied: ‘They are pollinating the trees, placing the male part with the female so that it becomes fertilized.’ The Messenger of Allah ﷺ said: ‘I do not think that this will benefit anything.’ They were informed of what he had said, so they stopped doing it. The Messenger of Allah ﷺ was then informed of what had happened, and he said: ‘If it benefits them, then let them do it. I merely expressed an opinion, so do not hold me to account for an opinion. But when I tell you something from Allah, then take it, for I will never lie about Allah, Mighty and Majestic.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2361)."},{"num":700,"demo":false,"sanad":"","matn":["عَنْ رَافِعِ بْنِ خَدِيجٍ قَالَ: قَدِمَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ، وَهُمْ يَأْبُرُونَ النَّخْلَ، يَقُولُونَ: يُلَقِّحُونَ النَّخْلَ فَقَالَ: مَا تَصْنَعُونَ؟ قَالُوا: كُنَّا نَصْنَعُهُ، قَالَ: لَعَلَّكُمْ لَوْ لَمْ تَفْعَلُوا كَانَ خَيْرًا، فَتَرَكُوهُ، فَنَفَضَتْ أَوْ فَنَقَصَتْ، قَالَ: فَذَكَرُوا ذَلِكَ لَهُ، فَقَالَ: إِنَّمَا أَنَا بَشَرٌ، إِذَا أَمَرْتُكُمْ بِشَيْءٍ مِنْ دِينِكُمْ، فَخُذُوا بِهِ، وَإِذَا أَمَرْتُكُمْ بِشَيْءٍ مِنْ رَأْيٍ، فَإِنَّمَا أَنَا بَشَرٌ، قَالَ عِكْرِمَةُ: أَوْ نَحْوَ هَذَا، قَالَ الْمَعْقِرِيُّ: فَنَفَضَتْ، وَلَمْ يَشُكَّ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2362) من طرق عن النّضر بن محمد، حدّثنا عكرمة (وهو ابن عمّار)، حدّثنا أبو النجاشيّ، حدّثني رافع بن خديج، فذكره.","grade":"صحيح","chapter_ar":"باب عصمة الأنبياء فيما يخبرون عن الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2362).","chapter_en":"The Protection of the Prophets From Error in What They Convey From Allah Most High","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Rāfiʿ ibn Khadīj, may Allah be pleased with him, reported: “The Prophet of Allah ﷺ came to Madinah while the people were pollinating their date-palms. He asked: ‘What are you doing?’ They replied: ‘We used to do this.’ He said: ‘Perhaps it would be better if you did not do it.’ So they stopped, and the dates failed to develop properly — or their yield decreased. They mentioned this to him, and he said: ‘I am only a human being. When I command you concerning something from your religion, then take it. But when I tell you something based on my own opinion, then I am only a human being.’” ʿIkrimah said: “Or words to that effect.” Al-Maʿqirī narrated: “They failed to develop,” without expressing doubt."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2362)."},{"num":701,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، وَعَنْ ثَابِتٍ، عَنْ أَنَسٍ: أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَرَّ بِقَوْمٍ يُلَقِّحُونَ فَقَالَ: لَوْ لَمْ تَفْعَلُوا لَصَلُحَ، قَالَ: فَخَرَجَ شِيصًا، فَمَرَّ بِهِمْ، فَقَالَ: مَا لِنَخْلِكُمْ، قَالُوا: قُلْتَ كَذَا وَكَذَا، قَالَ: أَنْتُمْ أَعْلَمُ بِأَمْرِ دُنْيَاكُمْ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2363) من طرق عن الأسود بن عامر، حدّثنا حمّاد بن سلمة، عن هشام بن عروة، عن أبيه، عن عائشة، وعن ثابت عن أنس، فذكراه.","grade":"صحيح","chapter_ar":"باب عصمة الأنبياء فيما يخبرون عن الله تعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2363).","chapter_en":"The Protection of the Prophets From Error in What They Convey From Allah Most High","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["ʿĀʾishah and Anas, may Allah be pleased with them, reported: The Prophet ﷺ passed by some people who were pollinating their date-palms and said: “Perhaps if you did not do it, they would turn out well.” But the fruit came out as shīṣ. He later passed by them and asked: “What happened to your date-palms?” They replied: “You said such-and-such.” He said: “You are more knowledgeable about the affairs of your worldly life.”"]},"buhuth":{"en":["The expression:","“It came out as shīṣ”","means poor-quality dates which, when they dry, become shriveled and worthless.","A Summary Concerning the Infallibility of the Prophets","Ahl al-Sunnah and the majority of Muslims agree that the Prophets, peace be upon them, are protected from error in what they convey from Allah Most High and in delivering His message, because this protection fulfills the purpose of revelation and prophethood.","Ahl al-Sunnah also hold that minor sins, as opposed to major sins, may occur from them in their actions, based on what has been reported in the Qurʾān and authentic narrations. However, they do not persist in them; rather, they hasten to repentance and seeking forgiveness. Thus, they are protected from persisting in such acts, and their repentance itself is an example to be followed, since we have been commanded to take them as models. And success is from Allah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2363)."},{"num":702,"demo":false,"sanad":"","matn":["عَنْ عُبَادَةَ بْنِ الصَّامِتِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَأَنَّ عِيسَى عَبْدُ اللَّهِ وَرَسُولُهُ وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ وَالْجَنَّةُ حَقٌّ وَالنَّارُ حَقٌّ أَدْخَلَهُ اللَّهُ الْجَنَّةَ عَلَى مَا كَانَ مِنَ الْعَمَلِ."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3435)، ومسلم في الإيمان (28) كلاهما من حديث الأوزاعيّ، قال: حدّثني عمير بن هانئ العنسيّ، حدّثني جُنادة بن أبي أميّة، قال: حدّثني عبادة بن الصّامت، فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بنبوة عيسى عليه السلام وأنه عبد الله ورسوله وكلمته ألقاها إلى مريم","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3435) and Muslim (28).","chapter_en":"The Obligation of Believing in the Prophethood of Jesus, peace be upon him,, That He Is the Servant and Messenger of Allah, and His Word Cast to Mary","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":12,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit may Allah be pleased with him reported that the Prophet ﷺ said: “Whoever testifies that there is no deity worthy of worship except Allah alone, without partner; that Muḥammad is His servant and Messenger; that Jesus is the servant and Messenger of Allah, His Word which He cast to Mary, and a spirit from Him; and that Paradise is true and the Fire is true—Allah will admit him into Paradise according to whatever deeds he had.”"]},"buhuth":{"en":["In another narration:","“He may enter through whichever of the eight gates of Paradise he wishes.”"]},"intro":{"ar":["قال الله تعالى:","﴿يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ وَلَا تَقُولُوا عَلَى اللهِ إِلَّا الْحَقَّ إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ فَآمِنُوا بِاللهِ وَرُسُلِهِ وَلَا تَقُولُوا ثَلَاثَةٌ انْتَهُوا خَيْرًا لَكُمْ إِنَّمَا اللهُ إِلَهٌ وَاحِدٌ سُبْحَانَهُ أَنْ يَكُونَ لَهُ وَلَدٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللهِ وَكِيلًا﴾","[النساء: ١٧١]","قوله تعالى:","﴿وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ﴾","أي: إنما هو عبد من عباد الله، ومخلوق من خلقه، قال له:","كن،","فكان، ورسول من رسله."],"en":["“O People of the Scripture, do not go to extremes in your religion, and do not say about Allah except the truth. The Messiah, Jesus son of Mary, was only a messenger of Allah, His Word which He cast to Mary, and a spirit from Him. So believe in Allah and His messengers, and do not say, ‘Three.’ Desist—it is better for you. Allah is only One Allah. Glorified is He above having a son. To Him belongs whatever is in the heavens and whatever is on the earth, and Allah is sufficient as Disposer of affairs.”","[Sūrat al-Nisāʾ 4:171]","His statement:","“His Word which He cast to Mary”","means that Jesus is only a servant among the servants of Allah and a created being from His creation. Allah said to him:","“Be,”","and he was. He is also one of His messengers."]}},"tuhfa":{},"full":1,"dr":1,"rep":[69],"tks":"متفق عليه: رواه البخاري (3435)، ومسلم (28)."},{"num":703,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَة قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم: وَالَّذِي نَفْسِي بِيَدِهِ لَيُوشِكَنَّ أَنْ يَنْزِلَ فِيكُمْ ابْنُ مَرْيَمَ حَكَمًا عَدْلًا فَيَكْسِرَ الصَّلِيبَ وَيَقْتُلَ الْخِنْزِيرَ وَيَضَعَ الْجِزْيَةَ وَيَفِيضَ الْمَالُ حَتَّى لَا يَقْبَلَهُ أَحَدٌ حَتَّى تَكُونَ السَّجْدَةُ الْوَاحِدَةُ خَيْرًا مِنَ الدُّنْيَا وَمَا فِيهَا ثُمَّ، يَقُولُ أَبُو هُرَيْرَةَ وَاقْرَءُوا إِنْ شِئْتُمْ: ﴿وَإِنْ مِنْ أَهْلِ الْكِتَابِ إِلَّا لَيُؤْمِنَنَّ بِهِ قَبْلَ مَوْتِهِ وَيَوْمَ الْقِيَامَةِ يَكُونُ عَلَيْهِمْ شَهِيدً﴾ [سورة النساء: 159]."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3448)، ومسلم في الإيمان (155) كلاهما من حديث يعقوب بن إبراهيم، عن أبيه، عن ابن شهاب، أن سعيد ابن المسيب سمع أبا هريرة يقول (فذكره).","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3448) and Muslim (155).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “By the One in whose Hand is my soul, the son of Mary will soon descend among you as a just judge. He will break the cross, kill the pig, abolish the jizyah, and wealth will become so abundant that no one will accept it, until a single prostration will be better than the world and everything in it.” Then Abū Hurayrah, may Allah be pleased with him, said: “Recite, if you wish: ‘There is none from the People of the Scripture except that he will surely believe in him before his death, and on the Day of Resurrection he will be a witness against them.’” [Sūrat al-Nisāʾ 4:159]"]},"buhuth":{"en":["Regarding His statement:","“Before his death,”","the pronoun refers to Jesus, peace be upon him. This is the correct interpretation, and it has been reported from Ibn ʿAbbās, Abū Hurayrah, and others. The view that the pronoun refers to each individual from the People of the Scripture is a remote interpretation."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3448)، ومسلم (155)."},{"num":704,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَقُومُ السَّاعَةُ حَتَّى يَنْزِلَ الرُّومُ بِالْأَعْمَاقِ أَوْ بِدَابِقٍ، فَيَخْرُجُ إِلَيْهِمْ جَيْشٌ مِنْ الْمَدِينَةِ مِنْ خِيَارِ أَهْلِ الْأَرْضِ يَوْمَئِذٍ، فَإِذَا تَصَافُّوا، قَالَتْ الرُّومُ: خَلُّوا بَيْنَنَا وَبَيْنَ الَّذِينَ سَبَوْا مِنَّا نُقَاتِلْهُمْ، فَيَقُولُ الْمُسْلِمُونَ: لَا وَاللَّهِ لَا نُخَلِّي بَيْنَكُمْ وَبَيْنَ إِخْوَانِنَا، فَيُقَاتِلُونَهُمْ، فَيَنْهَزِمُ ثُلُثٌ لَا يَتُوبُ اللَّهُ عَلَيْهِمْ أَبَدًا، وَيُقْتَلُ ثُلُثُهُمْ أَفْضَلُ الشُّهَدَاءِ عِنْدَ اللَّهِ، وَيَفْتَتِحُ الثُّلُثُ لَا يُفْتَنُونَ أَبَدًا، فَيَفْتَتِحُونَ قُسْطَنْطِينِيَّةَ فَبَيْنَمَا هُمْ يَقْتَسِمُونَ الْغَنَائِمَ قَدْ عَلَّقُوا سُيُوفَهُمْ بِالزَّيْتُونِ، إِذْ صَاحَ فِيهِمُ الشَّيْطَانُ إِنَّ الْمَسِيحَ قَدْ خَلَفَكُمْ فِي أَهْلِيكُمْ، فَيَخْرُجُونَ وَذَلِكَ بَاطِلٌ، فَإِذَا جَاءُوا الشَّأْمَ خَرَجَ فَبَيْنَمَا هُمْ يُعِدُّونَ لِلْقِتَالِ يُسَوُّونَ الصُّفُوفَ إِذْ أُقِيمَتِ الصَّلَاةُ، فَيَنْزِلُ عِيسَى ابْنُ مَرْيَمَ عَلَيْهِ السَّلَام فَأَمَّهُمْ، فَإِذَا رَآهُ عَدُوُّ اللَّهِ ذَابَ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ، فَلَوْ تَرَكَهُ لَانْذَابَ حَتَّى يَهْلِكَ، وَلَكِنْ يَقْتُلُهُ اللَّهُ بِيَدِهِ فَيُرِيهِمْ دَمَهُ فِي حَرْبَتِهِ."],"takhrij":"صحيح: رواه مسلم في الفتن (2897) عن زهير بن حرب، حدّثنا معلى بن منصور، حدّثنا سليمان بن بلال، حدّثنا سُهيل، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2897).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The Hour will not be established until the Romans encamp at al-Aʿmāq or Dābiq. An army from Madinah, consisting of the best people on earth at that time, will go out against them. When they line up for battle, the Romans will say: ‘Leave us with those who took captives from among us so that we may fight them.’ The Muslims will say: ‘No, by Allah, we will never leave you to fight our brothers.’ Then they will fight. One-third will flee, and Allah will never accept their repentance. One-third will be killed, and they will be the best martyrs before Allah. The remaining third will conquer and will never be afflicted by tribulation. They will conquer Constantinople. While they are dividing the spoils, having hung their swords upon the olive trees, Satan will cry out among them: ‘The Messiah has taken your place among your families!’ They will set out, although that report will be false. When they reach al-Shām, he will emerge. While they are preparing for battle and straightening their rows, the prayer will be established. Then Jesus son of Mary will descend and lead them. When the enemy of Allah sees him, he will melt as salt melts in water. Were Jesus to leave him, he would continue melting until he perished, but Allah will kill him by his hand, and he will show them his blood upon his spear.”"]},"buhuth":{"en":["The words:","“At al-Aʿmāq or Dābiq”","refer to two places in al-Shām near Aleppo and Antioch."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2897)."},{"num":705,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَة قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم: كَيْفَ أَنْتُمْ إِذَا نَزَلَ ابْنُ مَرْيَمَ فِيكُمْ وَإِمَامُكُمْ مِنْكُمْ.","وَفِي رِوَايَةِ: كَيْفَ أَنْتُمْ إِذَا نَزَلَ ابْنُ مَرْيَمَ مِنْ السَّمَاءِ فِيكُمْ وَإِمَامُكُمْ مِنْكُمْ."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3449)، ومسلم في الإيمان (155: 244) كلاهما من حديث يونس، عن ابن شهاب، عن نافع مولى أبي قتادة الأنصاريّ، قال: إنّ أبا هريرة قال (فذكر الحديث) ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3449) and Muslim (155).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “How will you be when the son of Mary descends among you while your imam is from among you?” In another narration:","“How will you be when the son of Mary descends from heaven among you while your imam is from among you?”"]},"buhuth":{"en":["The second wording was narrated by al-Bayhaqī in al-Asmāʾ wa al-Ṣifāt (2/166)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3449)، ومسلم (155)."},{"num":706,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ أَبَا الْقَاسِمِ الصَّادِقَ الْمَصْدُوقَ يَقُولُ: يَخْرُجُ أَعْوَرُ الدَّجَّالِ مَسِيحُ الضَّلَالَةِ قِبَلَ الْمَشْرِقِ فِي زَمَنِ اخْتِلَافٍ مِنَ النَّاسِ وَفُرْقَةٍ، فَيَبْلُغُ مَا شَاءَ اللَّهُ أَنْ يَبْلُغَ مِنَ الْأَرْضِ فِي أَرْبَعِينَ يَوْمًا اللَّهُ أَعْلَمُ مَا مِقْدَارُهَا، فَيَلْقَى الْمُؤْمِنُونَ شِدَّةً شَدِيدَةً . ثُمَّ يَنْزِلُ عِيسَى ابْنُ مَرْيَمَ عَلَيْهِ السَّلَام مِنَ السَّمَاءِ فَيَؤُمُّ النَّاسَ، فَإِذَا رَفَعَ رَأْسَهُ مِنْ رَكْعَتِهِ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، قَتَلَ اللَّهُ الْمَسِيحَ الدَّجَّالَ وَظَهَرَ الْمُسْلِمُونَ. فَأَحْلِفُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبَا الْقَاسِمِ الصَّادِقَ الْمَصْدُوقَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّهُ لَحَقٌّ، وَأَمَّا أَنَّهُ قَرِيبٌ فَكُلُّ مَا هُوَ آتٍ قَرِيبٌ."],"takhrij":"حسن: رواه البزار - كشف الأستار (3396)،  عن علي بن المنذر، عن محمد بن فضيل، عن عاصم بن كليب، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"حسن","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Bazzār in Kashf al-Astār (3396) and authenticated by Ibn Ḥibbān (6812).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, said: I heard Abū al-Qāsim ﷺ, the truthful and confirmed, say: “The one-eyed Dajjāl, the false messiah, will emerge from the direction of the east during a time of disagreement and division among the people. He will traverse whatever portion of the earth Allah wills him to traverse during forty days—Allah knows best their measure. The believers will encounter severe hardship. Then Jesus son of Mary will descend from heaven and lead the people. When he raises his head from bowing, he will say: ‘Allah hears the one who praises Him.’ Allah will cause the false messiah, the Dajjāl, to be killed, and the Muslims will prevail. I swear that if the Messenger of Allah ﷺ—Abū al-Qāsim, the truthful and confirmed—said it, then it is certainly true. As for its being near, everything that is coming is near.”"]},"buhuth":{"en":["The words:","“He will lead them”","were explained by Ibn Ḥibbān as meaning that he will direct them concerning the imamate, since the Arabs may attribute an action to the one who orders it just as they attribute it to the one who performs it.","The words:","“Allah killed the Dajjāl”","mean that Allah killed him at the hand of Jesus, peace be upon him,, similar to His statement:","“You did not kill them, but Allah killed them; and you did not throw when you threw, but Allah threw.”","[Sūrat al-Anfāl 8:17]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (3396)، وصححه ابن حبان (6812)."},{"num":707,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ بَيْنِي وَبَيْنَهُ نَبِيٌّ يَعْنِي عِيسَى، وَإِنَّهُ نَازِلٌ فَإِذَا رَأَيْتُمُوهُ فَاعْرِفُوهُ رَجُلٌ مَرْبُوعٌ إِلَى الْحُمْرَةِ وَالْبَيَاضِ بَيْنَ مُمَصَّرَتَيْنِ كَأَنَّ رَأْسَهُ يَقْطُرُ، وَإِنْ لَمْ يُصِبْهُ بَلَلٌ، فَيُقَاتِلُ النَّاسَ عَلَى الْإِسْلَامِ فَيَدُقُّ الصَّلِيبَ وَيَقْتُلُ الْخِنْزِيرَ وَيَضَعُ الْجِزْيَةَ وَيُهْلِكُ اللَّهُ فِي زَمَانِهِ الْمِلَلَ كُلَّهَا إِلَّا الْإِسْلَامَ وَيُهْلِكُ الْمَسِيحَ الدَّجَّالَ، فَيَمْكُثُ فِي الْأَرْضِ أَرْبَعِينَ سَنَةً ثُمَّ يُتَوَفَّى فَيُصَلِّي عَلَيْهِ الْمُسْلِمُونَ."],"takhrij":"حسن: رواه أبو داود (4324) وصحّحه ابنُ حبان (6821)، والحاكم (4163) كلّهم من طريق همام بن يحيى، عن قتادة، عن عبدالرحمن بن آدم، عن أبي هريرة، فذكر الحديث، واللّفظ لأبي داود.","grade":"حسن","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Abū Dāwūd (4324), and authenticated by Ibn Ḥibbān (6821) and al-Ḥākim (4163).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “There is no prophet between me and him—meaning Jesus son of Mary—and he will certainly descend. When you see him, recognize him: a man of medium height, with a complexion between reddish and white, wearing two lightly dyed garments. His head will appear to be dripping with water even though no wetness has touched it. He will fight the people for Islam, break the cross, kill the pig, abolish the jizyah, and Allah will cause every religion during his time to disappear except Islam. He will destroy the false messiah, the Dajjāl. He will remain upon the earth for forty years, then he will die, and the Muslims will perform the funeral prayer over him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4324)، وصححه ابن حبان (6821)، والحاكم (4163)."},{"num":708,"demo":false,"sanad":"","matn":["عَنْ النَّوَّاسِ بْنِ سَمْعَانَ قَالَ: ذَكَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الدَّجَّالَ ذَاتَ غَدَاةٍ، فَخَفَّضَ فِيهِ وَرَفَّعَ حَتَّى ظَنَنَّاهُ فِي طَائِفَةِ النَّخْلِ، فَلَمَّا رُحْنَا إِلَيْهِ عَرَفَ ذَلِكَ فِينَا، فَقَالَ: مَا شَأْنُكُمْ؟ قُلْنَا: يَا رَسُولَ اللَّهِ، ذَكَرْتَ الدَّجَّالَ غَدَاةً، فَخَفَّضْتَ فِيهِ وَرَفَّعْتَ حَتَّى ظَنَنَّاهُ فِي طَائِفَةِ النَّخْلِ، فَقَالَ: غَيْرُ الدَّجَّالِ أَخْوَفُنِي عَلَيْكُمْ إِنْ يَخْرُجْ، وَأَنَا فِيكُمْ فَأَنَا حَجِيجُهُ دُونَكُمْ، وَإِنْ يَخْرُجْ وَلَسْتُ فِيكُمْ، فَامْرُؤٌ حَجِيجُ نَفْسِهِ وَاللَّهُ خَلِيفَتِي عَلَى كُلِّ مُسْلِمٍ إِنَّهُ شَابٌّ قَطَطٌ عَيْنُهُ طَافِئَةٌ كَأَنِّي أُشَبِّهُهُ بِعَبْدِ الْعُزَّى بْنِ قَطَنٍ، فَمَنْ أَدْرَكَهُ مِنْكُمْ، فَلْيَقْرَأْ عَلَيْهِ فَوَاتِحَ سُورَةِ الْكَهْفِ إِنَّهُ خَارِجٌ خَلَّةً بَيْنَ الشَّأْمِ وَالْعِرَاقِ، فَعَاثَ يَمِينًا وَعَاثَ شِمَالًا، يَا عِبَادَ اللَّهِ فَاثْبُتُوا قُلْنَا: يَا رَسُولَ اللَّهِ، وَمَا لَبْثُهُ فِي الْأَرْضِ ؟، قَالَ: أَرْبَعُونَ يَوْمًا يَوْمٌ كَسَنَةٍ، وَيَوْمٌ كَشَهْرٍ، وَيَوْمٌ كَجُمُعَةٍ وَسَائِرُ أَيَّامِهِ كَأَيَّامِكُمْ، قُلْنَا: يَا رَسُولَ اللَّهِ، فَذَلِكَ الْيَوْمُ الَّذِي كَسَنَةٍ أَتَكْفِينَا فِيهِ صَلَاةُ يَوْمٍ؟ قَالَ: لَا اقْدُرُوا لَهُ قَدْرَهُ، قُلْنَا: يَا رَسُولَ اللَّهِ، وَمَا إِسْرَاعُهُ فِي الْأَرْضِ؟ قَالَ: كَالْغَيْثِ اسْتَدْبَرَتْهُ الرِّيحُ، فَيَأْتِي عَلَى الْقَوْمِ، فَيَدْعُوهُمْ فَيُؤْمِنُونَ بِهِ وَيَسْتَجِيبُونَ لَهُ، فَيَأْمُرُ السَّمَاءَ فَتُمْطِرُ، وَالْأَرْضَ فَتُنْبِتُ، فَتَرُوحُ عَلَيْهِمْ سَارِحَتُهُمْ أَطْوَلَ مَا كَانَتْ ذُرًا وَأَسْبَغَهُ ضُرُوعًا، وَأَمَدَّهُ خَوَاصِرَ ثُمَّ يَأْتِي الْقَوْمَ، فَيَدْعُوهُمْ فَيَرُدُّونَ عَلَيْهِ قَوْلَهُ فَيَنْصَرِفُ عَنْهُمْ، فَيُصْبِحُونَ مُمْحِلِينَ لَيْسَ بِأَيْدِيهِمْ شَيْءٌ مِنْ أَمْوَالِهِمْ وَيَمُرُّ بِالْخَرِبَةِ، فَيَقُولُ: لَهَا أَخْرِجِي كُنُوزَكِ، فَتَتْبَعُهُ كُنُوزُهَا كَيَعَاسِيبِ النَّحْلِ ثُمَّ يَدْعُو رَجُلًا مُمْتَلِئًا شَبَابًا، فَيَضْرِبُهُ بِالسَّيْفِ فَيَقْطَعُهُ جَزْلَتَيْنِ رَمْيَةَ الْغَرَضِ ثُمَّ يَدْعُوهُ، فَيُقْبِلُ وَيَتَهَلَّلُ وَجْهُهُ يَضْحَكُ فَبَيْنَمَا هُوَ كَذَلِكَ إِذْ بَعَثَ اللَّهُ الْمَسِيحَ ابْنَ مَرْيَمَ، فَيَنْزِلُ عِنْدَ الْمَنَارَةِ الْبَيْضَاءِ شَرْقِيَّ دِمَشْقَ بَيْنَ مَهْرُودَتَيْنِ، وَاضِعًا كَفَّيْهِ عَلَى أَجْنِحَةِ مَلَكَيْنِ إِذَا طَأْطَأَ رَأْسَهُ قَطَرَ، وَإِذَا رَفَعَهُ تَحَدَّرَ مِنْهُ جُمَانٌ كَاللُّؤْلُؤِ، فَلَا يَحِلُّ لِكَافِرٍ يَجِدُ رِيحَ نَفَسِهِ إِلَّا مَاتَ وَنَفَسُهُ يَنْتَهِي حَيْثُ يَنْتَهِي طَرْفُهُ، فَيَطْلُبُهُ حَتَّى يُدْرِكَهُ بِبَابِ لُدٍّ، فَيَقْتُلُهُ ثُمَّ يَأْتِي عِيسَى ابْنَ مَرْيَمَ قَوْمٌ قَدْ عَصَمَهُمُ اللَّهُ مِنْهُ، فَيَمْسَحُ عَنْ وُجُوهِهِمْ وَيُحَدِّثُهُمْ بِدَرَجَاتِهِمْ فِي الْجَنَّةِ، فَبَيْنَمَا هُوَ كَذَلِكَ إِذْ أَوْحَى اللَّهُ إِلَى عِيسَى إِنِّي قَدْ أَخْرَجْتُ عِبَادًا لِي لَا يَدَانِ لِأَحَدٍ بِقِتَالِهِمْ، فَحَرِّزْ عِبَادِي إِلَى الطُّورِ، وَيَبْعَثُ اللَّهُ يَأْجُوجَ وَمَأْجُوجَ وَهُمْ مِنْ كُلِّ حَدَبٍ يَنْسِلُونَ، فَيَمُرُّ أَوَائِلُهُمْ عَلَى بُحَيْرَةِ طَبَرِيَّةَ، فَيَشْرَبُونَ مَا فِيهَا وَيَمُرُّ آخِرُهُمْ، فَيَقُولُونَ: لَقَدْ كَانَ بِهَذِهِ مَرَّةً مَاءٌ، وَيُحْصَرُ نَبِيُّ اللَّهِ عِيسَى، وَأَصْحَابُهُ حَتَّى يَكُونَ رَأْسُ الثَّوْرِ لِأَحَدِهِمْ خَيْرًا مِنْ مِائَةِ دِينَارٍ لِأَحَدِكُمُ الْيَوْمَ فَيَرْغَبُ نَبِيُّ اللَّه عِيسَى وَأَصْحَابُهُ فَيُرْسِلُ اللَّهُ عَلَيْهِمُ النَّغَفَ فِي رِقَابِهِمْ، فَيُصْبِحُونَ فَرْسَى كَمَوْتِ نَفْسٍ وَاحِدَةٍ، ثُمَّ يَهْبِطُ نَبِيُّ اللَّهِ عِيسَى وَأَصْحَابُهُ إِلَى الْأَرْضِ، فَلَا يَجِدُونَ فِي الْأَرْضِ مَوْضِعَ شِبْرٍ إِلَّا مَلَأَهُ زَهَمُهُمْ وَنَتْنُهُمْ، فَيَرْغَبُ نَبِيُّ اللَّهِ عِيسَى وَأَصْحَابُهُ إِلَى اللَّهِ، فَيُرْسِلُ اللَّهُ طَيْرًا كَأَعْنَاقِ الْبُخْتِ، فَتَحْمِلُهُمْ فَتَطْرَحُهُمْ حَيْثُ شَاءَ اللَّهُ ثُمَّ يُرْسِلُ اللَّهُ مَطَرًا لَا يَكُنُّ مِنْهُ بَيْتُ مَدَرٍ، وَلَا وَبَرٍ فَيَغْسِلُ الْأَرْضَ حَتَّى يَتْرُكَهَا كَالزَّلَفَةِ، ثُمَّ يُقَالُ لِلْأَرْضِ: أَنْبِتِي ثَمَرَتَكِ وَرُدِّي بَرَكَتَكِ، فَيَوْمَئِذٍ تَأْكُلُ الْعِصَابَةُ مِنَ الرُّمَّانَةِ وَيَسْتَظِلُّونَ بِقِحْفِهَا، وَيُبَارَكُ فِي الرِّسْلِ حَتَّى أَنَّ اللِّقْحَةَ مِنَ الْإِبِلِ لَتَكْفِي الْفِئَامَ مِنَ النَّاسِ، وَاللِّقْحَةَ مِنَ الْبَقَرِ لَتَكْفِي الْقَبِيلَةَ مِنَ النَّاسِ، وَاللِّقْحَةَ مِنَ الْغَنَمِ لَتَكْفِي الْفَخِذَ مِنَ النَّاسِ، فَبَيْنَمَا هُمْ كَذَلِكَ إِذْ بَعَثَ اللَّهُ رِيحًا طَيِّبَةً، فَتَأْخُذُهُمْ تَحْتَ آبَاطِهِمْ، فَتَقْبِضُ رُوحَ كُلِّ مُؤْمِنٍ وَكُلِّ مُسْلِمٍ وَيَبْقَى شِرَارُ النَّاسِ يَتَهَارَجُونَ فِيهَا تَهَارُجَ الْحُمُرِ، فَعَلَيْهِمْ تَقُومُ السَّاعَةُ."],"takhrij":"صحيح: رواه مسلم في كتاب الفتن وأشراط السّاعة (2937) من طرق عن الوليد بن مسلم، حدّثني عبدالرحمن بن يزيد بن جابر، حدّثني يحيى بن جابر الطّائيّ قاضي حمص، حدّثني عبدالرحمن بن جبير، عن أبيه جبير بن نُفير الحضرميّ، أنّه سمع النّواس بن سمعان الكلابيّ، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2937).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Al-Nawwās ibn Samʿān, may Allah be pleased with him, reported: The Messenger of Allah ﷺ mentioned the Dajjāl one morning, at times lowering his voice concerning him and at other times raising it, until we imagined that he was somewhere among the palm trees. When we later returned to him, he noticed the effect this had upon us and asked: “What is the matter with you?” We replied: “O Messenger of Allah, you mentioned the Dajjāl this morning and spoke about him in such a manner that we imagined he was somewhere among the palm trees.” He said: “It is something other than the Dajjāl that I fear more for you. If he emerges while I am among you, I will contend with him on your behalf. But if he emerges when I am no longer among you, then every person must contend for himself, and Allah is my Guardian over every Muslim. He is a young man with very curly hair and a defective eye. I would compare him to ʿAbd al-ʿUzzā ibn Qaṭan. Whoever among you encounters him should recite over him the opening verses of Sūrat al-Kahf. He will emerge from a route between al-Shām and Iraq and spread corruption to the right and to the left. O servants of Allah, remain firm.” We asked: “O Messenger of Allah, how long will he remain upon the earth?” He replied: “Forty days: one day like a year, one day like a month, one day like a week, and the remainder of his days like your ordinary days.” We asked: “O Messenger of Allah, on that day which is like a year, will the prayers of a single day be sufficient for us?” He replied: “No. Estimate its time accordingly.” We asked: “O Messenger of Allah, how quickly will he travel through the earth?” He replied: “Like rain driven by the wind. He will come to a people and call them, and they will believe in him and respond to him. He will command the sky and it will rain, and command the earth and it will produce vegetation. Their grazing livestock will return to them with their humps higher than ever before, their udders fuller, and their flanks more extended. Then he will come to another people and call them, but they will reject what he says. He will leave them, and by morning they will be stricken with drought, possessing nothing of their wealth. He will pass by a ruined place and say: ‘Bring out your treasures.’ Its treasures will follow him like swarms of bees. Then he will summon a young man in the fullness of youth and strike him with a sword, cutting him into two pieces and separating them by the distance of an arrow-shot to its target. Then he will call him, and the man will come forward with his face radiant and laughing. While he is in that state, Allah will send the Messiah, Jesus son of Mary. He will descend beside the white minaret east of Damascus, wearing two lightly dyed garments and resting his hands upon the wings of two angels. When he lowers his head, drops will fall from it, and when he raises it, beads like pearls will roll from him. No disbeliever who smells the fragrance of his breath will remain alive, and his breath will reach as far as his sight reaches. He will pursue the Dajjāl until he catches him at the gate of Ludd and kills him. Then Jesus son of Mary will come to a people whom Allah protected from the Dajjāl. He will wipe their faces and inform them of their ranks in Paradise. While matters are in that state, Allah will reveal to Jesus: ‘I have brought forth servants of Mine whom no one has the power to fight. Take My servants to safety upon the Mount.’ Then Allah will send Gog and Magog, and they will descend rapidly from every elevated place. Their first ranks will pass by the Lake of Tiberias and drink what is in it. Their last ranks will pass by and say: ‘There was once water here.’ The Prophet of Allah, Jesus, and his companions will then be besieged until the head of an ox will be more valuable to one of them than one hundred dinars are to one of you today. The Prophet of Allah, Jesus, and his companions will supplicate to Allah, and Allah will send worms into the necks of Gog and Magog, so that by morning they will all fall dead like the death of a single soul. Then the Prophet of Allah, Jesus, and his companions will descend to the earth and will not find even a handspan of land that is not filled with their foul odor and stench. The Prophet of Allah, Jesus, and his companions will supplicate to Allah, and Allah will send birds whose necks are like the necks of Bactrian camels. They will carry the corpses away and cast them wherever Allah wills. Then Allah will send rain which no house of baked clay or tent of hair will be able to keep out. It will wash the earth until it leaves it like a polished surface. Then it will be said to the earth: ‘Bring forth your fruits and return your blessings.’ On that day, a group of people will eat from a single pomegranate and shelter beneath its rind. Blessing will be placed in milk so greatly that the milk of one she-camel will suffice a large group of people, the milk of one cow will suffice an entire tribe, and the milk of one ewe will suffice an entire clan. While they are in that state, Allah will send a pleasant wind which will take them beneath their armpits and seize the soul of every believer and every Muslim. Only the worst people will remain, openly engaging in sexual intercourse like donkeys, and upon them the Hour will be established.”"]},"buhuth":{"en":["The word:","“qaṭaṭ”","means extremely curly-haired.","The word:","“ṭāfiʾah,”","when read with a hamzah, means that the eye has no light in it. It has also been narrated without the hamzah, meaning that it protrudes from its place.","The word:","“khallah”","means a route or opening between al-Shām and Iraq.","The expression:","“ʿātha”","means to spread corruption, or to move swiftly in spreading it.","His statement:","“O servants of Allah, remain firm”","means: remain steadfast upon Islam. This is a warning from the Prophet ﷺ concerning the tribulation and an instruction to remain steadfast in Islam.","“Sāriḥatuhum”","means their grazing livestock.","“Dhurā”","is the plural of dhurwah, meaning the highest part of the camel’s hump, and here indicates abundant fatness.","“And their flanks more extended”","is an expression indicating fullness and satiation.","“Jazlatayn”","means two pieces.","The expression:","“The distance of an arrow-shot to the target”","means that the distance between the two pieces will be approximately the distance of an arrow shot toward its target.","The expression:","“between two mahrūd garments”","refers to two garments resembling cloth dyed with hurd. It has also been explained as cloth dyed with wars and saffron. The intent is to describe the beauty of his clothing.","The words:","“When he lowers his head, drops will fall, and when he raises it, beads like pearls will roll from him”","describe the beauty of Jesus, peace be upon him, in his appearance and clothing.","“The gate of Ludd,”","with a ḍammah on the lām and a doubled dāl, refers to a place in Palestine, today a city near Jerusalem.","“Lā yadān”","means that no one will possess the strength or ability to fight them.","“Naghaf”","refers to worms found in the noses of camels and sheep.","The words:","“No house will keep it out”","mean that even a house constructed of madar—hardened clay—will not prevent the rain from entering.","“Al-zalafah”","has been explained as a water basin and also as a mirror, expressing the earth’s complete cleanliness and smoothness.","“Al-risl”","means milk.","“Al-laqḥah”","means a she-camel that has recently given birth.","“Al-fiʾām”","means a large group of people.","“Al-fakhidh”","is a subdivision below the baṭn, while the baṭn itself is a subdivision below the tribe.","“Yatahārajūn”","means that men will engage in sexual intercourse with women openly in the presence of people, as donkeys do.","“Al-harj,” with a sākin rāʾ, here means sexual intercourse.","This indicates the widespread prevalence of corruption and immorality. It is established in authentic narrations:","“The Hour will not be established except upon the worst of people.”","Regarding the words:","“At the white minaret east of Damascus,”","another narration states that Jesus, peace be upon him, will descend at Bayt al-Maqdis, and another mentions Jordan. The first wording is the strongest.","Ibn Kathīr said:","“The most famous report concerning the place of his descent is that it will be at the eastern white minaret in Damascus. I have seen in some books that he will descend at the white minaret east of the Mosque of Damascus, and perhaps this is the preserved wording… There is no minaret in Damascus known as ‘the eastern minaret’ except the one beside the Umayyad Mosque on its eastern side. This is the most appropriate interpretation, because he will descend after the prayer has been established, and the imam of the Muslims will say to him:","‘O Spirit of Allah, come forward.’","He will say:","‘You come forward, for the prayer was established for you.’”","In another narration:","“Some of you are leaders over others, as an honor from Allah to this Ummah.”","Ibn Kathīr also mentioned that during his own time, in the year 741 AH, the Muslims rebuilt the minaret using white stone, and that its construction was funded from the wealth of Christians who had burned the earlier minaret which stood in its place.","He said:","“Perhaps this is among the manifest signs of Prophethood: that Allah caused this minaret to be rebuilt from the wealth of the Christians so that Jesus son of Mary may descend upon it, kill the pig, break the cross, and no longer accept jizyah from them. Rather, whoever accepts Islam will be spared; otherwise he will be killed, and likewise the other disbelievers.”","End quote.","Al-Nihāyah, al-Fitan wa al-Malāḥim (1/144).","The statement:","“The head of an ox will be better for one of them…”","indicates the extreme poverty and hardship they will experience after their provisions have been exhausted while they are besieged by Gog and Magog."]}},"tuhfa":{},"full":1,"dr":1,"rep":[16043],"tks":"صحيح: رواه مسلم (2937)."},{"num":709,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ٍ، وَجَاءَهُ رَجُلٌ، فَقَالَ: مَا هَذَا الْحَدِيثُ تُحَدِّثُ بِهِ ؟، تَقُولُ: إِنَّ السَّاعَةَ تَقُومُ إِلَى كَذَا وَكَذَا، فَقَالَ: سُبْحَانَ اللَّهِ أَوْ لَا إِلَهَ إِلَّا اللَّهُ، أَوْ كَلِمَةً نَحْوَهُمَا لَقَدْ هَمَمْتُ أَنْ لَا أُحَدِّثَ أَحَدًا شَيْئًا أَبَدًا إِنَّمَا، قُلْتُ: إِنَّكُمْ سَتَرَوْنَ بَعْدَ قَلِيلٍ أَمْرًا عَظِيمًا يُحَرَّقُ الْبَيْتُ وَيَكُونُ وَيَكُونُ، ثُمَّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَخْرُجُ الدَّجَّالُ فِي أُمَّتِي، فَيَمْكُثُ أَرْبَعِينَ لَا أَدْرِي أَرْبَعِينَ يَوْمًا، أَوْ أَرْبَعِينَ شَهْرًا، أَوْ أَرْبَعِينَ عَامًا، فَيَبْعَثُ اللَّهُ عِيسَى ابْنَ مَرْيَمَ، كَأَنَّهُ عُرْوَةُ بْنُ مَسْعُودٍ فَيَطْلُبُهُ فَيُهْلِكُهُ... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في الفتن (2940) عن عبيد الله بن معاذ العنبريّ، حدّثنا أبي، حدّثنا شعبة، عن النّعمان بن سالم، قال: سمعتُ يعقوب بن عاصم بن عروة بن مسعود الثقفي يقول: سمعت عبدالله بن عمرو وجاء رجل، فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2940).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ, may Allah be pleased with them, reported: A man came to him and said: “What is this narration you relate? You say that the Hour will occur by such-and-such a time?” He replied: “Glory be to Allah!” or, “There is no deity worthy of worship except Allah,” or words similar to that. “I nearly resolved never to narrate anything to anyone again. I only said that you will soon witness a tremendous event: the House will be burned, and such-and-such will happen.” Then he said: The Messenger of Allah ﷺ said: “The Dajjāl will emerge among my Ummah and remain for forty—I do not know whether forty days, forty months, or forty years. Then Allah will send Jesus son of Mary, who will resemble ʿUrwah ibn Masʿūd. He will pursue him and destroy him…”"]},"buhuth":{"en":["The words:","“I do not know whether forty days, forty months, or forty years”","represent uncertainty on the part of ʿAbdullāh ibn ʿAmr. Perhaps he did not precisely retain the detailed explanation from the Prophet ﷺ that appears in the preceding ḥadīth of al-Nawwās ibn Samʿān.","It is also possible that on one occasion the Prophet ﷺ simply said:","“Forty,”","without further explanation, while on another occasion he explained its details."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2940)."},{"num":710,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدُبٍ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: إِنَّ الدَّجَّالَ خَارِجٌ وَهُوَ أَعْوَرُ عَيْنِ الشِّمَالِ، عَلَيْهَا ظَفَرَةٌ غَلِيظَةٌ، وَإِنَّهُ يُبْرِئُ الْأَكْمَهَ وَالْأَبْرَصَ، وَيُحْيِي الْمَوْتَى، وَيَقُولُ لِلنَّاسِ أَنَا رَبُّكُمْ، فَمَنْ قَالَ: أَنْتَ رَبِّي، فَقَدْ فُتِنَ، وَمَنْ قَالَ: رَبِّيَ اللَّهُ، حَتَّى يَمُوتَ، فَقَدْ عُصِمَ مِنْ فِتْنَتِهِ، وَلَا فِتْنَةَ بَعْدَهُ عَلَيْهِ وَلَا عَذَابَ، فَيَلْبَثُ فِي الْأَرْضِ مَا شَاءَ اللَّهُ ثُمَّ يَجِيءُ عِيسَى ابْنُ مَرْيَمَ عَلَيْهِمَا السَّلَام مِنْ قِبَلِ الْمَغْرِبِ مُصَدِّقًا بِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَى مِلَّتِهِ، فَيَقْتُلُ الدَّجَّالَ، ثُمَّ إِنَّمَا هُوَ قِيَامُ السَّاعَةِ."],"takhrij":"حسن: رواه الإمام أحمد (20151)، والطبراني في الكبير (6918، 6918) كلاهما من حديث قتادة، عن الحسن، عن سمرة بن جندب، فذكره.","grade":"حسن","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (20151) and al-Ṭabarānī in al-Muʿjam al-Kabīr (6918, 6919).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Samurah ibn Jundub may Allah be pleased with him reported that the Prophet of Allah ﷺ used to say: “The Dajjāl will emerge. He will be blind in his left eye, over which there will be a thick covering. He will cure the one born blind and the leper, give life to the dead, and say to the people: ‘I am your lord.’ Whoever says: ‘You are my lord,’ has fallen into tribulation. But whoever continues saying: ‘My Lord is Allah,’ until he dies will be protected from his trial, and no trial or punishment will come upon him afterward. He will remain upon the earth for as long as Allah wills. Then Jesus son of Mary will come from the direction of the west, affirming Muḥammad ﷺ and following his religion. He will kill the Dajjāl, and after that only the establishment of the Hour will remain.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (20151)، والطبراني في الكبير (6918، 6919)."},{"num":711,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ الْيَمَانِ فِي حَدِيثِ طَوِيل وَفِيهِ: فَلَمَّا قَامُوا يُصَلُّونَ نَزَلَ عِيسَى ابْنُ مَرْيَمَ أَمَامَهُمْ فَصَلَّى بِهِمْ (أَيْ فِي بَيْتِ الْمَقْدِسِ)، فَلَمَّا انْصَرَفَ قَالَ: هَكَذَا، فَرِّجُوا بَيْنِي وَبَيْنَ عَدُوِّ اللَّهِ (الدَّجَّال).قَالَ: فَيَذُوبُ يَعْنِي ذَوْبَ الْمِلْحِ فَيُسَلِّطُ اللَّهُ عَلَيْهِمُ الْمُسْلِمِينَ فَيَقْتُلُونَهُمْ حَتَّى إِنَّ الْحَجَرَ وَالشَّجَرَ لَيُنَادِي: يَا عَبْدَ اللَّهِ، يَا عَبْدَ الرَّحْمَنِ، يَا مُسْلِمُ هَذَا يَهُودِيٌّ فَاقْتُلْهُ، فَيُعِينُهُمُ اللَّهُ وَيَظْهَرُ الْمُسْلِمُونَ، فَيَكْسِرُ الصَّلِيبَ، وَيَقْتُلُ الْخِنْزِيرَ، وَيَضَعُ الْجِزْيَةَ...."],"takhrij":"صحيح: رواه ابن منده (1033)، والحاكم (8507) كلاهما عن سعيد بن سليمان الواسطيّ، ثنا خلف بن خليفة، عن أبي مالك الأشجعيّ، عن ربعي بن حراش، عن حذيفة، فذكر الحديث بطوله، وهو مذكور في موضعه، واللّفظ لابن منده.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Ibn Mandah (1033) and al-Ḥākim (8507).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Ḥudhayfah ibn al-Yamān may Allah be pleased with him reported in a lengthy narration, in which it says: “When they stand for prayer, Jesus son of Mary will descend as their leader and pray with them”—meaning in Bayt al-Maqdis. When the prayer has ended, he will say: “Open the way between me and the enemy of Allah,” meaning the Dajjāl. “He will begin to melt like salt melts. Then Allah will empower the Muslims against his followers and they will kill them, until even stones and trees will call out: ‘O ʿAbdullāh, O ʿAbd al-Raḥmān, O Muslim, there is a Jew here with me, so kill him.’ Allah will aid them and the Muslims will prevail. Jesus will break the cross, kill the pig, and abolish the jizyah…”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن منده (1033)، والحاكم (8507)."},{"num":712,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ أَسِيدٍ الْغِفَارِيِّ قَالَ: اطَّلَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْنَا وَنَحْنُ نَتَذَاكَرُ، فَقَالَ: مَا تَذَاكَرُونَ؟ قَالُوا: نَذْكُرُ السَّاعَةَ، قَالَ: إِنَّهَا لَنْ تَقُومَ حَتَّى تَرَوْنَ قَبْلَهَا عَشْرَ آيَاتٍ، فَذَكَرَ الدُّخَانَ، وَالدَّجَّالَ، وَالدَّابَّةَ، وَطُلُوعَ الشَّمْسِ مِنْ مَغْرِبِهَا، وَنُزُولَ عِيسَى ابْنِ مَرْيَمَ عَلَيْهِ السَّلَام، وَيَأَجُوجَ وَمَأْجُوجَ، وَثَلَاثَةَ خُسُوفٍ خَسْفٌ بِالْمَشْرِقِ، وَخَسْفٌ بِالْمَغْرِبِ، وَخَسْفٌ بِجَزِيرَةِ الْعَرَبِ، وَآخِرُ ذَلِكَ نَارٌ تَخْرُجُ مِنْ الْيَمَنِ تَطْرُدُ النَّاسَ إِلَى مَحْشَرِهِمْ.","وَفِي رِوَايَةِ: وَنَارٌ تَخْرُجُ مِنْ قُعْرَةِ عَدَنٍ.","وَفِي رِوَايَةِ: وَرِيحٌ تُلْقِي النَّاسَ فِي الْبَحْرِ."],"takhrij":"صحيح: رواه مسلم في الفتن (2901) من طرق عن سفيان بن عيينة، عن فُراتٍ القزّاز، عن أبي الطّفيل، عن حذيفة بن أسيد الغفاريّ، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2901). The other wordings were also narrated by Muslim.","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Ḥudhayfah ibn Usayd al-Ghifārī, may Allah be pleased with him, reported: The Prophet ﷺ came upon us while we were discussing something and asked: “What are you discussing?” They replied: “We are discussing the Hour.” He said: “It will not be established until you see ten signs before it.” He then mentioned: “The smoke, the Dajjāl, the Beast, the rising of the sun from the west, the descent of Jesus son of Mary peace be upon him, Gog and Magog, and three major landslides: one in the east, one in the west, and one in the Arabian Peninsula. The last of them will be a fire emerging from Yemen that will drive the people toward their place of gathering.” In another narration:","“A fire will emerge from the depths of Aden.” And in another narration:","“A wind that will cast people into the sea.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2901)، والروايات الأخرى أيضا عند مسلم."},{"num":713,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ أَسِيدٍ فِي حَدِيثِ طَوِيل وَفِيهِ: إِذَا أَصْبَحُوا، فَيُصْبِحُونَ وَمَعَهُمْ عِيسَى ابْنِ مَرْيَمَ، فَيَقْتُلُ الدَّجَّالَ، وَيَهْزِمُ أَصْحَابَهُ، حَتَّى إِنَّ الشَّجَرَ وَالْحَجَرَ وَالْمَدَرَ، يَقُولُ: يَا مُؤْمِنُ، هَذَا يَهُودِيٌّ عِنْدِي، فَاقْتُلْهُ... الْحَدِيثَ."],"takhrij":"صحيح: رواه الحاكم (8612) من حديث مسدّد، ثنا معاذ بن هشام، حدثني أبي، عن قتادة، عن أبي الطفيل، قال: كنتُ بالكوفة. فقيل: خرج الدّجال. قال: فأتينا حذيفة بن أسيد، فذكر مثله.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ḥākim (8612).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Ḥudhayfah ibn Usayd may Allah be pleased with him reported in a lengthy narration, in which it says: “When morning comes, Jesus son of Mary will be among them. He will kill the Dajjāl and defeat his followers, until even the tree, stone, and clod of earth will say: ‘O believer, there is a Jew here with me, so kill him…’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الحاكم (8612)."},{"num":714,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ مَوْلَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّم: عِصَابَتَانِ مِنْ أُمَّتِي أَحْرَزَهُمَا اللَّهُ مِنَ النَّارِ: عِصَابَةٌ تَغْزُو الْهِنْدَ، وَعِصَابَةٌ تَكُونُ مَعَ عِيسَى ابْنِ مَرْيَمَ."],"takhrij":"حسن: رواه النسائيّ (3175) عن محمد بن عبدالله بن عبدالرحيم، حدثنا أسد بن موسى، قال: حدثنا بقية، قال: حدثني أبو بكر الزّبيدي، عن أخيه محمد بن الوليد، عن لقمان بن عامر، عن عبدالأعلى بن عدي البهرانيّ، عن ثوبان، فذكره.","grade":"حسن","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Nasāʾī (3175), Aḥmad (22396), al-Ṭabarānī in al-Muʿjam al-Awsaṭ (6737), and in Musnad al-Shāmiyyīn (1851).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Thawbān, the freed servant of the Messenger of Allah ﷺ, reported that the Messenger of Allah ﷺ said: “Two groups from my Ummah Allah will protect from the Fire: a group that fights in India, and a group that will be with Jesus son of Mary.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (3175)، وأحمد (22396)، والطبراني في الأوسط (6737)، وفي مسند الشاميين (1851)."},{"num":715,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: سَمِعْتُ النَّبِيّَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي يُقَاتِلُونَ عَلَى الْحَقِّ، ظَاهِرِينَ إِلَى يَوْمِ الْقِيَامَةِ قَالَ: فَيَنْزِلُ عِيسَى ابْنُ مَرْيَمَ عَلَيْهِ السَّلام، فَيَقُولُ أَمِيرُهُمْ: تَعَالَ صَلِّ لَنَا، فَيَقُولُ: لَا، إِنَّ بَعْضَكُمْ عَلَى بَعْضٍ أُمَرَاءُ، تَكْرِمَةَ اللَّهِ هَذِهِ الأُمَّةَ."],"takhrij":"صحيح: رواه مسلم في الإيمان (156) من طرق عن حجاج (وهو ابن محمد)، عن ابن جريج، قال: أخبرني أبو الزبير، أن جابر بن عبدالله يقول (فذكره).","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (156).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: I heard the Prophet ﷺ say: “A group from my Ummah will continue fighting upon the truth, prevailing until the Day of Resurrection. Then Jesus son of Mary peace be upon him will descend, and their leader will say: ‘Come and lead us in prayer.’ He will reply: ‘No. Some of you are leaders over others, as an honor Allah has granted this Ummah.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (156)."},{"num":716,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ أَنَّهُ قَالَ: إِنَّ امْرَأَةً مِنَ الْيَهُودِ بِالْمَدِينَةِ وَلَدَتْ غُلَامًا مَمْسُوحَةٌ عَيْنُهُ، طَالِعَةٌ نَاتِئَةٌ، فَأَشْفَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكُونَ الدَّجَّالَ...... فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا ابْنَ صَائِدٍ، إِنَّا قَدْ خَبَّأْنَا لَكَ خَبِيئًا، فَمَا هُوَ؟ قَالَ: الدُّخُّ، الدُّخُّ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اخْسَأْ، اخْسَأْ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: ائْذَنْ لِي، فَأَقْتُلَهُ يَا رَسُولَ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنْ يَكُنْ هُوَ فَلَسْتَ صَاحِبَهُ، إِنَّمَا صَاحِبُهُ عِيسَى ابْنُ مَرْيَمَ، وَإِنْ لَا يَكُنْ فَلَيْسَ لَكَ أَنْ تَقْتُلَ رَجُلًا مِنْ أَهْلِ الْعَهْدِ، قَالَ: فَلَمْ يَزَلْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُشْفِقًا أَنَّهُ الدَّجَّالُ."],"takhrij":"صحيح: رواه الإمام أحمد (14955) عن محمد بن سابق، حدثنا إبراهيم طهمان، عن أبي الزبير، عن جابر، فذكره في حديث طويل.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (14955).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: “A Jewish woman in Madinah gave birth to a boy whose eye was defective, protruding, and bulging. The Messenger of Allah ﷺ feared that he might be the Dajjāl… The Messenger of Allah ﷺ said to him: ‘O Ibn Ṣayyād, we have concealed something for you. What is it?’ He replied: ‘Al-dukh, al-dukh.’ The Messenger of Allah ﷺ said: ‘Be humiliated! Be humiliated!’ ʿUmar ibn al-Khaṭṭāb said: ‘Permit me to kill him, O Messenger of Allah.’ The Messenger of Allah ﷺ replied: ‘If he is truly the Dajjāl, then you are not the one destined to deal with him; his opponent is Jesus son of Mary. But if he is not the Dajjāl, then you have no right to kill a man from among the people under covenant.’ Jābir said: The Messenger of Allah ﷺ continued to fear that he might be the Dajjāl.”"]},"buhuth":{"en":["The core of Jābir’s narration appears in an abbreviated form in Ṣaḥīḥ Muslim (2926), through Abū Naḍrah from Jābir ibn ʿAbdullāh, without this additional wording. It instead refers to the wording of the narration of al-Jarīrī from Abū Naḍrah from Abū Saʿīd, who said:","“The Messenger of Allah ﷺ and Abū Bakr met him on one of the roads of Madinah.","The Messenger of Allah ﷺ asked him:","‘Do you testify that I am the Messenger of Allah?’","He replied:","‘Do you testify that I am the messenger of Allah?’","The Messenger of Allah ﷺ said:","‘I believe in Allah, His angels, and His Books. What do you see?’","He replied:","‘I see a throne upon the water.’","The Messenger of Allah ﷺ said:","‘You see the throne of Iblīs upon the sea. What else do you see?’","He said:","‘I see a truthful one and a liar—or two liars and one truthful one.’","The Messenger of Allah ﷺ said:","‘The matter has been confused for him. Leave him.’”","End quote."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (14955)."},{"num":717,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: دَخَلَ عَلَيَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا أَبْكِي، فَقَالَ لِي: مَا يُبْكِيك؟ قُلْت: يَا رَسُولَ اللَّهِ، ذَكَرْتُ الدَّجَّالَ فَبَكَيْتُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنْ يَخْرُجْ الدَّجَّالُ وَأَنَا حَيٌّ كَفَيْتُكُمُوهُ، وَإِنْ يَخْرُجْ بَعْدِي فَإِنَّ رَبَّكُمْ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ، وَإِنَّهُ يَخْرُجُ فِي يَهُودِيَّةِ أَصْبَهَانَ حَتَّى يَأْتِيَ الْمَدِينَةَ، فَيَنْزِلَ نَاحِيَتَهَا، وَلَهَا يَوْمَئِذٍ سَبْعَةُ أَبْوَابٍ، عَلَى كُلِّ نَقْبٍ مِنْهَا مَلَكَانِ، فَيَخْرُجَ إِلَيْهِ شِرَارُ أَهْلِهَا حَتَّى الشَّامِ مَدِينَةٍ بِفِلَسْطِينَ بِبَابِ لُدٍّ.","وَقَالَ أَبُو دَاوُدَ مَرَّةً: حَتَّى يَأْتِيَ فِلَسْطِينَ بَابَ لُدٍّ، فَيَنْزِلَ عِيسَى عَلَيْهِ السَّلَام فَيَقْتُلَهُ، ثُمَّ يَمْكُثَ عِيسَى عَلَيْهِ السَّلَام فِي الْأَرْضِ أَرْبَعِينَ سَنَةً إِمَامًا عَدْلًا وَحَكَمًا مُقْسِطًا."],"takhrij":"حسن: رواه الإمام أحمد (24467) عن سليمان بن داود، قال: حدّثنا حرب بن شدّاد، عن يحيى بن أبي كثير، حدّثني الحضْرميّ بن لاحق، أنّ ذكوان أبا صالح أخبره، أنّ عائشة أخبرته، فذكرتْه.","grade":"حسن","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (24467) and authenticated by Ibn Ḥibbān (6822).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported: The Messenger of Allah ﷺ entered upon me while I was crying and asked: “What makes you cry?” I replied: “O Messenger of Allah, I remembered the Dajjāl, so I cried.” The Messenger of Allah ﷺ said: “If the Dajjāl emerges while I am alive, I will suffice you against him. If he emerges after me, then indeed your Lord, Mighty and Majestic, is not one-eyed. He will emerge among the Jews of Isfahan until he comes to Madinah and encamps near it. At that time Madinah will have seven gates, and at every entrance will be two angels. The worst of its people will go out to him, and he will continue toward al-Shām until he reaches a city in Palestine at the gate of Ludd.”","Abū Dāwūd once narrated: “Until he reaches Palestine at the gate of Ludd. Then Jesus, peace be upon him, will descend and kill him. Afterward, Jesus, peace be upon him, will remain upon the earth for forty years as a just imam and an equitable judge.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (24467)، وصححه ابن حبان (6822)."},{"num":718,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَهْبَطَ اللَّهُ تَعَالَى إِلَى الْأَرْضِ مُنْذُ خَلَقَ آدَمَ إِلَى أَنْ تَقُومَ السَّاعَةُ فِتْنَةً أَعْظَمَ مِنْ فِتْنَةِ الدَّجَّالِ، وَقَدْ قُلْتُ فِيهِ قَوْلًا لَمْ يَقُلْهُ أَحَدٌ قَبْلِي، إِنَّهُ آدَمُ جَعْدٌ، مَمْسُوحُ عَيْنِ الْيَسَارِ، عَلَى عَيْنِهِ ظَفَرَةٌ غَلِيظَةٌ، وَإِنَّهُ يُبْرِئُ الْأَكَمَهَ وَالْأَبْرَصَ، وَيَقُولُ: أَنَا رَبُّكُمْ، فَمَنْ قَالَ: رَبِّيَ اللَّهُ، فَلَا فِتْنَةَ عَلَيْهِ، وَمَنْ قَالَ: أَنْتَ رَبِّي، فَقَدِ افْتُتِنَ . يَلْبَثُ فِيكُمْ مَا شَاءَ اللَّهُ، ثُمَّ يَنْزِلُ عِيسَى ابْنُ مَرْيَمَ مُصَدِّقًا بِمُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى مِلَّتِهِ إِمَامًا مَهْدِيًّا وَحَكَمًا عَدْلًا فَيَقْتُلُ الدَّجَّالَ.","فَكَانَ الْحَسَنُ يَقُولُ: وَنَرَى أَنَّ ذَلِكَ عِنْدَ السَّاعَةِ."],"takhrij":"حسن: رواه الطبرانيّ في الأوسط (4580) عن عبدان بن أحمد، قال: حدثنا عمرو بن العباس الأرزيّ، قال حدثنا محمد بن مروان، قال: حدثنا يونس بن عبيد، عن الحسن، عن عبدالله بن مغفل، فذكر الحديث.","grade":"حسن","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (4577).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["ʿAbdullāh ibn Mughaffal may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Allah Most High has not sent down upon the earth, from the creation of Adam until the establishment of the Hour, any tribulation greater than the tribulation of the Dajjāl. I have said concerning him something no one before me said: He will have curly hair, his left eye will be wiped out, and over it will be a thick covering. He will cure the one born blind and the leper, and he will say: ‘I am your lord.’ Whoever says: ‘My Lord is Allah,’ will not be harmed by his tribulation. But whoever says: ‘You are my lord,’ has fallen into tribulation. He will remain among you for as long as Allah wills. Then Jesus son of Mary will descend, affirming Muḥammad ﷺ and following his religion, as a rightly guided imam and a just judge, and he will kill the Dajjāl.”","Al-Ḥasan used to say: “We consider that this will occur close to the Hour.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (4580)."},{"num":719,"demo":false,"sanad":"","matn":["عَنْ أَوْسِ بْنِ أَوْسٍ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَنْزِلُ عِيسَى ابْنُ مَرْيَمَ عَلَيْهِ السَّلَامُ عِنْدَ الْمَنَارَةِ الْبَيْضَاءِ شَرْقِيَّ دِمَشْقَ."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (590)، وتمّام في فوائده (1732)، والرّبعي في فضائل الشّام (106) كلّهم من طرق عن محمد بن شعيب، نا يزيد بن عبيدة، حدثني أبو الأشعث، عن أوس بن أوس الثقفيّ، فذكره.","grade":"حسن","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (1/186), Tammām in his Fawāʾid (1732), and al-Rabaʿī in Faḍāʾil al-Shām (106).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Aws ibn Aws al-Thaqafī may Allah be pleased with him reported that the Prophet ﷺ said: “Jesus son of Mary peace be upon him will descend beside the white minaret east of Damascus.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (590)، وتمام في فوائده (1732)، والربعي في فضائل الشام (106)."},{"num":720,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ عَلَى مَنْ نَاوَأَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ، وَيَنْزِلَ عِيسَى ابْنُ مَرْيَمَ."],"takhrij":"صحيح: رواه الإمام أحمد (19851) عن بهز، حدّثنا حمّاد بن سلمة، حدّثنا قتادة، عن مطرّف، عن عمران بن حصين، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (19851), with an authentic chain.","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “A group from my Ummah will continue to remain manifest upon the truth, prevailing over those who oppose them, until the command of Allah comes and Jesus son of Mary descends.”"]},"buhuth":{"en":["It was also narrated by Abū Dāwūd (2484) and Imām Aḥmad (19920), and authenticated by al-Ḥākim (2/71, 4/450), through another route. In that wording, instead of “until the command of Allah comes and Jesus son of Mary descends,” it says: “until the last of them fights the Messiah, the Dajjāl.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15678],"tks":"صحيح: رواه الإمام أحمد (19851)، وإسناده صحيح."},{"num":721,"demo":false,"sanad":"","matn":["عَنْ سَفِينَةَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خَطَبَنَا رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَلَا إِنَّهُ لَمْ يَكُنْ نَبِيٌّ قَبْلِي إِلَّا حَذَّرَ الدَّجَّالَ أُمَّتَهُ، وَهُوَ أَعْوَرُ عَيْنِهِ الْيُسْرَى، بِعَيْنِهِ الْيُمْنَى ظُفْرَةٌ غَلِيظَةٌ، مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَافِرٌ، يَخْرُجُ مَعَهُ وَادِيَانِ: أَحَدُهُمَا جَنَّةٌ، وَالْآخَرُ نَارٌ، فَنَارُهُ جَنَّةٌ وَجَنَّتُهُ نَارٌ، مَعَهُ مَلَكَانِ مِنَ الْمَلَائِكَةِ يُشْبِهَانِ نَبِيَّيْنِ مِنَ الْأَنْبِيَاءِ، لَوْ شِئْتُ سَمَّيْتُهُمَا بِأَسْمَائِهِمَا وَأَسْمَاءِ آبَائِهِمَا، وَاحِدٌ مِنْهُمَا عَنْ يَمِينِهِ وَالْآخَرُ عَنْ شِمَالِهِ، وَذَلِكَ فِتْنَةٌ، فَيَقُولُ الدَّجَّالُ: أَلَسْتُ بِرَبِّكُمْ؟ أَلَسْتُ أُحْيِي وَأُمِيتُ؟ فَيَقُولُ لَهُ أَحَدُ الْمَلَكَيْنِ: كَذَبْتَ. مَا يَسْمَعُهُ أَحَدٌ مِنَ النَّاسِ إِلَّا صَاحِبُهُ، فَيَقُولُ لَهُ: صَدَقْتَ. فَيَسْمَعُهُ النَّاسُ فَيَظُنُّونَ إِنَّمَا يُصَدِّقُ الدَّجَّالَ، وَذَلِكَ فِتْنَةٌ، ثُمَّ يَسِيرُ حَتَّى يَأْتِيَ الْمَدِينَةَ فَلَا يُؤْذَنُ لَهُ فِيهَا، فَيَقُولُ: هَذِهِ قَرْيَةُ ذَلِكَ الرَّجُلِ، ثُمَّ يَسِيرُ حَتَّى يَأْتِيَ الشَّامَ فَيُهْلِكُهُ اللهُ عِنْدَ عَقَبَةِ أَفِيقَ."],"takhrij":"حسن: رواه الإمام أحمد (21929)، والطبرانيّ في الكبير (6445).","grade":"حسن","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (21929) and al-Ṭabarānī in al-Muʿjam al-Kabīr (7/98).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Safīnah, the freed servant of the Messenger of Allah ﷺ, reported: The Messenger of Allah ﷺ delivered a sermon to us and said: “Indeed, there was no prophet before me except that he warned his nation about the Dajjāl. He is blind in his left eye, while upon his right eye is a thick growth, and between his eyes is written: ‘Disbeliever.’ Two valleys will accompany him: one of them will appear to be Paradise and the other Fire. His Fire will be Paradise, and his Paradise will be Fire. With him will be two angels resembling two prophets. If I wished, I could name those two prophets and their fathers. One will be on his right and the other on his left, and this will itself be a trial. The Dajjāl will say: ‘Am I not your lord? Do I not give life and cause death?’ One of the two angels will say to him: ‘You have lied.’ No one among the people will hear this except the other angel, who will say to him: ‘You have spoken the truth.’ The people will hear this and imagine that he is affirming the Dajjāl, and this will be a trial. Then he will travel until he reaches Madinah, but he will not be permitted to enter it. He will say: ‘This is the city of that man.’ Then he will continue until he reaches al-Shām, where Allah, Mighty and Majestic, will destroy him at the pass of Afīq.”"]},"buhuth":{"en":["It was also narrated by Ibn Abī Shaybah (15/137–138), Abū Dāwūd al-Ṭayālisī in his Musnad (1202), and Ibn ʿAdī in al-Kāmil (2/846).","Although the chain of this ḥadīth is judged Ḥasan, it contains some unusual and objectionable wording. Ḥashraj ibn Nabātah may have erred in some of these expressions, including:","“With him will be two angels,”","which is not found in another authentic ḥadīth.","Likewise, the wording:","“At the pass of Afīq.”","Afīq is a well-known mountain pass in the region of Ḥawrān on the route toward Jordan, approximately two miles long.","The established report is that Jesus son of Mary peace be upon him will kill the Dajjāl at the Gate of Ludd, as stated in the ḥadīth of al-Nawwās ibn Samʿān and other narrations."]}},"tuhfa":{},"full":1,"dr":1,"rep":[16050],"tks":"حسن: رواه الإمام أحمد (21929)، والطبراني في الكبير (6445)."},{"num":722,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ قَالَ: خَطَبَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ أَكْثَرُ خُطْبَتِهِ حَدِيثًا حَدَّثَنَاهُ عَنْ الدَّجَّالِ وَحَذَّرَنَاهُ ... فَقَالَتْ أُمُّ شَرِيكٍ بِنْتُ أَبِي الْعَكَرِ: يَا رَسُولَ اللَّهِ، فَأَيْنَ الْعَرَبُ يَوْمَئِذٍ؟ قَالَ: هُمْ يَوْمَئِذٍ قَلِيلٌ، وَجُلُّهُمْ بِبَيْتِ الْمَقْدِسِ، وَإِمَامُهُمْ رَجُلٌ صَالِحٌ، فَبَيْنَمَا إِمَامُهُمْ قَدْ تَقَدَّمَ يُصَلِّي بِهِمُ الصُّبْحَ، إِذْ نَزَلَ عَلَيْهِمْ عِيسَى ابْنُ مَرْيَمَ الصُّبْحَ، فَرَجَعَ ذَلِكَ الْإِمَامُ يَنْكُصُ، يَمْشِي الْقَهْقَرَى لِيَتَقَدَّمَ عِيسَى يُصَلِّي بِالنَّاسِ، فَيَضَعُ عِيسَى يَدَهُ بَيْنَ كَتِفَيْهِ، ثُمَّ يَقُولُ لَهُ: تَقَدَّمْ فَصَلِّ، فَإِنَّهَا لَكَ أُقِيمَتْ، فَيُصَلِّي بِهِمْ إِمَامُهُمْ، فَإِذَا انْصَرَفَ، قَالَ عِيسَى عَلَيْهِ السَّلَام: افْتَحُوا الْبَابَ، فَيُفْتَحُ وَوَرَاءَهُ الدَّجَّالُ مَعَهُ سَبْعُونَ أَلْفَ يَهُودِيٍّ، كُلُّهُمْ ذُو سَيْفٍ مُحَلًّى وَسَاجٍ، فَإِذَا نَظَرَ إِلَيْهِ الدَّجَّالُ ذَابَ كَمَا يَذُوبُ الْمِلْحُ فِي الْمَاءِ، وَيَنْطَلِقُ هَارِبًا، وَيَقُولُ عِيسَى عَلَيْهِ السَّلَام: إِنَّ لِي فِيكَ ضَرْبَةً لَنْ تَسْبِقَنِي بِهَا، فَيُدْرِكُهُ عِنْدَ بَابِ اللُّدِّ الشَّرْقِيِّ فَيَقْتُلُهُ، فَيَهْزِمُ اللَّهُ الْيَهُودَ، فَلَا يَبْقَى شَيْءٌ مِمَّا خَلَقَ اللَّهُ يَتَوَارَى بِهِ يَهُودِيٌّ إِلَّا أَنْطَقَ اللَّهُ ذَلِكَ الشَّيْءَ، لَا حَجَرَ، وَلَا شَجَرَ، وَلَا حَائِطَ، وَلَا دَابَّةَ إِلَّا الْغَرْقَدَةَ، فَإِنَّهَا مِنْ شَجَرِهِمْ لَا تَنْطِقُ، إِلَّا قَالَ: يَا عَبْدَ اللَّهِ الْمُسْلِمَ، هَذَا يَهُودِيٌّ، فَتَعَالَ اقْتُلْهُ...(فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ)."],"takhrij":"حسن: رواه ابن ماجه (4077) عن علي بن محمد، قال: حدّثنا عبدالرحمن المحاربيّ، عن إسماعيل بن رافع، عن أبي زرعة السيبانيّ يحيى بن أبي عمرو، عن أبي أمامة الباهليّ، فذكر الحديث بطوله، وهو مذكور في موضعه.","grade":"حسن","chapter_ar":"باب وجوب الإيمان بنزول عيسى عليه السلام وقتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (4077), Tammām in his Fawāʾid (1731), and Abū Dāwūd (4322).","chapter_en":"The Obligation of Believing in the Descent of Jesus, peace be upon him, and His Killing of the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Abū Umāmah al-Bāhilī, may Allah be pleased with him, reported: The Messenger of Allah ﷺ delivered a sermon to us, and most of his sermon concerned the Dajjāl and his warning to us about him. In the narration, Umm Sharīk bint Abī al-ʿAkar asked: “O Messenger of Allah, where will the Arabs be on that day?” He replied: “They will be few on that day, and most of them will be at Bayt al-Maqdis. Their leader will be a righteous man. While their leader has stepped forward to lead them in the Fajr prayer, Jesus son of Mary will descend upon them in the morning. Their leader will begin stepping backward so that Jesus may come forward and lead the people in prayer. Jesus will place his hand between his shoulders and say: ‘Go forward and pray, for the prayer was established for you.’ So their leader will lead them in prayer. When he finishes, Jesus peace be upon him will say: ‘Open the gate.’ It will be opened, and behind it will be the Dajjāl accompanied by seventy thousand Jews, each carrying an ornamented sword and a sāj. When the Dajjāl sees Jesus, he will begin melting as salt melts in water and will turn to flee. Jesus peace be upon him will say: ‘I have a blow destined for you which you will not escape.’ He will catch him at the eastern Gate of Ludd and kill him. Then Allah will defeat the Jews. Nothing among Allah’s creation behind which a Jew hides — no stone, tree, wall, or animal — will remain except that Allah will cause it to speak, with the exception of the gharqad tree, for it is among their trees and will not speak. It will say: ‘O Muslim servant of Allah, there is a Jew here, so come and kill him.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (4077)، وتمام في فوائده (1731)، وأبو داود (4322)."},{"num":723,"demo":false,"sanad":"","matn":["عَنْ النَّوَّاسِ بْنِ سَمْعَانَ قَالَ: ذَكَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الدَّجَّالَ ذَاتَ غَدَاةٍ، فَخَفَّضَ فِيهِ وَرَفَّعَ حَتَّى ظَنَنَّاهُ فِي طَائِفَةِ النَّخْلِ. ( فَمَا ذَكَرَ فِيهِ: إِنَّ عِيسَى عَلَيْهِ السَّلَام ) يُدْرِكَهُ بِبَابِ لُدٍّ، فَيَقْتُلُهُ."],"takhrij":"صحيح: رواه مسلم في الفتن (2937) في حديث طويل سبق ذكره في أوّل الباب.","grade":"صحيح","chapter_ar":"باب إن عيسى عليه السلام يقتل الدجال بباب لُدّ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim in al-Fitan (2937).","chapter_en":"Jesus, peace be upon him, Will Kill the Dajjāl at the Gate of Ludd","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":14,"content":{"translation":{"en":["Al-Nawwās ibn Samʿān, may Allah be pleased with him, reported: The Messenger of Allah ﷺ mentioned the Dajjāl one morning, at times lowering his voice and at other times raising it, until we imagined that he was among a cluster of date-palms. Among what he mentioned was: “Jesus, peace be upon him, will catch him at the Gate of Ludd and kill him.”"]},"buhuth":{"en":["Ludd is a city west of Jerusalem, approximately twenty-six miles away."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2937)."},{"num":724,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: إِنِّي لَأَرْجُو إِنْ طَالَ بِي عُمُرٌ أَنْ أَلْقَى عِيسَى ابْنَ مَرْيَمَ عَلَيْهِ السَّلَام، فَإِنْ عَجِلَ بِي مَوْتٌ، فَمَنْ لَقِيَهُ مِنْكُمْ فَلْيُقْرِئْهُ مِنِّي السَّلَامَ."],"takhrij":"صحيح: رواه الإمام أحمد (7970) عن محمد بن جعفر، حدّثنا شعبة، عن محمد بن زياد، عن أبي هريرة، فذكر مثله.","grade":"صحيح","chapter_ar":"باب سلام النبي ﷺ على عيسى عليه السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (7970).","chapter_en":"The Prophet ﷺ Sending Greetings of Peace to Jesus, peace be upon him,","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “I hope, if my life is prolonged, that I will meet Jesus son of Mary. But if death comes to me sooner, then whoever among you meets him should convey to him my greetings of peace.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (7970)."},{"num":725,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَدْرَكَ مِنْكُمْ عِيسَى ابْنَ مَرْيَمَ فَلْيَقْرَأْ مِنِّي السَّلَامَ."],"takhrij":"حسن: رواه الحاكم (8635) عن محمد بن المظفّر الحافظ، ثنا عبدالله بن سليمان، ثنا محمد بن مصفى الحمصيّ، ثنا إسماعيل، عن أيوب، عن أبي قلابة، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب سلام النبي ﷺ على عيسى عليه السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ḥākim (8635).","chapter_en":"The Prophet ﷺ Sending Greetings of Peace to Jesus, peace be upon him,","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":15,"content":{"translation":{"en":["Anas may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Whoever among you lives to meet Jesus son of Mary should convey to him my greetings of peace.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (8635)."},{"num":726,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَا أَوْلَى النَّاسِ بِعِيسَى ابْنِ مَرْيَمَ فِي الدُّنْيَا وَالْآخِرَةِ وَالْأَنْبِيَاءُ إِخْوَةٌ لِعَلَّاتٍ أُمَّهَاتُهُمْ شَتَّى وَدِينُهُمْ وَاحِدٌ."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3443) عن محمد بن سنان، حدّثنا فليح بن سليمان، حدثنا هلال بن علي، عن عبدالرحمن بن أبي عمرة، عن أبي هريرة، فذكره. ورواه مسلم في الفضائل (2365) من وجه آخر عن همّام بن منبه، عن أبي هريرة وزاد في آخره: فليس بيننا نبيٌّ.","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ: أنا أولى الناس بعيسى ابن مريم عليهما السلام","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3443) and Muslim in al-Faḍāʾil (2365).","chapter_en":"The Prophet’s ﷺ Statement: “I Am the Closest of People to Jesus Son of Mary”","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I am the closest of all people to Jesus son of Mary in this world and the Hereafter. The prophets are paternal brothers: their mothers are different, but their religion is one.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3443)، ومسلم (2365)."},{"num":727,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، لَيُهِلَّنَّ ابْنُ مَرْيَمَ بِفَجِّ الرَّوْحَاءِ حَاجًّا أَوْ مُعْتَمِرًا أَوْ لَيَثْنِيَنَّهُمَا."],"takhrij":"صحيح: رواه مسلم في الحجّ (1252) من حديث سفيان بن عيينة، حدثني الزهريّ، عن حنظلة الأسلميّ، قال: سمعتُ أبا هريرة يحدّث، فذكره.","grade":"صحيح","chapter_ar":"باب أن عيسى ابن مريم عليه السلام يحج البيت بعد قتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1252).","chapter_en":"Jesus Son of Mary peace be upon him Will Perform Ḥajj to the House After Killing the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “By the One in whose Hand is my soul, the son of Mary will certainly enter into iḥrām at the mountain pass of al-Rawḥāʾ, performing Ḥajj or ʿUmrah, or combining the two.”"]},"buhuth":{"en":["The pass of al-Rawḥāʾ lay along the route of the Prophet ﷺ from Madinah to Badr."]}},"tuhfa":{},"full":1,"dr":1,"rep":[4939,16000],"tks":"صحيح: رواه مسلم (1252)."},{"num":728,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَنْزِلُ عِيسَى ابْنُ مَرْيَمَ، فَيَقْتُلُ الْخِنْزِيرَ، وَيَمْحِي الصَّلِيبَ، وَيُجْمَعُ لَهُ الصَّلَاةُ، وَيُعْطِي الْمَالَ حَتَّى لَا يُقْبَلَ، وَيَضَعُ الْخَرَاجَ، وَيَنْزِلُ الرَّوْحَاءَ، فَيَحُجُّ مِنْهَا، أَوْ يَعْتَمِرُ، أَوْ يَجْمَعُهُمَا."],"takhrij":"صحيح: رواه الإمام أحمد (7903) عن يزيد، أخبرنا سفيان، عن الزهريّ، عن حنظلة، عن أبي هريرة، فذكر الحديث مثله.","grade":"صحيح","chapter_ar":"باب أن عيسى ابن مريم عليه السلام يحج البيت بعد قتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (7903).","chapter_en":"Jesus Son of Mary peace be upon him Will Perform Ḥajj to the House After Killing the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Jesus son of Mary will descend. He will kill the pig, abolish the cross, the prayer will be established for him, wealth will become so abundant that it will not be accepted, and he will abolish the jizyah. He will then come to al-Rawḥāʾ and from there perform Ḥajj or ʿUmrah, or combine the two.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (7903)."},{"num":729,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيَهْبِطَنَّ عِيسَى ابْنُ مَرْيَمَ حَكَمًا عَدْلا، وَإِمَامًا مُقْسِطًا وَلَيَسْلُكَنَّ فَجًّا حَاجًّا أَوْ مُعْتَمِرًا أَوْ بِنِيِّتِهِمَا وَلَيَأْتِيَنَّ قَبْرِي حَتَّى يُسَلِّمَ وَلأَرُدَّنَ عَلَيْهِ، يَقُولُ أَبُو هُرَيْرَةَ: أَيْ بَنِي أَخِي إِنْ رَأَيْتُمُوهُ، فَقُولُوا: أَبُو هُرَيْرَةَ يُقْرِئُكَ السَّلامَ."],"takhrij":"حسن: رواه الحاكم (4162) عن أبي الطيب محمد بن أحمد الحيريّ، ثنا محمد بن عبدالوهّاب، ثنا يعلى بن عبيد، ثنا محمد بن إسحاق، عن سعيد بن أبي سعيد المقبريّ، عن عطاء مولى أمّ صبية، وتحرّف فيه إلى أمّ حبيبة، قال: سمعت أبا هريرة، فذكره.","grade":"حسن","chapter_ar":"باب أن عيسى ابن مريم عليه السلام يحج البيت بعد قتله الدجال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan through supporting chains and corroborating reports: Narrated by al-Ḥākim (4162).","chapter_en":"Jesus Son of Mary peace be upon him Will Perform Ḥajj to the House After Killing the Dajjāl","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالرسل عليهم الصلاة والسلام","group_en":"Collection of Chapters Concerning Belief in the Messengers, Peace and Blessings Be Upon Them","part_no":2,"group_no":8,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “Jesus son of Mary will certainly descend as a just ruler and an equitable imam. He will certainly travel through a mountain pass while performing Ḥajj or ʿUmrah, or intending both, and he will certainly come to my grave and greet me with peace, and I will return his greeting.” Abū Hurayrah said: “O son of my brother, if you see him, then say: ‘Abū Hurayrah conveys greetings of peace to you.’”"]},"buhuth":{"en":["The author notes that the wording:","“He will certainly come to my grave…”","has not, to the author’s knowledge, been transmitted through authentic routes."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (4162)، إلا قوله:."},{"num":730,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ مِنَ الْأَنْبِيَاءِ قَبْلِي: نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا، وَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلَاةُ فَلْيُصَلِّ، وَأُحِلَّتْ لِي الْغَنَائِمُ، وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَى النَّاسِ كَافَّةً، وَأُعْطِيتُ الشَّفَاعَةَ."],"takhrij":"متفق عليه: رواه البخاريّ في الصلاة (438)، ومسلم في المساجد (521) كلاهما من حديث هُشيم، قال: حدّثنا سيَّار، وهو أبو الحكم، قال: حدّثنا يزيد الفقير، قال: حدّثنا جابر بن عبدالله، فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بعموم رسالة النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (438) and Muslim (521).","chapter_en":"The Obligation of Believing in the Universality of the Prophet’s ﷺ Message","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “I have been given five things which no prophet before me was given: I have been aided by fear cast into the enemy from the distance of a month’s journey; the earth has been made for me a place of prayer and a means of purification, so wherever a man from my Ummah is when the time for prayer comes, let him pray; the spoils of war have been made lawful for me; a prophet used to be sent specifically to his own people, whereas I have been sent to all mankind; and I have been granted intercession.”"]},"intro":{"ar":["قال الله تعالى:","﴿وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِلنَّاسِ بَشِيرًا وَنَذِيرًا﴾","[سبأ: ٢٨]","وقال الله تعالى:","﴿قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللهِ إِلَيْكُمْ جَمِيعًا﴾","[الأعراف: ١٥٨]","وقال تعالى:","﴿يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمْ بُرْهَانٌ مِنْ رَبِّكُمْ وَأَنْزَلْنَا إِلَيْكُمْ نُورًا مُبِينًا﴾","[النساء: ١٧٤]","وغيرها من الآيات، وهي كثيرة جدًا."],"en":["Allah Most High said:","“We have not sent you except to all mankind, as a bearer of glad tidings and a warner.”","[Sūrat Sabaʾ 34:28]","And Allah Most High said:","“Say: O mankind, indeed I am the Messenger of Allah to you all.”","[Sūrat al-Aʿrāf 7:158]","And He said:","“O mankind, there has come to you a proof from your Lord, and We have sent down to you a clear light.”","[Sūrat al-Nisāʾ 4:174]","There are many other verses concerning this as well."]}},"tuhfa":{},"full":1,"rep":[795,923],"tks":"متفق عليه: رواه البخاري (438)، ومسلم (521)."},{"num":731,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فُضِّلْتُ عَلَى الأَنْبِيَاءِ بِسِتٍّ، أُعْطِيتُ جَوَامِعَ الْكَلِمِ، وَنُصِرْتُ بِالرُّعْبِ، وَأُحِلَّتْ لِيَ الْغَنَائِمُ، وَجُعِلَتْ لِيَ الأَرْضُ طَهُورًا وَمَسْجِدًا، وَأُرْسِلْتُ إِلَى الْخَلْقِ كَافَّةً، وَخُتِمَ بِيَ النَّبِيُّونَ."],"takhrij":"صحيح: رواه مسلم في المساجد (523) من طرق عن إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة، فذكر مثله.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بعموم رسالة النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (523).","chapter_en":"The Obligation of Believing in the Universality of the Prophet’s ﷺ Message","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I have been favored over the prophets in six ways: I have been given concise yet comprehensive speech; I have been aided by fear cast into the enemy; the spoils of war have been made lawful for me; the earth has been made for me a means of purification and a place of prayer; I have been sent to all creation; and the prophets were sealed with me.”"]}},"tuhfa":{},"full":1,"rep":[796,8009,12026,12348,12906,13078],"tks":"صحيح: رواه مسلم (523)."},{"num":732,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُوتِيتُ خَمْسًا لَمْ يُؤْتَهُنَّ نَبِيٌّ كَانَ قَبْلِي نُصِرْتُ بِالرُّعْبِ، فَيُرْعَبُ مِنِّي الْعَدُوُّ عَنْ مَسِيرَةِ شَهْرٍ، وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا، وَأُحِلَّتْ لِي الْغَنَائِمُ وَلَمْ تَحِلَّ لِأَحَدٍ كَانَ قَبْلِي، وَبُعِثْتُ إِلَى الْأَحْمَرِ وَالْأَسْوَدِ، وَقِيلَ لِي: سَلْ تُعْطَهْ، فَاخْتَبَأْتُهَا شَفَاعَةً لِأُمَّتِي، وَهِيَ نَائِلَةٌ مِنْكُمْ إِنْ شَاءَ اللَّهُ، مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا."],"takhrij":"صحيح: رواه الإمام أحمد (21299) عن يعقوب، حدّثنا أبي، عن ابن إسحاق، حدّثني سليمان الأعمش، عن مجاهد بن جبر أبي الحجّاج، عن عبيد بن عمير اللّيثيّ، عن أبي ذر، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بعموم رسالة النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (21299).","chapter_en":"The Obligation of Believing in the Universality of the Prophet’s ﷺ Message","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Abū Dharr may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I was given five things which no prophet before me was given: I was aided by fear, so that the enemy fears me from the distance of a month’s journey; the earth was made for me a place of prayer and a means of purification; the spoils of war were made lawful for me, though they had not been made lawful for anyone before me; I was sent to the red and the black; and it was said to me: ‘Ask, and you will be given.’ So I reserved it as intercession for my Ummah. It will reach — if Allah wills — whoever among you meets Allah without associating anything with Him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[797,924],"tks":"صحيح: رواه الإمام أحمد (21299)."},{"num":733,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنَ الْأَنْبِيَاءِ نَبِيٌّ إِلَّا أُعْطِيَ مَا مِثْلهُ آمَنَ عَلَيْهِ الْبَشَرُ، وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَيَّ فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في فضائل القرآن (4981) ومسلم في الإيمان (152) كلاهما من حديث اللّيث، عن سعيد بن أبي سعيد المقبريّ، عن أبيه عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بعموم رسالة النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4981) and Muslim (152).","chapter_en":"The Obligation of Believing in the Universality of the Prophet’s ﷺ Message","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “There was no prophet except that he was given signs the like of which caused people to believe. What I have been given, however, is revelation which Allah revealed to me, and I therefore hope to have the greatest number of followers among them on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"rep":[3,9658,11819,11895,12747],"tks":"متفق عليه: رواه البخاري (4981)، ومسلم (152)."},{"num":734,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَا يَسْمَعُ بِي أَحَدٌ مِنْ هَذِهِ الأُمَّةِ يَهُودِيٌّ، وَلَا نَصْرَانِيٌّ، ثُمَّ يَمُوتُ وَلَمْ يُؤْمِنْ بِالَّذِي أُرْسِلْتُ بِهِ، إِلَّا كَانَ مِنْ أَصْحَابِ النَّارِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (153) عن يونس بن عبدالأعلى، أخبرنا ابن وهب، قال: وأخبرني عمرو، أن أبا يونس حدّثه عن أبي هريرة، فذكر مثله.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بعموم رسالة النبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (153).","chapter_en":"The Obligation of Believing in the Universality of the Prophet’s ﷺ Message","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “By the One in whose Hand is the soul of Muḥammad, no one from this nation — whether Jew or Christian — hears about me and then dies without believing in that with which I was sent except that he will be among the people of the Fire.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12548],"tks":"صحيح: رواه مسلم (153)."},{"num":735,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: مَا قَرَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْجِنِّ، وَمَا رَآهُمْ، انْطَلَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي طَائِفَةٍ مِنْ أَصْحَابِهِ عَامِدِينَ إِلَى سُوقِ عُكَاظٍ، وَقَدْ حِيلَ بَيْنَ الشَّيَاطِينِ وَبَيْنَ خَبَرِ السَّمَاءِ ... وَفِيهِ: فَانْطَلَقُوا يَضْرِبُونَ مَشَارِقَ الأَرْضِ وَمَغَارِبَهَا، فَمَرَّ النَّفَرُ الَّذِينَ أَخَذُوا نَحْوَ تِهَامَةَ، وَهُوَ بِنَخْلٍ عَامِدِينَ إِلَى سُوقِ عُكَاظٍ، وَهُوَ يُصَلِّي بِأَصْحَابِهِ صَلَاةَ الْفَجْرِ، فَلَمَّا سَمِعُوا الْقُرْآنَ، اسْتَمَعُوا لَهُ، وَقَالُوا: هَذَا الَّذِي حَالَ بَيْنَنَا وَبَيْنَ خَبَرِ السَّمَاءِ، فَرَجَعُوا إِلَى قَوْمِهِمْ، فَقَالُوا: يَا قَوْمَنَا، ﴿إِنَّا سَمِعْنَا قُرْءَانًا عَجَبًا يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ وَلَنْ نُشْرِكَ بِرَبِّنَا أَحَدًا﴾.. [سورة الجن: 1، 2]... الْحَدِيثَ."],"takhrij":"متفق عليه: رواه البخاري في كتاب الأذان (773) ومسلم في كتاب الصلاة (449، 149) كلا هما من رواية أبي عوانة، عن أبي بشر جعفر بن أبي وحشية، عن سعيد بن جبير، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في بعثة النبي ﷺ إلى الجن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (773) and Muslim (449:149).","chapter_en":"What Has Been Reported Concerning the Prophet ﷺ Being Sent to the Jinn","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, said: The Messenger of Allah ﷺ did not recite directly to the jinn on that occasion, nor did he see them. The Messenger of Allah ﷺ set out with a group of his Companions heading toward the market of ʿUkāẓ, after the devils had been prevented from obtaining news from heaven. The narration states: “They set out throughout the eastern and western regions of the earth. The group that traveled toward Tihāmah passed by Nakhlah while heading toward the market of ʿUkāẓ, where the Prophet ﷺ was leading his Companions in the Fajr prayer. When they heard the Qurʾān, they listened attentively to it and said: ‘This is what has come between us and the news of heaven.’ They then returned to their people and said: ‘O our people, indeed we have heard a wondrous Qurʾān. It guides to right guidance, so we have believed in it, and we will never associate anyone with our Lord…’” The ḥadīth continues."]},"intro":{"ar":["قال الله تعالى:","﴿وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنْصِتُوا فَلَمَّا قُضِيَ وَلَّوْا إِلَى قَوْمِهِمْ مُنْذِرِينَ ۝ قَالُوا يَا قَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنْزِلَ مِنْ بَعْدِ مُوسَى مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ يَهْدِي إِلَى الْحَقِّ وَإِلَى طَرِيقٍ مُسْتَقِيمٍ ۝ يَا قَوْمَنَا أَجِيبُوا دَاعِيَ اللهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُمْ مِنْ ذُنُوبِكُمْ وَيُجِرْكُمْ مِنْ عَذَابٍ أَلِيمٍ﴾","[الأحقاف: ٢٩–٣١]","وقال تعالى:","﴿قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِنَ الْجِنِّ فَقَالُوا إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا﴾","[الجن: ١]","وقال عز وجل:","﴿يَا مَعْشَرَ الْجِنِّ وَالْإِنْسِ أَلَمْ يَأْتِكُمْ رُسُلٌ مِنْكُمْ يَقُصُّونَ عَلَيْكُمْ آيَاتِي وَيُنْذِرُونَكُمْ لِقَاءَ يَوْمِكُمْ هَذَا قَالُوا شَهِدْنَا عَلَى أَنْفُسِنَا وَغَرَّتْهُمُ الْحَيَاةُ الدُّنْيَا وَشَهِدُوا عَلَى أَنْفُسِهِمْ أَنَّهُمْ كَانُوا كَافِرِينَ﴾","[الأنعام: ١٣٠]"],"en":["Allah Most High said:","“And when We directed to you a group of the jinn to listen to the Qurʾān, when they attended it they said: ‘Listen attentively.’ When it was concluded, they returned to their people as warners.","They said: ‘O our people, indeed we have heard a Book revealed after Moses, confirming what came before it. It guides to the truth and to a straight path.","O our people, respond to the caller of Allah and believe in him. He will forgive you some of your sins and protect you from a painful punishment.’”","[Sūrat al-Aḥqāf 46:29–31]","And He said:","“Say: It has been revealed to me that a group of the jinn listened and said: ‘Indeed, we have heard a wondrous Qurʾān.’”","[Sūrat al-Jinn 72:1]","And He, Mighty and Majestic, said:","“O company of jinn and mankind, did there not come to you messengers from among you, relating My verses to you and warning you of the meeting of this Day of yours?","They will say: ‘We testify against ourselves.’","The worldly life deceived them, and they will testify against themselves that they were disbelievers.”","[Sūrat al-Anʿām 6:130]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (773)، ومسلم (449: 149)."},{"num":736,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: أَنَّهُ كَانَ يَحْمِلُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِدَاوَةً لِوَضُوئِهِ وَحَاجَتِهِ...وَفِيهِ: فَقُلْتُ: مَا بَالُ الْعَظْمِ وَالرَّوْثَةِ؟ قَالَ: هُمَا مِنْ طَعَامِ الْجِنِّ وَإِنَّهُ أَتَانِي وَفْدُ جِنِّ نَصِيبِينَ وَنِعْمَ الْجِنُّ، فَسَأَلُونِي الزَّادَ، فَدَعَوْتُ اللَّهَ لَهُمْ أَنْ لَا يَمُرُّوا بِعَظْمٍ وَلَا بِرَوْثَةٍ إِلَّا وَجَدُوا عَلَيْهَا طَعَامًا."],"takhrij":"صحيح: رواه البخاري في كتاب مناقب الأنصار (3860) عن موسى بن إسماعيل، حدثنا عمرو بن يحيى بن سعيد قال: أخبرني جدي، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في بعثة النبي ﷺ إلى الجن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3860).","chapter_en":"What Has Been Reported Concerning the Prophet ﷺ Being Sent to the Jinn","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that he used to carry a small vessel of water for the Prophet ﷺ for his ablution and personal needs. In the narration, he said: I asked: “What is the matter with bones and dung?” He replied: “They are from the food of the jinn. A delegation of the jinn of Naṣībīn came to me — and excellent jinn they were — and asked me for provisions. So I supplicated to Allah for them that whenever they passed by a bone or dung, they would find food upon it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3860)."},{"num":737,"demo":false,"sanad":"","matn":["عَنْ عَلْقَمَةُ قَالَ: سَأَلْتُ ابْنَ مَسْعُودٍ فَقُلْتُ: هَلْ شَهِدَ أَحَدٌ مِنْكُمْ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةَ الْجِنِّ؟ قَالَ: لَا ،... وَفِيهِ: أَتَانِي دَاعِي الْجِنِّ، فَذَهَبْتُ مَعَهُ فَقَرَأْتُ عَلَيْهِمُ الْقُرْآنَ، قَالَ: فَانْطَلَقَ بِنَا فَأَرَانَا آثَارَهُمْ وَآثَارَ نِيرَانِهِمْ... الْحَدِيثَ."],"takhrij":"صحيح: رواه مسلم في كتاب الصلاة (450) عن محمد بن المثنى، حدثنا عبدالأعلى، عن داود، عن عامر قال: سألت علقمة: هل كان ابن مسعـــود شهــــــد مع رسول الله صلى الله عليه وسلم ليلة الجن؟ قال: فقال علقمة، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في بعثة النبي ﷺ إلى الجن","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (450).","chapter_en":"What Has Been Reported Concerning the Prophet ﷺ Being Sent to the Jinn","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["ʿAlqamah reported: I asked Ibn Masʿūd may Allah be pleased with him: “Did any of you accompany the Messenger of Allah ﷺ on the night of the jinn?” He replied: “No.” In the narration, the Prophet ﷺ said: “A caller from the jinn came to me, so I went with him and recited the Qurʾān to them.” Ibn Masʿūd said: He then took us and showed us their traces and the traces of their fires. The ḥadīth continues."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (450)."},{"num":738,"demo":false,"sanad":"","matn":["عَنْ مَيْسَرَةَ الْفَجْرِ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، مَتَى كُتِبْتَ نَبِيًّا؟ قَالَ: وآدَمُ بَيْنَ الرُّوحِ وَالْجَسَدِ."],"takhrij":"صحيح: رواه أحمد (20596)، والطبراني في الكبير (20/ح 834)، وابن أبي عاصم في السنة (410)، والآجري في الشريعة (943) كلهم من طريق عبدالرحمن بن مهدي، حدّثنا منصور بن سعد، عن بُديل، عن عبدالله بن شقيق، عن ميسرة الفجر، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب نبوة محمد ﷺ وآدم بين الروح والجسد","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (20596), al-Ṭabarānī in al-Muʿjam al-Kabīr (20/353), and Ibn Abī ʿĀṣim in al-Sunnah (410).","chapter_en":"The Prophethood of Muḥammad ﷺ While Adam Was Between the Soul and the Body","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Maysarah al-Fajr, may Allah be pleased with him, reported: I asked: “O Messenger of Allah, when were you written as a Prophet?” He replied: “While Adam was between the soul and the body.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20596)، والطبراني في الكبير (20/353)، وابن أبي عاصم في السنة (410)."},{"num":739,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالُوا: يَا رَسُولَ اللَّهِ مَتَى وَجَبَتْ لَكَ النُّبُوَّةُ؟ قَالَ: وَآدَمُ بَيْنَ الرُّوحِ وَالْجَسَدِ."],"takhrij":"صحيح: رواه الترمذي (3609) عن أبي همام الوليد بن شجاع بن الوليد البغدادي، حدثنا الوليد بن مسلم، عن الأوزاعي، عن يحي بن أبي كثير، عن أبي سلمة، عن أبي هريرة فذكر الحديث مثله.","grade":"صحيح","chapter_ar":"باب نبوة محمد ﷺ وآدم بين الروح والجسد","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Tirmidhī (3609).","chapter_en":"The Prophethood of Muḥammad ﷺ While Adam Was Between the Soul and the Body","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: They asked: “O Messenger of Allah, when was Prophethood established for you?” He replied: “While Adam was between the soul and the body.”"]},"buhuth":{"en":["Al-Tirmidhī said:","“Ḥasan Ṣaḥīḥ Gharīb.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3609)."},{"num":740,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ وَالنَّاسِ أَجْمَعِينَ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (15)، ومسلم في الإيمان (44) كلاهما من حديث عبدالعزيز بن صهيب، عن أنس، فذكره، واللّفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بالنبي ﷺ ومحبته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (15) and Muslim (44). The wording above is that of al-Bukhārī.","chapter_en":"The Obligation of Believing in the Prophet ﷺ and Loving Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “None of you believes until I am more beloved to him than his father, his child, and all people.”"]},"buhuth":{"en":["In Muslim’s wording:","“Until I am more beloved to him than his family, his wealth, and all people.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (15)، ومسلم (44)، واللفظ للبخاري."},{"num":741,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَن رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَوَالَّذِي نَفْسِي بِيَدِهِ، لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَالِدِهِ وَوَلَدِهِ."],"takhrij":"صحيح: رواه البخاريّ في الإيمان (14) عن أبي اليمان، قال: أخبرنا شعيب، قال: حدّثنا أبو الزّناد، عن الأعرج، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بالنبي ﷺ ومحبته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (14).","chapter_en":"The Obligation of Believing in the Prophet ﷺ and Loving Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “By the One in whose Hand is my soul, none of you will have faith until I am more beloved to him than his father and his child.”"]}},"tuhfa":{},"full":1,"rep":[110],"tks":"صحيح: رواه البخاري (14)."},{"num":742,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ هِشَامٍ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ آخِذٌ بِيَدِ عُمَرَ بْنِ الْخَطَّابِ، فَقَالَ لَهُ عُمَرُ: يَا رَسُولَ اللَّهِ لَأَنْتَ أَحَبُّ إِلَيَّ مِنْ كُلِّ شَيْءٍ إِلَّا مِنْ نَفْسِي، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا وَالَّذِي نَفْسِي بِيَدِهِ، حَتَّى أَكُونَ أَحَبَّ إِلَيْكَ مِنْ نَفْسِكَ، فَقَالَ لَهُ عُمَرُ: فَإِنَّهُ الْآنَ وَاللَّهِ لَأَنْتَ أَحَبُّ إِلَيَّ مِنْ نَفْسِي، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْآنَ يَا عُمَرُ."],"takhrij":"صحيح: رواه البخاريّ في الأيمان والنذور (6632) عن يحيى بن سليمان، قال: حدّثني ابن وهب، قال: أخبرني حيوةُ، قال: حدّثني أبو عقيل زهرة بن معبد، أنه سمع جدَّه عبدالله بن هشام، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بالنبي ﷺ ومحبته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (6632).","chapter_en":"The Obligation of Believing in the Prophet ﷺ and Loving Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn Hishām, may Allah be pleased with him, reported: We were with the Prophet ﷺ while he was holding the hand of ʿUmar ibn al-Khaṭṭāb may Allah be pleased with him. ʿUmar said to him: “O Messenger of Allah, you are more beloved to me than everything except myself.” The Prophet ﷺ replied: “No. By the One in whose Hand is my soul, not until I am more beloved to you than your own self.” ʿUmar then said: “Now, by Allah, you are more beloved to me than my own self.” The Prophet ﷺ said: “Now, O ʿUmar.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9862,12442],"tks":"صحيح: رواه البخاري (6632)."},{"num":743,"demo":false,"sanad":"","matn":["عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ذَاقَ طَعْمَ الإِيمَانِ مَنْ رَضِيَ بِاللَّهِ رَبًّا، وَبِالإِسْلَامِ دِينًا وَبِمُحَمَّدٍ رَسُولًا."],"takhrij":"صحيح: رواه مسلم في الإيمان (34) من طرق عن عبدالعزيز بن محمد الدّراورديّ، عن يزيد بن الهاد، عن محمد بن إبراهيم، عن عامر بن سعد، عن العباس بن عبدالمطلب، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بالنبي ﷺ ومحبته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (34).","chapter_en":"The Obligation of Believing in the Prophet ﷺ and Loving Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Al-ʿAbbās ibn ʿAbd al-Muṭṭalib may Allah be pleased with him reported that he heard the Messenger of Allah ﷺ say: “He has tasted the sweetness of faith who is pleased with Allah as his Lord, Islam as his religion, and Muḥammad as his Messenger.”"]}},"tuhfa":{},"full":1,"rep":[107],"tks":"صحيح: رواه مسلم (34)."},{"num":744,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ أَعْرَابِيًّا قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَتَى السَّاعَةُ؟ قَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَعْدَدْتَ لَهَا؟ قَالَ: حُبَّ اللَّهِ وَرَسُولِهِ، قَالَ: أَنْتَ مَعَ مَنْ أَحْبَبْتَ."],"takhrij":"متفق عليه: رواه مسلم في البرّ والصّلة (2639) عن عبدالله بن مسلمة بن قعنب، حدّثنا مالك، عن إسحاق بن عبدالله بن أبي طلحة، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب من أحب رسول الله ﷺ فهو معه في الجنة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2639).","chapter_en":"Whoever Loves the Messenger of Allah ﷺ Will Be With Him in Paradise","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: A Bedouin asked the Messenger of Allah ﷺ: “When is the Hour?” The Messenger of Allah ﷺ asked him: “What have you prepared for it?” He replied: “Love for Allah and His Messenger.” He said: “You will be with those whom you love.”"]},"buhuth":{"en":["Al-Bukhārī also narrated it in al-Aḥkām (7153), with the wording:","“While the Prophet ﷺ and I were leaving the mosque, we met a man at the entrance of the mosque.","He asked:","‘O Messenger of Allah, when is the Hour?’","The Prophet ﷺ asked:","‘What have you prepared for it?’","The man appeared humbled, then said:","‘O Messenger of Allah, I have not prepared for it a great amount of fasting, prayer, or charity, but I love Allah and His Messenger.’","He said:","‘You will be with those whom you love.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[111,13232,16352],"tks":"متفق عليه: رواه مسلم (2639)."},{"num":745,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مِنْ أَشَدِّ أُمَّتِي لِي حُبًّا نَاسٌ يَكُونُونَ بَعْدِي يَوَدُّ أَحَدُهُمْ لَوْ رَآنِي بِأَهْلِهِ وَمَالِهِ."],"takhrij":"صحيح: رواه مسلم في كتاب الجنّة (2832) عن قتيبة بن سعيد، حدّثنا يعقوب بن عبدالرحمن، عن سهيل، عن أبيه، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب فيمن يود رؤية النبي ﷺ بأهله وماله","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2832).","chapter_en":"Those Who Would Wish to See the Prophet ﷺ Even at the Cost of Their Family and Wealth","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Among those of my Ummah who will have the strongest love for me are people who will come after me. One of them would wish that he could see me even at the cost of his family and wealth.”"]},"buhuth":{"en":["The words:","“Among those of my Ummah who will have the strongest love for me”","mean: after the Companions may Allah be pleased with them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2832)."},{"num":746,"demo":false,"sanad":"","matn":["عَنْ أَبِي عَبْدِ الرَّحْمَنِ الْجُهَنِيِّ قَالَ: بَيْنَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَلَعَ رَاكِبَانِ، فَلَمَّا رَآهُمَا قَالَ: كِنْدِيَّانِ مَذْحِجِيَّانِ حَتَّى أَتَيَاهُ، فَإِذَا رِجَالٌ مِنْ مَذْحِجٍ، قَالَ: فَدَنَا إِلَيْهِ أَحَدُهُمَا لِيُبَايِعَهُ، قَالَ: فَلَمَّا أَخَذَ بِيَدِهِ، قَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ مَنْ رَآكَ فَآمَنَ بِكَ وَصَدَّقَكَ وَاتَّبَعَكَ، مَاذَا لَهُ؟ قَالَ: طُوبَى لَهُ، قَالَ: فَمَسَحَ عَلَى يَدِهِ فَانْصَرَفَ، ثُمَّ أَقْبَلَ الْآخَرُ حَتَّى أَخَذَ بِيَدِهِ لِيُبَايِعَهُ، قَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ مَنْ آمَنْ بِكَ وَصَدَّقَكَ وَاتَّبَعَكَ وَلَمْ يَرَكَ؟ قَالَ: طُوبَى لَهُ، ثُمَّ طُوبَى لَهُ، ثُمَّ طُوبَى لَهُ، قَالَ: فَمَسَحَ عَلَى يَدِهِ، فَانْصَرَفَ."],"takhrij":"حسن: رواه أحمد (17388)، والطبرانيّ في الكبير (22/ح 724)، والبزّار- كشف الأستار (2769)، كلّهم من طريق محمد بن إسحاق، حدّثني يزيد بن أبي حبيب، عن مرثد بن عبدالله اليزنيّ، عن أبي عبدالرحمن الجهنيّ، فذكر مثله، واللّفظ لأحمد.","grade":"حسن","chapter_ar":"باب فضل من آمن بالنبي ﷺ ولم يره","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (17388), al-Ṭabarānī in al-Muʿjam al-Kabīr (22/289), and al-Bazzār in Kashf al-Astār (2769).","chapter_en":"The Virtue of One Who Believes in the Prophet ﷺ Without Seeing Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abū ʿAbd al-Raḥmān al-Juhanī, may Allah be pleased with him, reported: While we were with the Messenger of Allah ﷺ, two riders appeared. When he saw them, he said: “Two men from Kindah, from Madhḥij.” When they reached him, they turned out to be two men from Madhḥij. One of them came forward to pledge allegiance to him. The Prophet ﷺ took his hand, and the man asked: “O Messenger of Allah, what about one who saw you, believed in you, affirmed you, and followed you? What will he receive?” He replied: “Ṭūbā for him.” He then passed his hand over the man’s hand, and the man departed. The other man then came forward and took his hand to pledge allegiance. He asked: “O Messenger of Allah, what about one who believes in you, affirms you, and follows you but never sees you?” He replied: “Ṭūbā for him, then Ṭūbā for him, then Ṭūbā for him.” He then passed his hand over his hand, and the man departed."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17388)، والطبراني في الكبير (22/289)، والبزار في كشف الأستار (2769)."},{"num":747,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُمُعَةَ حَبِيبِ بْنِ سِبَاعٍ قَالَ: تَغَدَّيْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَمَعَنَا أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ قَالَ: فَقَالَ: يَا رَسُولَ اللَّهِ هَلْ أَحَدٌ خَيْرٌ مِنَّا؟ أَسْلَمْنَا مَعَكَ وَجَاهَدْنَا مَعَكَ، قَالَ: نَعَمْ، قَوْمٌ يَكُونُونَ مِنْ بَعْدِكُمْ يُؤْمِنُونَ بِي وَلَمْ يَرَوْنِي."],"takhrij":"حسن: رواه الإمام أحمد (16976) والطبراني في الكبير (3537) وأبو يعلى (1559) وصحّحه الحاكم (6992) كلهم من حديث الأوزاعي قال: حدثني أسيد بن عبدالرحمن، قال: حدثني صالح بن جبير، قال: حدثني أبو جمعة، فذكره.","grade":"حسن","chapter_ar":"باب فضل من آمن بالنبي ﷺ ولم يره","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (16976), al-Ṭabarānī in al-Muʿjam al-Kabīr (3537), and Abū Yaʿlā (1559), and authenticated by al-Ḥākim (6992).","chapter_en":"The Virtue of One Who Believes in the Prophet ﷺ Without Seeing Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Abū Jumʿah Ḥabīb ibn Sibāʿ, may Allah be pleased with him, reported: We ate a midday meal with the Messenger of Allah ﷺ, and Abū ʿUbaydah ibn al-Jarrāḥ may Allah be pleased with him was with us. He asked: “O Messenger of Allah, is there anyone better than us? We embraced Islam with you and strove alongside you.” He replied: “Yes. People who will come after you, who will believe in me although they never saw me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (16976)، والطبراني في الكبير (3537)، وأبو يعلى (1559)، وصححه الحاكم (6992)."},{"num":748,"demo":false,"sanad":"","matn":["عَنْ فَضَالَةَ بْنِ عُبَيْدٍ، أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اللَّهُمَّ مَنْ آمَنَ بِكَ وَشَهِدَ أَنِّي رَسُولُكَ، فَحَبِّبْ إِلَيْهِ لِقَاءَكَ، وَسَهِّلْ عَلَيْهِ قَضَاءَكَ، وَأَقْلِلْ لَهُ مِنَ الدُّنْيَا، وَمَنْ لَمْ يُؤْمِنْ بِكَ وَيَشْهَدْ أَنِّي رَسُولُكَ، فَلَا تُحَبِّبْ إِلَيْهِ لِقَاءَكَ، وَلَا تُسَهِّلْ عَلَيْهِ قَضَاءَكَ، وَأَكْثِرْ لَهُ مِنَ الدُّنْيَا."],"takhrij":"صحيح: رواه الطبرانيّ في الكبير (18/ح 808) من طريق ابن وهب، عن سعيد بن أبي أيوب، عن أبي هانئ، عن عمرو بن مالك، عن فضالة بن عبيد، فذكره.","grade":"صحيح","chapter_ar":"باب دعاء النبي ﷺ لمن شهد له بالرسالة","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (18/313) and authenticated by Ibn Ḥibbān (208).","chapter_en":"The Prophet’s ﷺ Supplication for Those Who Testify to His Messengership","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “O Allah, whoever believes in You and testifies that I am Your Messenger, make meeting You beloved to him, make Your decree easy for him, and give him little of this world. And whoever does not believe in You and does not testify that I am Your Messenger, do not make meeting You beloved to him, do not make Your decree easy for him, and give him much of this world.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الكبير (18/ح 808)، وصححه ابن حبان (208)."},{"num":749,"demo":false,"sanad":"","matn":["عَنْ جُبَيْرِ بْنِ مُطْعِمٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِي خَمْسَةُ أَسْمَاءٍ أَنَا مُحمّدُ، وَأَحْمَدُ، وَأَنَا الْمَاحِي الّذِي يَمْحُو اللَّهُ بِي الْكُفْرَ، وَأَنَا الْحَاشِرُ الّذِي يُحْشَرُ النّاسُ عَلَى قَدَمَيَّ، وَأَنَا الْعَاقِبُ."],"takhrij":"متفق عليه: رواه مالك في أسماء النّبيّ صلى الله عليه وسلم (1) عن ابن شهاب، عن محمد بن جبير بن مطعم، أنّ النبيّ صلى الله عليه وسلم قال (فذكر الحديث).","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (1), al-Bukhārī (3532, 4896), and Muslim (2354).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Jubayr ibn Muṭʿim may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I have five names: I am Muḥammad, I am Aḥmad, I am al-Māḥī through whom Allah erases disbelief, I am al-Ḥāshir at whose feet the people will be gathered, and I am al-ʿĀqib.”"]},"buhuth":{"en":["Muslim adds:","“Al-ʿĀqib is the one after whom there is no prophet.”"]},"intro":{"ar":["قال الله تعالى:","﴿مَا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِنْ رِجَالِكُمْ وَلَكِنْ رَسُولَ اللهِ وَخَاتَمَ النَّبِيِّينَ وَكَانَ اللهُ بِكُلِّ شَيْءٍ عَلِيمًا﴾","[الأحزاب: ٤٠]"],"en":["Allah Most High said:","“Muḥammad is not the father of any of your men, but he is the Messenger of Allah and the Seal of the Prophets. And Allah is All-Knowing of everything.”","[Sūrat al-Aḥzāb 33:40]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8514],"tks":"متفق عليه: رواه مالك (1)، والبخاري (3532، 4896)، ومسلم (2354)."},{"num":750,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:كَانَتْ بَنُو إِسْرَائِيلَ تَسُوسُهُمُ الْأَنْبِيَاءُ كُلَّمَا هَلَكَ نَبِيٌّ خَلَفَهُ نَبِيٌّ، وَإِنَّهُ لَا نَبِيَّ بَعْدِي وَسَيَكُونُ خُلَفَاءُ فَيَكْثُرُونَ، قَالُوا: فَمَا تَأْمُرُنَا، قَالَ: فُوا بِبَيْعَةِ الْأَوَّلِ فَالْأَوَّلِ أَعْطُوهُمْ حَقَّهُمْ فَإِنَّ اللَّهَ سَائِلُهُمْ عَمَّا اسْتَرْعَاهُمْ."],"takhrij":"متفق عليه: رواه البخاريّ في أحاديث الأنبياء (3455)، ومسلم في الإمارة (1842) كلاهما عن محمد بن بشّار، حدّثنا محمد بن جعفر، حدّثنا شعبة، عن فُرات القزاز، سمعت أبا حازم، قال: قاعدتُ أبا هريرة خمس سنين، فسمعتُه يحدّث عن النبيّ صلى الله عليه وسلم فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3455) and Muslim (1842).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Prophet ﷺ said: “The Children of Israel were governed by the prophets. Whenever one prophet died, another prophet succeeded him. There will be no prophet after me, but there will be caliphs, and they will become numerous.” They asked: “What do you command us to do?” He replied: “Fulfill the pledge of allegiance to the first and then the next, and give them their rights, for Allah will question them concerning those whom He placed under their care.”"]}},"tuhfa":{},"full":1,"rep":[7657],"tks":"متفق عليه: رواه البخاري (3455)، ومسلم (1842)."},{"num":751,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: فَذَكَرَ الْحَدِيثَ الشَّفَاعَةُ بِطُولِهِ وَجَاءَ فِيهِ: فَيَقُولُونَ: يَا مُحَمَّدُ، أَنْتَ رَسُولُ اللَّهِ، وَخَاتَمُ الأَنْبِيَاءِ، وَغَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ، اشْفَعْ لَنَا إِلَى رَبِّكَ.... (الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4712)، ومسلم في الإيمان (194) كلاهما من حديث أبي حيان التيميّ، عن أبي زرعة، عن أبي هريرة، فذكره بطوله.","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4712) and Muslim (194).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported the lengthy ḥadīth of intercession, in which it states: “They will say: ‘O Muḥammad, you are the Messenger of Allah and the Seal of the Prophets. Allah has forgiven you what preceded of your sin and what came after it. Intercede for us with your Lord…’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4712)، ومسلم (194)."},{"num":752,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فُضِّلْتُ عَلَى الأَنْبِيَاءِ بِسِتٍّ، (فَذَكَرَ الْخِصَالِ السِّتِّ وَمِنْهَا)، وَخُتِمَ بِيَ النَّبِيُّونَ."],"takhrij":"صحيح: رواه مسلم في المساجد (523) من طرق عن إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (523).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I have been favored over the prophets in six ways.” He then mentioned the six qualities, among which was: “And the prophets were sealed with me.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (523)."},{"num":753,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَإِنِّي آخِرُ الْأَنْبِيَاءِ، وَإِنَّ مَسْجِدِي آخِرُ الْمَسَاجِدِ."],"takhrij":"صحيح: رواه مسلم في الحجّ (1394) عن إسحاق بن منصور، حدّثنا عيسى بن المنذر الحمصيّ، حدّثنا محمد بن حرب، حدّثنا الزُّبيديُّ، عن الزّهريّ، عن أبي سلمة بن عبدالرحمن، وأبي عبدالله الأغرّ مولى الجهنيين، وكان من أصحاب أبي هريرة، أنّهما سمعاَ أبا هريرة يقول: صلاةٌ في مسجد رسولِ الله صلى الله عليه وسلم أفضلُ من ألف صلاةٍ فيما سواه من المساجد، إلاّ المسجد الحرام. فإنّ رسول الله صلى الله عليه وسلم آخرُ الأنبياء. وإنَّ مسجدَه آخرُ المساجد.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (1394).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Indeed, I am the last of the prophets, and my mosque is the last of the mosques.”"]},"buhuth":{"en":["The statement:","“My mosque is the last of the mosques”","means the last mosque founded and built by a prophet, since no prophet will come after him to establish another prophetic mosque."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1394)."},{"num":754,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَقُومُ السَّاعَةُ حَتَّى تَلْحَقَ قَبَائِلُ مِنْ أُمَّتِي بِالْمُشْرِكِينَ، وَحَتَّى يَعْبُدُوا الْأَوْثَانَ، وَإِنَّهُ سَيَكُونُ فِي أُمَّتِي ثَلَاثُونَ كَذَّابُونَ كُلُّهُمْ يَزْعُمُ أَنَّهُ نَبِيٌّ، وَأَنَا خَاتَمُ النَّبِيِّينَ لَا نَبِيَّ بَعْدِي."],"takhrij":"صحيح: رواه أبو داود (4252)، والترمذيّ (2219)، والإمام أحمد (22394)، كلّهم من طرق عن حمّاد بن زيد، عن أيوب، عن أبي قلابة، عن أبي أسماء عمرو بن مرثد الرحبيّ، عن ثوبان، فذكر الحديث، واللّفظ للترمذيّ ولفظهما مطوّل، وسيأتي في كتاب الفتن.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4252), al-Tirmidhī (2219), and Aḥmad (22394), and authenticated by Ibn Ḥibbān (6714).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Thawbān may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “The Hour will not be established until tribes from my Ummah join the polytheists and until they worship idols. There will be thirty liars among my Ummah, each claiming that he is a prophet, while I am the Seal of the Prophets. There is no prophet after me.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15936,15940],"tks":"صحيح: رواه أبو داود (4252)، والترمذي (2219)، وأحمد (22394)، وصححه ابن حبان (6714)."},{"num":755,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ مَثَلِي وَمَثَلَ الْأَنْبِيَاءِ مِنْ قَبْلِي كَمَثَلِ رَجُلٍ بَنَى بَيْتًا فَأَحْسَنَهُ وَأَجْمَلَهُ إِلَّا مَوْضِعَ لَبِنَةٍ مِنْ زَاوِيَةٍ، فَجَعَلَ النَّاسُ يَطُوفُونَ بِهِ وَيَعْجَبُونَ لَهُ وَيَقُولُونَ هَلَّا وُضِعَتْ هَذِهِ اللَّبِنَةُ، قَالَ: فَأَنَا اللَّبِنَةُ وَأَنَا خَاتِمُ النَّبِيِّينَ."],"takhrij":"متفق عليه: رواه البخاريّ في المناقب (3535)، ومسلم في الفضائل (2286: 22) كلاهما عن قتيبة بن سعيد، حدّثنا إسماعيل بن جعفر، عن عبدالله بن دينار، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3535) and Muslim (2286:22).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “My example and the example of the prophets before me is like that of a man who built a house and made it excellent and beautiful, except for the place of one brick in one of its corners. The people began walking around it, admiring it and saying: ‘If only this brick were put in place!’ He said: ‘I am that brick, and I am the Seal of the Prophets.’”"]},"buhuth":{"en":["Aḥmad (7322) also narrated it with the wording:","“Except for this gap, and I am that gap.”","The word:","“al-thulmah”","means an opening or breach in something broken or demolished; that is, the one remaining place in the structure that had not yet been completed."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13076,14674],"tks":"متفق عليه: رواه البخاري (3535)، ومسلم (2286: 22)."},{"num":756,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ كَرَجُلٍ بَنَى دَارًا فَأَكْمَلَهَا وَأَحْسَنَهَا إِلَّا مَوْضِعَ لَبِنَةٍ فَجَعَلَ النَّاسُ يَدْخُلُونَهَا وَيَتَعَجَّبُونَ وَيَقُولُونَ: لَوْلَا مَوْضِعُ اللَّبِنَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في المناقب (3534)، ومسلم في الفضائل كلاهما من حديث سليم بن حيّان، حدّثنا سعيد بن ميناء، عن جابر بن عبدالله، فذكره.","grade":"متفق عليه","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3534) and Muslim (2287).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that the Prophet ﷺ said: “My example and the example of the prophets is like a man who built a house, completed it, and made it beautiful, except for the place of one brick. The people began entering it, marveling at it and saying: ‘If only the place of this brick were completed.’”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3534)، ومسلم (2287)."},{"num":757,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَثَلِي وَمَثَلُ الْأَنْبِيَاءِ مِنْ قَبْلِي، كَمَثَلِ رَجُلٍ بَنَى بُنْيَانًا فَأَحْسَنَهُ وَأَجْمَلَهُ، إِلَّا مَوْضِعَ لَبِنَةٍ مِنْ زَاوِيَةٍ مِنْ زَوَايَاهُ، فَجَعَلَ النَّاسُ يَطُوفُونَ بِهِ، وَيَعْجَبُونَ لَهُ وَيَقُولُونَ: هَلَّا وُضِعَتْ هَذِهِ اللَّبِنَةُ؟ قَالَ: فَأَنَا اللَّبِنَةُ وَأَنَا خَاتَمُ النَّبِيِّينَ."],"takhrij":"صحيح: رواه مسلمٌ في الفضائل (2286) من طرق عن أبي معاوية، عن الأعمش، عن أبي صالح، عن أبي سعيد، فذكره.","grade":"صحيح","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2286).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abū Saʿīd may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “My example and the example of the prophets before me is like that of a man who built a structure and made it excellent and beautiful, except for the place of one brick in one of its corners. The people began walking around it, admiring it and saying: ‘If only this brick were put in place!’ He said: ‘I am that brick, and I am the Seal of the Prophets.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2286)."},{"num":758,"demo":false,"sanad":"","matn":["عَنْ أُبَيِّ بْنِ كَعْبٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَثَلِي فِي النَّبِيِّينَ كَمَثَلِ رَجُلٍ بَنَى دَارًا فَأَحْسَنَهَا وَأَكْمَلَهَا وَأَجْمَلَهَا وَتَرَكَ مِنْهَا مَوْضِعَ لَبِنَةٍ، فَجَعَلَ النَّاسُ يَطُوفُونَ بِالْبِنَاءِ وَيَعْجَبُونَ مِنْهُ وَيَقُولُونَ: لَوْ تَمَّ مَوْضِعُ تِلْكَ اللَّبِنَةِ، وَأَنَا فِي النَّبِيِّينَ مَوْضِعُ تِلْكَ اللَّبِنَةِ."],"takhrij":"حسن: رواه الترمذيّ (3613) عن محمد بن بشّار، حدّثنا أبو عامر، حدّثنا زهير بن محمد، عن عبدالله بن محمد بن عقيل، عن الطّفيل بن أبي بن كعب، عن أبيه، فذكره.","grade":"حسن","chapter_ar":"باب وجوب الإيمان بأن النبي ﷺ خاتم النبيين ولا نبي بعده","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī (3613) and Aḥmad (21243).","chapter_en":"The Obligation of Believing That the Prophet ﷺ Is the Seal of the Prophets and That There Is No Prophet After Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Ubayy ibn Kaʿb may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “My example among the prophets is like that of a man who built a house, made it excellent, completed it, and beautified it, but left the place of one brick unfinished. The people began walking around the building, marveling at it and saying: ‘If only the place of that brick were completed.’ Among the prophets, I occupy the place of that brick.”"]},"buhuth":{"en":["Al-Tirmidhī said:","“A Ḥasan ḥadīth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3613)، وأحمد (21243)."},{"num":759,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ قَالَ: خَلَّفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلِيَّ بْنَ أَبِي طَالِبٍ فِي غَزْوَةِ تَبُوكَ، فَقَالَ: يَا رَسُولَ اللَّهِ، تُخَلِّفُنِي فِي النِّسَاءِ، وَالصِّبْيَانِ؟ فَقَالَ: أَمَا تَرْضَى أَنْ تَكُونَ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى، غَيْرَ أَنَّهُ لَا نَبِيَّ بَعْدِي."],"takhrij":"متفق عليه: رواه البخاريّ في فضائل أصحاب النّبيّ صلى الله عليه وسلم (3706)، ومسلم في فضائل علي بن أبي طالب (2404) كلاهما عن محمد بن بشار، قال: ثنا محمد بن جعفر غندر، حدّثنا شعبة، عن الحكم، عن مصعب بن سعد بن أبي وقّاص، عن سعد بن أبي وقّاص، فذكره، واللّفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ لعلي: «أنت مني بمنزلة هارون من موسى غير أنه لا نبي بعدي»","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3706, 4416) and Muslim (2404), with the wording of Muslim.","chapter_en":"The Prophet’s ﷺ Statement to ʿAlī: “You Are to Me as Aaron Was to Moses, Except That There Is No Prophet After Me”","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":10,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ, may Allah be pleased with him, reported: The Messenger of Allah ﷺ left ʿAlī ibn Abī Ṭālib may Allah be pleased with him behind during the expedition of Tabūk. ʿAlī said: “O Messenger of Allah, are you leaving me behind with the women and children?” He replied: “Are you not pleased to be to me as Aaron was to Moses, except that there is no prophet after me?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3706، 4416)، ومسلم (2404)، واللفظ لمسلم."},{"num":760,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ عُمَيْسٍ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِعَلِيٍّ: أَنْتَ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى، إِلَّا أَنَّهُ لَيْسَ بَعْدِي نَبِيّ."],"takhrij":"حسن: رواه الإمام أحمد (27081)، والنسائيّ في الكبرى (8143)، والطبرانيّ في الكبير (24/ح 388)، وابن أبي عاصم في السنة (1381، بتحقيق باسم) كلّهم من طريق موسى الجهنيّ، قال: دخلتُ على فاطمة بنت عليّ، فقال لها رفيقي أبو مَهَل: كم لكِ؟ قالت: ستة وثمانون سنة. قال: ما سمعتِ من أبيك شيئاً؟ قالت: حدَّثتني أسماءُ بنتُ عميس، فذكرت الحديث.","grade":"حسن","chapter_ar":"باب قول النبي ﷺ لعلي: «أنت مني بمنزلة هارون من موسى غير أنه لا نبي بعدي»","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (27081), al-Nasāʾī in al-Sunan al-Kubrā (8143), and al-Ṭabarānī in al-Muʿjam al-Kabīr (vol. 24, no. 386).","chapter_en":"The Prophet’s ﷺ Statement to ʿAlī: “You Are to Me as Aaron Was to Moses, Except That There Is No Prophet After Me”","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":10,"content":{"translation":{"en":["Asmāʾ bint ʿUmays may Allah be pleased with her reported that the Messenger of Allah ﷺ said to ʿAlī may Allah be pleased with him: “You are to me as Aaron was to Moses, except that there is no prophet after me.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9915],"tks":"حسن: رواه أحمد (27081)، والنسائي في الكبرى (8143)، والطبراني في الكبير (24، رقم 386)."},{"num":761,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِعَلِيٍّ: أَنْتَ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى إِلَّا أَنَّهُ لَا نَبِيَّ بَعْدِي."],"takhrij":"حسن: رواه الترمذيّ (3730) عن محمود بن غيلان، حدّثنا أبو أحمد الزّبيريّ، حدّثنا شريك، عن عبدالله بن محمد بن عقيل، عن جابر بن عبدالله، فذكر الحديث.","grade":"حسن","chapter_ar":"باب قول النبي ﷺ لعلي: «أنت مني بمنزلة هارون من موسى غير أنه لا نبي بعدي»","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan due to supporting reports: Narrated by al-Tirmidhī (3730) and Imām Aḥmad (14638).","chapter_en":"The Prophet’s ﷺ Statement to ʿAlī: “You Are to Me as Aaron Was to Moses, Except That There Is No Prophet After Me”","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":10,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that the Prophet ﷺ said to ʿAlī may Allah be pleased with him: “You are to me as Aaron was to Moses, except that there is no prophet after me.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9914],"tks":"حسن: رواه الترمذي (3730)، والإمام أحمد (14638)."},{"num":762,"demo":false,"sanad":"","matn":["عَنِ السَّائِبِ بْنِ يَزِيدَ يَقُولُ: ذَهَبَتْ بِي خَالَتِي إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ ابْنَ أُخْتِي وَجِعٌ فَمَسَحَ رَأْسِي وَدَعَا لِي بِالْبَرَكَةِ، ثُمَّ تَوَضَّأَ فَشَرِبْتُ مِنْ وَضُوئِهِ، ثُمَّ قُمْتُ خَلْفَ ظَهْرِهِ، فَنَظَرْتُ إِلَى خَاتَمِهِ بَيْنَ كَتِفَيْهِ، مِثْلَ زِرِّ الْحَجَلَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في الوضوء (190، 3541)، ومسلم في الفضائل (2345) كلاهما من طريق حاتم بن إسماعيل، عن الجعد بن عبدالرحمن، قال: سمعتُ السائب بن يزيد، فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خاتم النبوة وصفته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3541, 190) and Muslim (2345).","chapter_en":"What Has Been Reported Concerning the Seal of Prophethood and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Al-Sāʾib ibn Yazīd, may Allah be pleased with him, said: My maternal aunt took me to the Messenger of Allah ﷺ and said: “O Messenger of Allah, my sister’s son is ill.” He wiped my head and supplicated for blessing for me. Then he performed ablution, and I drank from the water remaining from his ablution. I then stood behind him and looked at the Seal between his shoulders. It was like the button of a ḥajalah."]},"buhuth":{"en":["Al-Qurṭubī said regarding the expression:","“the button of a ḥajalah”:","“The well-known narration reads zirr, with the letter zāy first.”","Abū al-Faraj Ibn al-Jawzī said:","“A ḥajalah is a structure resembling a small dome, covered with cloth, with a door made from the same material. It has a button and loop by which it is fastened when closed.”","Al-Qāḍī Abū al-Faḍl said:","“The zirr is that by which women fasten the loops of their curtained enclosures, like the buttons of a shirt. Here, ḥajalah is the singular of ḥijāl, meaning curtains with hanging drapes.”","Others said:","“The ḥajalah is the well-known bird, and its zirr is its egg,”","as Jābir described it:","“the egg of a pigeon.”","Al-Qurṭubī said:","“The first interpretation is more famous regarding the word zirr, while the second is closer to the intended meaning.”","Al-Mufhim (6/136)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[10204],"tks":"متفق عليه: رواه البخاري (3541، 190)، ومسلم (2345)."},{"num":763,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: رَأَيْتُ خَاتَمًا فِي ظَهْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَأَنَّهُ بَيْضَةُ حَمَامٍ. وَفِي رِوَايَةِ: عِنْدَ كَتِفِهِ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2344) عن محمد بن المثنى، حدّثنا محمد ابن جعفر، حدثنا شعبة، عن سماك، قال: سمعت جابر بن سمرة، فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في خاتم النبوة وصفته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2344).","chapter_en":"What Has Been Reported Concerning the Seal of Prophethood and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Jābir ibn Samurah, may Allah be pleased with him, reported: “I saw the Seal on the back of the Messenger of Allah ﷺ, and it was like the egg of a pigeon.” In another narration: “By his shoulder.”"]},"buhuth":{"en":["Al-Tirmidhī (3644) also narrated it with the wording:","“The Seal of the Messenger of Allah ﷺ — meaning the one between his shoulders — was a red protrusion like the egg of a pigeon.”","Al-Tirmidhī said:","“This is a Ḥasan Ṣaḥīḥ ḥadīth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2344)."},{"num":764,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ سَرْجِسَ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَكَلْتُ مَعَهُ خُبْزًا وَلَحْمًا أَوَ قَالَ: ثَرِيدًا، قَالَ، فَقُلْتُ لَهُ: أَسْتَغْفَرَ لَكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ، وَلَكَ ثُمَّ تَلَا هَذِهِ الْآيَةَ: ﴿وَاسْتَغْفِرْ لِذَنْبِكَ وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ﴾ [محمد: 19]. قَالَ: ثُمَّ دُرْتُ خَلْفَهُ، فَنَظَرْتُ إِلَى خَاتَمِ النُّبُوَّةِ بَيْنَ كَتِفَيْهِ عِنْدَ نَاغِضِ كَتِفِهِ الْيُسْرَى جُمْعًا عَلَيْهِ خِيلَانٌ كَأَمْثَالِ الثَّآلِيلِ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2346) من طرق عن عاصم الأحول، عن عبدالله بن سَرْجس، فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء في خاتم النبوة وصفته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2346).","chapter_en":"What Has Been Reported Concerning the Seal of Prophethood and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn Sarjis, may Allah be pleased with him, said: I saw the Prophet ﷺ and ate bread and meat with him — or he said: tharīd. He was asked: “Did the Prophet ﷺ seek forgiveness for you?” He replied: “Yes, and for you as well.” Then he recited the verse: “Seek forgiveness for your sin, and for the believing men and believing women.” [Sūrat Muḥammad 47:19] He continued: Then I went around behind him and looked at the Seal of Prophethood between his shoulders, near the upper part of his left shoulder. It was like a gathered hand, with moles upon it resembling small warts."]},"buhuth":{"en":["The expression:","“the nāghiḍ of his shoulder”","means the upper part of the shoulder.","The word:","“jumʿan”","means that it resembled a gathered palm, the form made when the fingers are brought together.","The word:","“khīlān”","is the plural of khāl, meaning moles or dark marks on the body.","The word:","“thāʾālīl”","is the plural of thuʾlūl, meaning small wart-like projections on the skin.","Al-Qurṭubī said in al-Mufhim (6/136), after mentioning some of these narrations:","“All of these expressions are close in meaning and indicate that the Seal of Prophethood was a raised red protrusion beneath his left shoulder. When described as smaller, it was like a pigeon’s egg, and when described more broadly, it was like a gathered hand. It has also been reported: ‘a raised piece of flesh,’ meaning elevated.”","As for his statement:","“It has been reported in al-Bukhārī: ‘It was a raised piece of flesh,’”","the author notes that this appears to be an attributional mistake, may Allah have mercy upon al-Qurṭubī. This precise wording was not found in Ṣaḥīḥ al-Bukhārī; rather, it appears in al-Tirmidhī’s al-Shamāʾil, as will come in the narration of Abū Naḍrah al-ʿAwqī from Abū Saʿīd al-Khudrī."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2346)."},{"num":765,"demo":false,"sanad":"","matn":["عَنْ قُرَّةَ بْنِ إِيَاسٍ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَهْطٍ مِنْ مُزَيْنَةَ، فَبَايَعْنَاهُ وَإِنَّ قَمِيصَهُ لَمُطْلَقُ الْأَزْرَارِ، قَالَ: فَبَايَعْتُهُ ثُمَّ أَدْخَلْتُ يَدَيَّ فِي جَيْبِ قَمِيصِهِ، فَمَسِسْتُ الْخَاتَمَ.","قَالَ عُرْوَةُ: فَمَا رَأَيْتُ مُعَاوِيَةَ وَلَا ابْنَهُ قَطُّ إِلَّا مُطْلِقَيْ أَزْرَارِهِمَا فِي شِتَاءٍ وَلَا حَرٍّ وَلَا يُزَرِّرَانِ أَزْرَارَهُمَا أَبَدًا."],"takhrij":"صحيح: رواه أبو داد (4082)، وابن ماجه (3578)، والترمذيّ في الشمائل (57) كلّهم من طريق زهير، حدّثنا عروة بن عبدالله بن قشير أبو مهل الجعفيّ، قال: حدّثني معاوية بن قرّة، عن أبيه (يعني قرّة بن إيّاس) قال: (فذكر مثله).","grade":"صحيح","chapter_ar":"باب ما جاء في خاتم النبوة وصفته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4082), Ibn Mājah (3578), and Aḥmad (15581), and authenticated by Ibn Ḥibbān (5452).","chapter_en":"What Has Been Reported Concerning the Seal of Prophethood and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Qurrah ibn Iyās, may Allah be pleased with him, said: I came to the Messenger of Allah ﷺ with a group from Muzaynah, and we pledged allegiance to him. His shirt was open at the buttons. He said: I pledged allegiance to him, then placed my hand through the opening of his shirt and touched the Seal. ʿUrwah said:","“I never saw Muʿāwiyah ibn Qurrah ibn Iyās, nor his son, except with the buttons of their shirts left open, whether in winter or summer. They would never fasten their buttons.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4082)، وابن ماجه (3578)، وأحمد (15581)، وصححه ابن حبان (5452)."},{"num":766,"demo":false,"sanad":"","matn":["عَنْ أَبِي زَيْدِ عَمْرِو بْنِ أَخْطَبِ الْأَنْصَارِيِّ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَبَا زَيْدٍ، ادْنُ مِنِّي وَامْسَحْ ظَهْرِي وَكَشَفَ ظَهْرَهُ، فَمَسَحْتُ ظَهْرَهُ، وَجَعَلْتُ الْخَاتَمَ بَيْنَ أَصَابِعِي، قَالَ: فَغَمَزْتُهَا، قَالَ: فَقِيلَ: وَمَا الْخَاتَمُ؟ قَالَ: شَعَرٌ مُجْتَمِعٌ عَلَى كَتِفِهِ."],"takhrij":"صحيح: رواه الإمام أحمد (22889)، وأبو يعلى (6846)، وعنه ابن حبان في صحيحه (6300)، والترمذيّ في الشمائل (19) كلّهم من طريق أبي عاصم النّبيل، حدّثنا عزرة بن ثابت، حدّثنا علباء بن أحمر اليشكريّ، حدّثنا أبو زيد، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في خاتم النبوة وصفته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Aḥmad (22889), Abū Yaʿlā (6846), and Ibn Ḥibbān (6300).","chapter_en":"What Has Been Reported Concerning the Seal of Prophethood and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Abū Zayd ʿAmr ibn Akhṭab al-Anṣārī, may Allah be pleased with him, said: The Messenger of Allah ﷺ said to me: “O Abū Zayd, come close to me and rub my back.” He uncovered his back, so I rubbed it and placed the Seal between my fingers. He said: I pressed it gently. He was asked: “What was the Seal?” He replied: “Hair gathered together upon his shoulder.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (22889)، وأبو يعلى (6846)، وابن حبان (6300)."},{"num":767,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ قَالَ: جَاءَ سَلْمَانُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَدِمَ الْمَدِينَةَ،... فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَصْحَابِهِ: ابْسُطُوا، فَنَظَرَ إِلَى الْخَاتَمِ الَّذِي عَلَى ظَهْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَآمَنَ بهِ... (فَذَكَرَ الْحَدِيثَ)."],"takhrij":"حسن: رواه الإمام أحمد (22997)، والبزّار- كشف الأستار (2726)، والطبرانيّ في الكبير (6070) كلّهم من طريق زيد بن الحباب، حدثني حسين بن واقد، حدثني عبدالله بن بريدة، قال: سمعت بريدة، فذكر قصة إسلام سلمان مطوّلاً، وستأتي في موضعها.","grade":"حسن","chapter_ar":"باب ما جاء في خاتم النبوة وصفته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (22997), al-Bazzār in Kashf al-Astār (2726), and al-Ṭabarānī in al-Muʿjam al-Kabīr (6070).","chapter_en":"What Has Been Reported Concerning the Seal of Prophethood and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Buraydah, may Allah be pleased with him, reported: Salmān came to the Messenger of Allah ﷺ when he arrived in Madinah. The Prophet ﷺ said to his Companions: “Eat.” Salmān then looked at the Seal upon the back of the Messenger of Allah ﷺ and believed in him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (22997)، والبزار في كشف الأستار (2726)، والطبراني في الكبير (6070)."},{"num":768,"demo":false,"sanad":"","matn":["عَنْ أَبِي نَضْرَةَ الْعَوَقِىّ قَالَ: سَأَلْتُ أَبَا سَعِيدٍ الْخُدْرِيَّ عَنْ خَاتَمِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: كَانَ فِي ظَهْرِهِ بِضْعَةٌ نَاشِزَةٌ."],"takhrij":"حسن: رواه الترمذيّ في الشّمائل (21) عن محمد بن بشّار، حدّثنا بشر بن الوضّاح، حدّثنا أبو عقيل الدّورقيّ، عن أبي نَضْرة العوقي، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في خاتم النبوة وصفته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Tirmidhī in al-Shamāʾil (21).","chapter_en":"What Has Been Reported Concerning the Seal of Prophethood and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Abū Naḍrah al-ʿAwqī reported: I asked Abū Saʿīd al-Khudrī may Allah be pleased with him about the Seal of the Messenger of Allah ﷺ. He replied: “There was a raised piece of flesh upon his back.”"]},"buhuth":{"en":["“Raised flesh” means flesh elevated above the surface of the body."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي في الشمائل (21)."},{"num":769,"demo":false,"sanad":"","matn":["عَنْ رُمَيْثَةَ قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: وَلَوْ أَشَاءُ أَنْ أُقَبِّلَ الْخَاتَمَ الَّذِي بَيْنَ كَتِفَيْهِ مِنْ قُرْبِي مِنْهُ، لَفَعَلْتُ يَقُولُ: اهْتَزَّ لَهُ عَرْشُ الرَّحْمَنِ تَبَارَكَ وَتَعَالَى، يُرِيدُ سَعْدَ بْنَ مُعَاذٍ يَوْمَ تُوُفِّيَ."],"takhrij":"حسن: رواه الإمام أحمد (26793)، والترمذيّ في الشمائل (17)، والطبرانيّ في الكبير (24/ح 703) كلّهم من طرق عن يوسف بن يعقوب الماجشون، عن أبيه، عن عاصم بن عمر بن قتادة، عن جدّته رُميثة، فذكرت مثله.","grade":"حسن","chapter_ar":"باب ما جاء في خاتم النبوة وصفته","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (26793), al-Tirmidhī in al-Shamāʾil (17), and al-Ṭabarānī in al-Muʿjam al-Kabīr (24/267).","chapter_en":"What Has Been Reported Concerning the Seal of Prophethood and Its Description","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["Rumaythah may Allah be pleased with her said: I heard the Messenger of Allah ﷺ — and because of how close I was to him, had I wished, I could have kissed the Seal between his shoulders — say: “The Throne of al-Raḥmān, Blessed and Exalted, shook.” He meant for Saʿd ibn Muʿādh on the day he died."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (26793)، والترمذي في الشمائل (17)، والطبراني في الكبير (24/267)."},{"num":770,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَمْ يَبْقَ مِنَ النُّبُوَّةِ إِلَّا الْمُبَشِّرَاتُ، قَالُوا: وَمَا الْمُبَشِّرَاتُ ؟، قَالَ: الرُّؤْيَا الصَّالِحَةُ."],"takhrij":"صحيح: رواه البخاريّ في التعبير (6990) عن أبي اليمان، أخبرنا شعيب، عن الزّهريّ، حدّثني سعيد بن المسيب، أنّ أبا هريرة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ذهاب النبوة بعد نبوة نبينا ﷺ وبقاء المبشرات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (6990).","chapter_en":"Prophethood Has Ended After the Prophethood of Our Prophet ﷺ, While Glad Tidings Remain","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Nothing remains of Prophethood except the glad tidings.” They asked: “What are the glad tidings?” He replied: “The righteous dream.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6990)."},{"num":771,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: كَشَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ السِّتَارَةَ وَالنَّاسُ صُفُوفٌ خَلْفَ أَبِي بَكْرٍ، فَقَالَ: أَيُّهَا النَّاسُ، إِنَّهُ لَمْ يَبْقَ مِنْ مُبَشِّرَاتِ النُّبُوَّةِ، إِلَّا الرُّؤْيَا الصَّالِحَةُ، يَرَاهَا الْمُسْلِمُ، أَوْ تُرَى لَهُ، أَلَا وَإِنِّي نُهِيتُ أَنْ أَقْرَأَ الْقُرْآنَ رَاكِعًا أَوْ سَاجِدًا، فَأَمَّا الرُّكُوعُ فَعَظِّمُوا فِيهِ الرَّبَّ عَزَّ وَجَلَّ، وَأَمَّا السُّجُودُ فَاجْتَهِدُوا فِي الدُّعَاءِ فَقَمِنٌ أَنْ يُسْتَجَابَ لَكُمْ."],"takhrij":"صحيح: رواه مسلم في الصّلاة (479) من طرق عن سفيان بن عيينة، أخبرني سليمان بن سحيم، عن إبراهيم بن عبدالله بن معبد، عن أبيه، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب ذهاب النبوة بعد نبوة نبينا ﷺ وبقاء المبشرات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (479).","chapter_en":"Prophethood Has Ended After the Prophethood of Our Prophet ﷺ, While Glad Tidings Remain","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: The Messenger of Allah ﷺ drew back the curtain while the people were standing in rows behind Abū Bakr may Allah be pleased with him, and said: “O people, nothing remains of the glad tidings of Prophethood except a righteous dream which a Muslim sees or which is seen for him. Indeed, I have been forbidden to recite the Qurʾān while bowing or prostrating. As for bowing, magnify the Lord, Mighty and Majestic, therein. As for prostration, strive earnestly in supplication, for it is most likely that your supplication will be answered.”"]},"buhuth":{"en":["The word:","“qamin”","with a fatḥah on the qāf and a kasrah on the mīm, means: fitting, likely, and deserving."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2108,2111,10931,11814],"tks":"صحيح: رواه مسلم (479)."},{"num":772,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا انْصَرَفَ مِنْ صَلَاةِ الْغَدَاةِ، يَقُولُ: هَلْ رَأَى أَحَدٌ مِنْكُمُ اللَّيْلَةَ رُؤْيَا؟ وَيَقُولُ: لَيْسَ يَبْقَى بَعْدِي مِنَ النُّبُوَّةِ، إِلَّا الرُّؤْيَا الصَّالِحَةُ."],"takhrij":"صحيح: رواه مالك في الموطأ في كتاب الرؤيا (3) وعنه أبو داود (5017)، وأحمد (8313) وصحّحه ابن حبان (6048)، والحاكم (8176) وقال: هذا حديث صحيح الإسناد ولم يخرجاه.","grade":"صحيح","chapter_ar":"باب ذهاب النبوة بعد نبوة نبينا ﷺ وبقاء المبشرات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Mālik (3), Abū Dāwūd (5017), and Aḥmad (8313), and authenticated by Ibn Ḥibbān (6048).","chapter_en":"Prophethood Has Ended After the Prophethood of Our Prophet ﷺ, While Glad Tidings Remain","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah, may Allah be pleased with him, reported: When the Messenger of Allah ﷺ finished the morning prayer, he would ask: “Did any of you see a dream last night?” And he would say: “Nothing of Prophethood will remain after me except the righteous dream.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مالك (3)، وأبو داود (5017)، وأحمد (8313)، وصححه ابن حبان (6048)."},{"num":773,"demo":false,"sanad":"","matn":["عَنْ أُمِّ كُرْزٍ الْكَعْبِيَّةِ، أَنَّ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ذَهَبَتِ النُّبُوَّةُ وَبَقِيَتِ الْمُبَشِّرَاتُ."],"takhrij":"حسن: رواه ابن ماجه (3896) عن هارون بن عبدالله الحمال، قال: حدّثنا سفيان بن عيينة، عن عبيد الله بن أبي يزيد، عن أبيه، عن سباع بن ثابت، عن أمّ كرز الكعبية، فذكره.","grade":"حسن","chapter_ar":"باب ذهاب النبوة بعد نبوة نبينا ﷺ وبقاء المبشرات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Ibn Mājah (3896) and Aḥmad (27141), and authenticated by Ibn Ḥibbān (6047).","chapter_en":"Prophethood Has Ended After the Prophethood of Our Prophet ﷺ, While Glad Tidings Remain","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Umm Kurz al-Kaʿbiyyah may Allah be pleased with her reported that the Prophet ﷺ said: “Prophethood has gone, and the glad tidings remain.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3896)، وأحمد (27141)، وصححه ابن حبان (6047)."},{"num":774,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ بْنِ أَسِيدٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ذَهَبَتِ النُّبُوَّةُ فَلَا نُبُوَّةَ بَعْدِي إِلَّا الْمُبَشِّرَاتُ. قِيلَ: وَمَا الْمُبَشِّرَاتُ؟ قَالَ: الرُّؤْيَا الصَّالِحَةُ يَرَاهَا الرَّجُلُ أَوْ تُرَى لَهُ."],"takhrij":"حسن: رواه الطبرانيّ في الكبير (3051) عن محمد بن عبدالله الحضرميّ، ثنا الحسن بن علي الحلوانيّ، ثنا أبو عاصم، عن مهدي بن ميمون، عن عثمان بن عبيد، عن أبي الطّفيل، عن حذيفة بن أسيد، فذكره.","grade":"حسن","chapter_ar":"باب ذهاب النبوة بعد نبوة نبينا ﷺ وبقاء المبشرات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (3/200).","chapter_en":"Prophethood Has Ended After the Prophethood of Our Prophet ﷺ, While Glad Tidings Remain","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Ḥudhayfah ibn Usayd may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Prophethood has gone. There is no Prophethood after me except the glad tidings.” He was asked: “What are the glad tidings?” He replied: “The righteous dream which a man sees or which is seen for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (3051)."},{"num":775,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَبْقَى بَعْدِي مِنَ النُّبُوَّةِ شَيْءٌ، إِلَّا الْمُبَشِّرَاتُ. قَالُوا: يَا رَسُولَ اللَّهِ، وَمَا الْمُبَشِّرَاتُ؟ قَالَ: الرُّؤْيَا الصَّالِحَةُ يَرَاهَا الرَّجُلُ أَوْ تُرَى لَهُ."],"takhrij":"حسن: رواه أحمد (24977)، والبزّار- كشف الأستار (2118)، كلاهما من حديث يحيى بن أيوب، قال: حدثنا سعيد بن عبدالرحمن الجمحيّ، عن هشام بن عروة، عن أبيه، عن عائشة، فذكرت مثله، إلاّ أنّ البزّار قال: يراها الرّجل الصّالح.","grade":"حسن","chapter_ar":"باب ذهاب النبوة بعد نبوة نبينا ﷺ وبقاء المبشرات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Aḥmad (24977) and al-Bazzār in Kashf al-Astār (2118).","chapter_en":"Prophethood Has Ended After the Prophethood of Our Prophet ﷺ, While Glad Tidings Remain","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported that the Prophet ﷺ said: “Nothing of Prophethood will remain after me except the glad tidings.” They asked: “O Messenger of Allah, what are the glad tidings?” He replied: “The righteous dream which a man sees or which is seen for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (24977)، والبزار في كشف الأستار (2118)."},{"num":776,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ سَفَرٍ، حَتَّى إِذَا دَفَعْنَا إِلَى حَائِطٍ مِنْ حِيطَانِ بَنِي النَّجَّارِ، إِذَا فِيهِ جَمَلٌ لَا يَدْخُلُ الْحَائِطَ أَحَدٌ إِلَّا شَدَّ عَلَيْهِ، قَالَ: فَذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ حَتَّى أَتَى الْحَائِطَ، فَدَعَا الْبَعِيرَ، فَجَاءَ وَاضِعًا مِشْفَرَهُ إِلَى الْأَرْضِ، حَتَّى بَرَكَ بَيْنَ يَدَيْهِ، قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَاتُوا خِطَامَه فَخَطَمَهُ وَدَفَعَهُ إِلَى صَاحِبِهِ، قَالَ: ثُمَّ الْتَفَتَ إِلَى النَّاسِ فَقَالَ: إِنَّهُ لَيْسَ شَيْءٌ بَيْنَ السَّمَاءِ وَالْأَرْضِ، إِلَّا يَعْلَمُ أَنِّي رَسُولُ اللَّهِ، إِلَّا عَاصِيَ الْجِنِّ وَالْإِنْسِ."],"takhrij":"حسن: رواه الإمام أحمد (14333)، وعبد بن حميد (1122)، والدّارميّ (18) كلّهم من طرق عن الأجلح، عن الذيال بن حرملة، عن جابر بن عبدالله، فذكره.","grade":"حسن","chapter_ar":"باب ما من شيء بين السماء والأرض إلا يشهد لنبوة محمد رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (14333), ʿAbd ibn Ḥumayd (1122), and al-Dārimī (18).","chapter_en":"Nothing Between Heaven and Earth Except That It Bears Witness to the Prophethood of Muḥammad, the Messenger of Allah ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, reported: We returned with the Messenger of Allah ﷺ from a journey until we came to a walled garden belonging to Banū al-Najjār. Inside it was a camel which would charge anyone who entered the garden. They mentioned this to the Prophet ﷺ. He came to the garden and called the camel. It approached with its lower lip lowered toward the ground until it knelt before him. The Prophet ﷺ said: “Bring its halter.” They haltered it, and he handed it to its owner. Then he turned toward the people and said: “There is nothing between heaven and earth except that it knows that I am the Messenger of Allah, except the disobedient among the jinn and mankind.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (14333)، وعبد بن حميد (1122)، والدارمي (18)."},{"num":777,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي لَأَعْرِفُ حَجَرًا بِمَكَّةَ كَانَ يُسَلِّمُ عَلَيَّ قَبْلَ أَنْ أُبْعَثَ، إِنِّي لَأَعْرِفُهُ الْآنَ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2277) عن أبي بكر بن أبي شيبة، حدّثنا يحيى بن أبي بُكير، عن إبراهيم بن طهمان، حدثني سماك بن حرب، عن جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب ما من شيء بين السماء والأرض إلا يشهد لنبوة محمد رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2277).","chapter_en":"Nothing Between Heaven and Earth Except That It Bears Witness to the Prophethood of Muḥammad, the Messenger of Allah ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn Samurah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Indeed, I know a stone in Makkah that used to greet me with salām before I was commissioned as a Prophet. I still know it now.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8546,9659],"tks":"صحيح: رواه مسلم (2277)."},{"num":778,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ كَانَ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فُرِجَ سَقْفُ بَيْتِي وَأَنَا بِمَكَّةَ فَنَزَلَ جِبْرِيلُ عَلَيْهِ السَّلامُ، فَفَرَجَ صَدْرِي، ثُمَّ غَسَلَهُ مِنْ مَاءِ زَمْزَمَ، ثُمَّ جَاءَ بِطَسْتٍ مِنْ ذَهَبٍ مُمْتَلِئٍ حِكْمَةً وَإِيمَانًا فَأَفْرَغَهَا فِي صَدْرِي ثُمَّ أَطْبَقَهُ، ثُمَّ أَخَذَ بِيَدِي فَعَرَجَ بِي إِلَى السَّمَاءِ، فَلَمَّا جِئْنَا السَّمَاءَ الدُّنْيَا قَالَ جِبْرِيلُ عَلَيْهِ السَّلَام لِخَازِنِ السَّمَاءِ الدُّنْيَا: افْتَحْ، قَالَ: مَنْ هَذَا؟ قَالَ: هَذَا جِبْرِيلُ، قَالَ: هَلْ مَعَكَ أَحَدٌ؟ قَالَ: نَعَمْ مَعِيَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَأُرْسِلَ إِلَيْهِ؟ قَالَ: نَعَمْ، فَفَتَحَ، قَالَ: فَلَمَّا عَلَوْنَا السَّمَاءَ الدُّنْيَا، فَإِذَا رَجُلٌ عَنْ يَمِينِهِ أَسْوِدَةٌ وَعَنْ يَسَارِهِ أَسْوِدَةٌ، قَالَ: فَإِذَا نَظَرَ قِبَلَ يَمِينِهِ ضَحِكَ، وَإِذَا نَظَرَ قِبَلَ شِمَالِهِ بَكَى، قَالَ: فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالِابْنِ الصَّالِحِ، قَالَ: قُلْتُ: يَا جِبْرِيلُ مَنْ هَذَا؟ قَالَ: هَذَا آدَمُ عَلَيْهِ السَّلامُ وَهَذِهِ الأَسْوِدَةُ عَنْ يَمِينِهِ، وَعَنْ شِمَالِهِ نَسَمُ بَنِيهِ، فَأَهْلُ الْيَمِينِ أَهْلُ الْجَنَّةِ وَالأَسْوِدَةُ الَّتِي عَنْ شِمَالِهِ أَهْلُ النَّارِ، فَإِذَا نَظَرَ قِبَلَ يَمِينِهِ ضَحِكَ وَإِذَا نَظَرَ قِبَلَ شِمَالِهِ بَكَى، قَالَ: ثُمَّ عَرَجَ بِي جِبْرِيلُ حَتَّى أَتَى السَّمَاءَ الثَّانِيَةَ، فَقَالَ لِخَازِنِهَا: افْتَحْ، قَالَ: فَقَالَ لَهُ خَازِنُهَا: مِثْلَ مَا قَالَ خَازِنُ السَّمَاءِ الدُّنْيَا، فَفَتَحَ.","فَقَالَ أَنَسُ بْنُ مَالِكٍ: فَذَكَرَ أَنَّهُ وَجَدَ فِي السَّمَاوَاتِ آدَمَ وَإِدْرِيسَ وَعِيسَى وَمُوسَى وَإِبْرَاهِيمَ صَلَوَاتُ اللَّهِ عَلَيْهِمْ أَجْمَعِينَ، وَلَمْ يُثْبِتْ كَيْفَ مَنَازِلُهُمْ غَيْرَ أَنَّهُ ذَكَرَ أَنَّهُ قَدْ وَجَدَ آدَمَ عَلَيْهِ السَّلَام فِي السَّمَاءِ الدُّنْيَا وَإِبْرَاهِيمَ فِي السَّمَاءِ السَّادِسَةِ، قَالَ: فَلَمَّا مَرَّ جِبْرِيلُ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِدْرِيسَ صَلَوَاتُ اللَّهِ عَلَيْهِ، قَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالأَخِ الصَّالِحِ، قَالَ: ثُمَّ مَرَّ، فَقُلْتُ: مَنْ هَذَا؟ فَقَالَ: هَذَا إِدْرِيسُ، قَالَ: ثُمَّ مَرَرْتُ بِمُوسَى عَلَيْهِ السَّلَام، فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالأَخِ الصَّالِحِ، قَالَ: قُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا مُوسَى، قَالَ: ثُمَّ مَرَرْتُ بِعِيسَى، فَقَالَ مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالأَخِ الصَّالِحِ، قُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا عِيسَى ابْنُ مَرْيَمَ، قَالَ: ثُمَّ مَرَرْتُ بِإِبْرَاهِيمَ عَلَيْهِ السَّلَام، فَقَالَ: مَرْحَبًا بِالنَّبِيِّ الصَّالِحِ وَالِابْنِ الصَّالِحِ، قَالَ: قُلْتُ: مَنْ هَذَا؟ قَالَ: هَذَا ِ إبْرَاهِيمُ.","قَالَ ابْنُ شِهَابٍ، وَأَخْبَرَنِي ابْنُ حَزْمٍ، أَنَّ ابْنَ عَبَّاسٍ، وَأَبَا حَبَّةَ الْأَنْصَارِيَّ كَانَا يَقُولَانِ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثُمَّ عُرِجَ بِي حَتَّى ظَهَرْتُ لِمُسْتَوًى أَسْمَعُ فِيهِ صَرِيفَ الأَقْلَامِ.","قَالَ ابْنُ حَزْمٍ، وَأَنَسُ بْنُ مَالِكٍ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَفَرَضَ اللَّهُ عَلَى أُمَّتِي خَمْسِينَ صَلَاةً. قَالَ: فَرَجَعْتُ بِذَلِكَ حَتَّى أَمَرَ بِمُوسَى فَقَالَ مُوسَى عَلَيْهِ السَّلَامُ: مَاذَا فَرَضَ رَبُّكَ عَلَى أُمَّتِكَ؟ قَالَ: قُلْتُ: فَرَضَ عَلَيْهِمْ خَمْسِينَ صَلَاةً قَالَ لِي مُوسَى عَلَيْهِ السَّلَامُ فَرَاجِعْ رَبَّكَ فَإِنَّ أُمَّتَكَ لَا تُطِيقُ ذَلِكَ. قَالَ فَرَاجَعْتُ رَبِّي، فَوَضَعَ شَطْرَهَا. قَالَ: فَرَجَعْتُ إِلَى مُوسَى عَلَيْهِ السَّلَامُ فَأخْبَرْتُهُ، قَالَ: رَاجِعْ رَبَّكَ فَإِنَّ أُمَّتَكَ لَا تُطِيقُ ذَلِكَ قَالَ فَرَاجَعْتُ رَبِّي فَقَالَ هِيَ خَمْسٌ وَهِيَ خَمْسُونَ لَا يُبَدَّلُ الْقَوْلُ لَدَيَّ قَالَ فَرَجَعْتُ إِلَى مُوسَى فَقَالَ رَاجِعْ رَبَّكَ فَقُلْتُ قَدْ اسْتَحْيَيْت مِنْ رَبِّي. قَالَ: ثُمَّ انْطَلَقَ بِي جِبْرِيلُ حَتَّى نَأْتِيَ سِدْرَةَ الْمُنْتَهَى فَغَشِيَهَا أَلْوَانٌ لَا أَدْرِي مَا هِيَ. قَالَ: ثُمَّ أُدْخِلَتْ الْجَنَّةَ فَإِذَا فِيهَا جَنَابِذُ اللُّؤْلُؤِ وَإِذَا تُرَابُهَا الْمِسْكُ."],"takhrij":"متفق عليه: رواه البخاريّ في الصلاة (349)، ومسلم في الإيمان (163) كلاهما من حديث يونس (هو الأيلي)، عن ابن شهاب الزهري، عن أنس بن مالك، قال: كان أبو ذرّ يحدّث. فذكر الحديث. واللّفظ لمسلم، ولفظ البخاريّ قريب منه.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الإيمان بما خُص به النبي ﷺ من الإسراء والمعراج، وما جاء فيه من الآيات البينات","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (349) and Muslim (163). The wording is that of Muslim.","chapter_en":"Belief in What the Prophet ﷺ Was Specifically Honored With of the Night Journey and Ascension, and the Clear Signs That Occurred Therein","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":14,"content":{"translation":{"en":["Abū Dharr may Allah be pleased with him used to relate that the Messenger of Allah ﷺ said: “The roof of my house was opened while I was in Makkah, and Jibrīl, peace be upon him, descended. He opened my chest and washed it with Zamzam water. Then he brought a golden basin filled with wisdom and faith, poured it into my chest, and closed it. Then he took me by the hand and ascended with me toward heaven. When we reached the lowest heaven, Jibrīl, peace be upon him, said to its gatekeeper: ‘Open.’ He asked: ‘Who is this?’ Jibrīl replied: ‘This is Jibrīl.’ He asked: ‘Is anyone with you?’ He replied: ‘Yes, Muḥammad ﷺ is with me.’ He asked: ‘Has he been sent for?’ He replied: ‘Yes.’ So he opened the gate. When we ascended into the lowest heaven, there was a man with multitudes to his right and multitudes to his left. Whenever he looked toward his right, he laughed, and whenever he looked toward his left, he wept. He said: ‘Welcome to the righteous Prophet and the righteous son.’ I asked: ‘O Jibrīl, who is this?’ He replied: ‘This is Adam peace be upon him. These multitudes on his right and left are the souls of his descendants. Those on his right are the people of Paradise, while those on his left are the people of the Fire. Whenever he looks toward his right, he laughs, and whenever he looks toward his left, he weeps.’ Then Jibrīl ascended with me until he reached the second heaven. He said to its gatekeeper: ‘Open.’ Its gatekeeper asked him the same questions that the gatekeeper of the lowest heaven had asked, and then opened it.”","Anas ibn Mālik said: He mentioned that in the heavens he encountered Adam, Idrīs, Jesus, Moses, and Abraham — may Allah’s peace and blessings be upon them all. He did not specify their exact levels, except that he mentioned that Adam peace be upon him was in the lowest heaven and Abraham, peace be upon him, was in the sixth heaven. He continued: “When Jibrīl and the Messenger of Allah ﷺ passed by Idrīs peace be upon him, he said: ‘Welcome to the righteous Prophet and the righteous brother.’ I asked: ‘Who is this?’ Jibrīl replied: ‘This is Idrīs.’ Then I passed by Moses, peace be upon him,, who said: ‘Welcome to the righteous Prophet and the righteous brother.’ I asked: ‘Who is this?’ He replied: ‘This is Moses.’ Then I passed by Jesus, who said: ‘Welcome to the righteous Prophet and the righteous brother.’ I asked: ‘Who is this?’ He replied: ‘This is Jesus son of Mary.’ Then I passed by Abraham, peace be upon him,, who said: ‘Welcome to the righteous Prophet and the righteous son.’ I asked: ‘Who is this?’ He replied: ‘This is Abraham.’” Ibn Shihāb said:","Ibn Ḥazm informed me that Ibn ʿAbbās and Abū Ḥabbah al-Anṣārī used to say that the Messenger of Allah ﷺ said: “Then I was taken upward until I reached a level where I could hear the scratching of the pens.” Ibn Ḥazm and Anas ibn Mālik reported that the Messenger of Allah ﷺ said:","“Then Allah prescribed fifty prayers for my Ummah. I returned with that until I passed by Moses. Moses peace be upon him asked: ‘What has your Lord prescribed for your Ummah?’ I replied: ‘He has prescribed fifty prayers for them.’ Moses, peace be upon him, said: ‘Return to your Lord, for your Ummah will not be able to bear that.’ So I returned to my Lord, and He reduced them by half. Then I returned to Moses, peace be upon him, and informed him. He said: ‘Return to your Lord, for your Ummah will not be able to bear that.’ So I returned to my Lord, and He said: ‘They are five, yet they are fifty. My word is not changed.’ I returned to Moses, and he said: ‘Return to your Lord.’ I replied: ‘I have become shy before my Lord.’ Then Jibrīl took me onward until we came to Sidrat al-Muntahā, the Lote Tree of the Utmost Boundary. It was enveloped by colors whose nature I did not know. Then I was admitted into Paradise. There were domes of pearls within it, and its soil was musk.”"]},"intro":{"ar":["قال الله تعالى:","﴿سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى الَّذِي بَارَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ آيَاتِنَا إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ﴾","[الإسراء: ١]","قال الزهري:","أُسري برسول الله ﷺ إلى بيت المقدس قبل خروجه إلى المدينة بسنة.","هكذا ذكر موسى بن عقبة عن ابن شهاب، وهو قول عروة أيضًا.","دلائل النبوة للبيهقي (٢/٣٥٤–٣٥٥).","وهذا هو الصحيح، وكان الإسراء والمعراج في ليلة واحدة ومرة واحدة، بالروح والجسد، يقظة لا منامًا، على رأي جمهور العلماء.","قال القرطبي:","«وعليه يدل ظاهر الكتاب وصحيح الأخبار، ومبادرة قريش لإنكار ذلك وتكذيبه، ولو كان منامًا لما أنكروه، ولما افتتن به من افتتن؛ إذ كثيرًا ما يرى في المنام أمور عجيبة وأحوال هائلة، فلا يستبعد ذلك في النوم، وإنما يستبعد في اليقظة».","المفهم (١/٣٨٥).","فهذه الآية أصل في إثبات الإسراء، وأنه كان بقدرة الله تعالى، لإراءة نبيه ﷺ من آياته.","واحتجاج القرطبي مبناه أن إنكار قريش ووقوع الفتنة إنما يليق بخبر عن أمر وقع يقظة لا منامًا.","وفي الحديث الآتي تظهر الآيات البينات عمليًا: شق الصدر، والعروج، ولقاء الأنبياء، وفرض الصلاة، ثم تخفيفها إلى خمس مع بقاء أجر الخمسين."],"en":["Allah Most High said:","“Glory be to the One who took His servant by night from al-Masjid al-Ḥarām to al-Masjid al-Aqṣā, whose surroundings We have blessed, in order to show him some of Our signs. Indeed, He alone is the All-Hearing, All-Seeing.”","[Sūrat al-Isrāʾ 17:1]","Al-Zuhrī said:","“The Messenger of Allah ﷺ was taken on the Night Journey to Bayt al-Maqdis one year before his departure to Madinah.”","This is how Mūsā ibn ʿUqbah reported it from Ibn Shihāb, and it was also the view of ʿUrwah.","Dalāʾil al-Nubuwwah by al-Bayhaqī (2/354–355).","The manuscript states that this is the correct view: the Night Journey and Ascension occurred in a single night and on one occasion, with both body and soul, while awake rather than in a dream, according to the majority of scholars.","Al-Qurṭubī said:","“The apparent meaning of the Qurʾān and the authentic reports indicate this, as does Quraysh’s immediate denial and rejection of it. Had it merely been a dream, they would not have denied it, nor would those who were tested by it have been tested; for people frequently see astonishing and terrifying things in dreams, and such matters are not considered far-fetched during sleep. They are only considered extraordinary when occurring while awake.”","Al-Mufhim (1/385).","This verse is a foundational proof for the Night Journey and that it occurred by the power of Allah Most High, so that He might show His Prophet ﷺ some of His signs.","Al-Qurṭubī’s argument is based upon the fact that Quraysh’s denial and the trial that followed are fitting only for a report concerning an event that occurred while awake, not merely in a dream.","The following ḥadīth contains clear manifestations of these signs: the opening of the Prophet’s ﷺ chest, the ascent through the heavens, meeting the prophets, the prescription of prayer, and its reduction to five prayers while retaining the reward of fifty."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (349)، ومسلم (163)، واللفظ لمسلم."},{"num":779,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: لَمَّا نَزَلَتْ: ﴿وَأَنْذِرْ عَشِيرَتَكَ الأَقْرَبِينَ﴾ [سورة الشعراء: 214] صَعِدَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الصَّفَا، فَجَعَلَ يُنَادِي: يَا بَنِي فِهْرٍ، يَا بَنِي عَدِيٍّ، لِبُطُونِ قُرَيْشٍ حَتَّى اجْتَمَعُوا، فَجَعَلَ الرَّجُلُ إِذَا لَمْ يَسْتَطِعْ أَنْ يَخْرُجَ، أَرْسَلَ رَسُولًا لِيَنْظُرَ مَا هُوَ، فَجَاءَ أَبُو لَهَبٍ وَقُرَيْشٌ، فَقَالَ: أَرَأَيْتَكُمْ لَوْ أَخْبَرْتُكُمْ أَنَّ خَيْلًا بِالْوَادِي تُرِيدُ أَنْ تُغِيرَ عَلَيْكُمْ أَكُنْتُمْ مُصَدِّقِيَّ؟ قَالُوا: نَعَمْ، مَا جَرَّبْنَا عَلَيْكَ إِلَّا صِدْقًا، قَالَ: فَإِنِّي نَذِيرٌ لَكُمْ بَيْنَ يَدَيْ عَذَابٍ شَدِيدٍ، فَقَالَ أَبُو لَهَبٍ: تَبًّا لَكَ سَائِرَ الْيَوْمِ أَلِهَذَا جَمَعْتَنَا؟ فَنَزَلَتْ: ﴿تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ (1) مَا أَغْنَى عَنْهُ مَالُهُ وَمَا كَسَبَ (2)﴾ [المسد: 1، 2]."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4770) ومسلم في الإيمان (208) كلاهما من حديث الأعمش، قال: حدثني عمرو بن مرة، عن سعيد بن جبير عن ابن عباس فذكره واللفظ للبخاري، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"باب أن النبي ﷺ نذير بين يدي عذاب شديد","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4770) and Muslim (208). The wording is that of al-Bukhārī.","chapter_en":"The Prophet ﷺ Is a Warner Before a Severe Punishment","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, reported: When the verse was revealed: “And warn your closest relatives,” [Sūrat al-Shuʿarāʾ 26:214] the Prophet ﷺ ascended al-Ṣafā and began calling: “O Banū Fihr! O Banū ʿAdī!” calling the various clans of Quraysh until they gathered. If a man was unable to come himself, he sent someone to find out what was happening. Abū Lahab and the people of Quraysh came. The Prophet ﷺ said: “Tell me: if I informed you that cavalry in the valley were about to attack you, would you believe me?” They replied: “Yes. We have never experienced anything from you except truthfulness.” He said: “Then indeed I am a warner to you before a severe punishment.” Abū Lahab said: “May you perish for the rest of this day! Is this why you gathered us?” Then there was revealed: “May the hands of Abū Lahab perish, and may he perish. His wealth and whatever he earned will not benefit him.” [Sūrat al-Masad 111:1–2]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4770)، ومسلم (208)، واللفظ للبخاري."},{"num":780,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّمَا أَنَا بَشَرٌ، وَإِنَّهُ يَأْتِينِي الْخَصْمُ، فَلَعَلَّ بَعْضَكُمْ أَنْ يَكُونَ أَبْلَغَ مِنْ بَعْضٍ، فَأَحْسِبُ أَنَّهُ صَدَقَ، فَأَقْضِيَ لَهُ بِذَلِكَ، فَمَنْ قَضَيْتُ لَهُ بِحَقِّ مُسْلِمٍ، فَإِنَّمَا هِيَ قِطْعَةٌ مِنَ النَّارِ فَلْيَأْخُذْهَا أَوْ فَلْيَتْرُكْهَا."],"takhrij":"متفق عليه: رواه البخاريّ في المظالم (2458)، ومسلم في الأقضية (1713) كلاهما من حديث الزّهريّ، قال: أخبرني عروة بن الزبير، أن زينب بنت أمّ سلمة أخبرته، أنّ أمّها أم سلمة زوج النبي صلى الله عليه وسلم أخبرتها، فذكرته.","grade":"متفق عليه","chapter_ar":"باب بشرية الرسول ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2458) and Muslim (1713).","chapter_en":"The Humanity of the Messenger ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":16,"content":{"translation":{"en":["Umm Salamah may Allah be pleased with her reported that the Messenger of Allah ﷺ said: “I am only a human being, and litigants come before me. Perhaps one of you is more eloquent in presenting his case than another, so I may think that he is truthful and judge in his favor on that basis. Whoever I award something that rightfully belongs to another Muslim, then it is only a piece of the Fire. So let him take it, or let him leave it.”"]},"intro":{"ar":["قال الله تعالى:","﴿قُلْ إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ يُوحَىٰ إِلَيَّ أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾","[الكهف: ١١٠]","وقال تعالى:","﴿وَمَا جَعَلْنَا لِبَشَرٍ مِنْ قَبْلِكَ الْخُلْدَ أَفَإِنْ مِتَّ فَهُمُ الْخَالِدُونَ﴾","[الأنبياء: ٣٤]","وقال تعالى:","﴿وَقَالُوا مَالِ هَذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ وَيَمْشِي فِي الْأَسْوَاقِ﴾","[الفرقان: ٧]","وقد ورد في الصحيحين مرفوعًا:","«إنما أنا بشر مثلكم، أنسى كما تنسون، فإذا نسيت فذكروني».","رواه البخاري (٤٠١)، ومسلم (٥٧٢)."],"en":["Allah Most High said:","“Say: I am only a human being like you, to whom it has been revealed that your Allah is One Allah.”","[Sūrat al-Kahf 18:110]","And Allah Most High said:","“We did not grant immortality to any human being before you. So if you die, will they then live forever?”","[Sūrat al-Anbiyāʾ 21:34]","And He said:","“They say: What is the matter with this Messenger that he eats food and walks in the marketplaces?”","[Sūrat al-Furqān 25:7]","It is also authentically reported from the Prophet ﷺ:","“I am only a human being like you. I forget just as you forget, so when I forget, remind me.”","Narrated by al-Bukhārī (401) and Muslim (572)."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2458)، ومسلم (1713)."},{"num":781,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ، فَأَيُّمَا رَجُلٍ مِنَ الْمُسْلِمِينَ سَبَبْتُهُ، أَوْ لَعَنْتُهُ، أَوْ جَلَدْتُهُ فَاجْعَلْهَا لَهُ زَكَاةً وَرَحْمَةً."],"takhrij":"متفق عليه: رواه مسلم في البر والصلة (2601) عن محمد بن عبدالله بن نمر، حدّثنا أبي، حدثنا الأعمش، عن أبي صالح، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب بشرية الرسول ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2601).","chapter_en":"The Humanity of the Messenger ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “O Allah, I am only a human being. Whichever Muslim I have reviled, cursed, or struck, make that for him a purification and mercy.”"]},"buhuth":{"en":["Al-Bukhārī (6361) and Muslim also narrated the wording:","“O Allah, whichever believer I have reviled, make that a means of nearness for him to You on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2601)."},{"num":782,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: دَخَلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلَانِ، فَكَلَّمَاهُ بِشَيْءٍ لَا أَدْرِي مَا هُوَ، فَأَغْضَبَاهُ فَلَعَنَهُمَا وَسَبَّهُمَا، فَلَمَّا خَرَجَا، قُلْتُ: يَا رَسُولَ اللَّهِ، مَنْ أَصَابَ مِنَ الْخَيْرِ شَيْئًا مَا أَصَابَهُ هَذَانِ، قَالَ: وَمَا ذَاكِ، قَالَتْ: قُلْتُ: لَعَنْتَهُمَا وَسَبَبْتَهُمَا، قَالَ: أَوَ مَا عَلِمْتِ مَا شَارَطْتُ عَلَيْهِ رَبِّي؟ قُلْتُ: اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ، فَأَيُّ الْمُسْلِمِينَ لَعَنْتُهُ أَوْ سَبَبْتُهُ فَاجْعَلْهُ لَهُ زَكَاةً وَأَجْرًا."],"takhrij":"صحيح: رواه مسلم في البر والصّلة (2600) عن زهير بن حرب، حدّثنا جرير، عن الأعمش، عن أبي الضُّحى، عن مسروق، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب بشرية الرسول ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2600).","chapter_en":"The Humanity of the Messenger ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":16,"content":{"translation":{"en":["ʿĀʾishah may Allah be pleased with her reported: Two men came to the Messenger of Allah ﷺ and spoke to him about something whose nature I do not know. They angered him, so he cursed and rebuked them. After they left, I said: “O Messenger of Allah, no one has attained such good as these two have attained!” He asked: “What do you mean?” I said: “You cursed and rebuked them!” He replied: “Do you not know the condition I made with my Lord? I said: ‘O Allah, I am only a human being. Whichever Muslim I curse or rebuke, make that for him a purification and a reward.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2600)."},{"num":783,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّمَا أَنَا بَشَرٌ، وَإِنِّي اشْتَرَطْتُ عَلَى رَبِّي عَزَّ وَجَلَّ، أَيُّ عَبْدٍ مِنَ الْمُسْلِمِينَ سَبَبْتُهُ أَوْ شَتَمْتُهُ أَنْ يَكُونَ ذَلِكَ لَهُ زَكَاةً وَأَجْرًا."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2602) من طرق عن حجّاج بن محمد، قال: قال ابن جريج: أخبرني أبو الزبير، أنه سمع جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب بشرية الرسول ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2602).","chapter_en":"The Humanity of the Messenger ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":16,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh, may Allah be pleased with them, said: I heard the Messenger of Allah ﷺ say: “I am only a human being, and I made a condition with my Lord, Mighty and Majestic, that whichever servant among the Muslims I revile or rebuke, it be made for him a purification and a reward.”"]}},"tuhfa":{},"full":1,"rep":[9639],"tks":"صحيح: رواه مسلم (2602)."},{"num":784,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَتْ عِنْدَ أُمِّ سُلَيْمٍ يَتِيمَةٌ وَهِيَ أُمُّ أَنَسٍ، فَرَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْيَتِيمَةَ، فَقَالَ: آنْتِ هِيَهْ؟ لَقَدْ كَبِرْتِ لَا كَبِرَ سِنُّكِ، فَرَجَعَتِ الْيَتِيمَةُ إِلَى أُمِّ سُلَيْمٍ تَبْكِي، فَقَالَتْ أُمُّ سُلَيْمٍ: مَا لَكِ يَا بُنَيَّةُ؟ قَالَتْ: الْجَارِيَةُ دَعَا عَلَيَّ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا يَكْبَرَ سِنِّي، فَالْآنَ لَا يَكْبَرُ سِنِّي أَبَدًا، أَوْ قَالَتْ: قَرْنِي. فَخَرَجَتْ أُمُّ سُلَيْمٍ مُسْتَعْجِلَةً تَلُوثُ خِمَارَهَا حَتَّى لَقِيَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا لَكِ يَا أُمَّ سُلَيْمٍ؟ فَقَالَتْ: يَا نَبِيَّ اللَّهِ، أَدَعَوْتَ عَلَى يَتِيمَتِي؟ قَالَ: وَمَا ذَاكِ يَا أُمَّ سُلَيْمٍ؟ قَالَتْ: زَعَمَتْ أَنَّكَ دَعَوْتَ أَنْ لَا يَكْبَرَ سِنُّهَا وَلَا يَكْبَرَ قَرْنُهَا، قَالَ: فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَالَ: يَا أُمَّ سُلَيْمٍ أَمَا تَعْلَمِينَ أَنَّ شَرْطِي عَلَى رَبِّي أَنِّي اشْتَرَطْتُ عَلَى رَبِّي، فَقُلْتُ: إِنَّمَا أَنَا بَشَرٌ أَرْضَى كَمَا يَرْضَى الْبَشَرُ، وَأَغْضَبُ كَمَا يَغْضَبُ الْبَشَرُ، فَأَيُّمَا أَحَدٍ دَعَوْتُ عَلَيْهِ مِنْ أُمَّتِي بِدَعْوَةٍ لَيْسَ لَهَا بِأَهْلٍ أَنْ تَجْعَلَهَا لَهُ طَهُورًا وَزَكَاةً وَقُرْبَةً يُقَرِّبُهُ بِهَا مِنْهُ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2603) عن زهير بن حرب وأبي معن الرّقاشيّ، واللّفظ لزهير، قالا: حدّثنا عمر بن يونس، حدّثنا عكرمة بن عمار، حدّثنا إسحاق بن أبي طلحة، حدّثني أنس بن مالك، فذكره.","grade":"صحيح","chapter_ar":"باب بشرية الرسول ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (2603).","chapter_en":"The Humanity of the Messenger ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":16,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: There was an orphan girl under the care of Umm Sulaym — the mother of Anas. The Messenger of Allah ﷺ saw the orphan girl and said: “Is that you? You have grown! May your age not increase.” The orphan girl returned to Umm Sulaym crying. Umm Sulaym asked: “What is wrong, my daughter?” The girl replied: “The Prophet of Allah ﷺ supplicated against me that my age should never increase,” or she said, “my lifespan.” Umm Sulaym went out hurriedly, wrapping her head-covering as she went, until she met the Messenger of Allah ﷺ. The Messenger of Allah ﷺ asked her: “What is wrong, O Umm Sulaym?” She replied: “O Prophet of Allah, did you supplicate against my orphan girl?” He asked: “What is that, O Umm Sulaym?” She said: “She claims that you supplicated that neither her age nor her lifespan should increase.” The Messenger of Allah ﷺ laughed and then said: “O Umm Sulaym, do you not know the condition I made with my Lord? I made a condition with my Lord and said: ‘I am only a human being. I become pleased as human beings become pleased, and I become angry as human beings become angry. So whichever person from my Ummah I supplicate against with a supplication which he does not deserve, make it for him a purification, a cleansing, and a means of nearness by which You bring him close to You on the Day of Resurrection.’” Abū Maʿn narrated the word: “yutayyimah” in the diminutive form in all three places in the ḥadīth."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9643],"tks":"صحيح: رواه مسلم (2603)."},{"num":785,"demo":false,"sanad":"","matn":["عَنْ الْمُغِيرَةِ بْنِ شُعْبَةَ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى حَتَّى انْتَفَخَتْ قَدَمَاهُ، فَقِيلَ لَهُ: أَتَكَلَّفُ هَذَا وَقَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ؟ فَقَالَ: أَفَلَا أَكُونُ عَبْدًا شَكُورًا."],"takhrij":"متفق عليه: رواه البخاريّ في التهجّد (1130)، ومسلم في صفات المنافقين (2819) كلاهما من حديث زياد بن علاقة، عن المغيرة بن شعبة، فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهية رفع النبي ﷺ فوق المنزلة التي أنزله الله سبحانه وتعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1130) and Muslim (2819).","chapter_en":"The Dislike of Raising the Prophet ﷺ Above the Rank in Which Allah, Glorified and Exalted, Placed Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah, may Allah be pleased with him, reported: The Prophet ﷺ prayed until his feet became swollen. It was said to him: “Do you exert yourself to this extent when Allah has forgiven you what preceded of your sin and what followed?” He replied: “Should I not then be a grateful servant?”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1130)، ومسلم (2819)."},{"num":786,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: سَمِعْتُ عُمَرَ يَقُولُ عَلَى الْمِنْبَر: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا تُطْرُونِي كَمَا أَطْرَتِ النَّصَارَى ابْنَ مَرْيَمَ فَإِنَّمَا أَنَا عَبْدُهُ، فَقُولُوا: عَبْدُ اللَّهِ وَرَسُولُهُ."],"takhrij":"صحيح: رواه البخاريّ في أحاديث الأنبياء (3445) عن الحميديّ، حدّثنا سفيان، قال: سمعتُ الزّهريّ يقول: أخبرني عبيدالله بن عبدالله، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب كراهية رفع النبي ﷺ فوق المنزلة التي أنزله الله سبحانه وتعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3445).","chapter_en":"The Dislike of Raising the Prophet ﷺ Above the Rank in Which Allah, Glorified and Exalted, Placed Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["Ibn ʿAbbās, may Allah be pleased with them, said: I heard ʿUmar may Allah be pleased with him say from the pulpit: I heard the Prophet ﷺ say: “Do not exaggerate in praising me as the Christians exaggerated in praising the son of Mary. I am only His servant, so say: ‘The servant of Allah and His Messenger.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3445)."},{"num":787,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ يَقُولُ: سَمِعْتُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَا تُطْرُونِي كَمَا أَطْرَتِ النَّصَارَى ابْنَ مَرْيَمَ فَإِنَّمَا أَنَا عَبْدُهُ، فَقُولُوا: عَبْدُ اللَّهِ وَرَسُولُهُ."],"takhrij":"صحيح: رواه البخاريّ في أحاديث الأنبياء (3445) عن الحميديّ، حدّثنا سفيان، قال: سمعت الزّهريّ يقول: أخبرني عبيد الله بن عبدالله، عن ابن عباس، سمع عمر يقول على المنبر، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب كراهية رفع النبي ﷺ فوق المنزلة التي أنزله الله سبحانه وتعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by al-Bukhārī (3445).","chapter_en":"The Dislike of Raising the Prophet ﷺ Above the Rank in Which Allah, Glorified and Exalted, Placed Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["ʿUmar, may Allah be pleased with him, said: I heard the Messenger of Allah ﷺ say: “Do not exaggerate in praising me as the Christians exaggerated in praising the son of Mary. I am only His servant, so say: ‘The servant of Allah and His Messenger.’”"]}},"tuhfa":{},"full":1,"rep":[12233],"tks":"صحيح: رواه البخاري (3445)."},{"num":788,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ رَجُلًا قَالَ: يَا مُحَمَّدُ، يَا خَيْرَنَا وَابْنَ خَيْرِنَا، وَيَا سَيِّدَنَا وَابْنَ سَيِّدِنَا. فَقَالَ: قُولُوا بِقَوْلِكُمْ، وَلَا يَسْتَجِرَّكُمْ الشَّيْطَانُ أَوْ الشَّيَاطِينُ، إِحْدَى الْكَلِمَتَيْنِ، أَنَا مُحَمَّدُ عَبْدِ اللَّهِ وَرَسُولُهُ، مَا أُحِبُّ أَنْ تَرْفَعُونِي فَوْقَ مَنْزِلَتِي الَّتِي أَنْزَلَنِي اللَّهُ."],"takhrij":"صحيح: رواه أحمد (13596) عن عفّان، حدّثنا حمّاد بن سلمة، عن ثابت، عن أنس، فذكره.ومن هذا الطّريق رواه البيهقيّ في المدخل (536)، وانظر فيه مزيداً من التخريج.","grade":"صحيح","chapter_ar":"باب كراهية رفع النبي ﷺ فوق المنزلة التي أنزله الله سبحانه وتعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Imām Aḥmad (13596) and al-Bayhaqī in al-Madkhal (536).","chapter_en":"The Dislike of Raising the Prophet ﷺ Above the Rank in Which Allah, Glorified and Exalted, Placed Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["Anas, may Allah be pleased with him, reported: A man said: “O Muḥammad, O best of us and son of the best of us; O our master and son of our master.” He replied: “Say what you ordinarily say, but do not let Satan — or the devils — draw you beyond the proper limit. I am Muḥammad, the servant of Allah and His Messenger. I do not like for you to raise me above the rank in which Allah has placed me.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه الإمام أحمد (13596)، والبيهقي في المدخل (536)."},{"num":789,"demo":false,"sanad":"","matn":["عَنِ الْحُسَيْنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ: يَا أَيُّهَا النَّاسُ، لا تَرْفَعُونِي فَوْقَ قِدْرِي، فَإِنَّ اللَّهَ اتَّخَذَنِي عَبْدًا قَبْلَ أَنْ يَتَّخِذَنِي نَبِيًّاَ."],"takhrij":"حسن: رواه الطبراني في الكبير (2889)، والحاكم (4825) كلاهما من طريق علي بن قادم، حدثنا عبد السلام بن حرب، عن يحيى بن سعيد (هو الأنصاري)، عن علي بن الحسين، عن أبيه (وهو الحسين بن علي بن أبي طالب) قال: أحبّونا بحبّ الإسلام، ثم ذكر الحديث.","grade":"حسن","chapter_ar":"باب كراهية رفع النبي ﷺ فوق المنزلة التي أنزله الله سبحانه وتعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (3/138) and al-Ḥākim (4825).","chapter_en":"The Dislike of Raising the Prophet ﷺ Above the Rank in Which Allah, Glorified and Exalted, Placed Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["Al-Ḥusayn ibn ʿAlī ibn Abī Ṭālib may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “O people, do not raise me above my proper rank, for Allah made me a servant before He made me a Prophet.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (2889)، والحاكم (4825)."},{"num":790,"demo":false,"sanad":"","matn":["عَنْ مُطَرِّفِ بْنِ عَبْدِاللَّهِ بْنِ الشِّخِّيرِ قَالَ: قَالَ أَبِي: انْطَلَقْتُ فِي وَفْدِ بَنِي عَامِرٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْنَا: أَنْتَ سَيِّدُنَا، فَقَالَ: السَّيِّدُ اللَّهُ، قُلْنَا: وَأَفْضَلُنَا فَضْلًا وَأَعْظَمُنَا طَوْلًا، فَقَالَ: قُولُوا بِقَوْلِكُمْ أَوْ بَعْضِ قَوْلِكُمْ، وَلَا يَسْتَجْرِيَنَّكُمُ الشَّيْطَانُ."],"takhrij":"صحيح: رواه أبو داود (4806) عن مسدّد، حدّثنا بشر، يعني ابن المفضَّل،، حدّثنا أبو سلمة، سعيد بن يزيد، عن أبي نضرة، عن مطرف، فذكره.","grade":"صحيح","chapter_ar":"باب كراهية رفع النبي ﷺ فوق المنزلة التي أنزله الله سبحانه وتعالى","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Abū Dāwūd (4806), Aḥmad (16311), and al-Bayhaqī in al-Madkhal (537).","chapter_en":"The Dislike of Raising the Prophet ﷺ Above the Rank in Which Allah, Glorified and Exalted, Placed Him","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":17,"content":{"translation":{"en":["Muṭarrif ibn ʿAbdullāh ibn al-Shikhkhīr reported: My father, may Allah be pleased with him, said: I went with the delegation of Banū ʿĀmir to the Messenger of Allah ﷺ, and we said: “You are our master.” He replied: “The Master is Allah, Blessed and Exalted.” We said: “And you are the greatest of us in virtue and the greatest of us in generosity.” He replied: “Say what you ordinarily say, or some of what you ordinarily say, but do not let Satan draw you beyond the proper limit.”"]},"buhuth":{"en":["Another narration adds:","“And the radiant jafnah.”","At its conclusion is the wording:","“Do not let him lead you astray.”","Regarding the expression:","“the radiant jafnah,”","Ibn al-Athīr said in al-Nihāyah:","The Arabs used to call a generous chief who fed people a “jafnah,” because he would set down a large serving vessel and feed people from it, so he was named after it.","“Al-gharrāʾ” means bright or white, indicating that it was filled with fat and rich food.","Regarding the expression:","“yastajirrannakum,”","with a doubled rāʾ, it comes from jarr, meaning “to drag.”","Al-Sindī said that this reading is correct."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4806)، وأحمد (16311)، والبيهقي في المدخل (537)."},{"num":791,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ افْتَقَدَ ثَابِتَ بْنَ قَيْسٍ، فَقَالَ: رَجُلٌ يَا رَسُولَ اللَّهِ أَنَا أَعْلَمُ لَكَ عِلْمَهُ فَأَتَاهُ فَوَجَدَهُ جَالِسًا فِي بَيْتِهِ مُنَكِّسًا رَأْسَهُ، فَقَالَ: مَا شَأْنُكَ؟ فَقَالَ: شَرٌّ كَانَ يَرْفَعُ صَوْتَهُ فَوْقَ صَوْتِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَدْ حَبِطَ عَمَلُهُ وَهُوَ مِنْ أَهْلِ النَّارِ. فَأَتَى الرَّجُلُ فَأَخْبَرَهُ أَنَّهُ، قَالَ: كَذَا وَكَذَا.","فَقَالَ مُوسَى بْنُ أَنَسٍ: فَرَجَعَ الْمَرَّةَ الْآخِرَةَ بِبِشَارَةٍ عَظِيمَةٍ، فَقَالَ: اذْهَبْ إِلَيْهِ فَقُلْ لَهُ إِنَّكَ لَسْتَ مِنْ أَهْلِ النَّارِ وَلَكِنْ مِنْ أَهْلِ الْجَنَّةِ."],"takhrij":"متفق عليه: رواه البخاريّ في المناقب (3613)، وفي التفسير bukhari(4846) عن علي بن عبدالله، حدّثنا أزهر بن سعد، أخبرنا ابنُ عون، قال: أنبأني موسى بن أنس، عن أنس بن مالك، فذكر مثله.ورواه مسلم في الإيمان من وجه آخر كما يأتي.","grade":"متفق عليه","chapter_ar":"ذكر ما يدل على أن رفع الصوت على النبي ﷺ من الكبائر ومحبط للأعمال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4846, 3613) and Muslim (119:187).","chapter_en":"Mention of What Indicates That Raising One’s Voice Above the Prophet ﷺ Is Among the Major Sins and Can Nullify Deeds","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: The Prophet ﷺ noticed that Thābit ibn Qays was absent. A man said: “O Messenger of Allah, I can find out what has happened to him.” He went to him and found him sitting in his house with his head lowered. He asked: “What is wrong with you?” Thābit replied: “Something terrible! I used to raise my voice above the voice of the Prophet ﷺ, so my deeds have been nullified and I am among the people of the Fire!” The man returned to the Prophet ﷺ and informed him of what Thābit had said. Mūsā ibn Anas said:","The man returned to him the final time carrying tremendous glad tidings, saying: “Go to him and tell him: ‘You are not among the people of the Fire. Rather, you are among the people of Paradise.’”"]}},"tuhfa":{},"full":1,"rep":[10118],"tks":"متفق عليه: رواه البخاري (4846، 3613)، ومسلم (119: 187)."},{"num":792,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: لَمَّا نَزَلَتْ هَذِهِ الآيَةُ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ وَلَا تَجْهَرُوا لَهُ بِالْقَوْلِ كَجَهْرِ بَعْضِكُمْ لِبَعْضٍ أَنْ تَحْبَطَ أَعْمَالُكُمْ وَأَنْتُمْ لَا تَشْعُرُونَ﴾ [ الحجرات: 2]. جَلَسَ ثَابِتُ بْنُ قَيْسٍ فِي بَيْتِهِ، وَقَالَ: أَنَا مِنْ أَهْلِ النَّارِ....فَذَكَرَ ذَلِكَ سَعْدٌ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بَلْ هُوَ مِنْ أَهْلِ الْجَنَّة.","وَفِي رِوَايَةِ: (قَالَ سَعْدٌ) فَكُنَّا نَرَاهُ يَمْشِي بَيْنَ أَظْهُرِنَا رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (119: 188) عن هُريم بن عبدالأعلى الأسديّ، حدّثنا المعتمر بن سليمان، سمعت أبي يذكر عن ثابت، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"ذكر ما يدل على أن رفع الصوت على النبي ﷺ من الكبائر ومحبط للأعمال","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (119:188).","chapter_en":"Mention of What Indicates That Raising One’s Voice Above the Prophet ﷺ Is Among the Major Sins and Can Nullify Deeds","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":18,"content":{"translation":{"en":["Anas ibn Mālik, may Allah be pleased with him, reported: When the following verse was revealed: “O you who believe, do not raise your voices above the voice of the Prophet, nor speak loudly to him as you speak loudly to one another, lest your deeds become worthless while you do not realize it.” [Sūrat al-Ḥujurāt 49:2] Thābit ibn Qays, may Allah be pleased with him, said: “By Allah, I am the one who used to raise my voice in the presence of the Messenger of Allah ﷺ, and I fear that I am among the people of the Fire.” The Prophet ﷺ said: “Rather, he is among the people of Paradise.”","Anas said: Afterward, we would see him walking among us as a man from the people of Paradise."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (119: 188)."},{"num":793,"demo":false,"sanad":"","matn":["عَنْ أَبِي سُفْيَانَ قَالَ (فَذَكَرَهُ فِي حَدِيثِ طَوِيلٍ): كَانَ فِي رِسَالَةٍ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إلَى هِرَقْلَ:... بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ سَلَامٌ عَلَى مَنِ اتَّبَعَ الْهُدَى، أَمَّا بَعْدُ، فَإِنِّي أَدْعُوكَ بِدِعَايَةِ الْإِسْلَامِ أَسْلِمْ تَسْلَمْ، وَأَسْلِمْ يُؤْتِكَ اللَّهُ أَجْرَكَ مَرَّتَيْنِ، وَإِنْ تَوَلَّيْتَ فَإِنَّ عَلَيْكَ إِثْمَ الْأَرِيسِيِّينَ. ﴿ قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ وَلَا نُشْرِكَ بِهِ شَيْئًا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللَّهِ فَإِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ ﴾ [سورة آل عمران: 64]... (فَذَكَرَ الْحَدِيثَ)."],"takhrij":"متفق عليه: رواه البخاريّ في التفسير (4553)، ومسلم في الجهاد (1773) كلاهما من حديث عبدالرزّاق، أخبرنا معمر، عن الزّهريّ، عبدالله بن عبدالله بن عتبة، عن ابن عباس، أنّ أبا سفيان أخبره من فِيهِ إلى فِيهِ قال (فذكر الحديث).","grade":"متفق عليه","chapter_ar":"باب مضاعفة أجر الكتابي إذا آمن بالنبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4553) and Muslim (1773).","chapter_en":"The Reward of a Person From the People of the Scripture Is Doubled if He Believes in the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":19,"content":{"translation":{"en":["Abū Sufyān, may Allah be pleased with him, said: The letter of the Prophet ﷺ to Heraclius contained: “In the Name of Allah, the Most Merciful, the Especially Merciful. From Muḥammad, the Messenger of Allah, to Heraclius, the ruler of the Romans. Peace be upon whoever follows guidance. To proceed: I invite you with the call of Islam. Accept Islam and you will be safe. Accept Islam and Allah will give you your reward twice. But if you turn away, then upon you will be the sin of the Arīsiyyīn. ‘Say: O People of the Scripture, come to a word that is equitable between us and you: that we worship none except Allah, associate nothing with Him, and that none of us take others as lords besides Allah. But if they turn away, then say: Bear witness that we are Muslims.’” [Āl ʿImrān 3:64]"]},"buhuth":{"en":["The word:","“al-Arīsiyyīn”","is the plural of Arīsī, derived from arīs, meaning a farmer or agricultural laborer."]},"intro":{"ar":["قال الله تعالى:","﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ مِنْ قَبْلِهِ هُمْ بِهِ يُؤْمِنُونَ ۝ وَإِذَا يُتْلَى عَلَيْهِمْ قَالُوا آمَنَّا بِهِ إِنَّهُ الْحَقُّ مِنْ رَبِّنَا إِنَّا كُنَّا مِنْ قَبْلِهِ مُسْلِمِينَ ۝ أُولَئِكَ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ بِمَا صَبَرُوا وَيَدْرَءُونَ بِالْحَسَنَةِ السَّيِّئَةَ وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ﴾","[القصص: ٥٢–٥٤]","نزلت هذه الآية في طائفة آمنوا بالنبي ﷺ، كعبد الله بن سلام من اليهود، وسلمان الفارسي من النصارى."],"en":["Allah Most High said:","“Those to whom We gave the Scripture before it believe in it. When it is recited to them, they say: ‘We believe in it. Indeed, it is the truth from our Lord. Indeed, even before it we were Muslims.’ Those will be given their reward twice because of their patience. They repel evil with good and spend from what We have provided them.”","[Sūrat al-Qaṣaṣ 28:52–54]","This verse was revealed concerning a group who believed in the Prophet ﷺ, such as ʿAbdullāh ibn Salām from the Jews and Salmān al-Fārisī from the Christians."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4553)، ومسلم (1773)."},{"num":794,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، أَنَّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلَاثَةٌ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ الرَّجُلُ تَكُونُ لَهُ الْأَمَةُ، فَيُعَلِّمُهَا فَيُحْسِنُ تَعْلِيمَهَا، وَيُؤَدِّبُهَا فَيُحْسِنُ أَدَبَهَا، ثُمَّ يُعْتِقُهَا فَيَتَزَوَّجُهَا فَلَهُ أَجْرَانِ، وَمُؤْمِنُ أَهْلِ الْكِتَابِ الَّذِي كَانَ مُؤْمِنًا ثُمَّ آمَنَ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَهُ أَجْرَانِ، وَالْعَبْدُ الَّذِي يُؤَدِّي حَقَّ اللَّهِ وَيَنْصَحُ لِسَيِّدِهِ. ثُمَّ قَالَ الشَّعْبِيُّ: وَأَعْطَيْتُكَهَا بِغَيْرِ شَيْءٍ وَقَدْ كَانَ الرَّجُلُ يَرْحَلُ فِي أَهْوَنَ مِنْهَا إِلَى الْمَدِينَةِ."],"takhrij":"متفق عليه: رواه البخاريّ في الجهاد (3011)، ومسلم في الإيمان (154) كلاهما من حديث سفيان بن عيينة، حدّثنا صالح بن حيي أبو حسن، قال: سمعتُ الشّعبيّ يقول: حدّثني أبو بردة، أنّه سمع أباه، عن النبيّ صلى الله عليه وسلم، فذكر مثله. واللّفظ للبخاريّ، ولفظ مسلم قريب منه، وفيه: ورجل كانت له أمّة، فغذّاها فأحسن غذاءها ثم أدّبها، فأحسن أدبها....","grade":"متفق عليه","chapter_ar":"باب مضاعفة أجر الكتابي إذا آمن بالنبي ﷺ","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3011) and Muslim (154).","chapter_en":"The Reward of a Person From the People of the Scripture Is Doubled if He Believes in the Prophet ﷺ","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":19,"content":{"translation":{"en":["Abū Mūsā may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “Three people will be given their reward twice: A man who owns a slave woman, teaches her and perfects her education, disciplines her and perfects her upbringing, then frees her and marries her — he will have two rewards; a believer from the People of the Scripture who was a believer and then believed in the Prophet ﷺ — he will have two rewards; and a slave who fulfills the right of Allah and is sincere toward his master.” Al-Shaʿbī then said: “I have given this to you for nothing, while a man would once travel to Madinah for something less than this.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3011)، ومسلم (154)."},{"num":795,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ رَسُولُ اللّَهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ مِنَ الْأَنْبِيَاءِ قَبْلِي نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ، وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا، وَأَيُّمَا رَجُلٍ مِنْ أُمَّتِي أَدْرَكَتْهُ الصَّلَاةُ فَلْيُصَلِّ وَأُحِلَّتْ لِي الْغَنَائِمُ، وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَى النَّاسِ كَافَّةً، وَأُعْطِيتُ الشَّفَاعَةَ."],"takhrij":"متفق عليه: رواه البخاريّ في الصلاة (438)، ومسلم في المساجد (521) كلاهما من حديث هُشيم، قال: حدّثنا سيَّار، وهو أبو الحكم، قال: حدّثنا يزيد الفقير، قال: حدّثنا جابر بن عبدالله، فذكره.","grade":"متفق عليه","chapter_ar":"باب الإيمان بالخصال التي فُضِّل بها النبي ﷺ على غيره","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (438) and Muslim (521).","chapter_en":"Belief in the Qualities by Which the Prophet ﷺ Was Favored Over Others","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":20,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh may Allah be pleased with them reported that the Messenger of Allah ﷺ said: “I have been given five things which were not given to any prophet before me: I have been aided by fear cast into the enemy from the distance of a month’s journey; the earth has been made for me a place of prayer and a means of purification, so wherever a man from my Ummah is when the time for prayer comes, let him pray; the spoils of war have been made lawful for me; a prophet used to be sent specifically to his own people, whereas I have been sent to all mankind; and I have been granted intercession.”"]}},"tuhfa":{},"full":1,"rep":[730,923],"tks":"متفق عليه: رواه البخاري (438)، ومسلم (521)."},{"num":796,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فُضِّلْتُ عَلَى الأَنْبِيَاءِ بِسِتٍّ، أُعْطِيتُ جَوَامِعَ الْكَلِمِ، وَنُصِرْتُ بِالرُّعْبِ، وَأُحِلَّتْ لِيَ الْغَنَائِمُ، وَجُعِلَتْ لِيَ الأَرْضُ طَهُورًا وَمَسْجِدًا، وَأُرْسِلْتُ إِلَى الْخَلْقِ كَافَّةً، وَخُتِمَ بِيَ النَّبِيُّونَ."],"takhrij":"صحيح: رواه مسلم في المساجد (523) من طرق عن إسماعيل بن جعفر، عن العلاء، عن أبيه، عن أبي هريرة، فذكر مثله.","grade":"صحيح","chapter_ar":"باب الإيمان بالخصال التي فُضِّل بها النبي ﷺ على غيره","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (523).","chapter_en":"Belief in the Qualities by Which the Prophet ﷺ Was Favored Over Others","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I have been favored over the prophets in six ways: I was given concise yet comprehensive speech; I was aided by fear cast into the enemy; the spoils of war were made lawful for me; the earth was made for me a means of purification and a place of prayer; I was sent to all creation; and the prophets were sealed with me.”"]}},"tuhfa":{},"full":1,"rep":[731,8009,12026,12348,12906,13078],"tks":"صحيح: رواه مسلم (523)."},{"num":797,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُوتِيتُ خَمْسًا لَمْ يُؤْتَهُنَّ نَبِيٌّ كَانَ قَبْلِي نُصِرْتُ بِالرُّعْبِ، فَيُرْعَبُ مِنِّي الْعَدُوُّ عَنْ مَسِيرَةِ شَهْرٍ، وَجُعِلَتْ لِي الْأَرْضُ مَسْجِدًا وَطَهُورًا، وَأُحِلَّتْ لِي الْغَنَائِمُ وَلَمْ تَحِلَّ لِأَحَدٍ كَانَ قَبْلِي، وَبُعِثْتُ إِلَى الْأَحْمَرِ وَالْأَسْوَدِ، وَقِيلَ لِي: سَلْ تُعْطَهْ، فَاخْتَبَأْتُهَا شَفَاعَةً لِأُمَّتِي، وَهِيَ نَائِلَةٌ مِنْكُمْ إِنْ شَاءَ اللَّهُ، مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا."],"takhrij":"صحيح: رواه الإمام أحمد (21299) عن يعقوب، حدّثنا أبي، عن ابن إسحاق، حدّثني سليمان الأعمش، عن مجاهد بن جبر أبي الحجّاج، عن عبيد بن عمير اللّيثيّ، عن أبي ذر، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بالخصال التي فُضِّل بها النبي ﷺ على غيره","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (21299).","chapter_en":"Belief in the Qualities by Which the Prophet ﷺ Was Favored Over Others","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":20,"content":{"translation":{"en":["Abū Dharr may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “I was given five things which no prophet before me was given: I was aided by fear, so that the enemy fears me from the distance of a month’s journey; the earth was made for me a place of prayer and a means of purification; the spoils of war were made lawful for me, though they had not been lawful for anyone before me; I was sent to the red and the black; and it was said to me: ‘Ask, and you will be given.’ So I reserved it as intercession for my Ummah. It will reach — if Allah wills — whoever among you meets Allah without associating anything with Him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[732,924],"tks":"صحيح: رواه الإمام أحمد (21299)."},{"num":798,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فُضِّلْنَا عَلَى النَّاسِ بِثَلَاثٍ، جُعِلَتْ صُفُوفُنَا كَصُفُوفِ الْمَلَائِكَةِ، وَجُعِلَتْ لَنَا الأَرْضُ كُلُّهَا مَسْجِدًا، وَجُعِلَتْ تُرْبَتُهَا لَنَا طَهُورًا، إِذَا لَمْ نَجِدِ الْمَاءَ."],"takhrij":"صحيح: رواه مسلم في المساجد (522) عن أبي بكر بن أبي شيبة، حدّثنا محمد بن فضيل، عن أبي مالك الأشجعيّ، عن ربعي، عن حذيفة، فذكره.","grade":"صحيح","chapter_ar":"باب الإيمان بالخصال التي فُضِّل بها النبي ﷺ على غيره","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ṣaḥīḥ: Narrated by Muslim (522).","chapter_en":"Belief in the Qualities by Which the Prophet ﷺ Was Favored Over Others","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":20,"content":{"translation":{"en":["Ḥudhayfah may Allah be pleased with him reported that the Messenger of Allah ﷺ said: “We have been favored over the people in three ways: Our rows have been made like the rows of the angels; the entire earth has been made for us a place of prayer; and its soil has been made for us a means of purification when we cannot find water.”"]}},"tuhfa":{},"full":1,"rep":[13161],"tks":"صحيح: رواه مسلم (522)."},{"num":799,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ غَزْوَةِ تَبُوكَ قَامَ مِنَ اللَّيْلِ يُصَلِّي، فَاجْتَمَعَ وَرَاءَهُ رِجَالٌ مِنْ أَصْحَابِهِ يَحْرُسُونَهُ حَتَّى إِذَا صَلَّى وَانْصَرَفَ إِلَيْهِمْ، فَقَالَ لَهُمْ: لَقَدْ أُعْطِيتُ اللَّيْلَةَ خَمْسًا، مَا أُعْطِيَهُنَّ أَحَدٌ قَبْلِي: أَمَّا أَنَا فَأُرْسِلْتُ إِلَى النَّاسِ كُلِّهِمْ عَامَّةً، وَكَانَ مَنْ قَبْلِي إِنَّمَا يُرْسَلُ إِلَى قَوْمِهِ، وَنُصِرْتُ عَلَى الْعَدُوِّ بِالرُّعْبِ، وَلَوْ كَانَ بَيْنِي وَبَيْنَهُمْ مَسِيرَةُ شَهْرٍ لَمُلِئَ مِنْهُ رُعْبًا، وَأُحِلَّتْ لِي الْغَنَائِمُ آكُلُهَا، وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ أَكْلَهَا، كَانُوا يُحْرِقُونَهَا، وَجُعِلَتْ لِي الْأَرْضُ مَسَاجِدَ وَطَهُورًا، أَيْنَمَا أَدْرَكَتْنِي الصَّلَاةُ تَمَسَّحْتُ وَصَلَّيْتُ، وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ ذَلِكَ، إِنَّمَا كَانُوا يُصَلُّونَ فِي كَنَائِسِهِمْ وَبِيَعِهِمْ، وَالْخَامِسَةُ، هِيَ مَا هِيَ، قِيلَ لِي سَلْ، فَإِنَّ كُلَّ نَبِيٍّ قَدْ سَأَلَ، فَأَخَّرْتُ مَسْأَلَتِي إِلَى يَوْمِ الْقِيَامَةِ، فَهِيَ لَكُمْ وَلِمَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"حسن: رواه الإمام أحمد (7068) عن قتيبة بن سعيد، حدّثنا بكر بن مُضر، عن ابن الهاد، عن عمرو بن شعيب، عن أبيه، عن جدّه، فذكره.","grade":"حسن","chapter_ar":"باب الإيمان بالخصال التي فُضِّل بها النبي ﷺ على غيره","chapter_ur":"","part_ar":"كتاب الإيمان","part_ur":"","takhrij_en":"Ḥasan: Narrated by Imām Aḥmad (7068).","chapter_en":"Belief in the Qualities by Which the Prophet ﷺ Was Favored Over Others","part_en":"The Book of Faith","group_ar":"جموع أبواب الإيمان بالنبي ﷺ","group_en":"Collection of Chapters Concerning Faith in the Prophet ﷺ","part_no":2,"group_no":9,"chapter_no":20,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr, may Allah be pleased with them, reported: During the year of the expedition of Tabūk, the Messenger of Allah ﷺ stood during the night in prayer. A number of his Companions gathered behind him to guard him. When he finished praying and turned toward them, he said: “Tonight I have been given five things which no one before me was given: As for me, I have been sent to all people universally, whereas those before me were sent only to their own peoples. I have been granted victory over the enemy through fear, such that even if the distance between me and them were a month’s journey, they would be filled with fear of me. The spoils of war have been made lawful for me to consume, whereas those before me regarded consuming them as forbidden and would burn them. The earth has been made for me places of prayer and a means of purification. Wherever the time for prayer reaches me, I purify myself with it and pray. Those before me treated this matter differently; they would pray only in their churches and synagogues. And as for the fifth — it is what it is: I was told, ‘Ask, for every prophet has asked.’ So I postponed my request until the Day of Resurrection. It is for you and for whoever testifies that there is no deity worthy of worship except Allah.”"]},"buhuth":{"en":["Its chain is Ḥasan because of ʿAmr ibn Shuʿayb, for his ḥadīth is Ḥasan.","Al-Haythamī said in al-Majmaʿ (10/367): “It was narrated by Aḥmad, and its narrators are trustworthy.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[925,8012,9634],"tks":"حسن: رواه الإمام أحمد (7068)."}]);